ON CONFLICT (skill, group_type, group_key)
DO UPDATE SET
  name = EXCLUDED.name,
  description = EXCLUDED.description,
  display_order = EXCLUDED.display_order,
  updated_at = NOW()
WHERE aptis_groups.name IS DISTINCT FROM EXCLUDED.name
   OR aptis_groups.description IS DISTINCT FROM EXCLUDED.description
   OR aptis_groups.display_order IS DISTINCT FROM EXCLUDED.display_order;

-- 2. Upsert Audio Content Blocks (Zero-Write via IS DISTINCT FROM)
INSERT INTO public.aptis_content_blocks (skill, block_type, source_key, title, content, metadata, content_hash)
VALUES
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set001-q001-audio', 'Part 1 Question 1 Audio', 'Man: I finally bought the small car I told you about! Friend: That''s great news! How much did it set you back? Man: The dealer first showed me a larger model for 3,550 pounds, and the version with a full service package came to 4,250. The small one itself cost me 3,250 pounds, which was within my budget. Friend: That sounds like a good deal. Man: Yes, I chose the basic package and used the money I saved to pay for insurance.', '{"source_key":"listening-p1-set001-q001-audio","skill":"listening","part_number":1,"transcript":"Man: I finally bought the small car I told you about! Friend: That''s great news! How much did it set you back? Man: The dealer first showed me a larger model for 3,550 pounds, and the version with a full service package came to 4,250. The small one itself cost me 3,250 pounds, which was within my budget. Friend: That sounds like a good deal. Man: Yes, I chose the basic package and used the money I saved to pay for insurance.","transcript_status":"source_word_comment","word_comment_ids":["0"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'dbba2018cbbffdc0ca222900dd51386957f52e23c34bd74d0b18c6e1145f0dcd'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set001-q002-audio', 'Part 1 Question 2 Audio', 'Ahmed: Rose, are we still meeting for dinner tonight? I originally suggested half past seven, but my meeting may not finish until then. past seven is definitely too early for me. Could we make it to eight instead? Rose: That works well. I''ll book the table and wait inside if I arrive before you. Just message me when you leave the office. Nobody else needed to change their plans after the updated time was agreed.', '{"source_key":"listening-p1-set001-q002-audio","skill":"listening","part_number":1,"transcript":"Ahmed: Rose, are we still meeting for dinner tonight? I originally suggested half past seven, but my meeting may not finish until then. past seven is definitely too early for me. Could we make it to eight instead? Rose: That works well. I''ll book the table and wait inside if I arrive before you. Just message me when you leave the office. Nobody else needed to change their plans after the updated time was agreed.","transcript_status":"source_word_comment","word_comment_ids":["1"],"speaker_labels":["Ahmed"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'cff244123c5ddc77b1a92c69bfc6d30ff727d08d8dc1f750582cbc318340b5d2'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set001-q003-audio', 'Part 1 Question 3 Audio', 'Man: I''m trying to call the teleshop, but I have three similar numbers written down. Is it 102030? Friend: No, that belongs to the delivery company. And 301020 is the repair line. The teleshop number is 201030. Man: Great, I''ll save it properly this time. I need to ask whether the television I ordered is still available. A second check confirmed that no part of the total had been counted twice.', '{"source_key":"listening-p1-set001-q003-audio","skill":"listening","part_number":1,"transcript":"Man: I''m trying to call the teleshop, but I have three similar numbers written down. Is it 102030? Friend: No, that belongs to the delivery company. And 301020 is the repair line. The teleshop number is 201030. Man: Great, I''ll save it properly this time. I need to ask whether the television I ordered is still available. A second check confirmed that no part of the total had been counted twice.","transcript_status":"source_word_comment","word_comment_ids":["2"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'be5f0e8e06bb10e0640f8f224e10409074b5b7d5a6ced454dda8ba96c6e668a4'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set001-q004-audio', 'Part 1 Question 4 Audio', 'Man: I like the green top in the window, but it is a little too bright for work. Do you have the same design in blue? Assistant: We do, although the blue one is only available in a larger size. Man: In that case, I''ll take the black top. It fits well and will match my trousers. I may come back for something more colourful another day.', '{"source_key":"listening-p1-set001-q004-audio","skill":"listening","part_number":1,"transcript":"Man: I like the green top in the window, but it is a little too bright for work. Do you have the same design in blue? Assistant: We do, although the blue one is only available in a larger size. Man: In that case, I''ll take the black top. It fits well and will match my trousers. I may come back for something more colourful another day.","transcript_status":"source_word_comment","word_comment_ids":["3"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '36b6f1b21a9fe6ce30541cbfb7c8be8ef90022f004765245e9bf78cc1db0f5a4'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set001-q005-audio', 'Part 1 Question 5 Audio', 'Man: Shall we meet at the station before lunch? Sister: It will be extremely crowded because several trains arrive together. The university is , but it is too far from the shops we need. Man: Let''s meet at the park instead, beside the main gate. Sister: Perfect. I''ll bring the documents, and afterwards we can walk into town together. The nearby landmarks were useful, although neither was the destination itself.', '{"source_key":"listening-p1-set001-q005-audio","skill":"listening","part_number":1,"transcript":"Man: Shall we meet at the station before lunch? Sister: It will be extremely crowded because several trains arrive together. The university is , but it is too far from the shops we need. Man: Let''s meet at the park instead, beside the main gate. Sister: Perfect. I''ll bring the documents, and afterwards we can walk into town together. The nearby landmarks were useful, although neither was the destination itself.","transcript_status":"source_word_comment","word_comment_ids":["4"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'bc62a71b8303df5bf369a5782419991d34a7c951daef7195162a8542bc8cdcef'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set001-q006-audio', 'Part 1 Question 6 Audio', 'Woman: Lisa and I have just returned from a week by the sea. People sometimes think we are mother and daughter because she is a little older and always looks after me. Others assume she was once my teacher. In fact, we are best friends and have known each other since secondary school. We travel together whenever our work schedules allow it. The explanation helped listeners understand why the other guesses sounded believable.', '{"source_key":"listening-p1-set001-q006-audio","skill":"listening","part_number":1,"transcript":"Woman: Lisa and I have just returned from a week by the sea. People sometimes think we are mother and daughter because she is a little older and always looks after me. Others assume she was once my teacher. In fact, we are best friends and have known each other since secondary school. We travel together whenever our work schedules allow it. The explanation helped listeners understand why the other guesses sounded believable.","transcript_status":"source_word_comment","word_comment_ids":["5"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'f18c08809694b97c712e794a8c7e5895c2b98d4a377adb45a8574e0026c88c37'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set001-q007-audio', 'Part 1 Question 7 Audio', 'Woman: We talked about replacing the computer because it is slow, and my husband also wants a smaller car. However, the change we are making to the house is the window. The current one is too large and lets in too much sunlight during the afternoon. We have ordered a smaller design with thicker glass, and the work should begin next month. Nothing else needed to change once the main decision had been made.', '{"source_key":"listening-p1-set001-q007-audio","skill":"listening","part_number":1,"transcript":"Woman: We talked about replacing the computer because it is slow, and my husband also wants a smaller car. However, the change we are making to the house is the window. The current one is too large and lets in too much sunlight during the afternoon. We have ordered a smaller design with thicker glass, and the work should begin next month. Nothing else needed to change once the main decision had been made.","transcript_status":"source_word_comment","word_comment_ids":["6"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '7c794befc99caaa112b9fe6e678667317888b4b344031f5873284a32c14a3e73'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set001-q008-audio', 'Part 1 Question 8 Audio', 'Receptionist: I''ve checked today''s clinic list again. Carl, Harry and Matthew are from the UK, while two other clients are visiting from France. Leslie is the only person from the United States, so we have one American client today. Her appointment is at eleven. Please make sure the correct form is waiting at reception before she arrives. The receipt and the current price list were checked once more afterwards.', '{"source_key":"listening-p1-set001-q008-audio","skill":"listening","part_number":1,"transcript":"Receptionist: I''ve checked today''s clinic list again. Carl, Harry and Matthew are from the UK, while two other clients are visiting from France. Leslie is the only person from the United States, so we have one American client today. Her appointment is at eleven. Please make sure the correct form is waiting at reception before she arrives. The receipt and the current price list were checked once more afterwards.","transcript_status":"source_word_comment","word_comment_ids":["7"],"speaker_labels":["Receptionist"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'e27af967c501a654e1cedfd8d4397864acaefbf6abb154df85e247cfd735e7e1'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set001-q009-audio', 'Part 1 Question 9 Audio', 'Anna: I enjoy walking early because everywhere is before classes begin. I sometimes walk through the park at weekends, and my neighbourhood is pleasant in the evening. Every morning, though, I go for a walk around the college campus. I usually pass the library and sports centre before returning to my accommodation to collect my books for the first lesson. The route becomes simple once the correct building or entrance comes into view.', '{"source_key":"listening-p1-set001-q009-audio","skill":"listening","part_number":1,"transcript":"Anna: I enjoy walking early because everywhere is before classes begin. I sometimes walk through the park at weekends, and my neighbourhood is pleasant in the evening. Every morning, though, I go for a walk around the college campus. I usually pass the library and sports centre before returning to my accommodation to collect my books for the first lesson. The route becomes simple once the correct building or entrance comes into view.","transcript_status":"source_word_comment","word_comment_ids":["8"],"speaker_labels":["Anna"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '7ebc6ad975c02db352dad3340c58bb2af236d47211013ab0d078115ac81f8eab'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set001-q010-audio', 'Part 1 Question 10 Audio', 'Girl: Hi, I was in your café this afternoon and I think I left my bag there. I paid at the counter, but I am sure I still had it afterwards. I did not sit near the door. My table was in the corner beside a tall plant, so could you look there first? It is a small brown bag with my keys inside. They planned to arrive early enough to avoid any further confusion there.', '{"source_key":"listening-p1-set001-q010-audio","skill":"listening","part_number":1,"transcript":"Girl: Hi, I was in your café this afternoon and I think I left my bag there. I paid at the counter, but I am sure I still had it afterwards. I did not sit near the door. My table was in the corner beside a tall plant, so could you look there first? It is a small brown bag with my keys inside. They planned to arrive early enough to avoid any further confusion there.","transcript_status":"source_word_comment","word_comment_ids":["9"],"speaker_labels":["Girl"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'f5cc33a54722cfc1f60a95318ac701985febf401468dd95f824345b4f99f53c4'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set001-q011-audio', 'Part 1 Question 11 Audio', 'Helen: My whole family has come to see me off before I start college. We are not inside the university area yet, and we are nowhere near the library complex. We are standing in the residential area just outside the campus, beside some small shops and trees. Dad is unloading my bags while everyone else is saying goodbye. It feels exciting and a little emotional.', '{"source_key":"listening-p1-set001-q011-audio","skill":"listening","part_number":1,"transcript":"Helen: My whole family has come to see me off before I start college. We are not inside the university area yet, and we are nowhere near the library complex. We are standing in the residential area just outside the campus, beside some small shops and trees. Dad is unloading my bags while everyone else is saying goodbye. It feels exciting and a little emotional.","transcript_status":"source_word_comment","word_comment_ids":["10"],"speaker_labels":["Helen"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '6ba8dcda86b2dd7a0f0da4e0699905ed87479b9f2db74cea955f8e62240c0962'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set001-q012-audio', 'Part 1 Question 12 Audio', 'Woman: I''m checking the timing for dinner tonight because I need to catch a train afterwards. The journey to the station is not thirty minutes unless I take a taxi, and fifty minutes would include waiting for the bus. Walking normally takes about forty minutes. I''ll leave the restaurant early enough to buy my ticket and find the correct platform without rushing. They noted the change immediately so nobody would follow the earlier timetable.', '{"source_key":"listening-p1-set001-q012-audio","skill":"listening","part_number":1,"transcript":"Woman: I''m checking the timing for dinner tonight because I need to catch a train afterwards. The journey to the station is not thirty minutes unless I take a taxi, and fifty minutes would include waiting for the bus. Walking normally takes about forty minutes. I''ll leave the restaurant early enough to buy my ticket and find the correct platform without rushing. They noted the change immediately so nobody would follow the earlier timetable.","transcript_status":"source_word_comment","word_comment_ids":["11"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '86b85a194aaccd6f140dd8b332a3fc1da2710c22ad35ec2be1447d147fca7e7a'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set001-q013-audio', 'Part 1 Question 13 Audio', 'Man: Our train was supposed to depart at nine, but a signal problem caused a delay. At first, staff warned us that we might have to wait until ten o''clock. Fortunately, the problem was fixed sooner, and the train actually left at half past nine. We arrived later than planned, but we still had enough time to attend the morning meeting. The remaining activities could continue normally once the correct time was clear.', '{"source_key":"listening-p1-set001-q013-audio","skill":"listening","part_number":1,"transcript":"Man: Our train was supposed to depart at nine, but a signal problem caused a delay. At first, staff warned us that we might have to wait until ten o''clock. Fortunately, the problem was fixed sooner, and the train actually left at half past nine. We arrived later than planned, but we still had enough time to attend the morning meeting. The remaining activities could continue normally once the correct time was clear.","transcript_status":"source_word_comment","word_comment_ids":["12"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '4eed283c6355acc9fd86faac4c9ba007b87350f098c4c10afd4a1f5257f8f340'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set002-q001-audio', 'Part 1 Question 14 Audio', 'Woman: I''m comparing the flights for my trip next month. There is an afternoon service for 300 pounds, but it arrives too late for the conference. The flexible ticket costs 400 pounds because changes are included. The morning flight I need is 350 pounds. It is not the cheapest option, although its arrival time is much more convenient. The figures became clear once the different products or categories were separated.', '{"source_key":"listening-p1-set002-q001-audio","skill":"listening","part_number":1,"transcript":"Woman: I''m comparing the flights for my trip next month. There is an afternoon service for 300 pounds, but it arrives too late for the conference. The flexible ticket costs 400 pounds because changes are included. The morning flight I need is 350 pounds. It is not the cheapest option, although its arrival time is much more convenient. The figures became clear once the different products or categories were separated.","transcript_status":"source_word_comment","word_comment_ids":["13"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'a3e57937e1a6430d47274dd780ace4462feabee98c08aeaed081594f695d8509'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set002-q002-audio', 'Part 1 Question 15 Audio', 'Woman: I advertised my old music player for sixty dollars, but nobody wanted to pay that much. One buyer offered forty, which felt too low because it still worked perfectly. We eventually agreed on fifty dollars, and I sold it last weekend. I used part of the money to buy new headphones and put the rest into my savings account. Everyone involved used the latest record instead of relying on memory.', '{"source_key":"listening-p1-set002-q002-audio","skill":"listening","part_number":1,"transcript":"Woman: I advertised my old music player for sixty dollars, but nobody wanted to pay that much. One buyer offered forty, which felt too low because it still worked perfectly. We eventually agreed on fifty dollars, and I sold it last weekend. I used part of the money to buy new headphones and put the rest into my savings account. Everyone involved used the latest record instead of relying on memory.","transcript_status":"source_word_comment","word_comment_ids":["14"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '05dde5e09883a33f10497c51b84071c620857ac71d1ce0094c55435d3a3d9f74'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set002-q003-audio', 'Part 1 Question 16 Audio', 'Woman: He is often late, so people assume he oversleeps or returns home because he has forgotten something. Today neither of those things happened. He left the house on time but reached the platform just as the doors closed, so the main reason was that he missed the train. He had to wait twenty minutes for the next service and called the office immediately. Once that was understood, the rest of the situation made much more sense.', '{"source_key":"listening-p1-set002-q003-audio","skill":"listening","part_number":1,"transcript":"Woman: He is often late, so people assume he oversleeps or returns home because he has forgotten something. Today neither of those things happened. He left the house on time but reached the platform just as the doors closed, so the main reason was that he missed the train. He had to wait twenty minutes for the next service and called the office immediately. Once that was understood, the rest of the situation made much more sense.","transcript_status":"source_word_comment","word_comment_ids":["15"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '7e3e474317a891b2f85338214795de347d2d6bb78b21c8b76ea03945c3e5859d'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set002-q004-audio', 'Part 1 Question 17 Audio', 'Mother: Hi, could you pick up a few groceries on your way home? Son: Sure, Mum. What do you need? Mother: The milk is two pounds fifty, and the large loaf of bread costs three pounds fifty. A dozen eggs is only one pound fifty today, so please buy two boxes if they still have them. Son: Got it. Is that everything? Mother: Yes, I need the eggs for a cake, but the other things are for tomorrow''s breakfast. Thank you, dear.', '{"source_key":"listening-p1-set002-q004-audio","skill":"listening","part_number":1,"transcript":"Mother: Hi, could you pick up a few groceries on your way home? Son: Sure, Mum. What do you need? Mother: The milk is two pounds fifty, and the large loaf of bread costs three pounds fifty. A dozen eggs is only one pound fifty today, so please buy two boxes if they still have them. Son: Got it. Is that everything? Mother: Yes, I need the eggs for a cake, but the other things are for tomorrow''s breakfast. Thank you, dear.","transcript_status":"source_word_comment","word_comment_ids":["16"],"speaker_labels":["Mother"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'da4c58c27202900b27010e2c21e5d57146f80e01bb7e3df2e010c53f243b79e0'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set002-q005-audio', 'Part 1 Question 18 Audio', 'Man: Hi, I''m calling to confirm where we should meet. I could wait at home, but then we might miss each other when you arrive. Woman: True, and the garden is completely wet after all that rain. Man: Exactly. Let''s meet outside the shop opposite the station instead. I''ll be standing near the entrance with a blue umbrella. Woman: Perfect, I''ll head there now. We can walk home together from there.', '{"source_key":"listening-p1-set002-q005-audio","skill":"listening","part_number":1,"transcript":"Man: Hi, I''m calling to confirm where we should meet. I could wait at home, but then we might miss each other when you arrive. Woman: True, and the garden is completely wet after all that rain. Man: Exactly. Let''s meet outside the shop opposite the station instead. I''ll be standing near the entrance with a blue umbrella. Woman: Perfect, I''ll head there now. We can walk home together from there.","transcript_status":"source_word_comment","word_comment_ids":["17"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '53196e581bcab079053fe9ee70be23b0a8b5891f335fddf8464b893686e2c4c5'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set002-q006-audio', 'Part 1 Question 19 Audio', 'Julie: Professor, I cannot finish the assignment by Thursday morning. Could I submit it on Friday? Professor: Friday is difficult because the department will be closed. I can extend the deadline until Saturday morning. Upload it before midday, and make sure the reference list is included. Julie: Thank you. That gives me an extra evening to check the final section carefully. The new arrangement also avoided a rushed journey at the busiest part of the day.', '{"source_key":"listening-p1-set002-q006-audio","skill":"listening","part_number":1,"transcript":"Julie: Professor, I cannot finish the assignment by Thursday morning. Could I submit it on Friday? Professor: Friday is difficult because the department will be closed. I can extend the deadline until Saturday morning. Upload it before midday, and make sure the reference list is included. Julie: Thank you. That gives me an extra evening to check the final section carefully. The new arrangement also avoided a rushed journey at the busiest part of the day.","transcript_status":"source_word_comment","word_comment_ids":["18"],"speaker_labels":["Julie"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '2289c1c11355dcb88d48447b64e5b150b9f541a46154a2ca0f7f3251017567e6'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set002-q007-audio', 'Part 1 Question 20 Audio', 'Tour guide: Welcome to our town. Older guidebooks say around eight thousand people lived here, and an estimate from several years ago suggested nine thousand. The latest local records show that the population has reached ten thousand. Most new residents live near the railway station, while the historic centre still contains the small shops and cafés we will visit today. The written information was updated immediately to prevent another mistake later.', '{"source_key":"listening-p1-set002-q007-audio","skill":"listening","part_number":1,"transcript":"Tour guide: Welcome to our town. Older guidebooks say around eight thousand people lived here, and an estimate from several years ago suggested nine thousand. The latest local records show that the population has reached ten thousand. Most new residents live near the railway station, while the historic centre still contains the small shops and cafés we will visit today. The written information was updated immediately to prevent another mistake later.","transcript_status":"source_word_comment","word_comment_ids":["19"],"speaker_labels":["Tour guide"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'efaab6f5af759002d4cbef884e9790bc816f5e5bd24a1912be26cb6be4bc29c9'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set002-q008-audio', 'Part 1 Question 21 Audio', 'Man: After work, I do not usually cycle home because the main road is too busy. I sometimes meet a client in the late afternoon, but there is no appointment today. I''m going running in the park instead. It helps me clear my mind after sitting at a desk, and I normally finish with a short walk before going home for dinner. The other possibilities were useful to discuss but were not selected.', '{"source_key":"listening-p1-set002-q008-audio","skill":"listening","part_number":1,"transcript":"Man: After work, I do not usually cycle home because the main road is too busy. I sometimes meet a client in the late afternoon, but there is no appointment today. I''m going running in the park instead. It helps me clear my mind after sitting at a desk, and I normally finish with a short walk before going home for dinner. The other possibilities were useful to discuss but were not selected.","transcript_status":"source_word_comment","word_comment_ids":["20"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'a4e1bac4f79c95be053e0ab7f7d75ee756778257801822f8f5500095fa47eddb'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set002-q009-audio', 'Part 1 Question 22 Audio', 'Man: Do you spend most of your free time reading? Woman: I enjoy books, and I occasionally play chess with my cousin, but neither is my favourite form of entertainment. I most enjoy going to the theatre. Seeing actors perform live feels more exciting than watching something at home, and I usually discuss the play with friends over coffee afterwards. The most important feature appeared before the speaker moved on to other information.', '{"source_key":"listening-p1-set002-q009-audio","skill":"listening","part_number":1,"transcript":"Man: Do you spend most of your free time reading? Woman: I enjoy books, and I occasionally play chess with my cousin, but neither is my favourite form of entertainment. I most enjoy going to the theatre. Seeing actors perform live feels more exciting than watching something at home, and I usually discuss the play with friends over coffee afterwards. The most important feature appeared before the speaker moved on to other information.","transcript_status":"source_word_comment","word_comment_ids":["21"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'dd9ead62854b1a31a3f8fbfb4e3f33e21a5619801cefd7bfa32b1cfaf0a63b9a'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set002-q010-audio', 'Part 1 Question 23 Audio', 'Man: Hi, Maria. I''ll be in your town this weekend! Maria: Wonderful! When should we meet? Man: I first thought I could visit at ten on Saturday, but my train does not arrive until the evening. Eight on Sunday would be a little early after the journey. Maria: No rush - what time works for you? Man: I''ll see you at nine o''clock on Sunday. We can have breakfast together and then walk around the old market. Maria: That sounds perfect, I''ll look forward to it.', '{"source_key":"listening-p1-set002-q010-audio","skill":"listening","part_number":1,"transcript":"Man: Hi, Maria. I''ll be in your town this weekend! Maria: Wonderful! When should we meet? Man: I first thought I could visit at ten on Saturday, but my train does not arrive until the evening. Eight on Sunday would be a little early after the journey. Maria: No rush - what time works for you? Man: I''ll see you at nine o''clock on Sunday. We can have breakfast together and then walk around the old market. Maria: That sounds perfect, I''ll look forward to it.","transcript_status":"source_word_comment","word_comment_ids":["22"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '983d480230614d8221faad14d6d159be6520e205fddea8a22ddb92dd89fd853d'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set002-q011-audio', 'Part 1 Question 24 Audio', 'Man: I''m calling about tomorrow''s client meeting. The room is available from 9:15, but we need time to set up the equipment. Eleven fifteen is when the clients must leave for another appointment. We will therefore start at 10:15 as originally agreed. Please arrive twenty minutes early so we can test the presentation and organise the printed documents. The revised timing left enough room for travel and preparation beforehand.', '{"source_key":"listening-p1-set002-q011-audio","skill":"listening","part_number":1,"transcript":"Man: I''m calling about tomorrow''s client meeting. The room is available from 9:15, but we need time to set up the equipment. Eleven fifteen is when the clients must leave for another appointment. We will therefore start at 10:15 as originally agreed. Please arrive twenty minutes early so we can test the presentation and organise the printed documents. The revised timing left enough room for travel and preparation beforehand.","transcript_status":"source_word_comment","word_comment_ids":["23"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '33fb2a64bb5f19938954a0eeb38b9344fc435a32e24c9fe3cc5c8b747dd4dda2'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set002-q012-audio', 'Part 1 Question 25 Audio', 'Recorded message: Thank you for calling the department store. Press one if you want to make a complaint about a recent purchase. Press two for repairs or technical support. If you are interested in buying a new computer, press three to speak to a sales adviser. Please have an idea of your budget and the type of work you need the computer to handle. No extra charge or item needed to be added to that figure.', '{"source_key":"listening-p1-set002-q012-audio","skill":"listening","part_number":1,"transcript":"Recorded message: Thank you for calling the department store. Press one if you want to make a complaint about a recent purchase. Press two for repairs or technical support. If you are interested in buying a new computer, press three to speak to a sales adviser. Please have an idea of your budget and the type of work you need the computer to handle. No extra charge or item needed to be added to that figure.","transcript_status":"source_word_comment","word_comment_ids":["24"],"speaker_labels":["Recorded message"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '00bac8a388c503c919e5e76e9f6bd6cc236bbc80d8a40c3645fca8ddb8dc1d7a'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set002-q013-audio', 'Part 1 Question 26 Audio', 'Expert: A higher salary may make an unhappy employee feel better for a short time, and searching for a completely new job is another possibility. However, if the main problem is the local team or working environment, the best solution may be to request a transfer to another branch. The employee can keep the same benefits while trying a different manager and group of colleagues.', '{"source_key":"listening-p1-set002-q013-audio","skill":"listening","part_number":1,"transcript":"Expert: A higher salary may make an unhappy employee feel better for a short time, and searching for a completely new job is another possibility. However, if the main problem is the local team or working environment, the best solution may be to request a transfer to another branch. The employee can keep the same benefits while trying a different manager and group of colleagues.","transcript_status":"source_word_comment","word_comment_ids":["25"],"speaker_labels":["Expert"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '342312dd959099c08c154fe48851e8d134366a2663159d49046f42d37a532a8f'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set003-q001-audio', 'Part 1 Question 27 Audio', 'Man: Do you remember how good you were at swimming at school? Woman: I enjoyed it, but I never competed seriously. I also joined the running club for one term. Football was the sport I was really good at, and I played for the school team for three years. We won several local matches, and I still meet some of my former teammates occasionally. The practical details made that option more suitable than either earlier suggestion.', '{"source_key":"listening-p1-set003-q001-audio","skill":"listening","part_number":1,"transcript":"Man: Do you remember how good you were at swimming at school? Woman: I enjoyed it, but I never competed seriously. I also joined the running club for one term. Football was the sport I was really good at, and I played for the school team for three years. We won several local matches, and I still meet some of my former teammates occasionally. The practical details made that option more suitable than either earlier suggestion.","transcript_status":"source_word_comment","word_comment_ids":["26"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'fc0188331f9dd7064a94edd681cc564b7b5a03575d548fbd904351a30b5284f7'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set003-q002-audio', 'Part 1 Question 28 Audio', 'Pierre: Sarah is bringing the drinks, and Tom has promised to prepare two large salads. What should we take to the picnic? Emma: We should bring the main food, perhaps sandwiches, chicken and some bread. Pierre: Good idea. Then everyone will have something substantial to eat. I''ll pack it in a cool box, and you can bring plates and napkins. After making the decision, the remaining arrangements were straightforward.', '{"source_key":"listening-p1-set003-q002-audio","skill":"listening","part_number":1,"transcript":"Pierre: Sarah is bringing the drinks, and Tom has promised to prepare two large salads. What should we take to the picnic? Emma: We should bring the main food, perhaps sandwiches, chicken and some bread. Pierre: Good idea. Then everyone will have something substantial to eat. I''ll pack it in a cool box, and you can bring plates and napkins. After making the decision, the remaining arrangements were straightforward.","transcript_status":"source_word_comment","word_comment_ids":["27"],"speaker_labels":["Pierre"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '4d247b3e8f8ad082589e07f86708a255e3f5da5ed966997f7c098346d2553a80'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set003-q003-audio', 'Part 1 Question 29 Audio', 'Saleswoman: The house was built in the 1920s, and much of it has been carefully preserved. The wooden floor is original, and the basic architecture has not changed. The furniture, however, is not original; it was replaced a few years ago to make the rooms more comfortable. The owners selected modern pieces that still suit the age and style of the property. The other possibilities were useful to discuss but were not selected.', '{"source_key":"listening-p1-set003-q003-audio","skill":"listening","part_number":1,"transcript":"Saleswoman: The house was built in the 1920s, and much of it has been carefully preserved. The wooden floor is original, and the basic architecture has not changed. The furniture, however, is not original; it was replaced a few years ago to make the rooms more comfortable. The owners selected modern pieces that still suit the age and style of the property. The other possibilities were useful to discuss but were not selected.","transcript_status":"source_word_comment","word_comment_ids":["28"],"speaker_labels":["Saleswoman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'd2327ee4712b3d315956d5a3c51e1d542df9228e4ef3dbcd90d5f84ba04bf88a'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set003-q004-audio', 'Part 1 Question 30 Audio', 'Station announcement: Passengers for Greenfield should not wait on Platform Five, as that platform is being used by the local service. Platform Eight is closed for maintenance this morning. The 10:30 train to Greenfield will arrive on Platform Two. Please move there now, keep behind the yellow line, and have your tickets ready before the train arrives. Anyone following the directions carefully should reach the correct place without difficulty.', '{"source_key":"listening-p1-set003-q004-audio","skill":"listening","part_number":1,"transcript":"Station announcement: Passengers for Greenfield should not wait on Platform Five, as that platform is being used by the local service. Platform Eight is closed for maintenance this morning. The 10:30 train to Greenfield will arrive on Platform Two. Please move there now, keep behind the yellow line, and have your tickets ready before the train arrives. Anyone following the directions carefully should reach the correct place without difficulty.","transcript_status":"source_word_comment","word_comment_ids":["29"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '4aa25ba4b42cef3bb72db20700e92f207c8d61ef86faea7d1599c6def2ac2550'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set003-q005-audio', 'Part 1 Question 31 Audio', 'Artist: People often imagine that I work from nine to five and keep every weekend free. My job is different because I work irregular hours. Sometimes I paint early in the morning, while on other days I continue late into the night or work on Saturday. The schedule depends on exhibitions, commissions and when I feel most creative. The final comments added context without changing the main description.', '{"source_key":"listening-p1-set003-q005-audio","skill":"listening","part_number":1,"transcript":"Artist: People often imagine that I work from nine to five and keep every weekend free. My job is different because I work irregular hours. Sometimes I paint early in the morning, while on other days I continue late into the night or work on Saturday. The schedule depends on exhibitions, commissions and when I feel most creative. The final comments added context without changing the main description.","transcript_status":"source_word_comment","word_comment_ids":["30"],"speaker_labels":["Artist"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '479a08fdb327ae8a4088e5970243e72915d74900cd9a13d15ab0b1fb46134230'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set003-q006-audio', 'Part 1 Question 32 Audio', 'Student: Do you drive to school every day? Teacher: No, parking near the school is difficult. I used to take the bus, but waiting for it often made me late. Now I walk to school because my house is only fifteen minutes away. The journey gives me some exercise, and I usually arrive feeling more awake and ready for the first lesson. The choice fitted the situation better than the other ideas they had discussed.', '{"source_key":"listening-p1-set003-q006-audio","skill":"listening","part_number":1,"transcript":"Student: Do you drive to school every day? Teacher: No, parking near the school is difficult. I used to take the bus, but waiting for it often made me late. Now I walk to school because my house is only fifteen minutes away. The journey gives me some exercise, and I usually arrive feeling more awake and ready for the first lesson. The choice fitted the situation better than the other ideas they had discussed.","transcript_status":"source_word_comment","word_comment_ids":["31"],"speaker_labels":["Student"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'fe69a43cd9e5857f3926c161d847035dae0d44f79901230cb12c782f0f34ccb9'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set003-q007-audio', 'Part 1 Question 33 Audio', 'Anne: Hi, Sally. Could you stop at the shop on your way home? We already have enough bread, and I bought milk this morning. What I need is eggs because I want to finish the cake for dinner. Please get a dozen if possible. Do not forget to collect your brother from school first, and keep the receipt for me. It also left enough time and energy for the rest of the day.', '{"source_key":"listening-p1-set003-q007-audio","skill":"listening","part_number":1,"transcript":"Anne: Hi, Sally. Could you stop at the shop on your way home? We already have enough bread, and I bought milk this morning. What I need is eggs because I want to finish the cake for dinner. Please get a dozen if possible. Do not forget to collect your brother from school first, and keep the receipt for me. It also left enough time and energy for the rest of the day.","transcript_status":"source_word_comment","word_comment_ids":["32"],"speaker_labels":["Anne"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '3aeb863451cc2dd9762f88dda2548c10420e5b66ee1fcf4eb954ea02ac2f952c'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set003-q008-audio', 'Part 1 Question 34 Audio', 'Mother: Your science homework is important, and we should review the history chapter later. However, the subject you clearly enjoy most is art. You spend hours drawing, and you always notice colours and small details. Your latest picture is excellent. Finish the outline tonight, and tomorrow we can buy some new paints for the final version. The alternatives remained possible on another occasion, but not this time.', '{"source_key":"listening-p1-set003-q008-audio","skill":"listening","part_number":1,"transcript":"Mother: Your science homework is important, and we should review the history chapter later. However, the subject you clearly enjoy most is art. You spend hours drawing, and you always notice colours and small details. Your latest picture is excellent. Finish the outline tonight, and tomorrow we can buy some new paints for the final version. The alternatives remained possible on another occasion, but not this time.","transcript_status":"source_word_comment","word_comment_ids":["33"],"speaker_labels":["Mother"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'b428e00695c16fac0675569e9fbdb4ebad623e909be5840b579f6aa0959b4a67'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set003-q009-audio', 'Part 1 Question 35 Audio', 'Tour guide: I''m sorry, but today''s city tour cannot go ahead. The weather is actually pleasant, and the bus is working normally, so neither of those is the problem. We simply do not have enough people to run the tour. Anyone who booked can move to tomorrow''s group or receive a full refund at the information desk. The later information ruled out the assumptions made at the beginning.', '{"source_key":"listening-p1-set003-q009-audio","skill":"listening","part_number":1,"transcript":"Tour guide: I''m sorry, but today''s city tour cannot go ahead. The weather is actually pleasant, and the bus is working normally, so neither of those is the problem. We simply do not have enough people to run the tour. Anyone who booked can move to tomorrow''s group or receive a full refund at the information desk. The later information ruled out the assumptions made at the beginning.","transcript_status":"source_word_comment","word_comment_ids":["34"],"speaker_labels":["Tour guide"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '9b2106d937c7fb7680b2a08f7796358e5600ff02308110af5350df893ccba8c2'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set003-q010-audio', 'Part 1 Question 36 Audio', 'Man: I used to work as a chef, and later I taught history for several years. Both jobs were rewarding, but now I want to become a writer. I have been collecting ideas for short stories and have already planned my first novel. I will continue working part-time while I write, because finishing a complete book may take a long time. After making the decision, the remaining arrangements were straightforward.', '{"source_key":"listening-p1-set003-q010-audio","skill":"listening","part_number":1,"transcript":"Man: I used to work as a chef, and later I taught history for several years. Both jobs were rewarding, but now I want to become a writer. I have been collecting ideas for short stories and have already planned my first novel. I will continue working part-time while I write, because finishing a complete book may take a long time. After making the decision, the remaining arrangements were straightforward.","transcript_status":"source_word_comment","word_comment_ids":["35"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'bfa51721c395599b8995b312e0bf3ceff45fb4c36296127e045b64ee4bfe3084'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set003-q011-audio', 'Part 1 Question 37 Audio', 'Tom: Hi, Mike. I first thought we could meet at six this evening, but I have to finish some work. Five is obviously too early now. Let''s meet at seven in the park instead. Mike: That is fine. I''ll bring a basketball, and we can buy some snacks on the way. Send me a message when you leave home. The remaining activities could continue normally once the correct time was clear.', '{"source_key":"listening-p1-set003-q011-audio","skill":"listening","part_number":1,"transcript":"Tom: Hi, Mike. I first thought we could meet at six this evening, but I have to finish some work. Five is obviously too early now. Let''s meet at seven in the park instead. Mike: That is fine. I''ll bring a basketball, and we can buy some snacks on the way. Send me a message when you leave home. The remaining activities could continue normally once the correct time was clear.","transcript_status":"source_word_comment","word_comment_ids":["36"],"speaker_labels":["Tom"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '6a7485511dea4a02649e4d76a528d69faf799565a6b7e46b5ae9ad780c775f41'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set003-q012-audio', 'Part 1 Question 38 Audio', 'Finance expert: Young people should certainly avoid spending too much on clothes, and they should save something for emergencies whenever possible. What they should not do is keep asking for more money when their budget runs out. It is better to record regular expenses, reduce unnecessary purchases and avoid borrowing. Learning to manage a limited amount is an important financial skill. That option matched the person''s needs more closely than the alternatives.', '{"source_key":"listening-p1-set003-q012-audio","skill":"listening","part_number":1,"transcript":"Finance expert: Young people should certainly avoid spending too much on clothes, and they should save something for emergencies whenever possible. What they should not do is keep asking for more money when their budget runs out. It is better to record regular expenses, reduce unnecessary purchases and avoid borrowing. Learning to manage a limited amount is an important financial skill. That option matched the person''s needs more closely than the alternatives.","transcript_status":"source_word_comment","word_comment_ids":["37"],"speaker_labels":["Finance expert"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '2e2b6381876ea6a85b5efbffd4e51198f0832020e7620dbc7cb33a2cfe80feb1'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set003-q013-audio', 'Part 1 Question 39 Audio', 'Woman: Officer, I need to report something missing. My wallet is still in my handbag, and my car is parked where I left it. I have lost my phone, probably while I was walking through the park. It has a dark green case. I tried calling it from another number, but nobody answered, so I hope someone has handed it in. Nothing else needed to change once the main decision had been made.', '{"source_key":"listening-p1-set003-q013-audio","skill":"listening","part_number":1,"transcript":"Woman: Officer, I need to report something missing. My wallet is still in my handbag, and my car is parked where I left it. I have lost my phone, probably while I was walking through the park. It has a dark green case. I tried calling it from another number, but nobody answered, so I hope someone has handed it in. Nothing else needed to change once the main decision had been made.","transcript_status":"source_word_comment","word_comment_ids":["38"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '8e72520e37c033cd1d0f14bc21ebfb0467e972cb12ef9c49187f05c353ed9c2b'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set004-q001-audio', 'Part 1 Question 40 Audio', 'Student: I grew up in a small village with my parents, and next month I hope to move into an apartment with friends. Right now, however, I live in a town hall near the university. Part of the building has been converted into temporary student accommodation. It is not luxurious, but the location is convenient and I can walk to lectures in ten minutes. A clear landmark nearby makes the correct place easy to recognise on arrival.', '{"source_key":"listening-p1-set004-q001-audio","skill":"listening","part_number":1,"transcript":"Student: I grew up in a small village with my parents, and next month I hope to move into an apartment with friends. Right now, however, I live in a town hall near the university. Part of the building has been converted into temporary student accommodation. It is not luxurious, but the location is convenient and I can walk to lectures in ten minutes. A clear landmark nearby makes the correct place easy to recognise on arrival.","transcript_status":"source_word_comment","word_comment_ids":["39"],"speaker_labels":["Student"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '42a65270334d997cd5fc61e681f35d37216b456339cf2060f8640105a472231a'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set004-q002-audio', 'Part 1 Question 41 Audio', 'Student: Last year I studied maths and science, and both subjects were useful. This year, I''m going to take a computer course because I want to learn more about technology. The class includes programming, basic design and several practical projects. I am especially looking forward to building a small website rather than spending all my time reading textbooks. It also left enough time and energy for the rest of the day.', '{"source_key":"listening-p1-set004-q002-audio","skill":"listening","part_number":1,"transcript":"Student: Last year I studied maths and science, and both subjects were useful. This year, I''m going to take a computer course because I want to learn more about technology. The class includes programming, basic design and several practical projects. I am especially looking forward to building a small website rather than spending all my time reading textbooks. It also left enough time and energy for the rest of the day.","transcript_status":"source_word_comment","word_comment_ids":["40"],"speaker_labels":["Student"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'b889e2a5fe28667c6d0216ac204d27c97b61061251966e165ee7fb36e89e6e3c'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set004-q003-audio', 'Part 1 Question 42 Audio', 'Girl: I''m going to a show at the city theatre on Saturday. There will be a dance performance near the beginning and a big celebration in the middle when the winners are announced. The show will end with a surprise performance, although the organisers have not said who will appear. I plan to stay until the end because everyone says that final part will be special.', '{"source_key":"listening-p1-set004-q003-audio","skill":"listening","part_number":1,"transcript":"Girl: I''m going to a show at the city theatre on Saturday. There will be a dance performance near the beginning and a big celebration in the middle when the winners are announced. The show will end with a surprise performance, although the organisers have not said who will appear. I plan to stay until the end because everyone says that final part will be special.","transcript_status":"source_word_comment","word_comment_ids":["41"],"speaker_labels":["Girl"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '30222e3df766b2cf6b93755b6d1bdb8282abd32db804bb4fe4cbb776f1a4319d'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set004-q004-audio', 'Part 1 Question 43 Audio', 'Man: I need gifts for two friends. The mugs look attractive, but they are heavy to carry, and the candles may break in my suitcase. I''m going to buy clothes instead because I already know both friends'' sizes. I''ll choose a shirt for one and a warm scarf for the other. Could you put them in separate gift bags, please? The practical details made that option more suitable than either earlier suggestion.', '{"source_key":"listening-p1-set004-q004-audio","skill":"listening","part_number":1,"transcript":"Man: I need gifts for two friends. The mugs look attractive, but they are heavy to carry, and the candles may break in my suitcase. I''m going to buy clothes instead because I already know both friends'' sizes. I''ll choose a shirt for one and a warm scarf for the other. Could you put them in separate gift bags, please? The practical details made that option more suitable than either earlier suggestion.","transcript_status":"source_word_comment","word_comment_ids":["42"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'f5257f4a4c108119fd3a20e54705dba341c2ed4568586044148fdc425d74e80f'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set004-q005-audio', 'Part 1 Question 44 Audio', 'Man: Hello, I think I left something in your shop. My jacket and books are both with me, but I cannot find my glasses. They are brown with round frames. I remember taking them off while I tried on a jacket, so they may be near the changing room. Could you keep them safely if a member of staff finds them? After making the decision, the remaining arrangements were straightforward.', '{"source_key":"listening-p1-set004-q005-audio","skill":"listening","part_number":1,"transcript":"Man: Hello, I think I left something in your shop. My jacket and books are both with me, but I cannot find my glasses. They are brown with round frames. I remember taking them off while I tried on a jacket, so they may be near the changing room. Could you keep them safely if a member of staff finds them? After making the decision, the remaining arrangements were straightforward.","transcript_status":"source_word_comment","word_comment_ids":["43"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '072e024c9b8f91b4a3e3d8960e9d5fdf7d815b547b392d23b7cbc9bd211bf06c'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set004-q006-audio', 'Part 1 Question 45 Audio', 'Anna: Are we still meeting this afternoon? The mall is convenient, but it will be crowded because of the sale. The park is pleasant, although the weather may turn wet. Let''s meet at the marketplace at three instead. I want to visit the new ice-cream shop and buy some fresh fruit. I''ll wait beside the main entrance if I arrive first. The nearby landmarks were useful, although neither was the destination itself.', '{"source_key":"listening-p1-set004-q006-audio","skill":"listening","part_number":1,"transcript":"Anna: Are we still meeting this afternoon? The mall is convenient, but it will be crowded because of the sale. The park is pleasant, although the weather may turn wet. Let''s meet at the marketplace at three instead. I want to visit the new ice-cream shop and buy some fresh fruit. I''ll wait beside the main entrance if I arrive first. The nearby landmarks were useful, although neither was the destination itself.","transcript_status":"source_word_comment","word_comment_ids":["44"],"speaker_labels":["Anna"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'b76128e0d5b863810e4aa113e7cc0b3285cc0cefa0c65f97f5c1e4c942e97bb7'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set004-q007-audio', 'Part 1 Question 46 Audio', 'Auctioneer: This cabinet looks old, but not every part dates from the same period. The doors were replaced after they became damaged, and the handles are modern copies. The drawer is the original part and still has the maker''s mark underneath. That detail increases the cabinet''s value. Bidding will begin in a moment, so please examine the photographs in the catalogue. That option matched the person''s needs more closely than the alternatives.', '{"source_key":"listening-p1-set004-q007-audio","skill":"listening","part_number":1,"transcript":"Auctioneer: This cabinet looks old, but not every part dates from the same period. The doors were replaced after they became damaged, and the handles are modern copies. The drawer is the original part and still has the maker''s mark underneath. That detail increases the cabinet''s value. Bidding will begin in a moment, so please examine the photographs in the catalogue. That option matched the person''s needs more closely than the alternatives.","transcript_status":"source_word_comment","word_comment_ids":["45"],"speaker_labels":["Auctioneer"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '0abfd8d53ca99e149b55761d7937ff996d4f544e16490a3c5cafe531a398c284'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set004-q008-audio', 'Part 1 Question 47 Audio', 'Voice message: Hi, Evan. I heard that you are sick and wanted to check how you feel. You may also be tired after sleeping badly, but this sounds more serious than ordinary tiredness. Please rest, drink plenty of water and do not go to work today. I can bring soup and collect any medicine you need after I finish my morning appointment. Nothing else needed to change once the main decision had been made.', '{"source_key":"listening-p1-set004-q008-audio","skill":"listening","part_number":1,"transcript":"Voice message: Hi, Evan. I heard that you are sick and wanted to check how you feel. You may also be tired after sleeping badly, but this sounds more serious than ordinary tiredness. Please rest, drink plenty of water and do not go to work today. I can bring soup and collect any medicine you need after I finish my morning appointment. Nothing else needed to change once the main decision had been made.","transcript_status":"source_word_comment","word_comment_ids":["46"],"speaker_labels":["Voice message"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '1cc7048acbde7c0a7a2ddf7887d0bc7858e3b63f11e29e0b20d3d008db113a32'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set004-q009-audio', 'Part 1 Question 48 Audio', 'Tour guide: Before we begin, let me show you where our office is. It is not next to the park, although you will pass the park during the tour. The rooms above the restaurant belong to another company. Our office is opposite the hotel where you are staying. You can visit it until six if you need tickets, maps or help with tomorrow''s activities. A clear landmark nearby makes the correct place easy to recognise on arrival.', '{"source_key":"listening-p1-set004-q009-audio","skill":"listening","part_number":1,"transcript":"Tour guide: Before we begin, let me show you where our office is. It is not next to the park, although you will pass the park during the tour. The rooms above the restaurant belong to another company. Our office is opposite the hotel where you are staying. You can visit it until six if you need tickets, maps or help with tomorrow''s activities. A clear landmark nearby makes the correct place easy to recognise on arrival.","transcript_status":"source_word_comment","word_comment_ids":["47"],"speaker_labels":["Tour guide"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'fe93d1e216982435df92e3b35ac72e62ee69ceaad1bedba40c8d59f54deb5b53'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set004-q010-audio', 'Part 1 Question 49 Audio', 'Station announcement: The departure board originally showed 9:30, and 9:45 is the expected arrival time at the next station. The train itself leaves at 9:15 this morning. Passengers should go to Platform Four now and keep their luggage with them. The doors will close one minute before departure, so please do not wait in the café. Everyone agreed to confirm the smaller details by message later that day.', '{"source_key":"listening-p1-set004-q010-audio","skill":"listening","part_number":1,"transcript":"Station announcement: The departure board originally showed 9:30, and 9:45 is the expected arrival time at the next station. The train itself leaves at 9:15 this morning. Passengers should go to Platform Four now and keep their luggage with them. The doors will close one minute before departure, so please do not wait in the café. Everyone agreed to confirm the smaller details by message later that day.","transcript_status":"source_word_comment","word_comment_ids":["48"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '6ec34904fdd2288068dbbf0519b9b458485c1a540f523b974a23b418c714e5e3'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set004-q011-audio', 'Part 1 Question 50 Audio', 'Sarah: Hi, John. I''m leaving a message about our meeting today. We originally agreed on two o''clock, but I have an appointment that will not finish in time. One o''clock would be even more difficult. Could we meet at three o''clock instead? I''ll be at the café near the station. Please call me if the new time causes any problem. Nobody else needed to change their plans after the updated time was agreed.', '{"source_key":"listening-p1-set004-q011-audio","skill":"listening","part_number":1,"transcript":"Sarah: Hi, John. I''m leaving a message about our meeting today. We originally agreed on two o''clock, but I have an appointment that will not finish in time. One o''clock would be even more difficult. Could we meet at three o''clock instead? I''ll be at the café near the station. Please call me if the new time causes any problem. Nobody else needed to change their plans after the updated time was agreed.","transcript_status":"source_word_comment","word_comment_ids":["49"],"speaker_labels":["Sarah"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'aa991984bf161822ec936d77c6f512493d1ff79a59ba3fd72ab464eda7afbc4e'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set004-q012-audio', 'Part 1 Question 51 Audio', 'Woman: I bought a new dress for my cousin''s wedding. I first tried a black-and-white one, but the pattern looked too informal. The long white dress fitted well, although I worried about keeping it clean. The one I finally bought is long and red. It is comfortable, and the colour looks especially good with the shoes I already own. The comparison became easier once the less important details were separated.', '{"source_key":"listening-p1-set004-q012-audio","skill":"listening","part_number":1,"transcript":"Woman: I bought a new dress for my cousin''s wedding. I first tried a black-and-white one, but the pattern looked too informal. The long white dress fitted well, although I worried about keeping it clean. The one I finally bought is long and red. It is comfortable, and the colour looks especially good with the shoes I already own. The comparison became easier once the less important details were separated.","transcript_status":"source_word_comment","word_comment_ids":["50"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '16b717c2aff70a39d11f6ab6a80ff6fc8c23a26e63069a1137310981c0287189'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set004-q013-audio', 'Part 1 Question 52 Audio', 'Career adviser: With a mathematics degree, you could continue studying at college or train to become a teacher. Man: Teaching does not suit me because I am not very patient, and I do not want several more years of study. I have decided to work in business. I''m interested in financial analysis, where I can use numbers while also working with clients and colleagues. After making the decision, the remaining arrangements were straightforward.', '{"source_key":"listening-p1-set004-q013-audio","skill":"listening","part_number":1,"transcript":"Career adviser: With a mathematics degree, you could continue studying at college or train to become a teacher. Man: Teaching does not suit me because I am not very patient, and I do not want several more years of study. I have decided to work in business. I''m interested in financial analysis, where I can use numbers while also working with clients and colleagues. After making the decision, the remaining arrangements were straightforward.","transcript_status":"source_word_comment","word_comment_ids":["51"],"speaker_labels":["Career adviser"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'e3ed23c5f606f3e515153b4b8ac11ea25e52453c065ea70e4b91457f54eb646a'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set005-q001-audio', 'Part 1 Question 53 Audio', 'Anna: My old manager George was not as strict as some people remember, and it was never true that he disliked me. He expected high standards, but he also explained things clearly. What I value most is that he taught me a lot about work. He showed me how to speak to clients, organise my time and learn from mistakes without losing confidence. The other possibilities were useful to discuss but were not selected.', '{"source_key":"listening-p1-set005-q001-audio","skill":"listening","part_number":1,"transcript":"Anna: My old manager George was not as strict as some people remember, and it was never true that he disliked me. He expected high standards, but he also explained things clearly. What I value most is that he taught me a lot about work. He showed me how to speak to clients, organise my time and learn from mistakes without losing confidence. The other possibilities were useful to discuss but were not selected.","transcript_status":"source_word_comment","word_comment_ids":["52"],"speaker_labels":["Anna"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'e305caca2455593536500031b8ff6c37380a66f0ca902f0bb9355cc6d3629844'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set005-q002-audio', 'Part 1 Question 54 Audio', 'Linda: At lunchtime, many of my colleagues order coffee, and some prefer fruit juice. I nearly always have tea with my meal. It is lighter than coffee and helps me relax during a busy day. I usually make a large cup before sitting down to eat, then take the rest back to my desk if the lunch break ends early. That option matched the person''s needs more closely than the alternatives.', '{"source_key":"listening-p1-set005-q002-audio","skill":"listening","part_number":1,"transcript":"Linda: At lunchtime, many of my colleagues order coffee, and some prefer fruit juice. I nearly always have tea with my meal. It is lighter than coffee and helps me relax during a busy day. I usually make a large cup before sitting down to eat, then take the rest back to my desk if the lunch break ends early. That option matched the person''s needs more closely than the alternatives.","transcript_status":"source_word_comment","word_comment_ids":["53"],"speaker_labels":["Linda"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'cf6f2faf392d9fd2f6c3689ec2b408689d8e738ded103e51a1b8254c5b5a9ef8'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set005-q003-audio', 'Part 1 Question 55 Audio', 'Colleague 1: We need to meet about the new project. Sunday is usually , but I use it to prepare for the week. Saturday is impossible because I have a family event. Could we meet on Tuesday instead? Colleague 2: Tuesday works for me. I''ll reserve a small meeting room, and we can review the timetable before speaking to the rest of the team. The updated schedule suited the people involved better than either earlier suggestion.', '{"source_key":"listening-p1-set005-q003-audio","skill":"listening","part_number":1,"transcript":"Colleague 1: We need to meet about the new project. Sunday is usually , but I use it to prepare for the week. Saturday is impossible because I have a family event. Could we meet on Tuesday instead? Colleague 2: Tuesday works for me. I''ll reserve a small meeting room, and we can review the timetable before speaking to the rest of the team. The updated schedule suited the people involved better than either earlier suggestion.","transcript_status":"source_word_comment","word_comment_ids":["54"],"speaker_labels":["Colleague 1"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'b8336a495e6c39b72e612b8d1e08bdde84e86d44f62ca9194084babc615193e9'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set005-q004-audio', 'Part 1 Question 56 Audio', 'John: Hi, Professor Smith. I''m calling to confirm our assignment meeting. We discussed Tuesday morning, but you are teaching then. Thursday afternoon was another possibility, although I have a laboratory class. We agreed on Thursday morning at ten in your office. I''ll bring my outline and the sources I have found so far, and I''d especially like advice on the conclusion. The revised timing left enough room for travel and preparation beforehand.', '{"source_key":"listening-p1-set005-q004-audio","skill":"listening","part_number":1,"transcript":"John: Hi, Professor Smith. I''m calling to confirm our assignment meeting. We discussed Tuesday morning, but you are teaching then. Thursday afternoon was another possibility, although I have a laboratory class. We agreed on Thursday morning at ten in your office. I''ll bring my outline and the sources I have found so far, and I''d especially like advice on the conclusion. The revised timing left enough room for travel and preparation beforehand.","transcript_status":"source_word_comment","word_comment_ids":["55"],"speaker_labels":["John"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'f75a22f6342ac8850fbb897cdf07b289fe7bcd207c4ace9c98a32d302e2477ed'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set005-q005-audio', 'Part 1 Question 57 Audio', 'Catering announcement: Lunch was originally expected at 12:30, but one of the ovens stopped working. The kitchen hoped to finish by 1:15, although that is no longer realistic. Lunch will be ready at 2:00 p.m. Students may have fruit and drinks while they wait. Please remain in the main hall until staff announce that the dining area is open. Everyone agreed to confirm the smaller details by message later that day.', '{"source_key":"listening-p1-set005-q005-audio","skill":"listening","part_number":1,"transcript":"Catering announcement: Lunch was originally expected at 12:30, but one of the ovens stopped working. The kitchen hoped to finish by 1:15, although that is no longer realistic. Lunch will be ready at 2:00 p.m. Students may have fruit and drinks while they wait. Please remain in the main hall until staff announce that the dining area is open. Everyone agreed to confirm the smaller details by message later that day.","transcript_status":"source_word_comment","word_comment_ids":["56"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'd27a171b1816a0b19af6e7df4e46b73f0cb64d10fa2ba391b8ef0e4810162db7'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set005-q006-audio', 'Part 1 Question 58 Audio', 'Douglas: Hi, Kay. I''m not calling to ask for another favour, and we can arrange a meeting some other time. I mainly wanted to say thank you for helping with the project. Kay: Oh, it was no trouble at all! How did it go? Douglas: Your advice solved the problem with our final section, and the client was very pleased. Kay: That''s such a relief to hear! Douglas: When things are less busy, I''d like to buy you coffee and tell you the full story. Kay: I''d love that. Well done to you both!', '{"source_key":"listening-p1-set005-q006-audio","skill":"listening","part_number":1,"transcript":"Douglas: Hi, Kay. I''m not calling to ask for another favour, and we can arrange a meeting some other time. I mainly wanted to say thank you for helping with the project. Kay: Oh, it was no trouble at all! How did it go? Douglas: Your advice solved the problem with our final section, and the client was very pleased. Kay: That''s such a relief to hear! Douglas: When things are less busy, I''d like to buy you coffee and tell you the full story. Kay: I''d love that. Well done to you both!","transcript_status":"source_word_comment","word_comment_ids":["57"],"speaker_labels":["Douglas"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '161d0efe74668ee872c31ec497c378e9f382e04d929f63dd19dca2d0bf77270d'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set005-q007-audio', 'Part 1 Question 59 Audio', 'Woman: I''m meeting an old friend at a café this morning, so I''m going to have coffee with her. We may order lunch if we stay long enough, but tea is not part of today''s plan. We have not seen each other for months, and I want time for a proper conversation. Afterwards, I need to collect a parcel and do some shopping. The practical details made that option more suitable than either earlier suggestion.', '{"source_key":"listening-p1-set005-q007-audio","skill":"listening","part_number":1,"transcript":"Woman: I''m meeting an old friend at a café this morning, so I''m going to have coffee with her. We may order lunch if we stay long enough, but tea is not part of today''s plan. We have not seen each other for months, and I want time for a proper conversation. Afterwards, I need to collect a parcel and do some shopping. The practical details made that option more suitable than either earlier suggestion.","transcript_status":"source_word_comment","word_comment_ids":["58"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '14876f246691e26e018f459dedc98550c70f8f586ce53d82a43e64278e81f98d'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set005-q008-audio', 'Part 1 Question 60 Audio', 'Linda: People say my mother and I have a similar appearance, and our personalities are alike in some ways. What we really have in common is our interests. We both enjoy reading, gardening and visiting small exhibitions. Our taste in music is different, but we can talk for hours about books or spend an entire afternoon choosing plants for the garden. After making the decision, the remaining arrangements were straightforward.', '{"source_key":"listening-p1-set005-q008-audio","skill":"listening","part_number":1,"transcript":"Linda: People say my mother and I have a similar appearance, and our personalities are alike in some ways. What we really have in common is our interests. We both enjoy reading, gardening and visiting small exhibitions. Our taste in music is different, but we can talk for hours about books or spend an entire afternoon choosing plants for the garden. After making the decision, the remaining arrangements were straightforward.","transcript_status":"source_word_comment","word_comment_ids":["59"],"speaker_labels":["Linda"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'b850fc2118eea2ea0482908e0592124474ca590d89b66d5585ae10407b9735ef'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set005-q009-audio', 'Part 1 Question 61 Audio', 'Radio speaker: Every morning, I take a bus from my village to the edge of the city, then change to a crowded train. The whole journey takes over an hour, so I listen to music or read on the way. I''m not describing a weekend plan or a favourite hobby; I''m talking about my journey to work and how I manage the daily travel. The other possibilities were useful to discuss but were not selected.', '{"source_key":"listening-p1-set005-q009-audio","skill":"listening","part_number":1,"transcript":"Radio speaker: Every morning, I take a bus from my village to the edge of the city, then change to a crowded train. The whole journey takes over an hour, so I listen to music or read on the way. I''m not describing a weekend plan or a favourite hobby; I''m talking about my journey to work and how I manage the daily travel. The other possibilities were useful to discuss but were not selected.","transcript_status":"source_word_comment","word_comment_ids":["60"],"speaker_labels":["Radio speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'cce7a96fc40099cb6262689b0bbcf73e5dcf832d77d2056508d1a66a88ff63e7'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set005-q010-audio', 'Part 1 Question 62 Audio', 'Woman: Walk straight ahead until you reach the square. The museum is in front of it, and there is a small car park behind it, but neither is the library. The library is on the left of the square, beside a flower shop. It is a large stone building with wide steps, so you should recognise it easily once you reach the centre. Anyone following the directions carefully should reach the correct place without difficulty.', '{"source_key":"listening-p1-set005-q010-audio","skill":"listening","part_number":1,"transcript":"Woman: Walk straight ahead until you reach the square. The museum is in front of it, and there is a small car park behind it, but neither is the library. The library is on the left of the square, beside a flower shop. It is a large stone building with wide steps, so you should recognise it easily once you reach the centre. Anyone following the directions carefully should reach the correct place without difficulty.","transcript_status":"source_word_comment","word_comment_ids":["61"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'a7fb8a9ca18bb055c103f696c6ffed1e9848bb871615ba6bf2dfdb7e70a028ea'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set005-q011-audio', 'Part 1 Question 63 Audio', 'Woman: I considered travelling east because the coastal towns look interesting, and the north would be perfect for a winter trip. This time, however, I''m going to the south, where I plan to spend several days in the mountains. I have booked a small hotel near a hiking route and hope the weather will be clear enough for long walks. The final location also allowed the group to continue the journey together.', '{"source_key":"listening-p1-set005-q011-audio","skill":"listening","part_number":1,"transcript":"Woman: I considered travelling east because the coastal towns look interesting, and the north would be perfect for a winter trip. This time, however, I''m going to the south, where I plan to spend several days in the mountains. I have booked a small hotel near a hiking route and hope the weather will be clear enough for long walks. The final location also allowed the group to continue the journey together.","transcript_status":"source_word_comment","word_comment_ids":["62"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '6a63e8d1ee3a723afbdc7ecd8826650c1cf292b0657a0b0fa07f3a7d1201af95'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set005-q012-audio', 'Part 1 Question 64 Audio', 'Tour representative: The bus cannot wait behind the hotel because delivery vehicles use that space. The side entrance is also too narrow for a large coach. We will wait by the hotel''s main entrance, where the driver can see the entire group. Please be there ten minutes early, keep your luggage beside you and tell the guide if anyone is missing. A clear landmark nearby makes the correct place easy to recognise on arrival.', '{"source_key":"listening-p1-set005-q012-audio","skill":"listening","part_number":1,"transcript":"Tour representative: The bus cannot wait behind the hotel because delivery vehicles use that space. The side entrance is also too narrow for a large coach. We will wait by the hotel''s main entrance, where the driver can see the entire group. Please be there ten minutes early, keep your luggage beside you and tell the guide if anyone is missing. A clear landmark nearby makes the correct place easy to recognise on arrival.","transcript_status":"source_word_comment","word_comment_ids":["63"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '77b7dec12e89766cb13c91f2d76985486dd13949aa7db62f43d04438739c7469'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set005-q013-audio', 'Part 1 Question 65 Audio', 'Woman: Buying in bulk can reduce the price of some products, and putting money into a bank account is useful for long-term savings. My most practical daily advice is to use public transport instead of driving. Bus or train fares are usually lower than petrol, parking and car maintenance. Try it for a month and keep a record of how much you save. It also left enough time and energy for the rest of the day.', '{"source_key":"listening-p1-set005-q013-audio","skill":"listening","part_number":1,"transcript":"Woman: Buying in bulk can reduce the price of some products, and putting money into a bank account is useful for long-term savings. My most practical daily advice is to use public transport instead of driving. Bus or train fares are usually lower than petrol, parking and car maintenance. Try it for a month and keep a record of how much you save. It also left enough time and energy for the rest of the day.","transcript_status":"source_word_comment","word_comment_ids":["64"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '90a75c91977cb684745b71c84e2385f8548739f49592cbf92796f3f052e64191'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set006-q001-audio', 'Part 1 Question 66 Audio', 'Lalia: I''m planning my trip into the city tomorrow. Someone told me the bus fare was three pounds, while another person said four pounds fifty because that included a return ticket. I think a single journey will cost two pounds fifty. I''ll take a little extra money in case the price has changed, but it still seems cheaper than using a taxi. The final record was saved so the same confusion would not happen again.', '{"source_key":"listening-p1-set006-q001-audio","skill":"listening","part_number":1,"transcript":"Lalia: I''m planning my trip into the city tomorrow. Someone told me the bus fare was three pounds, while another person said four pounds fifty because that included a return ticket. I think a single journey will cost two pounds fifty. I''ll take a little extra money in case the price has changed, but it still seems cheaper than using a taxi. The final record was saved so the same confusion would not happen again.","transcript_status":"source_word_comment","word_comment_ids":["65"],"speaker_labels":["Lalia"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '6aa3b3ca99a6855fbf14acb7f33452c335eb5b5e206d7b0af6d04e29163c0781'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set006-q002-audio', 'Part 1 Question 67 Audio', 'Friend: So, are you still planning to move abroad for work? Man: Yes, I have already found a possible job there, and I am gradually saving enough money for the move. Friend: That sounds exciting. Is everything falling into place? Man: Most things, yes. My main problem is persuading my family. They are worried about the distance and think I will be lonely. Friend: I can understand that. Have you talked to them about it? Man: I have tried to explain the career benefits and promised to visit regularly, but they still want me to stay close to home.', '{"source_key":"listening-p1-set006-q002-audio","skill":"listening","part_number":1,"transcript":"Friend: So, are you still planning to move abroad for work? Man: Yes, I have already found a possible job there, and I am gradually saving enough money for the move. Friend: That sounds exciting. Is everything falling into place? Man: Most things, yes. My main problem is persuading my family. They are worried about the distance and think I will be lonely. Friend: I can understand that. Have you talked to them about it? Man: I have tried to explain the career benefits and promised to visit regularly, but they still want me to stay close to home.","transcript_status":"source_word_comment","word_comment_ids":["66"],"speaker_labels":["Friend"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '119aee0beedb6c4a916dbf45701a6c7095712d17aaf5ade4a8b45b237d3c4af1'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set006-q003-audio', 'Part 1 Question 68 Audio', 'Woman: I usually relax at home in the afternoon, and I considered visiting the museum if the weather was bad. Today I''m going on a city tour instead. I''ve lived here for years but have never seen many of the historic buildings. The tour begins near the town hall and ends at the riverside market, where I plan to have dinner. After making the decision, the remaining arrangements were straightforward.', '{"source_key":"listening-p1-set006-q003-audio","skill":"listening","part_number":1,"transcript":"Woman: I usually relax at home in the afternoon, and I considered visiting the museum if the weather was bad. Today I''m going on a city tour instead. I''ve lived here for years but have never seen many of the historic buildings. The tour begins near the town hall and ends at the riverside market, where I plan to have dinner. After making the decision, the remaining arrangements were straightforward.","transcript_status":"source_word_comment","word_comment_ids":["67"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '3149fabc744eac5130fda2d94fe0dd855821ffb5ea7e773608d55e5b7cf7f4c9'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set006-q004-audio', 'Part 1 Question 69 Audio', 'Nate: I spent a week in Thailand before arriving in India, and I''m giving myself three days to see the Taj Mahal and the surrounding area. My total stay in India will be two weeks. After visiting Agra, I''m travelling north by train and then spending several days with friends before I fly home at the end of the month. The remaining activities could continue normally once the correct time was clear.', '{"source_key":"listening-p1-set006-q004-audio","skill":"listening","part_number":1,"transcript":"Nate: I spent a week in Thailand before arriving in India, and I''m giving myself three days to see the Taj Mahal and the surrounding area. My total stay in India will be two weeks. After visiting Agra, I''m travelling north by train and then spending several days with friends before I fly home at the end of the month. The remaining activities could continue normally once the correct time was clear.","transcript_status":"source_word_comment","word_comment_ids":["68"],"speaker_labels":["Nate"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '6a5d05925335b820fa65649410f6e72edfcbfd7e598077b4acb735609fda8c7c'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set006-q005-audio', 'Part 1 Question 70 Audio', 'Man: I liked the film''s music, but I thought the characters were rather predictable. Woman: I disagree; the characters felt believable, although the music was too loud for me. Man: At least we both enjoyed the ending. Woman: Yes, the final scene was surprising and brought the story together well. We clearly agree on that, even if our opinions differ about almost everything else. The most important feature appeared before the speaker moved on to other information.', '{"source_key":"listening-p1-set006-q005-audio","skill":"listening","part_number":1,"transcript":"Man: I liked the film''s music, but I thought the characters were rather predictable. Woman: I disagree; the characters felt believable, although the music was too loud for me. Man: At least we both enjoyed the ending. Woman: Yes, the final scene was surprising and brought the story together well. We clearly agree on that, even if our opinions differ about almost everything else. The most important feature appeared before the speaker moved on to other information.","transcript_status":"source_word_comment","word_comment_ids":["69"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '1ffa47522cf90a2f2d7238362b39a65061b86409f5d2b94b22ee34a56bd5a504'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set006-q006-audio', 'Part 1 Question 71 Audio', 'Clinic message: This is the doctor''s office calling about your appointment. Friday the 14th is no longer available because the clinic will be closed, and Thursday the 30th belongs to another patient''s booking. Your new appointment is on Thursday the 13th at 10:30. Please call us if that date is impossible, and bring your previous test results when you come. The updated schedule suited the people involved better than either earlier suggestion.', '{"source_key":"listening-p1-set006-q006-audio","skill":"listening","part_number":1,"transcript":"Clinic message: This is the doctor''s office calling about your appointment. Friday the 14th is no longer available because the clinic will be closed, and Thursday the 30th belongs to another patient''s booking. Your new appointment is on Thursday the 13th at 10:30. Please call us if that date is impossible, and bring your previous test results when you come. The updated schedule suited the people involved better than either earlier suggestion.","transcript_status":"source_word_comment","word_comment_ids":["70"],"speaker_labels":["Clinic message"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '57294b2eb0bb6587299eed06d3407b968ae04dd2a1cb7978f246a7711d976b84'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set006-q007-audio', 'Part 1 Question 72 Audio', 'Max: Hi, I''m calling about the computer you are selling. Is it still available? Friend: Yes, it is! What offer were you thinking? Max: I could offer 150 pounds for an older machine, but 350 is beyond my budget. I can pay 250 pounds for yours if the keyboard, screen and charger are all working. Friend: They are all in good condition, I promise. Max: Great. I would also like to test it briefly before I decide. Friend: Of course, no problem. Max: If everything is fine, I can collect it on Saturday morning. Friend: Saturday works perfectly. See you then.', '{"source_key":"listening-p1-set006-q007-audio","skill":"listening","part_number":1,"transcript":"Max: Hi, I''m calling about the computer you are selling. Is it still available? Friend: Yes, it is! What offer were you thinking? Max: I could offer 150 pounds for an older machine, but 350 is beyond my budget. I can pay 250 pounds for yours if the keyboard, screen and charger are all working. Friend: They are all in good condition, I promise. Max: Great. I would also like to test it briefly before I decide. Friend: Of course, no problem. Max: If everything is fine, I can collect it on Saturday morning. Friend: Saturday works perfectly. See you then.","transcript_status":"source_word_comment","word_comment_ids":["71"],"speaker_labels":["Max"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'a82464f9c5f683342652ada5cd0f64a6ed0f66845e7315650508c5bc938bbc09'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set006-q008-audio', 'Part 1 Question 73 Audio', 'Aman: Could I have a drink, please? I first thought about beer, but it is a little early in the day. Water would be sensible, although I want something with more flavour. I''ll have an iced tea. It sounds refreshing in this warm weather. Please serve it without too much sugar, and could I also have a glass of water on the side? It also left enough time and energy for the rest of the day.', '{"source_key":"listening-p1-set006-q008-audio","skill":"listening","part_number":1,"transcript":"Aman: Could I have a drink, please? I first thought about beer, but it is a little early in the day. Water would be sensible, although I want something with more flavour. I''ll have an iced tea. It sounds refreshing in this warm weather. Please serve it without too much sugar, and could I also have a glass of water on the side? It also left enough time and energy for the rest of the day.","transcript_status":"source_word_comment","word_comment_ids":["72"],"speaker_labels":["Aman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'fb5ef4f035f76f5bd583f7eaacd02324a5f8b4e07cf68eb1ddd319eeb8b4c55d'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set006-q009-audio', 'Part 1 Question 74 Audio', 'Mary: I''ve moved into my new house and still need several pieces of furniture. I already know which mirror I want for the living room, but I cannot find a suitable table for the dining area. Do you know where I can buy a new table? I''m looking for something simple, not too expensive, and large enough for six people. The alternatives remained possible on another occasion, but not this time.', '{"source_key":"listening-p1-set006-q009-audio","skill":"listening","part_number":1,"transcript":"Mary: I''ve moved into my new house and still need several pieces of furniture. I already know which mirror I want for the living room, but I cannot find a suitable table for the dining area. Do you know where I can buy a new table? I''m looking for something simple, not too expensive, and large enough for six people. The alternatives remained possible on another occasion, but not this time.","transcript_status":"source_word_comment","word_comment_ids":["73"],"speaker_labels":["Mary"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'e73997c8cb2e78da2c148bbc9e1350c1cf591898b24c0ca7d0162f0ce286787e'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set006-q010-audio', 'Part 1 Question 75 Audio', 'Man: What drinks do you recommend? Waiter: We have milk tea, hot tea and iced tea. Man: Milk tea sounds too sweet, and I do not want a hot drink in this weather. I''ll choose the iced tea. Please bring it with lemon and very little sugar. I''ll decide what to eat after I have looked at the menu for a few more minutes. The practical details made that option more suitable than either earlier suggestion.', '{"source_key":"listening-p1-set006-q010-audio","skill":"listening","part_number":1,"transcript":"Man: What drinks do you recommend? Waiter: We have milk tea, hot tea and iced tea. Man: Milk tea sounds too sweet, and I do not want a hot drink in this weather. I''ll choose the iced tea. Please bring it with lemon and very little sugar. I''ll decide what to eat after I have looked at the menu for a few more minutes. The practical details made that option more suitable than either earlier suggestion.","transcript_status":"source_word_comment","word_comment_ids":["74"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '850d7ef659b203ea01a219553ff2306ec381ee6b5ebe55cb2eab65f34a3f9ea7'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set006-q011-audio', 'Part 1 Question 76 Audio', 'Louis: Shall we meet at the café inside the station? Standar: It is usually packed before the evening trains. Louis: The benches near the ticket counter may be noisy as well. Let''s meet outside the station beside the taxi sign. Standar: Good idea. That will be easier to find, and we can go inside together once everyone has arrived. The chosen place was more convenient and easier for everyone to find.', '{"source_key":"listening-p1-set006-q011-audio","skill":"listening","part_number":1,"transcript":"Louis: Shall we meet at the café inside the station? Standar: It is usually packed before the evening trains. Louis: The benches near the ticket counter may be noisy as well. Let''s meet outside the station beside the taxi sign. Standar: Good idea. That will be easier to find, and we can go inside together once everyone has arrived. The chosen place was more convenient and easier for everyone to find.","transcript_status":"source_word_comment","word_comment_ids":["75"],"speaker_labels":["Louis"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '54afb0da03ab9efa50746d61e575bde60d898bd7ae08d59ddc8a0b548d2c3a83'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set006-q012-audio', 'Part 1 Question 77 Audio', 'Jane: Martha, are we still meeting at four? I''ve been asked to stay at work longer, so I cannot arrive that early. Six o''clock is possible, but it would leave us very little time before the shops close. Could we meet at half past five? Martha: That suits me. I''ll wait outside the bookshop and call if I cannot see you. The remaining activities could continue normally once the correct time was clear.', '{"source_key":"listening-p1-set006-q012-audio","skill":"listening","part_number":1,"transcript":"Jane: Martha, are we still meeting at four? I''ve been asked to stay at work longer, so I cannot arrive that early. Six o''clock is possible, but it would leave us very little time before the shops close. Could we meet at half past five? Martha: That suits me. I''ll wait outside the bookshop and call if I cannot see you. The remaining activities could continue normally once the correct time was clear.","transcript_status":"source_word_comment","word_comment_ids":["76"],"speaker_labels":["Jane"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '82b81388050a802fee1717950fcb506325388d47376c4bc7c702e15c88729832'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set006-q013-audio', 'Part 1 Question 78 Audio', 'Woman: I went shopping for something to wear on my trip. I considered a blouse, but the sleeves were uncomfortable, and I decided I could borrow a hat from a friend. I bought a dress instead because it fitted me perfectly and would work for both dinner and sightseeing. I chose a light material so it will be easy to pack without becoming badly creased.', '{"source_key":"listening-p1-set006-q013-audio","skill":"listening","part_number":1,"transcript":"Woman: I went shopping for something to wear on my trip. I considered a blouse, but the sleeves were uncomfortable, and I decided I could borrow a hat from a friend. I bought a dress instead because it fitted me perfectly and would work for both dinner and sightseeing. I chose a light material so it will be easy to pack without becoming badly creased.","transcript_status":"source_word_comment","word_comment_ids":["77"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '2888b7988fa79d1b3e9fa9ffd48b5acdd3d7b95addadf9d692a722e61dc46ed2'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set007-q001-audio', 'Part 1 Question 79 Audio', 'Woman: Our babysitter is a responsible college student. One neighbour thought she was twenty, and another guessed twenty-two because she seems very confident. She is actually twenty-one years old. She has looked after our child for nearly a year, helps with homework and always follows our instructions. We feel comfortable leaving the house because she knows exactly what to do in an emergency. The final comments added context without changing the main description.', '{"source_key":"listening-p1-set007-q001-audio","skill":"listening","part_number":1,"transcript":"Woman: Our babysitter is a responsible college student. One neighbour thought she was twenty, and another guessed twenty-two because she seems very confident. She is actually twenty-one years old. She has looked after our child for nearly a year, helps with homework and always follows our instructions. We feel comfortable leaving the house because she knows exactly what to do in an emergency. The final comments added context without changing the main description.","transcript_status":"source_word_comment","word_comment_ids":["78"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '9b4af52739f36ff56f7ce4d3aa9390257018a0d2ea5831da472c920521b507d6'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set007-q002-audio', 'Part 1 Question 80 Audio', 'Man: After university, I applied to several large companies and even considered staying at the university as a research assistant. I am working in a bank now. The job is busy, but I enjoy dealing with clients and learning how different businesses manage money. The salary is good, and the office is close enough for me to travel there by bus. A clear landmark nearby makes the correct place easy to recognise on arrival.', '{"source_key":"listening-p1-set007-q002-audio","skill":"listening","part_number":1,"transcript":"Man: After university, I applied to several large companies and even considered staying at the university as a research assistant. I am working in a bank now. The job is busy, but I enjoy dealing with clients and learning how different businesses manage money. The salary is good, and the office is close enough for me to travel there by bus. A clear landmark nearby makes the correct place easy to recognise on arrival.","transcript_status":"source_word_comment","word_comment_ids":["79"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '9d36c355d0c4d73bf1ee91f30bcfc5ac743b689179af03ceee8eff90eef65717'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set007-q003-audio', 'Part 1 Question 81 Audio', 'Man: When I came home, I could not find my key. I searched the car and then looked throughout the bedroom, but it was not in either place. Eventually, I found it in the front-door lock, where I had left it without noticing. I was lucky nobody had taken it. I now keep a spare key with a neighbour in case the same thing happens again.', '{"source_key":"listening-p1-set007-q003-audio","skill":"listening","part_number":1,"transcript":"Man: When I came home, I could not find my key. I searched the car and then looked throughout the bedroom, but it was not in either place. Eventually, I found it in the front-door lock, where I had left it without noticing. I was lucky nobody had taken it. I now keep a spare key with a neighbour in case the same thing happens again.","transcript_status":"source_word_comment","word_comment_ids":["80"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '0f442fd3f4b1c75dc6b186564386c8d671cb05779c03cfcc8f43c4abee858c40'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set007-q004-audio', 'Part 1 Question 82 Audio', 'Man: Hi, Mum. I''m stuck in traffic, but it is beginning to move. I first thought I would be fifteen minutes late, and twenty minutes was the worst estimate from the travel app. I should arrive only ten minutes late now. Please do not wait to start dinner. I''ll come straight home as soon as the road ahead is clear. Nobody else needed to change their plans after the updated time was agreed.', '{"source_key":"listening-p1-set007-q004-audio","skill":"listening","part_number":1,"transcript":"Man: Hi, Mum. I''m stuck in traffic, but it is beginning to move. I first thought I would be fifteen minutes late, and twenty minutes was the worst estimate from the travel app. I should arrive only ten minutes late now. Please do not wait to start dinner. I''ll come straight home as soon as the road ahead is clear. Nobody else needed to change their plans after the updated time was agreed.","transcript_status":"source_word_comment","word_comment_ids":["81"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'ef513e7d14d71b271918628a9a5180005d825a652808e990c8badd164a3d17aa'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set007-q005-audio', 'Part 1 Question 83 Audio', 'Woman: The cinema listing is a little confusing. Seven o''clock is when the main advertisements were expected to end, and 9:20 is the approximate time the film finishes. The movie itself begins at 6:40. We should arrive by half past six to collect the tickets and buy something to drink. Afterwards, we can have dinner at the new restaurant nearby. The new arrangement also avoided a rushed journey at the busiest part of the day.', '{"source_key":"listening-p1-set007-q005-audio","skill":"listening","part_number":1,"transcript":"Woman: The cinema listing is a little confusing. Seven o''clock is when the main advertisements were expected to end, and 9:20 is the approximate time the film finishes. The movie itself begins at 6:40. We should arrive by half past six to collect the tickets and buy something to drink. Afterwards, we can have dinner at the new restaurant nearby. The new arrangement also avoided a rushed journey at the busiest part of the day.","transcript_status":"source_word_comment","word_comment_ids":["82"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'e79adfef8822c34e4437a171ba2bd9385d5b70c863364332b29bb6bdb8c3d8ca'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set007-q006-audio', 'Part 1 Question 84 Audio', 'Man: I''ve finished my classes, so shall we meet at school? Friend: I am already on the other side of town. Man: We could use the café, but we go there all the time. Let''s meet by the park instead, near the small bridge. Friend: Fine. I''ll bring a jacket in case it gets cold, and we can decide where to go next. The chosen place was more convenient and easier for everyone to find.', '{"source_key":"listening-p1-set007-q006-audio","skill":"listening","part_number":1,"transcript":"Man: I''ve finished my classes, so shall we meet at school? Friend: I am already on the other side of town. Man: We could use the café, but we go there all the time. Let''s meet by the park instead, near the small bridge. Friend: Fine. I''ll bring a jacket in case it gets cold, and we can decide where to go next. The chosen place was more convenient and easier for everyone to find.","transcript_status":"source_word_comment","word_comment_ids":["83"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '8761763e531d2b4bb61788ea91f09aa7bcb9df04843969c01f00cadfb5ac6fa2'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set007-q007-audio', 'Part 1 Question 85 Audio', 'Man: To reach the university, go straight along Main Street. At the hospital, turn left rather than right and continue until you see a supermarket. When you reach the traffic lights, turn right. The campus entrance will be a short distance ahead on the left. If you pass the sports centre, you have gone too far and should turn back. The nearby landmarks were useful, although neither was the destination itself.', '{"source_key":"listening-p1-set007-q007-audio","skill":"listening","part_number":1,"transcript":"Man: To reach the university, go straight along Main Street. At the hospital, turn left rather than right and continue until you see a supermarket. When you reach the traffic lights, turn right. The campus entrance will be a short distance ahead on the left. If you pass the sports centre, you have gone too far and should turn back. The nearby landmarks were useful, although neither was the destination itself.","transcript_status":"source_word_comment","word_comment_ids":["84"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'fe4477de0136b15f5129a863f7e5873e7bf1bf8957da34f1b1e584c39a34f18c'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set007-q008-audio', 'Part 1 Question 86 Audio', 'Saleswoman: We have a basic computer for 135 pounds, a faster model for 145 and another with extra storage for 155. The cheapest computer in the shop is the 135-pound model. It is suitable for email, documents and simple internet use, although it is not powerful enough for modern games. You can try all three before deciding which one best meets your needs. The figures became clear once the different products or categories were separated.', '{"source_key":"listening-p1-set007-q008-audio","skill":"listening","part_number":1,"transcript":"Saleswoman: We have a basic computer for 135 pounds, a faster model for 145 and another with extra storage for 155. The cheapest computer in the shop is the 135-pound model. It is suitable for email, documents and simple internet use, although it is not powerful enough for modern games. You can try all three before deciding which one best meets your needs. The figures became clear once the different products or categories were separated.","transcript_status":"source_word_comment","word_comment_ids":["85"],"speaker_labels":["Saleswoman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '0f4bfed37f150b6a3beab0048c2cb56a1c48b1ba50d70070c8bbdce9f34ece0f'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set007-q009-audio', 'Part 1 Question 87 Audio', 'Tour guide: This building has had several very different uses. It opened as a museum in the 1920s and later became a cinema after the war. Today, it is a department store with shops on five floors. The exterior has changed very little, although the inside was completely redesigned. Look above the entrance and you can still see the original museum name carved into the stone.', '{"source_key":"listening-p1-set007-q009-audio","skill":"listening","part_number":1,"transcript":"Tour guide: This building has had several very different uses. It opened as a museum in the 1920s and later became a cinema after the war. Today, it is a department store with shops on five floors. The exterior has changed very little, although the inside was completely redesigned. Look above the entrance and you can still see the original museum name carved into the stone.","transcript_status":"source_word_comment","word_comment_ids":["86"],"speaker_labels":["Tour guide"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '58ee122f31e66a2c993a60335e12412a271df5ef8bc3b6b56c0ae85dc38c5650'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set007-q010-audio', 'Part 1 Question 88 Audio', 'Interviewer: Your application mentions engineering and teaching. Which was your most recent job? David: I studied engineering but did not work as an engineer, and I only helped at a school briefly. My last full-time job was as an electrician. I installed lighting and repaired electrical systems in homes and offices. I left because I wanted a position with more responsibility and regular training. The choice fitted the situation better than the other ideas they had discussed.', '{"source_key":"listening-p1-set007-q010-audio","skill":"listening","part_number":1,"transcript":"Interviewer: Your application mentions engineering and teaching. Which was your most recent job? David: I studied engineering but did not work as an engineer, and I only helped at a school briefly. My last full-time job was as an electrician. I installed lighting and repaired electrical systems in homes and offices. I left because I wanted a position with more responsibility and regular training. The choice fitted the situation better than the other ideas they had discussed.","transcript_status":"source_word_comment","word_comment_ids":["87"],"speaker_labels":["Interviewer"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'b5de9604c5cccaf8a7eb607152cba270f213d53a6c9ad14d51c0909ba0c0b49b'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set007-q011-audio', 'Part 1 Question 89 Audio', 'Man: Some people become doctors because the salary can be high, and my family would certainly be proud of me. My main reason is that I want to help people. I like the idea of solving practical problems and supporting patients when they are worried or in pain. I know the training is long, but the work feels meaningful enough to justify the effort. The other explanations sounded possible at first but did not match the evidence.', '{"source_key":"listening-p1-set007-q011-audio","skill":"listening","part_number":1,"transcript":"Man: Some people become doctors because the salary can be high, and my family would certainly be proud of me. My main reason is that I want to help people. I like the idea of solving practical problems and supporting patients when they are worried or in pain. I know the training is long, but the work feels meaningful enough to justify the effort. The other explanations sounded possible at first but did not match the evidence.","transcript_status":"source_word_comment","word_comment_ids":["88"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '7a389679992a87c4942e6182369e040ec01c0cb7f3ec2c96e1546c04325d0fed'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set007-q012-audio', 'Part 1 Question 90 Audio', 'Woman: Officer, I need to report a missing bag. My necklace is still around my neck, and I found my wallet in my coat pocket. The bag disappeared while I was waiting for a bus near the shopping centre. It is medium-sized and grey, with a red strap. My laptop and several work documents are inside, so I need to recover it as soon as possible.', '{"source_key":"listening-p1-set007-q012-audio","skill":"listening","part_number":1,"transcript":"Woman: Officer, I need to report a missing bag. My necklace is still around my neck, and I found my wallet in my coat pocket. The bag disappeared while I was waiting for a bus near the shopping centre. It is medium-sized and grey, with a red strap. My laptop and several work documents are inside, so I need to recover it as soon as possible.","transcript_status":"source_word_comment","word_comment_ids":["89"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '5997826472edba22c7346952adf4d21adce2d5b00c56452f8db390123bd420da'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set007-q013-audio', 'Part 1 Question 91 Audio', 'Friend: Which teacher do you like most, Tom? Tom: Miss Taylor explains science clearly, and Mr Styles makes history lessons entertaining. My favourite teacher is Miss Brown. Friend: What makes her stand out? Tom: She teaches English and always encourages us to express our own ideas rather than memorising answers. She is new to the school, but her lessons are already the ones I look forward to most. She also gives useful feedback without making students feel embarrassed.', '{"source_key":"listening-p1-set007-q013-audio","skill":"listening","part_number":1,"transcript":"Friend: Which teacher do you like most, Tom? Tom: Miss Taylor explains science clearly, and Mr Styles makes history lessons entertaining. My favourite teacher is Miss Brown. Friend: What makes her stand out? Tom: She teaches English and always encourages us to express our own ideas rather than memorising answers. She is new to the school, but her lessons are already the ones I look forward to most. She also gives useful feedback without making students feel embarrassed.","transcript_status":"source_word_comment","word_comment_ids":["90"],"speaker_labels":["Friend"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '3efa7d93382307414be4c5db9b54bde83e41a339e633160d2ebb8033c310f8f0'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set008-q001-audio', 'Part 1 Question 92 Audio', 'Woman: I''d like to return this dress, please. The colour is exactly what I wanted, and I actually like the pattern. The problem is the size. It felt comfortable in the shop, but at home I realised it was too tight around the shoulders. Could I exchange it for the same dress in a larger size rather than receive a refund? Understanding the real cause made it easier to decide what to do next.', '{"source_key":"listening-p1-set008-q001-audio","skill":"listening","part_number":1,"transcript":"Woman: I''d like to return this dress, please. The colour is exactly what I wanted, and I actually like the pattern. The problem is the size. It felt comfortable in the shop, but at home I realised it was too tight around the shoulders. Could I exchange it for the same dress in a larger size rather than receive a refund? Understanding the real cause made it easier to decide what to do next.","transcript_status":"source_word_comment","word_comment_ids":["91"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '460011a67ba344db1309de56de98614744ad12701ef6b74b32aa66754da91e32'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set008-q002-audio', 'Part 1 Question 93 Audio', 'Louis: The restaurant looks attractive, and the food is genuinely delicious. The prices are not especially cheap, though. My main complaint is that the service is slow. We waited twenty minutes before anyone took our order and another long time for the bill. The staff were polite and apologised, but the delays made the whole meal less enjoyable than it should have been. People focusing only on the first detail could easily misunderstand the speaker.', '{"source_key":"listening-p1-set008-q002-audio","skill":"listening","part_number":1,"transcript":"Louis: The restaurant looks attractive, and the food is genuinely delicious. The prices are not especially cheap, though. My main complaint is that the service is slow. We waited twenty minutes before anyone took our order and another long time for the bill. The staff were polite and apologised, but the delays made the whole meal less enjoyable than it should have been. People focusing only on the first detail could easily misunderstand the speaker.","transcript_status":"source_word_comment","word_comment_ids":["92"],"speaker_labels":["Louis"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '6ba171ceae2a3f96af561c593c3e3a7ec2987258e3c3447efef97fd3673f1249'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set008-q003-audio', 'Part 1 Question 94 Audio', 'Teacher: We are not at school today, and the building is certainly not a museum. The students are inside a townhouse that has been preserved as part of the local history project. We are examining how families lived there a century ago. Please stay with your group, do not touch the furniture and meet me again in the entrance hall at twelve. Anyone following the directions carefully should reach the correct place without difficulty.', '{"source_key":"listening-p1-set008-q003-audio","skill":"listening","part_number":1,"transcript":"Teacher: We are not at school today, and the building is certainly not a museum. The students are inside a townhouse that has been preserved as part of the local history project. We are examining how families lived there a century ago. Please stay with your group, do not touch the furniture and meet me again in the entrance hall at twelve. Anyone following the directions carefully should reach the correct place without difficulty.","transcript_status":"source_word_comment","word_comment_ids":["93"],"speaker_labels":["Teacher"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'f466414d3b9118cdf5db91b7ce9dfe3e950e9c7c69a2ebf40a4988c6cac4884d'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set008-q004-audio', 'Part 1 Question 95 Audio', 'Friend 1: Are we meeting at eight this evening? Friend 2: No, that was only a suggestion after my class. Seven was also discussed, but it would be a little late for dinner. We agreed on 6:30 p.m. Friend 1: Right, I remember now. I''ll book a table for to seven and wait outside if I arrive before you. The updated schedule suited the people involved better than either earlier suggestion.', '{"source_key":"listening-p1-set008-q004-audio","skill":"listening","part_number":1,"transcript":"Friend 1: Are we meeting at eight this evening? Friend 2: No, that was only a suggestion after my class. Seven was also discussed, but it would be a little late for dinner. We agreed on 6:30 p.m. Friend 1: Right, I remember now. I''ll book a table for to seven and wait outside if I arrive before you. The updated schedule suited the people involved better than either earlier suggestion.","transcript_status":"source_word_comment","word_comment_ids":["94"],"speaker_labels":["Friend 1"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '9cdf9911c436901ebc51ac7dd8b573d221d4bb1f34d487bb0a8332c80223dfb8'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set008-q005-audio', 'Part 1 Question 96 Audio', 'Woman: I used to shop at a department store in the centre, and the local market is useful for food. These days, I go to the new shopping mall that opened near the station. It has a wider range of clothes and several cafés, and the buses stop directly outside. I usually spend less time travelling between different shops because everything is in one place.', '{"source_key":"listening-p1-set008-q005-audio","skill":"listening","part_number":1,"transcript":"Woman: I used to shop at a department store in the centre, and the local market is useful for food. These days, I go to the new shopping mall that opened near the station. It has a wider range of clothes and several cafés, and the buses stop directly outside. I usually spend less time travelling between different shops because everything is in one place.","transcript_status":"source_word_comment","word_comment_ids":["95"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '5c53c8bb92028009e9b57e68e629ba86e4058e3e717051f097c330a02affb410'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set008-q006-audio', 'Part 1 Question 97 Audio', 'Woman: Watching a film at home is relaxing, and I play sports occasionally when friends invite me. My favourite thing to do in my spare time is go to the theatre. I love seeing a live performance and noticing how the audience reacts. Afterwards, I usually read reviews or discuss the play with whoever came with me over a drink. The other features were noticeable but were less important in the description.', '{"source_key":"listening-p1-set008-q006-audio","skill":"listening","part_number":1,"transcript":"Woman: Watching a film at home is relaxing, and I play sports occasionally when friends invite me. My favourite thing to do in my spare time is go to the theatre. I love seeing a live performance and noticing how the audience reacts. Afterwards, I usually read reviews or discuss the play with whoever came with me over a drink. The other features were noticeable but were less important in the description.","transcript_status":"source_word_comment","word_comment_ids":["96"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'a4b29cd3008367e108b763749b637dec13e9915294d7a0af662aef39473c53b2'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set008-q007-audio', 'Part 1 Question 98 Audio', 'Woman: I enjoy running for exercise and learned to swim when I was young, but the sport I am really good at is football. I have played in several local teams and usually take a midfield position. I like having to make decisions and work with other players. Training twice a week also keeps me fit without feeling repetitive. The alternatives remained possible on another occasion, but not this time.', '{"source_key":"listening-p1-set008-q007-audio","skill":"listening","part_number":1,"transcript":"Woman: I enjoy running for exercise and learned to swim when I was young, but the sport I am really good at is football. I have played in several local teams and usually take a midfield position. I like having to make decisions and work with other players. Training twice a week also keeps me fit without feeling repetitive. The alternatives remained possible on another occasion, but not this time.","transcript_status":"source_word_comment","word_comment_ids":["97"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '9294234edb8b0dfb21b22f1eb14ad6114ef1a38ec7d6171d5d69dbbb1aad6016'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set008-q008-audio', 'Part 1 Question 99 Audio', 'John: Professor, I know we considered Wednesday morning and briefly mentioned Monday, but neither time works with our classes. We are meeting on Thursday morning at ten, correct? Professor: Yes, come to my office then. Bring the first two sections of your assignment, and we will spend most of the meeting discussing your research method and the evidence you have collected. The new arrangement also avoided a rushed journey at the busiest part of the day.', '{"source_key":"listening-p1-set008-q008-audio","skill":"listening","part_number":1,"transcript":"John: Professor, I know we considered Wednesday morning and briefly mentioned Monday, but neither time works with our classes. We are meeting on Thursday morning at ten, correct? Professor: Yes, come to my office then. Bring the first two sections of your assignment, and we will spend most of the meeting discussing your research method and the evidence you have collected. The new arrangement also avoided a rushed journey at the busiest part of the day.","transcript_status":"source_word_comment","word_comment_ids":["98"],"speaker_labels":["John"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '1a8ed95396f6482ac4449e0c651c5c33645c42de313c2aab5a669713599eb77c'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set008-q009-audio', 'Part 1 Question 100 Audio', 'Man: Our whole trip lasted longer than the time we spent in India. We were in Thailand first, and within India we stayed one week in Delhi. Altogether, we spent two weeks in India before flying home. The original plan had been three weeks, but work commitments forced us to shorten it. Even so, we visited several cities and travelled overnight by train twice. They noted the change immediately so nobody would follow the earlier timetable.', '{"source_key":"listening-p1-set008-q009-audio","skill":"listening","part_number":1,"transcript":"Man: Our whole trip lasted longer than the time we spent in India. We were in Thailand first, and within India we stayed one week in Delhi. Altogether, we spent two weeks in India before flying home. The original plan had been three weeks, but work commitments forced us to shorten it. Even so, we visited several cities and travelled overnight by train twice. They noted the change immediately so nobody would follow the earlier timetable.","transcript_status":"source_word_comment","word_comment_ids":["99"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '1fdbf086df4a1eca7fbc79637d4f33c98484a7e2a9ea65bacad803fff5ae452a'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set008-q010-audio', 'Part 1 Question 101 Audio', 'Man: I usually avoid driving because traffic into the city is heavy, and flying would make no sense for such a short journey. I travel by train. The service is normally reliable, I can work during the trip, and the station is close to my office. I only use the car when engineering work closes the railway at weekends. The other possibilities were useful to discuss but were not selected.', '{"source_key":"listening-p1-set008-q010-audio","skill":"listening","part_number":1,"transcript":"Man: I usually avoid driving because traffic into the city is heavy, and flying would make no sense for such a short journey. I travel by train. The service is normally reliable, I can work during the trip, and the station is close to my office. I only use the car when engineering work closes the railway at weekends. The other possibilities were useful to discuss but were not selected.","transcript_status":"source_word_comment","word_comment_ids":["100"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'ce052b1238e524414bbc34c361532a7f9cc057d288f3f43be936102c7639f85d'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set008-q011-audio', 'Part 1 Question 102 Audio', 'Malik: I thought about going to the library to return some books, and I may walk through the park afterwards. The place I need first is the town hall. I have an appointment there to ask about a housing form. The office closes at four, so I want to deal with that before doing anything less urgent in the centre. Anyone following the directions carefully should reach the correct place without difficulty.', '{"source_key":"listening-p1-set008-q011-audio","skill":"listening","part_number":1,"transcript":"Malik: I thought about going to the library to return some books, and I may walk through the park afterwards. The place I need first is the town hall. I have an appointment there to ask about a housing form. The office closes at four, so I want to deal with that before doing anything less urgent in the centre. Anyone following the directions carefully should reach the correct place without difficulty.","transcript_status":"source_word_comment","word_comment_ids":["101"],"speaker_labels":["Malik"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'da71de1bac391ffdb80031db2732732ba346139d859289fa494e5dbf2a7f1093'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set008-q012-audio', 'Part 1 Question 103 Audio', 'Man: The streets are full of students, small cafés and bookshops. There are several lecture buildings, a large library and sports facilities nearby. It is not mainly a shopping district, although there are some stores, and most of the homes are farther away. I am describing a university area, especially the busy streets immediately around the main campus. The atmosphere becomes noticeably during university holidays.', '{"source_key":"listening-p1-set008-q012-audio","skill":"listening","part_number":1,"transcript":"Man: The streets are full of students, small cafés and bookshops. There are several lecture buildings, a large library and sports facilities nearby. It is not mainly a shopping district, although there are some stores, and most of the homes are farther away. I am describing a university area, especially the busy streets immediately around the main campus. The atmosphere becomes noticeably during university holidays.","transcript_status":"source_word_comment","word_comment_ids":["102"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '5e32935e8e6e960ee6c219a8b9e3ee23d216d6240dff40091f8185b833bddbc9'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set008-q013-audio', 'Part 1 Question 104 Audio', 'Man: I might go to the park at the weekend, and there is a film I want to see at the cinema. Tomorrow, though, I need to go to the town hall. I have to collect an official document before the office closes. If that takes less time than expected, I may stop for coffee and visit the cinema afterwards. A clear landmark nearby makes the correct place easy to recognise on arrival.', '{"source_key":"listening-p1-set008-q013-audio","skill":"listening","part_number":1,"transcript":"Man: I might go to the park at the weekend, and there is a film I want to see at the cinema. Tomorrow, though, I need to go to the town hall. I have to collect an official document before the office closes. If that takes less time than expected, I may stop for coffee and visit the cinema afterwards. A clear landmark nearby makes the correct place easy to recognise on arrival.","transcript_status":"source_word_comment","word_comment_ids":["103"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '776f5b138d11ef4669bf84f44b431f43e2638e4e96f925f3a8180c28d01f8c47'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set009-q001-audio', 'Part 1 Question 105 Audio', 'Student: I thought the assignment was due on Friday, but that is only when we discuss the draft in class. Sunday is the date for a different project. This assignment is due on Saturday. We have to upload it before midnight, including the reference list. I plan to finish on Friday evening so I still have time to check the formatting. Everyone agreed to confirm the smaller details by message later that day.', '{"source_key":"listening-p1-set009-q001-audio","skill":"listening","part_number":1,"transcript":"Student: I thought the assignment was due on Friday, but that is only when we discuss the draft in class. Sunday is the date for a different project. This assignment is due on Saturday. We have to upload it before midnight, including the reference list. I plan to finish on Friday evening so I still have time to check the formatting. Everyone agreed to confirm the smaller details by message later that day.","transcript_status":"source_word_comment","word_comment_ids":["104"],"speaker_labels":["Student"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '84587966524df32811db227636fdaa5810a4393834532f7c25c3fc41fda942c8'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set009-q002-audio', 'Part 1 Question 106 Audio', 'Woman: The action scenes were exciting, and the ending was clever, but neither was my favourite part of the film. I liked the mountain scenes best. The wide views looked beautiful on the cinema screen and made the journey in the story feel much more dramatic. I would watch the film again mainly to see those landscapes and the outdoor photography. The alternatives remained possible on another occasion, but not this time.', '{"source_key":"listening-p1-set009-q002-audio","skill":"listening","part_number":1,"transcript":"Woman: The action scenes were exciting, and the ending was clever, but neither was my favourite part of the film. I liked the mountain scenes best. The wide views looked beautiful on the cinema screen and made the journey in the story feel much more dramatic. I would watch the film again mainly to see those landscapes and the outdoor photography. The alternatives remained possible on another occasion, but not this time.","transcript_status":"source_word_comment","word_comment_ids":["105"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'c37cdd05dd2db93c5b51b984ab596d2be433cd1e3f873dbab6f1c6aee4b50843'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set009-q003-audio', 'Part 1 Question 107 Audio', 'Girl: Mum, I''ve looked at three dresses for the school event. The short blue one is pretty, but it feels too casual. The long white one looks elegant, although I''m worried it will get dirty. Mother: So which one do you prefer? Girl: I want the long red dress. It fits well, and I can wear it with the black shoes I already have. Could you come and see it tomorrow? Mother: Of course, I''d love to! I''ll come by tomorrow afternoon.', '{"source_key":"listening-p1-set009-q003-audio","skill":"listening","part_number":1,"transcript":"Girl: Mum, I''ve looked at three dresses for the school event. The short blue one is pretty, but it feels too casual. The long white one looks elegant, although I''m worried it will get dirty. Mother: So which one do you prefer? Girl: I want the long red dress. It fits well, and I can wear it with the black shoes I already have. Could you come and see it tomorrow? Mother: Of course, I''d love to! I''ll come by tomorrow afternoon.","transcript_status":"source_word_comment","word_comment_ids":["106"],"speaker_labels":["Girl"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'e2b02eb850303664727851cdd1535980ffc53683f61df5c08f6c5457c6a6e99a'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set009-q004-audio', 'Part 1 Question 108 Audio', 'Girl: I do not drive, and the bus often arrives late in the morning. I walk to school because it is only about fifteen minutes from my house. The route goes through a residential street and past a small park. When the weather is bad, my father sometimes gives me a lift, but walking is my normal way of getting there. After making the decision, the remaining arrangements were straightforward.', '{"source_key":"listening-p1-set009-q004-audio","skill":"listening","part_number":1,"transcript":"Girl: I do not drive, and the bus often arrives late in the morning. I walk to school because it is only about fifteen minutes from my house. The route goes through a residential street and past a small park. When the weather is bad, my father sometimes gives me a lift, but walking is my normal way of getting there. After making the decision, the remaining arrangements were straightforward.","transcript_status":"source_word_comment","word_comment_ids":["107"],"speaker_labels":["Girl"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '0800791c8b40735f9b4f172651fb19d5c6558320c7f1bb81896dff9ffa633cba'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set009-q005-audio', 'Part 1 Question 109 Audio', 'Station announcement: The timetable originally showed a 9:30 departure, while 9:00 is the time the train leaves the previous station. Today''s service will leave this station at 9:15. Passengers should move to Platform Three and be ready before the doors close. Please do not wait for another announcement, as the train is expected to depart on time. The remaining activities could continue normally once the correct time was clear.', '{"source_key":"listening-p1-set009-q005-audio","skill":"listening","part_number":1,"transcript":"Station announcement: The timetable originally showed a 9:30 departure, while 9:00 is the time the train leaves the previous station. Today''s service will leave this station at 9:15. Passengers should move to Platform Three and be ready before the doors close. Please do not wait for another announcement, as the train is expected to depart on time. The remaining activities could continue normally once the correct time was clear.","transcript_status":"source_word_comment","word_comment_ids":["108"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '2aecb8bd9207793c19c4bca1d22627ef0b93d2d151cc6b12336ba269bcc1f8eb'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set009-q006-audio', 'Part 1 Question 110 Audio', 'Teacher: The first computer science lesson will not be in Room 101 because another class is using it. Room 203 has fewer computers and is reserved for a small group. We will study in Room 301. It is on the third floor beside the lift. Please arrive early enough to log in and check that your account is working. Anyone following the directions carefully should reach the correct place without difficulty.', '{"source_key":"listening-p1-set009-q006-audio","skill":"listening","part_number":1,"transcript":"Teacher: The first computer science lesson will not be in Room 101 because another class is using it. Room 203 has fewer computers and is reserved for a small group. We will study in Room 301. It is on the third floor beside the lift. Please arrive early enough to log in and check that your account is working. Anyone following the directions carefully should reach the correct place without difficulty.","transcript_status":"source_word_comment","word_comment_ids":["109"],"speaker_labels":["Teacher"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '591b7de7861947cea34736f6978c1ed3f1642edc026953a9a3816b4fd402915d'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set009-q007-audio', 'Part 1 Question 111 Audio', 'Woman: The station looks close on the map, but fifteen minutes is only possible by taxi. Twenty-five minutes would include stopping at the shops on the way. It normally takes twenty minutes to get there on foot. I''ll leave a little earlier because I need to buy a ticket, find the platform and meet my friend before the train arrives. The updated schedule suited the people involved better than either earlier suggestion.', '{"source_key":"listening-p1-set009-q007-audio","skill":"listening","part_number":1,"transcript":"Woman: The station looks close on the map, but fifteen minutes is only possible by taxi. Twenty-five minutes would include stopping at the shops on the way. It normally takes twenty minutes to get there on foot. I''ll leave a little earlier because I need to buy a ticket, find the platform and meet my friend before the train arrives. The updated schedule suited the people involved better than either earlier suggestion.","transcript_status":"source_word_comment","word_comment_ids":["110"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '3ee91fe6a9a03a4046f197dc83feef3e4782edb1c347656cf980ae8b42005214'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set009-q008-audio', 'Part 1 Question 112 Audio', 'Woman: I do not have to go to work today, and staying home all afternoon would make me restless. I''m going to go for a drive in the countryside. The weather is clear, and I want to visit a small village I have never seen before. I''ll take some food with me and return before it gets dark. The choice fitted the situation better than the other ideas they had discussed.', '{"source_key":"listening-p1-set009-q008-audio","skill":"listening","part_number":1,"transcript":"Woman: I do not have to go to work today, and staying home all afternoon would make me restless. I''m going to go for a drive in the countryside. The weather is clear, and I want to visit a small village I have never seen before. I''ll take some food with me and return before it gets dark. The choice fitted the situation better than the other ideas they had discussed.","transcript_status":"source_word_comment","word_comment_ids":["111"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'be569ebd4de960cdf44c357bea9f50a6918f699cf66ae1afbc8e8da71bdb7d5e'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set009-q009-audio', 'Part 1 Question 113 Audio', 'Mother: Please buy a dozen eggs for the cake. The bread costs two pounds, and the large bottle of milk is three pounds, but the eggs are one pound fifty. I only need one box today. Check that none are broken before you pay, and put them carefully at the top of the shopping bag so they do not get damaged. No extra charge or item needed to be added to that figure.', '{"source_key":"listening-p1-set009-q009-audio","skill":"listening","part_number":1,"transcript":"Mother: Please buy a dozen eggs for the cake. The bread costs two pounds, and the large bottle of milk is three pounds, but the eggs are one pound fifty. I only need one box today. Check that none are broken before you pay, and put them carefully at the top of the shopping bag so they do not get damaged. No extra charge or item needed to be added to that figure.","transcript_status":"source_word_comment","word_comment_ids":["112"],"speaker_labels":["Mother"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '098aaa54e4874dc19ce5b58eb3f0ad90e37e42b3e483577a430c9d850fd00743'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set009-q010-audio', 'Part 1 Question 114 Audio', 'Woman: Hi, I''m calling to tell you about lunch. I first said it might be ready at one, but the meat needs longer in the oven. Husband: Should I come home earlier then? Woman: Three o''clock would be too late for the children. Lunch will be ready at two. Could you come home a little before then and set the table? Husband: Of course, I''ll head back just before two. Woman: Perfect, I still need to finish the vegetables and make the sauce.', '{"source_key":"listening-p1-set009-q010-audio","skill":"listening","part_number":1,"transcript":"Woman: Hi, I''m calling to tell you about lunch. I first said it might be ready at one, but the meat needs longer in the oven. Husband: Should I come home earlier then? Woman: Three o''clock would be too late for the children. Lunch will be ready at two. Could you come home a little before then and set the table? Husband: Of course, I''ll head back just before two. Woman: Perfect, I still need to finish the vegetables and make the sauce.","transcript_status":"source_word_comment","word_comment_ids":["113"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'cd66477a012e64c5ac946ae9ea849499d49f224972965bcdf956511df96839ed'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set009-q011-audio', 'Part 1 Question 115 Audio', 'Colleague: The meeting room is free from four, but several people have another appointment then. Three o''clock was suggested, although the manager cannot attend at that time. The meeting is at two this afternoon. Please arrive ten minutes early with the sales figures. We want to finish by half past three so the visitors can catch their train. The new arrangement also avoided a rushed journey at the busiest part of the day.', '{"source_key":"listening-p1-set009-q011-audio","skill":"listening","part_number":1,"transcript":"Colleague: The meeting room is free from four, but several people have another appointment then. Three o''clock was suggested, although the manager cannot attend at that time. The meeting is at two this afternoon. Please arrive ten minutes early with the sales figures. We want to finish by half past three so the visitors can catch their train. The new arrangement also avoided a rushed journey at the busiest part of the day.","transcript_status":"source_word_comment","word_comment_ids":["114"],"speaker_labels":["Colleague"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '4373033b51aad3ea7bec5b12256116783a597a2c8baedb425bf5d54d5cc130ce'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set009-q012-audio', 'Part 1 Question 116 Audio', 'Colleague 1: Monday is difficult because the weekly reports are due, and Wednesday is already full of client calls. Could we meet on Tuesday? Colleague 2: Yes, Tuesday afternoon works well. I''ll reserve the smaller meeting room and send everyone the agenda. We should focus first on the launch date, then discuss the budget if there is enough time. They noted the change immediately so nobody would follow the earlier timetable.', '{"source_key":"listening-p1-set009-q012-audio","skill":"listening","part_number":1,"transcript":"Colleague 1: Monday is difficult because the weekly reports are due, and Wednesday is already full of client calls. Could we meet on Tuesday? Colleague 2: Yes, Tuesday afternoon works well. I''ll reserve the smaller meeting room and send everyone the agenda. We should focus first on the launch date, then discuss the budget if there is enough time. They noted the change immediately so nobody would follow the earlier timetable.","transcript_status":"source_word_comment","word_comment_ids":["115"],"speaker_labels":["Colleague 1"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '27a6789fc18e1dee09191f9640315a700026267d96e5d2ce360849c6ca080a48'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set009-q013-audio', 'Part 1 Question 117 Audio', 'Woman: I sometimes go cycling with friends, and I used to run regularly, but walking is the form of exercise I choose most often. It is easy to fit into my day and does not require special equipment. On holiday, I walk even more because I enjoy exploring new streets, parks and countryside paths at a relaxed pace. The other possibilities were useful to discuss but were not selected.', '{"source_key":"listening-p1-set009-q013-audio","skill":"listening","part_number":1,"transcript":"Woman: I sometimes go cycling with friends, and I used to run regularly, but walking is the form of exercise I choose most often. It is easy to fit into my day and does not require special equipment. On holiday, I walk even more because I enjoy exploring new streets, parks and countryside paths at a relaxed pace. The other possibilities were useful to discuss but were not selected.","transcript_status":"source_word_comment","word_comment_ids":["116"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'a1d83b6d6565a9ec31393b953439fcd246e0cfd70e55235a3cb9a2e1eaff5468'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set010-q001-audio', 'Part 1 Question 118 Audio', 'Man: When we travel to India, we do not usually head straight to the mountains, and the beach is too far from where our relatives live. We often go to the park near their home. It has a lake, food stalls and a large area where the children can play. We normally spend several hours there before returning for dinner. There was still enough time to arrive, prepare and deal with any small delay.', '{"source_key":"listening-p1-set010-q001-audio","skill":"listening","part_number":1,"transcript":"Man: When we travel to India, we do not usually head straight to the mountains, and the beach is too far from where our relatives live. We often go to the park near their home. It has a lake, food stalls and a large area where the children can play. We normally spend several hours there before returning for dinner. There was still enough time to arrive, prepare and deal with any small delay.","transcript_status":"source_word_comment","word_comment_ids":["117"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'b7dc45d9db28d118ab148353ab8e1025e797605a4336f376af814a8287cc5f97'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set010-q002-audio', 'Part 1 Question 119 Audio', 'Woman: We considered the back entrance because it is , but delivery vehicles use that area. The side entrance was locked when we arrived. We met at the front entrance, where the sign and ticket office were easy to see. I arrived first and waited beside the steps until the others came. From there, we all went inside together. The final location also allowed the group to continue the journey together.', '{"source_key":"listening-p1-set010-q002-audio","skill":"listening","part_number":1,"transcript":"Woman: We considered the back entrance because it is , but delivery vehicles use that area. The side entrance was locked when we arrived. We met at the front entrance, where the sign and ticket office were easy to see. I arrived first and waited beside the steps until the others came. From there, we all went inside together. The final location also allowed the group to continue the journey together.","transcript_status":"source_word_comment","word_comment_ids":["118"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'f97077c94e1546706d4ca546a95163bc1555291d10fcce4701b2c9113ccf4e69'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set010-q003-audio', 'Part 1 Question 120 Audio', 'Student: Germany was our original choice, and Spain was discussed because the weather would be warmer. Next semester, we will study in France. The university has a strong programme for international students, and several of our courses will be taught in English. I have started learning basic French so everyday tasks will be easier when we arrive. The choice fitted the situation better than the other ideas they had discussed.', '{"source_key":"listening-p1-set010-q003-audio","skill":"listening","part_number":1,"transcript":"Student: Germany was our original choice, and Spain was discussed because the weather would be warmer. Next semester, we will study in France. The university has a strong programme for international students, and several of our courses will be taught in English. I have started learning basic French so everyday tasks will be easier when we arrive. The choice fitted the situation better than the other ideas they had discussed.","transcript_status":"source_word_comment","word_comment_ids":["119"],"speaker_labels":["Student"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '3bf4db2d76eb85a5cb2a38cc6bb3c900d176bdccb05e6ed4ac95f2651687dea2'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set010-q004-audio', 'Part 1 Question 121 Audio', 'Financial adviser: Using public transport and buying second-hand items can both reduce costs. My strongest advice to young people is to cook for yourself. Meals prepared at home are usually much cheaper than eating in cafés or ordering food. Plan several simple dishes, buy only what you need and take lunch to work or college instead of purchasing it every day. It also left enough time and energy for the rest of the day.', '{"source_key":"listening-p1-set010-q004-audio","skill":"listening","part_number":1,"transcript":"Financial adviser: Using public transport and buying second-hand items can both reduce costs. My strongest advice to young people is to cook for yourself. Meals prepared at home are usually much cheaper than eating in cafés or ordering food. Plan several simple dishes, buy only what you need and take lunch to work or college instead of purchasing it every day. It also left enough time and energy for the rest of the day.","transcript_status":"source_word_comment","word_comment_ids":["120"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'bcd69333699d20521bb689ab6f98bb25390636538f08741a5077c4cf22245b0c'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set010-q005-audio', 'Part 1 Question 122 Audio', 'Woman: My car did not break down, and although the traffic was heavy, I still reached the station in time. The problem was that I went to the wrong platform and missed the train. I had to wait for the next service, which made me late for work. Now I check the departure board carefully as soon as I enter the station. That detail changed how everyone involved understood the problem.', '{"source_key":"listening-p1-set010-q005-audio","skill":"listening","part_number":1,"transcript":"Woman: My car did not break down, and although the traffic was heavy, I still reached the station in time. The problem was that I went to the wrong platform and missed the train. I had to wait for the next service, which made me late for work. Now I check the departure board carefully as soon as I enter the station. That detail changed how everyone involved understood the problem.","transcript_status":"source_word_comment","word_comment_ids":["121"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '2938aa78085a2db9306e5775248274fc5db72408d0c909e73d6ebb98c102b051'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set010-q006-audio', 'Part 1 Question 123 Audio', 'Girl: The show includes a short speech near the beginning, and there will be a firework display outside before the interval. It will end with a surprise performance. The organisers have not announced the performer, but people expect it to be someone well known. I''m staying until the final curtain because I do not want to miss the part everyone is talking about. The practical details made that option more suitable than either earlier suggestion.', '{"source_key":"listening-p1-set010-q006-audio","skill":"listening","part_number":1,"transcript":"Girl: The show includes a short speech near the beginning, and there will be a firework display outside before the interval. It will end with a surprise performance. The organisers have not announced the performer, but people expect it to be someone well known. I''m staying until the final curtain because I do not want to miss the part everyone is talking about. The practical details made that option more suitable than either earlier suggestion.","transcript_status":"source_word_comment","word_comment_ids":["122"],"speaker_labels":["Girl"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'd8e9ba5838406654330be7f136f6334d8b4cc773b73f45d8c6350cca3d04f98e'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set010-q007-audio', 'Part 1 Question 124 Audio', 'Woman: I could sleep at home this afternoon, and the cinema has a film I would like to see. Instead, I''m going on a city tour. I have lived here for two years but still know very little about the old buildings. The tour starts at the main square and finishes beside the river, so I may have dinner there afterwards. After making the decision, the remaining arrangements were straightforward.', '{"source_key":"listening-p1-set010-q007-audio","skill":"listening","part_number":1,"transcript":"Woman: I could sleep at home this afternoon, and the cinema has a film I would like to see. Instead, I''m going on a city tour. I have lived here for two years but still know very little about the old buildings. The tour starts at the main square and finishes beside the river, so I may have dinner there afterwards. After making the decision, the remaining arrangements were straightforward.","transcript_status":"source_word_comment","word_comment_ids":["123"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '08f506b3b454640394b2223820415391cba8311501f45e0e0f365297b655ab31'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set010-q008-audio', 'Part 1 Question 125 Audio', 'Woman: I started my new exercise routine by planning forty-five minutes of cycling, but that left me too tired. An hour would include travelling to the gym and warming up. I actually spend thirty-five minutes cycling. After that, I stretch for ten minutes and walk home slowly. The shorter session is easier to repeat several times each week without losing motivation. That amount matched the official record rather than either earlier estimate.', '{"source_key":"listening-p1-set010-q008-audio","skill":"listening","part_number":1,"transcript":"Woman: I started my new exercise routine by planning forty-five minutes of cycling, but that left me too tired. An hour would include travelling to the gym and warming up. I actually spend thirty-five minutes cycling. After that, I stretch for ten minutes and walk home slowly. The shorter session is easier to repeat several times each week without losing motivation. That amount matched the official record rather than either earlier estimate.","transcript_status":"source_word_comment","word_comment_ids":["124"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '805dff333741b5a46d7dcb0d927787a8d4c2f1960a28a158be0d61156c83c83f'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set010-q009-audio', 'Part 1 Question 126 Audio', 'Mother: Hi, I''m calling about when we should meet today. I originally said I would meet you at two, but my appointment will not finish in time. Son: That''s fine. What time works instead? Mother: Six o''clock is possible, although it would be too late for the shopping we need to do. I''ll meet you at three o''clock outside the station. Son: Alright, I''ll wait near the ticket machines. Mother: Call me if the train is delayed or you arrive before I do.', '{"source_key":"listening-p1-set010-q009-audio","skill":"listening","part_number":1,"transcript":"Mother: Hi, I''m calling about when we should meet today. I originally said I would meet you at two, but my appointment will not finish in time. Son: That''s fine. What time works instead? Mother: Six o''clock is possible, although it would be too late for the shopping we need to do. I''ll meet you at three o''clock outside the station. Son: Alright, I''ll wait near the ticket machines. Mother: Call me if the train is delayed or you arrive before I do.","transcript_status":"source_word_comment","word_comment_ids":["125"],"speaker_labels":["Mother"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '22a7630fc5d3f36616a14b2fe896a16cbe9adb456e4e4f98be6aeb742f928f0f'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set010-q010-audio', 'Part 1 Question 127 Audio', 'Jack: I''m calling to give you directions to my place. Friend: Great, which house is yours? Jack: When you come, do not stop at the black one on the corner. The green house belongs to my neighbour. Mine is the red house halfway along the street, with a small tree beside the gate. Friend: Got it, the red one with the tree. Jack: Exactly! I''ll leave the outside light on if it gets dark, and you can park in the space directly in front.', '{"source_key":"listening-p1-set010-q010-audio","skill":"listening","part_number":1,"transcript":"Jack: I''m calling to give you directions to my place. Friend: Great, which house is yours? Jack: When you come, do not stop at the black one on the corner. The green house belongs to my neighbour. Mine is the red house halfway along the street, with a small tree beside the gate. Friend: Got it, the red one with the tree. Jack: Exactly! I''ll leave the outside light on if it gets dark, and you can park in the space directly in front.","transcript_status":"source_word_comment","word_comment_ids":["126"],"speaker_labels":["Jack"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '0db64ede2c757b477ebbe4399bd82d77d070e3ae18639f62a778ea80139e6cde'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set010-q011-audio', 'Part 1 Question 128 Audio', 'Man: After work, I do not go straight home unless the weather is terrible. I sometimes stop at the coffee shop, but only when I am meeting someone. Most evenings, I play football with colleagues at the sports centre. The match helps me forget about work, and afterwards I walk home, take a shower and eat a late dinner. The choice fitted the situation better than the other ideas they had discussed.', '{"source_key":"listening-p1-set010-q011-audio","skill":"listening","part_number":1,"transcript":"Man: After work, I do not go straight home unless the weather is terrible. I sometimes stop at the coffee shop, but only when I am meeting someone. Most evenings, I play football with colleagues at the sports centre. The match helps me forget about work, and afterwards I walk home, take a shower and eat a late dinner. The choice fitted the situation better than the other ideas they had discussed.","transcript_status":"source_word_comment","word_comment_ids":["127"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'f9dd751d410fb487d75941bd2981a2d2bf35daa0772299a942013b7127c98888'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set010-q012-audio', 'Part 1 Question 129 Audio', 'Author: I have tried writing in the morning, but I spend too long answering messages and organising the day. At night, I am usually too tired to concentrate. I normally write in the afternoons, after lunch and before the house becomes busy again. I work for about three hours, then stop even if a chapter is not completely finished. Everyone agreed to confirm the smaller details by message later that day.', '{"source_key":"listening-p1-set010-q012-audio","skill":"listening","part_number":1,"transcript":"Author: I have tried writing in the morning, but I spend too long answering messages and organising the day. At night, I am usually too tired to concentrate. I normally write in the afternoons, after lunch and before the house becomes busy again. I work for about three hours, then stop even if a chapter is not completely finished. Everyone agreed to confirm the smaller details by message later that day.","transcript_status":"source_word_comment","word_comment_ids":["128"],"speaker_labels":["Author"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '5500b25ee90874bc0f576bbb0e23b91c6af2cc84d727368b9a5a8d4831fb5fe9'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set010-q013-audio', 'Part 1 Question 130 Audio', 'Woman: I occasionally go shopping on Saturday, and last month I attended a friend''s birthday party. My usual Saturday routine is to see my family. We have lunch at my parents'' house and often stay until the evening. It is the one day when everyone is normally free, so we try not to arrange other activities unless something important comes up. The alternatives remained possible on another occasion, but not this time.', '{"source_key":"listening-p1-set010-q013-audio","skill":"listening","part_number":1,"transcript":"Woman: I occasionally go shopping on Saturday, and last month I attended a friend''s birthday party. My usual Saturday routine is to see my family. We have lunch at my parents'' house and often stay until the evening. It is the one day when everyone is normally free, so we try not to arrange other activities unless something important comes up. The alternatives remained possible on another occasion, but not this time.","transcript_status":"source_word_comment","word_comment_ids":["129"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'ce0148eb6575ae9005193bae7b484f53493bad332d0c0b7d0739ea8120fe75d8'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set011-q001-audio', 'Part 1 Question 131 Audio', 'Man: On family trips, I enjoy hiking and the children are always interested in shopping for souvenirs. My wife most enjoys photography. She carries a small camera everywhere and stops whenever she sees an unusual building, landscape or local market. At the end of the trip, she creates an album, which is much more interesting than the photographs I take on my phone. The practical details made that option more suitable than either earlier suggestion.', '{"source_key":"listening-p1-set011-q001-audio","skill":"listening","part_number":1,"transcript":"Man: On family trips, I enjoy hiking and the children are always interested in shopping for souvenirs. My wife most enjoys photography. She carries a small camera everywhere and stops whenever she sees an unusual building, landscape or local market. At the end of the trip, she creates an album, which is much more interesting than the photographs I take on my phone. The practical details made that option more suitable than either earlier suggestion.","transcript_status":"source_word_comment","word_comment_ids":["130"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'de351cac3687187c337aab7b7c89c04ac2ee2fb1eb5c5f4a84ac3b1821be3f50'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set011-q002-audio', 'Part 1 Question 132 Audio', 'Woman: My mother supported my education, and I used a computer for many school projects, but neither first inspired me to become a scientist. It began when I found a large stone near my home. I wanted to know why it contained different colours and where it came from. That curiosity led me to read about geology and eventually choose science as a career. Understanding the real cause made it easier to decide what to do next.', '{"source_key":"listening-p1-set011-q002-audio","skill":"listening","part_number":1,"transcript":"Woman: My mother supported my education, and I used a computer for many school projects, but neither first inspired me to become a scientist. It began when I found a large stone near my home. I wanted to know why it contained different colours and where it came from. That curiosity led me to read about geology and eventually choose science as a career. Understanding the real cause made it easier to decide what to do next.","transcript_status":"source_word_comment","word_comment_ids":["131"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'ac1a81bbf04744e7d13a15efb348ad82670d3cc0d5dd88e780a9d18ba926484a'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set011-q003-audio', 'Part 1 Question 133 Audio', 'Speaker: Our team is unavailable on Monday morning because the weekly reports are due. Friday afternoon was suggested, but several people will already have left for a conference. The meeting is scheduled for Wednesday afternoon at two. We will use the main conference room and should finish before four. Please send any agenda items to me by Tuesday evening. The remaining activities could continue normally once the correct time was clear.', '{"source_key":"listening-p1-set011-q003-audio","skill":"listening","part_number":1,"transcript":"Speaker: Our team is unavailable on Monday morning because the weekly reports are due. Friday afternoon was suggested, but several people will already have left for a conference. The meeting is scheduled for Wednesday afternoon at two. We will use the main conference room and should finish before four. Please send any agenda items to me by Tuesday evening. The remaining activities could continue normally once the correct time was clear.","transcript_status":"source_word_comment","word_comment_ids":["132"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'b5f740b01bef7f2da71d0f2536ce096c106b01312f881dffe980f5545ec63f6a'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set011-q004-audio', 'Part 1 Question 134 Audio', 'Newsreader: The first version of the housing plan proposed 1,500 homes, while campaigners feared the number might rise to 2,500. The approved development will contain 2,000 new houses. Building will take place in several stages, and the project also includes a school, shops and public green space. The first residents are expected to move in within three years. The figures became clear once the different products or categories were separated.', '{"source_key":"listening-p1-set011-q004-audio","skill":"listening","part_number":1,"transcript":"Newsreader: The first version of the housing plan proposed 1,500 homes, while campaigners feared the number might rise to 2,500. The approved development will contain 2,000 new houses. Building will take place in several stages, and the project also includes a school, shops and public green space. The first residents are expected to move in within three years. The figures became clear once the different products or categories were separated.","transcript_status":"source_word_comment","word_comment_ids":["133"],"speaker_labels":["Newsreader"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'af494c4ac1773880a8887cf4131cf00d13709af7ec45a6788915d6e77f1bc3e3'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set011-q005-audio', 'Part 1 Question 135 Audio', 'Writer: People know me as a writer now, and I worked in a library for a short period while finishing my first book. My first job was as a teacher. I taught young children for five years. That experience helped me explain ideas clearly, and many of the characters in my early stories were inspired by situations I observed in the classroom. Nothing else needed to change once the main decision had been made.', '{"source_key":"listening-p1-set011-q005-audio","skill":"listening","part_number":1,"transcript":"Writer: People know me as a writer now, and I worked in a library for a short period while finishing my first book. My first job was as a teacher. I taught young children for five years. That experience helped me explain ideas clearly, and many of the characters in my early stories were inspired by situations I observed in the classroom. Nothing else needed to change once the main decision had been made.","transcript_status":"source_word_comment","word_comment_ids":["134"],"speaker_labels":["Writer"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '867994a0c453779be429fb8a6d5b42c6664f314248d856e258bac08372e93a73'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set011-q006-audio', 'Part 1 Question 136 Audio', 'Mary: James is already twenty minutes late. Should we cancel the meeting? Jane: We need to make a decision today, and waiting longer will leave us no time. Let''s have the meeting without him and send him the notes afterwards. Mary: Agreed. We can begin with the budget, and if he arrives before we finish, he can join the discussion. The choice fitted the situation better than the other ideas they had discussed.', '{"source_key":"listening-p1-set011-q006-audio","skill":"listening","part_number":1,"transcript":"Mary: James is already twenty minutes late. Should we cancel the meeting? Jane: We need to make a decision today, and waiting longer will leave us no time. Let''s have the meeting without him and send him the notes afterwards. Mary: Agreed. We can begin with the budget, and if he arrives before we finish, he can join the discussion. The choice fitted the situation better than the other ideas they had discussed.","transcript_status":"source_word_comment","word_comment_ids":["135"],"speaker_labels":["Mary"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '9df1fb5f077dcd11a9ffe00128ccc8c446790625090e8ca29dbbfd2890b86fb7'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set011-q007-audio', 'Part 1 Question 137 Audio', 'Vincent: Hi, James. I''m not calling to invite you to a party, and I do not need help with work. I wondered whether you would like to go for a drink this evening. There is a new café near the station that stays open late. We could meet there after six and catch up, since we have not spoken properly for several weeks. The other explanations sounded possible at first but did not match the evidence.', '{"source_key":"listening-p1-set011-q007-audio","skill":"listening","part_number":1,"transcript":"Vincent: Hi, James. I''m not calling to invite you to a party, and I do not need help with work. I wondered whether you would like to go for a drink this evening. There is a new café near the station that stays open late. We could meet there after six and catch up, since we have not spoken properly for several weeks. The other explanations sounded possible at first but did not match the evidence.","transcript_status":"source_word_comment","word_comment_ids":["136"],"speaker_labels":["Vincent"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '5266a61012cfb304b9f1b3061645f03b130ca964941e598713aabb858f856e42'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set011-q008-audio', 'Part 1 Question 138 Audio', 'Samia: Could we meet at 9:30? Friend: I have an appointment that does not finish until then. Eleven would be possible, but it is later than we need. Samia: Let''s meet at ten o''clock outside the library. Friend: Perfect. I''ll return my books first, and afterwards we can walk to the market and have something to eat. Nobody else needed to change their plans after the updated time was agreed.', '{"source_key":"listening-p1-set011-q008-audio","skill":"listening","part_number":1,"transcript":"Samia: Could we meet at 9:30? Friend: I have an appointment that does not finish until then. Eleven would be possible, but it is later than we need. Samia: Let''s meet at ten o''clock outside the library. Friend: Perfect. I''ll return my books first, and afterwards we can walk to the market and have something to eat. Nobody else needed to change their plans after the updated time was agreed.","transcript_status":"source_word_comment","word_comment_ids":["137"],"speaker_labels":["Samia"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '96e49b636c0303f48e2ae5745f45135210dc0cc2760823a610be520853b8a692'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set011-q009-audio', 'Part 1 Question 139 Audio', 'Anna: Max, could you pick up the children this afternoon? I cannot do it because I have to stay late at the office. Max: Of course, is everything alright? Anna: An urgent report is due today, so I have to stay. I originally planned to leave on time and meet friends afterwards. Max: Don''t worry, I''ll pick them up.', '{"source_key":"listening-p1-set011-q009-audio","skill":"listening","part_number":1,"transcript":"Anna: Max, could you pick up the children this afternoon? I cannot do it because I have to stay late at the office. Max: Of course, is everything alright? Anna: An urgent report is due today, so I have to stay. I originally planned to leave on time and meet friends afterwards. Max: Don''t worry, I''ll pick them up.","transcript_status":"source_word_comment","word_comment_ids":["138"],"speaker_labels":["Anna"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '09bfb2a9223c459830a45d99b0a3fe06c217541483f21e880a723ad7edecf29e'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set011-q010-audio', 'Part 1 Question 140 Audio', 'Radio presenter: I watched three new films this week. The romantic film has good performances, and the comedy is enjoyable but rather predictable. The film I recommend is the action film. Its story moves , the main character is convincing and the final sequence is genuinely exciting. It is best seen at the cinema because the sound and large screen add a great deal. The full description explained why the earlier possibilities had sounded convincing.', '{"source_key":"listening-p1-set011-q010-audio","skill":"listening","part_number":1,"transcript":"Radio presenter: I watched three new films this week. The romantic film has good performances, and the comedy is enjoyable but rather predictable. The film I recommend is the action film. Its story moves , the main character is convincing and the final sequence is genuinely exciting. It is best seen at the cinema because the sound and large screen add a great deal. The full description explained why the earlier possibilities had sounded convincing.","transcript_status":"source_word_comment","word_comment_ids":["139"],"speaker_labels":["Radio presenter"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '088b3ea23142ba0832186e76d12fe2cbee1d73bbd258662fa29d8cca5653b69a'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set011-q011-audio', 'Part 1 Question 141 Audio', 'Greg: I own a car, but city-centre parking is too expensive. Cycling would be healthy, although the main road feels unsafe during rush hour. I go to work by bus. The stop is close to my house, and the journey takes about thirty minutes. I usually use the time to read the news or prepare a list of tasks for the day. The other possibilities were useful to discuss but were not selected.', '{"source_key":"listening-p1-set011-q011-audio","skill":"listening","part_number":1,"transcript":"Greg: I own a car, but city-centre parking is too expensive. Cycling would be healthy, although the main road feels unsafe during rush hour. I go to work by bus. The stop is close to my house, and the journey takes about thirty minutes. I usually use the time to read the news or prepare a list of tasks for the day. The other possibilities were useful to discuss but were not selected.","transcript_status":"source_word_comment","word_comment_ids":["140"],"speaker_labels":["Greg"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'ed7cd81e974671bd916752a5d151a1eb644e0214e24e75178c63190d90e25e2d'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set011-q012-audio', 'Part 1 Question 142 Audio', 'Nutrition expert: Fruit is healthy at any time, but for children the best time is in the morning. It provides energy and can be included with breakfast or a mid-morning snack. In the afternoon, many children already have other snacks, and fruit late in the evening may reduce their appetite for dinner. Offer a small variety rather than forcing them to eat a large amount.', '{"source_key":"listening-p1-set011-q012-audio","skill":"listening","part_number":1,"transcript":"Nutrition expert: Fruit is healthy at any time, but for children the best time is in the morning. It provides energy and can be included with breakfast or a mid-morning snack. In the afternoon, many children already have other snacks, and fruit late in the evening may reduce their appetite for dinner. Offer a small variety rather than forcing them to eat a large amount.","transcript_status":"source_word_comment","word_comment_ids":["141"],"speaker_labels":["Nutrition expert"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '30246122986ebea1dd70f1939116b378ab9d3c5f80cdfac96187088d37cb498d'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set011-q013-audio', 'Part 1 Question 143 Audio', 'Woman: I do not get up early simply to go to work, and the children are usually still asleep at that time. I wake before everyone else to have some time. I make tea, read for a few minutes and plan the day without interruption. Once the family is awake, the house becomes busy, so that peaceful half hour is important to me. The clarification prevented the same misunderstanding from affecting the next decision.', '{"source_key":"listening-p1-set011-q013-audio","skill":"listening","part_number":1,"transcript":"Woman: I do not get up early simply to go to work, and the children are usually still asleep at that time. I wake before everyone else to have some time. I make tea, read for a few minutes and plan the day without interruption. Once the family is awake, the house becomes busy, so that peaceful half hour is important to me. The clarification prevented the same misunderstanding from affecting the next decision.","transcript_status":"source_word_comment","word_comment_ids":["142"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'f9eda3962fbf59874c91bdd5cd27f78853ee635ab7105a5d04c119c6a654235b'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set012-q001-audio', 'Part 1 Question 144 Audio', 'Friend: So why are you finally learning to drive? Man: A road trip would be enjoyable, and I hope to take my family on holiday in the future. But the immediate reason I need to learn to drive is that I have to drive to work. My new office is outside the town, and no bus arrives early enough for my shift. Friend: That makes a lot of sense. Man: I have booked lessons and hope to pass the test within a few months. Friend: Good luck with it!', '{"source_key":"listening-p1-set012-q001-audio","skill":"listening","part_number":1,"transcript":"Friend: So why are you finally learning to drive? Man: A road trip would be enjoyable, and I hope to take my family on holiday in the future. But the immediate reason I need to learn to drive is that I have to drive to work. My new office is outside the town, and no bus arrives early enough for my shift. Friend: That makes a lot of sense. Man: I have booked lessons and hope to pass the test within a few months. Friend: Good luck with it!","transcript_status":"source_word_comment","word_comment_ids":["143"],"speaker_labels":["Friend"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '4983904e505d5f3db6decc9261354de10f795784883e9c44b130db88894cabf6'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set012-q002-audio', 'Part 1 Question 145 Audio', 'Friend 1: I went shopping yesterday and bought some clothes for the holiday. Friend 2: So did I. I looked at shoes first and nearly bought a novel, but I needed a lighter jacket and two shirts. Friend 1: I bought trousers and a dress. At least we both chose the same type of purchase, although our bags looked completely different when we met afterwards.', '{"source_key":"listening-p1-set012-q002-audio","skill":"listening","part_number":1,"transcript":"Friend 1: I went shopping yesterday and bought some clothes for the holiday. Friend 2: So did I. I looked at shoes first and nearly bought a novel, but I needed a lighter jacket and two shirts. Friend 1: I bought trousers and a dress. At least we both chose the same type of purchase, although our bags looked completely different when we met afterwards.","transcript_status":"source_word_comment","word_comment_ids":["144"],"speaker_labels":["Friend 1"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'b1ece30d262958cd933c9d05413da5c9c63d7652d8b737a887308c679473695b'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set012-q003-audio', 'Part 1 Question 146 Audio', 'Tour guide: Some local stories claim Rock City is two thousand years old, while older tourist guides give a figure of one thousand. Archaeological evidence suggests the city is about fifteen hundred years old. The earliest settlement was much smaller than the modern town. During today''s tour, we will see part of the original wall and several objects discovered beneath the market square. That characteristic remained the most useful way to describe the person or thing.', '{"source_key":"listening-p1-set012-q003-audio","skill":"listening","part_number":1,"transcript":"Tour guide: Some local stories claim Rock City is two thousand years old, while older tourist guides give a figure of one thousand. Archaeological evidence suggests the city is about fifteen hundred years old. The earliest settlement was much smaller than the modern town. During today''s tour, we will see part of the original wall and several objects discovered beneath the market square. That characteristic remained the most useful way to describe the person or thing.","transcript_status":"source_word_comment","word_comment_ids":["145"],"speaker_labels":["Tour guide"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '272f024d577be594b3f1acf74944ce4dbb53e40b0888aee262296b7852e421c5'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set012-q004-audio', 'Part 1 Question 147 Audio', 'University instructions: The basement contains storage rooms, and the student support centre is on the second floor. The main office is on the first floor of the central building. Go through the glass entrance and turn left after reception. Staff there can answer about enrolment, fees and timetables. The office is open from nine until five on weekdays. Signs in the area should guide visitors through the final part of the journey.', '{"source_key":"listening-p1-set012-q004-audio","skill":"listening","part_number":1,"transcript":"University instructions: The basement contains storage rooms, and the student support centre is on the second floor. The main office is on the first floor of the central building. Go through the glass entrance and turn left after reception. Staff there can answer about enrolment, fees and timetables. The office is open from nine until five on weekdays. Signs in the area should guide visitors through the final part of the journey.","transcript_status":"source_word_comment","word_comment_ids":["146"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'af658f4d5b0f668668e93efdd9f22f9456a5d851f5ff5c20f465dcea149be798'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set012-q005-audio', 'Part 1 Question 148 Audio', 'Director: Last month, Freeze Frame sold just over 200,000 copies, and our long-term target is 500,000. This month, sales rose to over 300,000 copies. Most of the increase came from digital subscriptions, although newsagent sales also improved. We are pleased with the result, but we still need to attract younger readers if we want the magazine to continue growing. The written information was updated immediately to prevent another mistake later.', '{"source_key":"listening-p1-set012-q005-audio","skill":"listening","part_number":1,"transcript":"Director: Last month, Freeze Frame sold just over 200,000 copies, and our long-term target is 500,000. This month, sales rose to over 300,000 copies. Most of the increase came from digital subscriptions, although newsagent sales also improved. We are pleased with the result, but we still need to attract younger readers if we want the magazine to continue growing. The written information was updated immediately to prevent another mistake later.","transcript_status":"source_word_comment","word_comment_ids":["147"],"speaker_labels":["Director"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '6f8be674d6593d0959c58f8b8e5eb1a8a0a836b6857dbba4a63998abc77153b4'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set012-q006-audio', 'Part 1 Question 149 Audio', 'Man: I realised after leaving my friend''s house that something was missing. My wallet was in my coat, and I was using my phone on the journey home. I had left my glasses at the house, probably on the table beside the sofa. I called immediately, and my friend found them. I''ll collect them tomorrow rather than risk damaging my spare pair. The other possibilities were useful to discuss but were not selected.', '{"source_key":"listening-p1-set012-q006-audio","skill":"listening","part_number":1,"transcript":"Man: I realised after leaving my friend''s house that something was missing. My wallet was in my coat, and I was using my phone on the journey home. I had left my glasses at the house, probably on the table beside the sofa. I called immediately, and my friend found them. I''ll collect them tomorrow rather than risk damaging my spare pair. The other possibilities were useful to discuss but were not selected.","transcript_status":"source_word_comment","word_comment_ids":["148"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '1f6ca1a799bc1f9fba77bec7fe4f3521769c3283cbf9a0bf4c207d3e597f406d'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set012-q007-audio', 'Part 1 Question 150 Audio', 'Man: Are you taking photographs of the boys'' team? Woman: No, they have already finished, and the coaches asked not to be photographed during their meeting. I''m taking a photo of the girls'' team before their final match. They are standing near the goal now. I want one formal picture and then a few natural shots while they warm up. The explanation helped listeners understand why the other guesses sounded believable.', '{"source_key":"listening-p1-set012-q007-audio","skill":"listening","part_number":1,"transcript":"Man: Are you taking photographs of the boys'' team? Woman: No, they have already finished, and the coaches asked not to be photographed during their meeting. I''m taking a photo of the girls'' team before their final match. They are standing near the goal now. I want one formal picture and then a few natural shots while they warm up. The explanation helped listeners understand why the other guesses sounded believable.","transcript_status":"source_word_comment","word_comment_ids":["149"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'bfc41e62d44e947563ffe104dded3f42c1ec2d8d2c326a3103c27dc5a58cdabe'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set012-q008-audio', 'Part 1 Question 151 Audio', 'David: The conference organiser gave me twenty minutes in total, but that included the introduction and I had originally prepared only ten minutes of material. My actual speech lasted fifteen minutes. That was enough time to explain the main results without rushing. Afterwards, the audience asked several useful , and two people stayed behind to discuss the project in more detail. The updated schedule suited the people involved better than either earlier suggestion.', '{"source_key":"listening-p1-set012-q008-audio","skill":"listening","part_number":1,"transcript":"David: The conference organiser gave me twenty minutes in total, but that included the introduction and I had originally prepared only ten minutes of material. My actual speech lasted fifteen minutes. That was enough time to explain the main results without rushing. Afterwards, the audience asked several useful , and two people stayed behind to discuss the project in more detail. The updated schedule suited the people involved better than either earlier suggestion.","transcript_status":"source_word_comment","word_comment_ids":["150"],"speaker_labels":["David"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '8d7ac06f26d711d53f39056d311fe124465700f2069b0e4595cb92137fe0bb0b'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set012-q009-audio', 'Part 1 Question 152 Audio', 'Woman: We visit relatives on special occasions, and in summer we sometimes spend a day at the beach. Most weekends, my family goes for a walk. We choose a park or a countryside path and take a picnic if the weather is good. It gives us time to talk without screens or household jobs, and even the children usually enjoy being outdoors. The choice fitted the situation better than the other ideas they had discussed.', '{"source_key":"listening-p1-set012-q009-audio","skill":"listening","part_number":1,"transcript":"Woman: We visit relatives on special occasions, and in summer we sometimes spend a day at the beach. Most weekends, my family goes for a walk. We choose a park or a countryside path and take a picnic if the weather is good. It gives us time to talk without screens or household jobs, and even the children usually enjoy being outdoors. The choice fitted the situation better than the other ideas they had discussed.","transcript_status":"source_word_comment","word_comment_ids":["151"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'f67ca9e5a6dc1a6873914d2fee24252b2053c4369adc61e1ab5263ab59f38784'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set012-q010-audio', 'Part 1 Question 153 Audio', 'Soobin: The kitchen is where everyone gathers for meals, and the living room has the biggest television. My favourite room is the bathroom. It may sound unusual, but it is the place in the house. I like having a long shower after work, and nobody interrupts me there. The room also has a large window that brings in plenty of natural light. The other features were noticeable but were less important in the description.', '{"source_key":"listening-p1-set012-q010-audio","skill":"listening","part_number":1,"transcript":"Soobin: The kitchen is where everyone gathers for meals, and the living room has the biggest television. My favourite room is the bathroom. It may sound unusual, but it is the place in the house. I like having a long shower after work, and nobody interrupts me there. The room also has a large window that brings in plenty of natural light. The other features were noticeable but were less important in the description.","transcript_status":"source_word_comment","word_comment_ids":["152"],"speaker_labels":["Soobin"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'a35de66f4d572ec71dfe83f350947c9acb8668b9f90b9d2a0a07c434c839856e'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set012-q011-audio', 'Part 1 Question 154 Audio', 'Woman: I often go out with friends at weekends, and I occasionally visit a café on Sunday afternoon. Last week, however, I stayed at home. The weather was terrible, so I cooked a large meal, watched two films and finally finished a book I had been reading for months. It was not exciting, but I felt rested by Monday morning. The alternatives remained possible on another occasion, but not this time.', '{"source_key":"listening-p1-set012-q011-audio","skill":"listening","part_number":1,"transcript":"Woman: I often go out with friends at weekends, and I occasionally visit a café on Sunday afternoon. Last week, however, I stayed at home. The weather was terrible, so I cooked a large meal, watched two films and finally finished a book I had been reading for months. It was not exciting, but I felt rested by Monday morning. The alternatives remained possible on another occasion, but not this time.","transcript_status":"source_word_comment","word_comment_ids":["153"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'fce31fdec3ca1204b01f8cf6fbac7b3ac0b72dbea01175e0cbc91d8473019f91'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set012-q012-audio', 'Part 1 Question 155 Audio', 'Saleswoman: The living room looks very spacious because of its high ceiling, and the main bedroom has enough space for large furniture. However, the kitchen is the largest room in the property. It includes a dining area and doors leading to the garden. The previous owners extended it several years ago, so it is ideal for a family that enjoys cooking and entertaining. Signs in the area should guide visitors through the final part of the journey.', '{"source_key":"listening-p1-set012-q012-audio","skill":"listening","part_number":1,"transcript":"Saleswoman: The living room looks very spacious because of its high ceiling, and the main bedroom has enough space for large furniture. However, the kitchen is the largest room in the property. It includes a dining area and doors leading to the garden. The previous owners extended it several years ago, so it is ideal for a family that enjoys cooking and entertaining. Signs in the area should guide visitors through the final part of the journey.","transcript_status":"source_word_comment","word_comment_ids":["154"],"speaker_labels":["Saleswoman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'f4ae6fc3113c68e9b778d3a5557236bf2163c8dc273a67af1d33e677a93adca3'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set012-q013-audio', 'Part 1 Question 156 Audio', 'Friend 1: The forecast has changed again. I hoped the trip would be hot and sunny, and yesterday they predicted mild, dry weather. Friend 2: Unfortunately, it will be cold and wet. We should take waterproof jackets and warm clothes. Friend 1: At least the hotel has an indoor pool, and we can move the picnic to another day if the rain continues. After making the decision, the remaining arrangements were straightforward.', '{"source_key":"listening-p1-set012-q013-audio","skill":"listening","part_number":1,"transcript":"Friend 1: The forecast has changed again. I hoped the trip would be hot and sunny, and yesterday they predicted mild, dry weather. Friend 2: Unfortunately, it will be cold and wet. We should take waterproof jackets and warm clothes. Friend 1: At least the hotel has an indoor pool, and we can move the picnic to another day if the rain continues. After making the decision, the remaining arrangements were straightforward.","transcript_status":"source_word_comment","word_comment_ids":["155"],"speaker_labels":["Friend 1"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'c21451e512619f9423896b1b3ef4439ec328c8698cd73d12fe00694e5a1ad8ac'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set013-q001-audio', 'Part 1 Question 157 Audio', 'Jana: My sister is not blonde; she has dark brown hair like mine. People often expect her to be tall because everyone else in our family is, but she is short. She is only a little over one metre fifty. That makes us easy to tell apart in photographs, although our faces and voices are similar enough to confuse people on the phone. People focusing only on the first detail could easily misunderstand the speaker.', '{"source_key":"listening-p1-set013-q001-audio","skill":"listening","part_number":1,"transcript":"Jana: My sister is not blonde; she has dark brown hair like mine. People often expect her to be tall because everyone else in our family is, but she is short. She is only a little over one metre fifty. That makes us easy to tell apart in photographs, although our faces and voices are similar enough to confuse people on the phone. People focusing only on the first detail could easily misunderstand the speaker.","transcript_status":"source_word_comment","word_comment_ids":["156"],"speaker_labels":["Jana"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'c61672f6df6b612c57621dfd6b55e7351ec66b84e6b501443424b43ee0b09029'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set013-q002-audio', 'Part 1 Question 158 Audio', 'Man: I sometimes eat at eight if I work late, and five o''clock is when I usually have a small snack. My normal evening meal is at seven o''clock. That gives me time to cook after work without eating too close to bedtime. At weekends, the schedule is less regular because I may meet friends or have a larger lunch with my family. There was still enough time to arrive, prepare and deal with any small delay.', '{"source_key":"listening-p1-set013-q002-audio","skill":"listening","part_number":1,"transcript":"Man: I sometimes eat at eight if I work late, and five o''clock is when I usually have a small snack. My normal evening meal is at seven o''clock. That gives me time to cook after work without eating too close to bedtime. At weekends, the schedule is less regular because I may meet friends or have a larger lunch with my family. There was still enough time to arrive, prepare and deal with any small delay.","transcript_status":"source_word_comment","word_comment_ids":["157"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '5deb772c4655357da7fc38e4ade5da44e49d2c115273d111cbe595dcf02ad532'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set013-q003-audio', 'Part 1 Question 159 Audio', 'Professor: Your report is progressing well, and I do not want another essay from you this term. I would like you to speak at the conference next month. Your research would be valuable to the audience, and the presentation only needs to last ten minutes. Start with the main result, use a few clear slides and leave time for at the end. Nothing else needed to change once the main decision had been made.', '{"source_key":"listening-p1-set013-q003-audio","skill":"listening","part_number":1,"transcript":"Professor: Your report is progressing well, and I do not want another essay from you this term. I would like you to speak at the conference next month. Your research would be valuable to the audience, and the presentation only needs to last ten minutes. Start with the main result, use a few clear slides and leave time for at the end. Nothing else needed to change once the main decision had been made.","transcript_status":"source_word_comment","word_comment_ids":["158"],"speaker_labels":["Professor"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '15957667f4f6f36f7b08056023de12f82de69111bb242dd0931daea676df999f'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set013-q004-audio', 'Part 1 Question 160 Audio', 'Woman: Was sport your favourite part of school? Man: I enjoyed football, but I was never especially good at it. Maths lessons were useful, although I found them stressful. My favourite thing was history classes. Our teacher told stories rather than simply giving us dates, and the class often discussed why people made particular decisions. That subject first made me interested in reading non-fiction. The later details made the distinction much clearer than the first impression.', '{"source_key":"listening-p1-set013-q004-audio","skill":"listening","part_number":1,"transcript":"Woman: Was sport your favourite part of school? Man: I enjoyed football, but I was never especially good at it. Maths lessons were useful, although I found them stressful. My favourite thing was history classes. Our teacher told stories rather than simply giving us dates, and the class often discussed why people made particular decisions. That subject first made me interested in reading non-fiction. The later details made the distinction much clearer than the first impression.","transcript_status":"source_word_comment","word_comment_ids":["159"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'c2031736d74ad7c5b42c0e315104f237eea0d7cc9fc1ada2bfdbb95797427d77'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set013-q005-audio', 'Part 1 Question 161 Audio', 'Radio presenter: The melody of the new song is pleasant, and the rhythm makes it easy to dance to. The most attractive part, however, is the words. They tell a simple but emotional story that many listeners can recognise. The singer delivers them clearly, and several lines stay in your mind long after the music has finished. That is probably why the song became popular so', '{"source_key":"listening-p1-set013-q005-audio","skill":"listening","part_number":1,"transcript":"Radio presenter: The melody of the new song is pleasant, and the rhythm makes it easy to dance to. The most attractive part, however, is the words. They tell a simple but emotional story that many listeners can recognise. The singer delivers them clearly, and several lines stay in your mind long after the music has finished. That is probably why the song became popular so","transcript_status":"source_word_comment","word_comment_ids":["160"],"speaker_labels":["Radio presenter"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '62b8d0c1ae0541887802b455d524714969187a17feaa734ac5f8b115e165b121'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set013-q006-audio', 'Part 1 Question 162 Audio', 'Man: There are few factories in this area, and traffic is much lighter than in the city. The main cause of poor air is fires in the countryside. During dry periods, farmers and landowners sometimes burn vegetation, and the smoke spreads across nearby villages. On still days it can remain in the air for hours, so residents are advised to keep windows closed. That detail changed how everyone involved understood the problem.', '{"source_key":"listening-p1-set013-q006-audio","skill":"listening","part_number":1,"transcript":"Man: There are few factories in this area, and traffic is much lighter than in the city. The main cause of poor air is fires in the countryside. During dry periods, farmers and landowners sometimes burn vegetation, and the smoke spreads across nearby villages. On still days it can remain in the air for hours, so residents are advised to keep windows closed. That detail changed how everyone involved understood the problem.","transcript_status":"source_word_comment","word_comment_ids":["161"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'd551b89d80e5338139b088406fcb47890c050ac513c1f997eb77f00e088815b6'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set013-q007-audio', 'Part 1 Question 163 Audio', 'Stephanie: I am applying for the childcare position. The advertisement says applicants must be over twenty, and I know some parents assumed I was twenty-five or even thirty because of my previous experience. I am twenty-one. I have completed a childcare course, worked at a summer camp and regularly looked after two younger cousins. I can also provide references from both families. The comparison became easier once the less important details were separated.', '{"source_key":"listening-p1-set013-q007-audio","skill":"listening","part_number":1,"transcript":"Stephanie: I am applying for the childcare position. The advertisement says applicants must be over twenty, and I know some parents assumed I was twenty-five or even thirty because of my previous experience. I am twenty-one. I have completed a childcare course, worked at a summer camp and regularly looked after two younger cousins. I can also provide references from both families. The comparison became easier once the less important details were separated.","transcript_status":"source_word_comment","word_comment_ids":["162"],"speaker_labels":["Stephanie"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '54aa844d95102db381476b4fa45f9dfef81a4722351b24294dd5058042deb59b'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set013-q008-audio', 'Part 1 Question 164 Audio', 'Man: We could go to the movies, but neither of us has checked what is showing. Woman: Staying at home is another option, although the weather may improve later. Man: Let''s make plans later, after we finish work and know how tired we feel. Woman: Agreed. I''ll call around six, and then we can decide whether to go out or cook something at home. After making the decision, the remaining arrangements were straightforward.', '{"source_key":"listening-p1-set013-q008-audio","skill":"listening","part_number":1,"transcript":"Man: We could go to the movies, but neither of us has checked what is showing. Woman: Staying at home is another option, although the weather may improve later. Man: Let''s make plans later, after we finish work and know how tired we feel. Woman: Agreed. I''ll call around six, and then we can decide whether to go out or cook something at home. After making the decision, the remaining arrangements were straightforward.","transcript_status":"source_word_comment","word_comment_ids":["163"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '355079601a40d5fc23905342bae560c7c502468dcfd78eed30cfaa553bbbba14'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set013-q009-audio', 'Part 1 Question 165 Audio', 'Woman: I considered a holiday at the beach because I enjoy swimming, and a city break would offer plenty of museums and restaurants. This year I''m going to the mountains. I have booked a small cabin near several walking routes. I want fresh air, evenings and a chance to spend time outdoors without the noise and crowds I experience at home. The nearby landmarks were useful, although neither was the destination itself.', '{"source_key":"listening-p1-set013-q009-audio","skill":"listening","part_number":1,"transcript":"Woman: I considered a holiday at the beach because I enjoy swimming, and a city break would offer plenty of museums and restaurants. This year I''m going to the mountains. I have booked a small cabin near several walking routes. I want fresh air, evenings and a chance to spend time outdoors without the noise and crowds I experience at home. The nearby landmarks were useful, although neither was the destination itself.","transcript_status":"source_word_comment","word_comment_ids":["164"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '44adc7b538b037dfd8a58cf05ac15c1e65da0688d5c99b04ca276aa5017d9b52'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set013-q010-audio', 'Part 1 Question 166 Audio', 'Tour guide: The group should not wait in the hotel lobby because the driver cannot see us there. The train station is part of tomorrow''s journey, not today''s. We will wait by the hotel''s main entrance. Please be there ten minutes before departure, keep your luggage together and tell me immediately if someone from your room has not arrived. Anyone following the directions carefully should reach the correct place without difficulty.', '{"source_key":"listening-p1-set013-q010-audio","skill":"listening","part_number":1,"transcript":"Tour guide: The group should not wait in the hotel lobby because the driver cannot see us there. The train station is part of tomorrow''s journey, not today''s. We will wait by the hotel''s main entrance. Please be there ten minutes before departure, keep your luggage together and tell me immediately if someone from your room has not arrived. Anyone following the directions carefully should reach the correct place without difficulty.","transcript_status":"source_word_comment","word_comment_ids":["165"],"speaker_labels":["Tour guide"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'd30102e1f94e87985533861c882c22a94f8f91c30ec3822dffe9c5f8d9468d1f'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set013-q011-audio', 'Part 1 Question 167 Audio', 'Tour guide: We will walk through the park in the morning and return to the hotel after the evening meal. Tea will be served on the river boat during the afternoon. Tables will already be prepared when we board, and you can enjoy the city view while the boat moves slowly downstream. Please tell staff in advance if you need a vegetarian snack. The final location also allowed the group to continue the journey together.', '{"source_key":"listening-p1-set013-q011-audio","skill":"listening","part_number":1,"transcript":"Tour guide: We will walk through the park in the morning and return to the hotel after the evening meal. Tea will be served on the river boat during the afternoon. Tables will already be prepared when we board, and you can enjoy the city view while the boat moves slowly downstream. Please tell staff in advance if you need a vegetarian snack. The final location also allowed the group to continue the journey together.","transcript_status":"source_word_comment","word_comment_ids":["166"],"speaker_labels":["Tour guide"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'bc2ddd4ffb739366c180d9ecee35fcdc650ba9cd45a88283a607c6b908c4dd6f'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set013-q012-audio', 'Part 1 Question 168 Audio', 'Man: The concert includes a fireworks display during the interval, and a famous singer will appear earlier as a special guest. The event will end with the city''s favourite group. They have not performed locally for several years, so organisers expect a large crowd to stay for the final set. Extra buses will leave the square shortly after the music finishes. The choice fitted the situation better than the other ideas they had discussed.', '{"source_key":"listening-p1-set013-q012-audio","skill":"listening","part_number":1,"transcript":"Man: The concert includes a fireworks display during the interval, and a famous singer will appear earlier as a special guest. The event will end with the city''s favourite group. They have not performed locally for several years, so organisers expect a large crowd to stay for the final set. Extra buses will leave the square shortly after the music finishes. The choice fitted the situation better than the other ideas they had discussed.","transcript_status":"source_word_comment","word_comment_ids":["167"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '2174f6e58e39457d7c764ef26f99a590df64104d2d667c765037b0c3bae01d50'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set013-q013-audio', 'Part 1 Question 169 Audio', 'Alice: I''m in a panic. I thought I had lost a book, but it was still on my desk, and my laptop is safely in its case. Friend: What''s missing then? Alice: I cannot find my phone. I last used it while paying at the café, so I may have left it on the counter. Could you call the café for me? Friend: Of course! Have you tried ringing it? Alice: I have already tried several times, but nobody has answered yet.', '{"source_key":"listening-p1-set013-q013-audio","skill":"listening","part_number":1,"transcript":"Alice: I''m in a panic. I thought I had lost a book, but it was still on my desk, and my laptop is safely in its case. Friend: What''s missing then? Alice: I cannot find my phone. I last used it while paying at the café, so I may have left it on the counter. Could you call the café for me? Friend: Of course! Have you tried ringing it? Alice: I have already tried several times, but nobody has answered yet.","transcript_status":"source_word_comment","word_comment_ids":["168"],"speaker_labels":["Alice"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'c4a019b6ec041ab04cf3a6f2b4733f7c04579e110225d18db0210ea163bd299c'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set014-q001-audio', 'Part 1 Question 170 Audio', 'Woman: We took a beach trip two years ago and have discussed doing a long road trip in the future. Last year, the family went camping. We stayed beside a lake for four nights, cooked outside and walked in the forest each day. The weather was colder than expected, but the children loved sleeping in a tent and asked to go again. The alternatives remained possible on another occasion, but not this time.', '{"source_key":"listening-p1-set014-q001-audio","skill":"listening","part_number":1,"transcript":"Woman: We took a beach trip two years ago and have discussed doing a long road trip in the future. Last year, the family went camping. We stayed beside a lake for four nights, cooked outside and walked in the forest each day. The weather was colder than expected, but the children loved sleeping in a tent and asked to go again. The alternatives remained possible on another occasion, but not this time.","transcript_status":"source_word_comment","word_comment_ids":["169"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'af98414664d58637e5c2da24a71367e40ffd7fe9b75b25cf9d78ae0ef0b6d187'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set014-q002-audio', 'Part 1 Question 171 Audio', 'Woman: These cleaning products are on sale today. The larger branded bottle costs two pounds, and the three-pound price is for a pack containing several items. The product I need is one pound fifty. I''ll buy two because we use it regularly. The shop is small, but its weekly offers are often better than the prices at the supermarket. A second check confirmed that no part of the total had been counted twice.', '{"source_key":"listening-p1-set014-q002-audio","skill":"listening","part_number":1,"transcript":"Woman: These cleaning products are on sale today. The larger branded bottle costs two pounds, and the three-pound price is for a pack containing several items. The product I need is one pound fifty. I''ll buy two because we use it regularly. The shop is small, but its weekly offers are often better than the prices at the supermarket. A second check confirmed that no part of the total had been counted twice.","transcript_status":"source_word_comment","word_comment_ids":["170"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '7a063aa86a9e39999760f4bfe34fa98a79efa9b72bc4989b6ff15d8d47121c19'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set014-q003-audio', 'Part 1 Question 172 Audio', 'Weather presenter: The west will be cloudy but mostly dry, while the south can expect strong winds and occasional rain. The weather will be best in the east. That area should have sunshine for most of the day, with mild temperatures and only light winds. Anyone planning outdoor activities should still take a jacket because conditions may become cooler during the evening. The chosen place was more convenient and easier for everyone to find.', '{"source_key":"listening-p1-set014-q003-audio","skill":"listening","part_number":1,"transcript":"Weather presenter: The west will be cloudy but mostly dry, while the south can expect strong winds and occasional rain. The weather will be best in the east. That area should have sunshine for most of the day, with mild temperatures and only light winds. Anyone planning outdoor activities should still take a jacket because conditions may become cooler during the evening. The chosen place was more convenient and easier for everyone to find.","transcript_status":"source_word_comment","word_comment_ids":["171"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '01124a3eb3288d6c1bc57f6b82570669ffd4f96d3314630c651aade33df68af5'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set014-q004-audio', 'Part 1 Question 173 Audio', 'Travel representative: Today''s flight is not cancelled because of a staff shortage, and engineers have found no technical problem with the aircraft. The reason is poor weather conditions at the destination. Strong winds make landing unsafe. Passengers can move to tomorrow''s flight, take the available train service or speak to us about a refund at the customer-service desk. The surrounding facts supported that explanation more strongly than the alternatives.', '{"source_key":"listening-p1-set014-q004-audio","skill":"listening","part_number":1,"transcript":"Travel representative: Today''s flight is not cancelled because of a staff shortage, and engineers have found no technical problem with the aircraft. The reason is poor weather conditions at the destination. Strong winds make landing unsafe. Passengers can move to tomorrow''s flight, take the available train service or speak to us about a refund at the customer-service desk. The surrounding facts supported that explanation more strongly than the alternatives.","transcript_status":"source_word_comment","word_comment_ids":["172"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'f82bfd189b034de98732121b8c589775a6b48195dea47826e18c4569a24c3cf3'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set014-q005-audio', 'Part 1 Question 174 Audio', 'Man: Last year, I went hiking once and swam when the weather was warm. The activity I enjoyed most was cycling through the countryside. The roads were , the views were excellent and we could stop whenever we wanted. One afternoon, we found a small village café and stayed there for nearly an hour before continuing the journey. That option matched the person''s needs more closely than the alternatives.', '{"source_key":"listening-p1-set014-q005-audio","skill":"listening","part_number":1,"transcript":"Man: Last year, I went hiking once and swam when the weather was warm. The activity I enjoyed most was cycling through the countryside. The roads were , the views were excellent and we could stop whenever we wanted. One afternoon, we found a small village café and stayed there for nearly an hour before continuing the journey. That option matched the person''s needs more closely than the alternatives.","transcript_status":"source_word_comment","word_comment_ids":["173"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'e189306995428f0f4250841ca8b63ee40c2193693214d0be8afea359e4bfb1f6'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set014-q006-audio', 'Part 1 Question 175 Audio', 'Man: The train is not always the cheapest option, and some seats can be uncomfortable when the service is crowded. I prefer it because it is practical. It avoids the worst traffic, runs at useful times and takes me close to the office. I can also read or answer messages during the journey instead of concentrating on driving the whole way. The clarification prevented the same misunderstanding from affecting the next decision.', '{"source_key":"listening-p1-set014-q006-audio","skill":"listening","part_number":1,"transcript":"Man: The train is not always the cheapest option, and some seats can be uncomfortable when the service is crowded. I prefer it because it is practical. It avoids the worst traffic, runs at useful times and takes me close to the office. I can also read or answer messages during the journey instead of concentrating on driving the whole way. The clarification prevented the same misunderstanding from affecting the next decision.","transcript_status":"source_word_comment","word_comment_ids":["174"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'aa7eaf60e7c61b3da73ae752aaf13b1283a2644e016e46721addee99d520d50f'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set014-q007-audio', 'Part 1 Question 176 Audio', 'Man: I''m at the new coffee shop. Do you know where to find it? Friend: I''m not sure, can you describe it? Man: The coffee shop is not inside the shopping centre, although you can see that building from the street. It is also not next to the bookstore. The shop is opposite the gift shop, beside a small pharmacy. Friend: Ah, I think I know it! Man: I''ll wait at a table near the window. If you come from the station, cross at the traffic lights and you should see it immediately.', '{"source_key":"listening-p1-set014-q007-audio","skill":"listening","part_number":1,"transcript":"Man: I''m at the new coffee shop. Do you know where to find it? Friend: I''m not sure, can you describe it? Man: The coffee shop is not inside the shopping centre, although you can see that building from the street. It is also not next to the bookstore. The shop is opposite the gift shop, beside a small pharmacy. Friend: Ah, I think I know it! Man: I''ll wait at a table near the window. If you come from the station, cross at the traffic lights and you should see it immediately.","transcript_status":"source_word_comment","word_comment_ids":["175"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '396e18efc0c3dea98d65b184606b4683f7a7696375ebd90ee3bcbf8a272e69c5'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set014-q008-audio', 'Part 1 Question 177 Audio', 'Tom: Hi Mum, I wanted to update you about this weekend. Mother: Of course! Are your aunt and uncle still coming? Tom: No, they''re not coming, and my cousin has exams. My sister and her children are visiting instead. Mother: Oh how lovely! When do they arrive? Tom: They will arrive on Saturday morning and stay for two nights. I have prepared the spare room, but I still need to find some games for the children and buy enough food for everyone. Mother: That''s wonderful, they''ll love it.', '{"source_key":"listening-p1-set014-q008-audio","skill":"listening","part_number":1,"transcript":"Tom: Hi Mum, I wanted to update you about this weekend. Mother: Of course! Are your aunt and uncle still coming? Tom: No, they''re not coming, and my cousin has exams. My sister and her children are visiting instead. Mother: Oh how lovely! When do they arrive? Tom: They will arrive on Saturday morning and stay for two nights. I have prepared the spare room, but I still need to find some games for the children and buy enough food for everyone. Mother: That''s wonderful, they''ll love it.","transcript_status":"source_word_comment","word_comment_ids":["176"],"speaker_labels":["Tom"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '9243225ea9d9ea34d82fb42a23680368976f6273ee88fdc17de8415f65166922'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set014-q009-audio', 'Part 1 Question 178 Audio', 'Woman: I do not expect writing to make me famous, and I know it may take a long time to earn much money. I want to become a writer because I hope to help people. Stories can make readers feel understood, introduce them to different experiences and explain difficult subjects in a personal way. I am especially interested in writing for teenagers who feel isolated or uncertain.', '{"source_key":"listening-p1-set014-q009-audio","skill":"listening","part_number":1,"transcript":"Woman: I do not expect writing to make me famous, and I know it may take a long time to earn much money. I want to become a writer because I hope to help people. Stories can make readers feel understood, introduce them to different experiences and explain difficult subjects in a personal way. I am especially interested in writing for teenagers who feel isolated or uncertain.","transcript_status":"source_word_comment","word_comment_ids":["177"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '1f30c4d6dcf559a9c2b1c44ee1be8cd472c9d293f03876c110bddd2f25c463cc'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set014-q010-audio', 'Part 1 Question 179 Audio', 'Brother: Lucy, I just finished my run. Is there anything to drink? Lucy: There is tea in the cupboard and coffee beside the kettle, but you said you wanted something simple after your run. Have some water. Brother: That sounds good actually. Lucy: I put a bottle in the fridge, and there are clean glasses on the table. Drink that first, then decide whether you still want anything else. You have not had enough to drink today. Brother: You''re right, thanks. I''ll have the water.', '{"source_key":"listening-p1-set014-q010-audio","skill":"listening","part_number":1,"transcript":"Brother: Lucy, I just finished my run. Is there anything to drink? Lucy: There is tea in the cupboard and coffee beside the kettle, but you said you wanted something simple after your run. Have some water. Brother: That sounds good actually. Lucy: I put a bottle in the fridge, and there are clean glasses on the table. Drink that first, then decide whether you still want anything else. You have not had enough to drink today. Brother: You''re right, thanks. I''ll have the water.","transcript_status":"source_word_comment","word_comment_ids":["178"],"speaker_labels":["Brother"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '969d5bb80ec554d511a9e9ccde3b4e85051999cc91384135908145981c2fe21d'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set014-q011-audio', 'Part 1 Question 180 Audio', 'Lucy: My sister is not simply taller than me, and we are certainly not completely different. We have similar characters. We are both calm in difficult situations, enjoy planning things carefully and need time alone after a busy day. Our appearance and hobbies are not identical, but friends often say our reactions and sense of humour are surprisingly alike. The full description explained why the earlier possibilities had sounded convincing.', '{"source_key":"listening-p1-set014-q011-audio","skill":"listening","part_number":1,"transcript":"Lucy: My sister is not simply taller than me, and we are certainly not completely different. We have similar characters. We are both calm in difficult situations, enjoy planning things carefully and need time alone after a busy day. Our appearance and hobbies are not identical, but friends often say our reactions and sense of humour are surprisingly alike. The full description explained why the earlier possibilities had sounded convincing.","transcript_status":"source_word_comment","word_comment_ids":["179"],"speaker_labels":["Lucy"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'fcec2bad3eacfe47c846c38dd10de8ff680d47749314f09b75922a297734d48a'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set014-q012-audio', 'Part 1 Question 181 Audio', 'Woman: Are you going to buy the T-shirt? Man: It is too casual for the new job, and I already own a hat. I need a suit for the office. This dark grey one fits well and can be worn with several shirts. Woman: Try the jacket once more before paying. Man: Good idea. I also need the trousers shortened slightly. The other possibilities were useful to discuss but were not selected.', '{"source_key":"listening-p1-set014-q012-audio","skill":"listening","part_number":1,"transcript":"Woman: Are you going to buy the T-shirt? Man: It is too casual for the new job, and I already own a hat. I need a suit for the office. This dark grey one fits well and can be worn with several shirts. Woman: Try the jacket once more before paying. Man: Good idea. I also need the trousers shortened slightly. The other possibilities were useful to discuss but were not selected.","transcript_status":"source_word_comment","word_comment_ids":["180"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'b3856f435083657ce458ff3678ebe9c83b51c7f827d5c37d6959680d1411d079'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set014-q013-audio', 'Part 1 Question 182 Audio', 'Tour guide: Some birds fly south in winter, and all species must continue searching for food. The birds we are observing behave differently: they stay together in groups for protection. A large group makes it easier to notice danger and helps them conserve warmth during cold nights. You may see several hundred gathering in the trees shortly before the sun goes down. That option matched the person''s needs more closely than the alternatives.', '{"source_key":"listening-p1-set014-q013-audio","skill":"listening","part_number":1,"transcript":"Tour guide: Some birds fly south in winter, and all species must continue searching for food. The birds we are observing behave differently: they stay together in groups for protection. A large group makes it easier to notice danger and helps them conserve warmth during cold nights. You may see several hundred gathering in the trees shortly before the sun goes down. That option matched the person''s needs more closely than the alternatives.","transcript_status":"source_word_comment","word_comment_ids":["181"],"speaker_labels":["Tour guide"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '205b10585e25f3bf88eac9b3d19dde6c3d68363567a9de90fbd2eb8dfeb503df'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set015-q001-audio', 'Part 1 Question 183 Audio', 'Man: Walk along the river for a few minutes, but do not cross the bridge. You will pass a shopping mall on your right. The football club is near a park, directly behind the children''s playground. The entrance has a large blue sign. Training starts at six, so arrive early because the changing rooms can become crowded. The final location also allowed the group to continue the journey together.', '{"source_key":"listening-p1-set015-q001-audio","skill":"listening","part_number":1,"transcript":"Man: Walk along the river for a few minutes, but do not cross the bridge. You will pass a shopping mall on your right. The football club is near a park, directly behind the children''s playground. The entrance has a large blue sign. Training starts at six, so arrive early because the changing rooms can become crowded. The final location also allowed the group to continue the journey together.","transcript_status":"source_word_comment","word_comment_ids":["182"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '18414775fa82bc19f4f14fe0565b1dfe5786f7ba3892e010c82fb6d7cd8821cf'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set015-q002-audio', 'Part 1 Question 184 Audio', 'Boy: My cat sometimes chases mice in the garden and watches birds through the window, but I do not feed it either of those. I give the cat fish. Usually it eats prepared cat food, but twice a week I add a small amount of cooked fish. I also make sure there is fresh water beside the bowl throughout the day. The choice fitted the situation better than the other ideas they had discussed.', '{"source_key":"listening-p1-set015-q002-audio","skill":"listening","part_number":1,"transcript":"Boy: My cat sometimes chases mice in the garden and watches birds through the window, but I do not feed it either of those. I give the cat fish. Usually it eats prepared cat food, but twice a week I add a small amount of cooked fish. I also make sure there is fresh water beside the bowl throughout the day. The choice fitted the situation better than the other ideas they had discussed.","transcript_status":"source_word_comment","word_comment_ids":["183"],"speaker_labels":["Boy"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '3c328eff40cbf45cfdfd544320f178af98768398c9676980c6dee1f6cefd2e32'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set015-q003-audio', 'Part 1 Question 185 Audio', 'Jack: Mum, I need to buy something for my sister''s birthday. Any ideas? Mother: What about some clothes or a toy? Jack: She already has plenty of clothes, and Dad is getting her a toy she asked for. I''m going to buy chocolates instead. Mother: That''s a lovely idea! Jack: She likes the dark ones with nuts, so I''ll choose a mixed box. Could you remind me which shop sells the brand she prefers? Mother: I think it''s the one near the post office. I''ll send you the name.', '{"source_key":"listening-p1-set015-q003-audio","skill":"listening","part_number":1,"transcript":"Jack: Mum, I need to buy something for my sister''s birthday. Any ideas? Mother: What about some clothes or a toy? Jack: She already has plenty of clothes, and Dad is getting her a toy she asked for. I''m going to buy chocolates instead. Mother: That''s a lovely idea! Jack: She likes the dark ones with nuts, so I''ll choose a mixed box. Could you remind me which shop sells the brand she prefers? Mother: I think it''s the one near the post office. I''ll send you the name.","transcript_status":"source_word_comment","word_comment_ids":["184"],"speaker_labels":["Jack"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '24de15674722edffd8bfa9e4d9f7e2c3fb0efea1a718d5df9f4059947f83f93c'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set015-q004-audio', 'Part 1 Question 186 Audio', 'Woman: I run regularly at home and sometimes go on a bike ride with friends. During the holiday, I''m going to go for a walk each day. The area has several coastal paths and a route through the hills. Walking will let me explore slowly and stop for photographs. I''ll take comfortable shoes and a light waterproof jacket in case the weather changes. The alternatives remained possible on another occasion, but not this time.', '{"source_key":"listening-p1-set015-q004-audio","skill":"listening","part_number":1,"transcript":"Woman: I run regularly at home and sometimes go on a bike ride with friends. During the holiday, I''m going to go for a walk each day. The area has several coastal paths and a route through the hills. Walking will let me explore slowly and stop for photographs. I''ll take comfortable shoes and a light waterproof jacket in case the weather changes. The alternatives remained possible on another occasion, but not this time.","transcript_status":"source_word_comment","word_comment_ids":["185"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '76362ba8fd043d6d74a2ad6727ba417f7e62509bc35780e98cb1b9584f2d2edf'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set015-q005-audio', 'Part 1 Question 187 Audio', 'Woman: The mall near my house has become rather old, and the boutique is too expensive for everyday clothes. I''m going shopping at a new shopping centre on the other side of town. It opened last week and has a wider range of stores. There is a direct bus from my street, so I will not have to worry about parking. Signs in the area should guide visitors through the final part of the journey.', '{"source_key":"listening-p1-set015-q005-audio","skill":"listening","part_number":1,"transcript":"Woman: The mall near my house has become rather old, and the boutique is too expensive for everyday clothes. I''m going shopping at a new shopping centre on the other side of town. It opened last week and has a wider range of stores. There is a direct bus from my street, so I will not have to worry about parking. Signs in the area should guide visitors through the final part of the journey.","transcript_status":"source_word_comment","word_comment_ids":["186"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'f8b7b819207eb1a9e1d1a96f72bf8f01954f81d6575e7b4a913c4a6f7b0f0a48'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set015-q006-audio', 'Part 1 Question 188 Audio', 'Friend: Jorge, what time does our match start? I thought it was three. Jorge: No, three is when the next game begins. Five o''clock is when we expect to be home. Our match starts at one p.m. Friend: Oh, that''s much earlier than I thought! Jorge: Yes. We should arrive by half past twelve to find seats and buy food. I''ll meet you outside the main gate near the ticket office. Friend: Perfect, I''ll be there by twelve.', '{"source_key":"listening-p1-set015-q006-audio","skill":"listening","part_number":1,"transcript":"Friend: Jorge, what time does our match start? I thought it was three. Jorge: No, three is when the next game begins. Five o''clock is when we expect to be home. Our match starts at one p.m. Friend: Oh, that''s much earlier than I thought! Jorge: Yes. We should arrive by half past twelve to find seats and buy food. I''ll meet you outside the main gate near the ticket office. Friend: Perfect, I''ll be there by twelve.","transcript_status":"source_word_comment","word_comment_ids":["187"],"speaker_labels":["Friend"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '29e519a724fe54709fcb6a2879c332f7410c4794ec5d50f177a65b14afd981d3'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set015-q007-audio', 'Part 1 Question 189 Audio', 'Man: The sports building at my school is green, and the science block was painted blue last summer. The teachers'' building is white. It stands near the main entrance and has a clock above the doors. New students often use it as a landmark because it can be seen from almost every part of the central playground. People focusing only on the first detail could easily misunderstand the speaker.', '{"source_key":"listening-p1-set015-q007-audio","skill":"listening","part_number":1,"transcript":"Man: The sports building at my school is green, and the science block was painted blue last summer. The teachers'' building is white. It stands near the main entrance and has a clock above the doors. New students often use it as a landmark because it can be seen from almost every part of the central playground. People focusing only on the first detail could easily misunderstand the speaker.","transcript_status":"source_word_comment","word_comment_ids":["188"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'dd2394af74c0b46df7e75c6baf04fdca1fac0129bc8fe9f8b7123cd344d9ad40'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set015-q008-audio', 'Part 1 Question 190 Audio', 'James: My mother and aunt did not have similar hairstyles, and their eye colours were different. What made them look alike was that they were both thin. Old family photographs show this clearly, even though they wore very different clothes. As they grew older, their faces remained similar, but my aunt became much shorter than my mother. The most important feature appeared before the speaker moved on to other information.', '{"source_key":"listening-p1-set015-q008-audio","skill":"listening","part_number":1,"transcript":"James: My mother and aunt did not have similar hairstyles, and their eye colours were different. What made them look alike was that they were both thin. Old family photographs show this clearly, even though they wore very different clothes. As they grew older, their faces remained similar, but my aunt became much shorter than my mother. The most important feature appeared before the speaker moved on to other information.","transcript_status":"source_word_comment","word_comment_ids":["189"],"speaker_labels":["James"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '0449694e5726eb7ec25f01240a510ae10fc3d9b679909e5965e92eae685b9953'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set015-q009-audio', 'Part 1 Question 191 Audio', 'Sarah: I sometimes watch television and read when I want a evening. In my free time, though, I usually go to the theatre and play sports. I attend a live performance about once a month and play tennis at weekends. I enjoy the variety: the theatre gives me new ideas, while sport keeps me active and helps me meet people. Nothing else needed to change once the main decision had been made.', '{"source_key":"listening-p1-set015-q009-audio","skill":"listening","part_number":1,"transcript":"Sarah: I sometimes watch television and read when I want a evening. In my free time, though, I usually go to the theatre and play sports. I attend a live performance about once a month and play tennis at weekends. I enjoy the variety: the theatre gives me new ideas, while sport keeps me active and helps me meet people. Nothing else needed to change once the main decision had been made.","transcript_status":"source_word_comment","word_comment_ids":["190"],"speaker_labels":["Sarah"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '29218ac5160c50c2b289efc2c324814171532ff31c8b50711da4342edbdbe4f2'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set015-q010-audio', 'Part 1 Question 192 Audio', 'Tour guide: Museum visits are arranged for the morning, and swimming is available before breakfast or after dinner. In the afternoon, guests can play golf. Equipment can be hired at the course, and beginners may book a short lesson. Anyone who does not want to play can relax at the hotel or join a guided walk through the nearby village. The choice fitted the situation better than the other ideas they had discussed.', '{"source_key":"listening-p1-set015-q010-audio","skill":"listening","part_number":1,"transcript":"Tour guide: Museum visits are arranged for the morning, and swimming is available before breakfast or after dinner. In the afternoon, guests can play golf. Equipment can be hired at the course, and beginners may book a short lesson. Anyone who does not want to play can relax at the hotel or join a guided walk through the nearby village. The choice fitted the situation better than the other ideas they had discussed.","transcript_status":"source_word_comment","word_comment_ids":["191"],"speaker_labels":["Tour guide"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '9250d2b6fa8edc30bbbe58e7f08bfeaf72768111638e4b45d69858a1340aea86'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set015-q011-audio', 'Part 1 Question 193 Audio', 'Woman: We originally expected twenty-five people, but several have cancelled. Fifteen chairs would not be enough once the speakers and organisers are included. We need twenty chairs in total. Please arrange them in four rows of five and leave a clear path to the door. The tables can remain at the back for documents and drinks. No extra charge or item needed to be added to that figure.', '{"source_key":"listening-p1-set015-q011-audio","skill":"listening","part_number":1,"transcript":"Woman: We originally expected twenty-five people, but several have cancelled. Fifteen chairs would not be enough once the speakers and organisers are included. We need twenty chairs in total. Please arrange them in four rows of five and leave a clear path to the door. The tables can remain at the back for documents and drinks. No extra charge or item needed to be added to that figure.","transcript_status":"source_word_comment","word_comment_ids":["192"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'f07be384c824bdd756fb5d6e77a3b8d047a434201829ac11a247a48ef3488a47'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set015-q012-audio', 'Part 1 Question 194 Audio', 'Teacher: I printed the documents yesterday, and the caretaker is arranging the seating now. My current task is ordering the food for the meeting. I need to confirm vegetarian choices and the final number of guests before midday. The caterer also needs to know what time to deliver everything. After that, I''ll check the presentation equipment and place copies of the agenda on each table.', '{"source_key":"listening-p1-set015-q012-audio","skill":"listening","part_number":1,"transcript":"Teacher: I printed the documents yesterday, and the caretaker is arranging the seating now. My current task is ordering the food for the meeting. I need to confirm vegetarian choices and the final number of guests before midday. The caterer also needs to know what time to deliver everything. After that, I''ll check the presentation equipment and place copies of the agenda on each table.","transcript_status":"source_word_comment","word_comment_ids":["193"],"speaker_labels":["Teacher"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '083a5f2dfae5f224eb66563c986addc66088b59ee099824424fb61a308b1021c'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set015-q013-audio', 'Part 1 Question 195 Audio', 'Adam: Hi, could I borrow your computer this week? Friend: Sure, when exactly do you need it? Adam: I first thought I would need it on Tuesday, but the research session was moved. Thursday is when I collect the data. I will need the computer on Friday to analyse the results and prepare the report. Friend: No problem, Friday works for me. Adam: Great. I can return it on Saturday morning, and I will save all my work in a separate folder. Friend: Take your time, no rush.', '{"source_key":"listening-p1-set015-q013-audio","skill":"listening","part_number":1,"transcript":"Adam: Hi, could I borrow your computer this week? Friend: Sure, when exactly do you need it? Adam: I first thought I would need it on Tuesday, but the research session was moved. Thursday is when I collect the data. I will need the computer on Friday to analyse the results and prepare the report. Friend: No problem, Friday works for me. Adam: Great. I can return it on Saturday morning, and I will save all my work in a separate folder. Friend: Take your time, no rush.","transcript_status":"source_word_comment","word_comment_ids":["194"],"speaker_labels":["Adam"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'c4bc49bddcba3afb904ace1340d56ed087c0eb581e06bdcf5fe44a1a0a05aeb2'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set016-q001-audio', 'Part 1 Question 196 Audio', 'Actor: Watching movies is part of my work as well as something I enjoy, and I occasionally play video games with friends. In my free time, I most like drawing. I carry a small sketchbook when I travel and draw people, buildings or costumes. It helps me slow down and observe details that I might later use when preparing a character. After making the decision, the remaining arrangements were straightforward.', '{"source_key":"listening-p1-set016-q001-audio","skill":"listening","part_number":1,"transcript":"Actor: Watching movies is part of my work as well as something I enjoy, and I occasionally play video games with friends. In my free time, I most like drawing. I carry a small sketchbook when I travel and draw people, buildings or costumes. It helps me slow down and observe details that I might later use when preparing a character. After making the decision, the remaining arrangements were straightforward.","transcript_status":"source_word_comment","word_comment_ids":["195"],"speaker_labels":["Actor"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'd8cfefc3a18bdb07ea78d5ad5e895fc615c01b78aa782fa7dcfddb190ed76c16'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set016-q002-audio', 'Part 1 Question 197 Audio', 'Principal: The school already has a library, and improvements to the sports field will happen next year. Our new facility will be a performance space. It will include a stage, lighting and seating for a large audience. Students can use it for plays, concerts and presentations, while the community may hire it for events during school holidays. The other possibilities were useful to discuss but were not selected.', '{"source_key":"listening-p1-set016-q002-audio","skill":"listening","part_number":1,"transcript":"Principal: The school already has a library, and improvements to the sports field will happen next year. Our new facility will be a performance space. It will include a stage, lighting and seating for a large audience. Students can use it for plays, concerts and presentations, while the community may hire it for events during school holidays. The other possibilities were useful to discuss but were not selected.","transcript_status":"source_word_comment","word_comment_ids":["196"],"speaker_labels":["Principal"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'c79b5c6c4a4d6330e3a8cc952a7cf0ed80728ce926bf03c20389e2dd0459092b'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set016-q003-audio', 'Part 1 Question 198 Audio', 'Man: Dubai has excellent shopping, although I rarely have time for it, and the weather is sometimes too hot for me. What I enjoy is my job here. The project is challenging, the team is international and I am learning skills that will be useful later. I also like meeting clients from different industries during the business trip. That option matched the person''s needs more closely than the alternatives.', '{"source_key":"listening-p1-set016-q003-audio","skill":"listening","part_number":1,"transcript":"Man: Dubai has excellent shopping, although I rarely have time for it, and the weather is sometimes too hot for me. What I enjoy is my job here. The project is challenging, the team is international and I am learning skills that will be useful later. I also like meeting clients from different industries during the business trip. That option matched the person''s needs more closely than the alternatives.","transcript_status":"source_word_comment","word_comment_ids":["197"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '9a144a8f3cc0199fe77f751b705179f4b8d3d09b9528d94f17e810952fe85eb8'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set016-q004-audio', 'Part 1 Question 199 Audio', 'Teacher: Changing schools would be unnecessary, and the after-school programme is aimed at a different age group. Father: Then I will arrange private classes for him. He needs individual help with reading and confidence, not more homework in a large group. Teacher: I agree. A tutor once or twice a week should support what we are doing in class. Nothing else needed to change once the main decision had been made.', '{"source_key":"listening-p1-set016-q004-audio","skill":"listening","part_number":1,"transcript":"Teacher: Changing schools would be unnecessary, and the after-school programme is aimed at a different age group. Father: Then I will arrange private classes for him. He needs individual help with reading and confidence, not more homework in a large group. Teacher: I agree. A tutor once or twice a week should support what we are doing in class. Nothing else needed to change once the main decision had been made.","transcript_status":"source_word_comment","word_comment_ids":["198"],"speaker_labels":["Teacher"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'bf988fcc44b12e1b29078665c8619696c84fe1d5bf8ec3be51567f2bec6b9b7c'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set016-q005-audio', 'Part 1 Question 200 Audio', 'Man: I considered driving to the city, but parking is expensive and the roads will be busy. The train is fast, although the station is far from my hotel. I''m going by bus. It stops near my accommodation, allows one large bag and costs less than the train. I have booked a morning service so I will arrive before lunch. The choice fitted the situation better than the other ideas they had discussed.', '{"source_key":"listening-p1-set016-q005-audio","skill":"listening","part_number":1,"transcript":"Man: I considered driving to the city, but parking is expensive and the roads will be busy. The train is fast, although the station is far from my hotel. I''m going by bus. It stops near my accommodation, allows one large bag and costs less than the train. I have booked a morning service so I will arrive before lunch. The choice fitted the situation better than the other ideas they had discussed.","transcript_status":"source_word_comment","word_comment_ids":["199"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '0bd41a412df00671ed38f9a46e0dc6b838b4db1a2119fa4e73f1ef2bdf3dccd5'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set016-q006-audio', 'Part 1 Question 201 Audio', 'Lily: I sometimes do yoga before breakfast, and I watch television if I am very tired. In the evening, I usually go for a walk. I follow a route through the park for about thirty minutes. It helps me relax after work and gives me some fresh air. When the weather is bad, I walk around the shopping centre instead. It also left enough time and energy for the rest of the day.', '{"source_key":"listening-p1-set016-q006-audio","skill":"listening","part_number":1,"transcript":"Lily: I sometimes do yoga before breakfast, and I watch television if I am very tired. In the evening, I usually go for a walk. I follow a route through the park for about thirty minutes. It helps me relax after work and gives me some fresh air. When the weather is bad, I walk around the shopping centre instead. It also left enough time and energy for the rest of the day.","transcript_status":"source_word_comment","word_comment_ids":["200"],"speaker_labels":["Lily"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '75e7f37c937271383d19b71365732e2cd1856060b94f715f4be54621fc32f85b'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set016-q007-audio', 'Part 1 Question 202 Audio', 'Clerk: A one-day ticket is ten dollars, while thirty dollars buys a card that includes several regional services. The standard bus card costs twenty dollars. You can use it on all city buses for one week and add more credit later. Keep the receipt until you test the card, because the office can replace it immediately if it does not work. The final record was saved so the same confusion would not happen again.', '{"source_key":"listening-p1-set016-q007-audio","skill":"listening","part_number":1,"transcript":"Clerk: A one-day ticket is ten dollars, while thirty dollars buys a card that includes several regional services. The standard bus card costs twenty dollars. You can use it on all city buses for one week and add more credit later. Keep the receipt until you test the card, because the office can replace it immediately if it does not work. The final record was saved so the same confusion would not happen again.","transcript_status":"source_word_comment","word_comment_ids":["201"],"speaker_labels":["Clerk"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'ef2440129290620595002ea5c9f997a2729fcc8aa4d0d875159f6fed7e1e0061'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set016-q008-audio', 'Part 1 Question 203 Audio', 'Woman: I thought there were twenty pounds in the kitchen drawer, but part of that money was used for groceries. Thirty pounds was the amount before we paid the delivery driver. There are ten pounds left now. I put the note in an envelope beside the shopping list, so please do not use it unless you need something essential for dinner. A second check confirmed that no part of the total had been counted twice.', '{"source_key":"listening-p1-set016-q008-audio","skill":"listening","part_number":1,"transcript":"Woman: I thought there were twenty pounds in the kitchen drawer, but part of that money was used for groceries. Thirty pounds was the amount before we paid the delivery driver. There are ten pounds left now. I put the note in an envelope beside the shopping list, so please do not use it unless you need something essential for dinner. A second check confirmed that no part of the total had been counted twice.","transcript_status":"source_word_comment","word_comment_ids":["202"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '673f34c0b919e211bb8a8131627edc6aec410b693c488973210405fd492d61b7'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set016-q009-audio', 'Part 1 Question 204 Audio', 'Boy: Route ten goes through the town centre, and bus nine stops near the sports hall. The bus that stops closest to my home is number eight. I get off beside the small supermarket and walk for only two minutes. It is much more convenient than the other routes, especially when I have a heavy school bag or the weather is wet. The written information was updated immediately to prevent another mistake later.', '{"source_key":"listening-p1-set016-q009-audio","skill":"listening","part_number":1,"transcript":"Boy: Route ten goes through the town centre, and bus nine stops near the sports hall. The bus that stops closest to my home is number eight. I get off beside the small supermarket and walk for only two minutes. It is much more convenient than the other routes, especially when I have a heavy school bag or the weather is wet. The written information was updated immediately to prevent another mistake later.","transcript_status":"source_word_comment","word_comment_ids":["203"],"speaker_labels":["Boy"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '261401df37a25c526a3c216bc0a4493dd9ff198b491b56547bc818f6475b812f'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set016-q010-audio', 'Part 1 Question 205 Audio', 'Woman: Dinner was originally planned for 8:30, but everyone will be hungry before then. Nine thirty is actually when the film we are watching should finish tomorrow, not tonight''s meal time. Dinner is at 7:30 p.m. The food is nearly ready, and I only need to make the salad. Please arrive a few minutes early and help set the table. The remaining activities could continue normally once the correct time was clear.', '{"source_key":"listening-p1-set016-q010-audio","skill":"listening","part_number":1,"transcript":"Woman: Dinner was originally planned for 8:30, but everyone will be hungry before then. Nine thirty is actually when the film we are watching should finish tomorrow, not tonight''s meal time. Dinner is at 7:30 p.m. The food is nearly ready, and I only need to make the salad. Please arrive a few minutes early and help set the table. The remaining activities could continue normally once the correct time was clear.","transcript_status":"source_word_comment","word_comment_ids":["204"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '5d8cc4f64e220394e92c0685674f6d58e247eb51def81897d136e52d6f9aae27'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set016-q011-audio', 'Part 1 Question 206 Audio', 'Colleague 1: Could we meet at 3:30? Colleague 2: I will still be with a client then. Four thirty may also be difficult because the manager is travelling back from another office. Let''s arrange the meeting for 5:30 p.m. Colleague 1: That works. I''ll send the agenda now, and we can keep the discussion short enough for everyone to leave before seven.', '{"source_key":"listening-p1-set016-q011-audio","skill":"listening","part_number":1,"transcript":"Colleague 1: Could we meet at 3:30? Colleague 2: I will still be with a client then. Four thirty may also be difficult because the manager is travelling back from another office. Let''s arrange the meeting for 5:30 p.m. Colleague 1: That works. I''ll send the agenda now, and we can keep the discussion short enough for everyone to leave before seven.","transcript_status":"source_word_comment","word_comment_ids":["205"],"speaker_labels":["Colleague 1"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'e3cb84137583f5adbcb2258ff7a8bef1fdb3c64a683f4120b204e8f977752942'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set016-q012-audio', 'Part 1 Question 207 Audio', 'Host: The invitation originally said five o''clock, but that was the time we expected dinner to be served. Four was suggested while we were planning the decorations. The party starts at three o''clock. Guests can arrive from then, and the garden games will begin at half past three. Please use the side entrance because the front room is being prepared for food. The updated schedule suited the people involved better than either earlier suggestion.', '{"source_key":"listening-p1-set016-q012-audio","skill":"listening","part_number":1,"transcript":"Host: The invitation originally said five o''clock, but that was the time we expected dinner to be served. Four was suggested while we were planning the decorations. The party starts at three o''clock. Guests can arrive from then, and the garden games will begin at half past three. Please use the side entrance because the front room is being prepared for food. The updated schedule suited the people involved better than either earlier suggestion.","transcript_status":"source_word_comment","word_comment_ids":["206"],"speaker_labels":["Host"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'bafc1964eda9b940cdd5b47b521c269f9490eee3e920795588524edd9bc284ba'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set016-q013-audio', 'Part 1 Question 208 Audio', 'Man: Most full-time staff work five days, and my first offer mentioned four. The contract I accepted requires me to work three days each week. The shifts are longer, but I have four days free for study and family responsibilities. I usually work Monday, Wednesday and Friday, although the manager may occasionally change one day when the shop is especially busy. The revised timing left enough room for travel and preparation beforehand.', '{"source_key":"listening-p1-set016-q013-audio","skill":"listening","part_number":1,"transcript":"Man: Most full-time staff work five days, and my first offer mentioned four. The contract I accepted requires me to work three days each week. The shifts are longer, but I have four days free for study and family responsibilities. I usually work Monday, Wednesday and Friday, although the manager may occasionally change one day when the shop is especially busy. The revised timing left enough room for travel and preparation beforehand.","transcript_status":"source_word_comment","word_comment_ids":["207"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'c7db50bdb6c0687db61be14211140d178057a9735ab4c6f823919a750963d466'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set017-q001-audio', 'Part 1 Question 209 Audio', 'Manager: Daniel is not ill, and he has already eaten, so neither of those explains why he cannot do the job today. He has another appointment that was arranged several weeks ago. He told us about it in advance and will return tomorrow. We have moved the urgent task to another employee, while the less important work can wait until he comes back. The other explanations sounded possible at first but did not match the evidence.', '{"source_key":"listening-p1-set017-q001-audio","skill":"listening","part_number":1,"transcript":"Manager: Daniel is not ill, and he has already eaten, so neither of those explains why he cannot do the job today. He has another appointment that was arranged several weeks ago. He told us about it in advance and will return tomorrow. We have moved the urgent task to another employee, while the less important work can wait until he comes back. The other explanations sounded possible at first but did not match the evidence.","transcript_status":"source_word_comment","word_comment_ids":["208"],"speaker_labels":["Manager"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '1247de85485e7b4cc0d42670105dab0141a0c050d89718ee62705a304f0167ee'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set017-q002-audio', 'Part 1 Question 210 Audio', 'Man: I am tired, but I am not going to sleep yet. I have had plenty to drink during the journey, so I do not need another drink. I''m going to get something to eat. I missed lunch, and there is a café beside the station that serves food until late. Afterwards, I''ll continue home and try to have an early night. The alternatives remained possible on another occasion, but not this time.', '{"source_key":"listening-p1-set017-q002-audio","skill":"listening","part_number":1,"transcript":"Man: I am tired, but I am not going to sleep yet. I have had plenty to drink during the journey, so I do not need another drink. I''m going to get something to eat. I missed lunch, and there is a café beside the station that serves food until late. Afterwards, I''ll continue home and try to have an early night. The alternatives remained possible on another occasion, but not this time.","transcript_status":"source_word_comment","word_comment_ids":["209"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'f738029fd2e0cb83164a539bba2be1130ff44ebdfd4df006fbaf6fe5fa4487d0'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set017-q003-audio', 'Part 1 Question 211 Audio', 'Woman: The new health centre is not beside the bus station, and the airport is on the other side of the city. It is next to the train station. Leave through the main station entrance and turn right; the centre is the modern glass building immediately after the taxi area. The reception desk is on the ground floor and opens at eight each morning. Signs in the area should guide visitors through the final part of the journey.', '{"source_key":"listening-p1-set017-q003-audio","skill":"listening","part_number":1,"transcript":"Woman: The new health centre is not beside the bus station, and the airport is on the other side of the city. It is next to the train station. Leave through the main station entrance and turn right; the centre is the modern glass building immediately after the taxi area. The reception desk is on the ground floor and opens at eight each morning. Signs in the area should guide visitors through the final part of the journey.","transcript_status":"source_word_comment","word_comment_ids":["210"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '6df7a2d6974b27313721971545c07730baf8bcc6da360faa7eb857730696e949'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set017-q004-audio', 'Part 1 Question 212 Audio', 'Assistant: The director''s presentation will not be in the bedroom or the living room; those rooms belong to the hotel accommodation. It will take place in the meeting room on the ground floor. The projector has already been tested, and sixty chairs are being arranged. Please enter through reception and collect a name badge before taking a seat. The chosen place was more convenient and easier for everyone to find.', '{"source_key":"listening-p1-set017-q004-audio","skill":"listening","part_number":1,"transcript":"Assistant: The director''s presentation will not be in the bedroom or the living room; those rooms belong to the hotel accommodation. It will take place in the meeting room on the ground floor. The projector has already been tested, and sixty chairs are being arranged. Please enter through reception and collect a name badge before taking a seat. The chosen place was more convenient and easier for everyone to find.","transcript_status":"source_word_comment","word_comment_ids":["211"],"speaker_labels":["Assistant"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'fa2cd0d27a17f2dbb072ed34c58402d7432a31be84c369755f2735b0abc0146c'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set017-q005-audio', 'Part 1 Question 213 Audio', 'Receptionist: The English class is on the first floor, and the science laboratory is on the third. The French class is on the second floor. Take the stairs beside reception and turn left when you reach the landing. The classroom number is 204. Lessons begin at nine, but students may enter ten minutes early to collect their books. The nearby landmarks were useful, although neither was the destination itself.', '{"source_key":"listening-p1-set017-q005-audio","skill":"listening","part_number":1,"transcript":"Receptionist: The English class is on the first floor, and the science laboratory is on the third. The French class is on the second floor. Take the stairs beside reception and turn left when you reach the landing. The classroom number is 204. Lessons begin at nine, but students may enter ten minutes early to collect their books. The nearby landmarks were useful, although neither was the destination itself.","transcript_status":"source_word_comment","word_comment_ids":["212"],"speaker_labels":["Receptionist"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '941e1465842efe0232b875a7e75c398c7b73f67f485ed7ebbbe79839ab0c1f16'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set017-q006-audio', 'Part 1 Question 214 Audio', 'Manager: We considered taking the staff to another city, and one colleague suggested a nearby village because it would be cheaper. This year, I''m taking them to a different country. We will spend three days in Portugal for training and team activities. Flights and accommodation are booked, but everyone needs to check that their passport is still valid. Anyone following the directions carefully should reach the correct place without difficulty.', '{"source_key":"listening-p1-set017-q006-audio","skill":"listening","part_number":1,"transcript":"Manager: We considered taking the staff to another city, and one colleague suggested a nearby village because it would be cheaper. This year, I''m taking them to a different country. We will spend three days in Portugal for training and team activities. Flights and accommodation are booked, but everyone needs to check that their passport is still valid. Anyone following the directions carefully should reach the correct place without difficulty.","transcript_status":"source_word_comment","word_comment_ids":["213"],"speaker_labels":["Manager"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'b117c5b49823a1d9cfd1e5dd0cff64feaa39e0ebe483adf3c8dfc42235493d63'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set017-q007-audio', 'Part 1 Question 215 Audio', 'Woman: I have packed food for the journey, and the hotel already provides books in the children''s room. I''m going to take games with me. They will help everyone pass the time if the weather is bad or the train is delayed. I have chosen several card activities and one small board set, all of which fit easily into my bag. Nothing else needed to change once the main decision had been made.', '{"source_key":"listening-p1-set017-q007-audio","skill":"listening","part_number":1,"transcript":"Woman: I have packed food for the journey, and the hotel already provides books in the children''s room. I''m going to take games with me. They will help everyone pass the time if the weather is bad or the train is delayed. I have chosen several card activities and one small board set, all of which fit easily into my bag. Nothing else needed to change once the main decision had been made.","transcript_status":"source_word_comment","word_comment_ids":["214"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '3731897cb6d08de4b432c0dbb26ea2c5fdb5789aa7293fcfd2f04d630a9530a9'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set017-q008-audio', 'Part 1 Question 216 Audio', 'Student 1: We could write about politics, but the subject is too broad. The economy is interesting, although another group has already chosen it. Let''s write about a historian, or more clearly, an important historical figure. Student 2: Good idea. We can compare several sources, explain the person''s influence and divide the research so each of us covers a different period. The choice fitted the situation better than the other ideas they had discussed.', '{"source_key":"listening-p1-set017-q008-audio","skill":"listening","part_number":1,"transcript":"Student 1: We could write about politics, but the subject is too broad. The economy is interesting, although another group has already chosen it. Let''s write about a historian, or more clearly, an important historical figure. Student 2: Good idea. We can compare several sources, explain the person''s influence and divide the research so each of us covers a different period. The choice fitted the situation better than the other ideas they had discussed.","transcript_status":"source_word_comment","word_comment_ids":["215"],"speaker_labels":["Student 1"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '6ab202f65460f026d1b18021e3f0826d355b16e69313d2e6b69fd6f47f425d72'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set017-q009-audio', 'Part 1 Question 217 Audio', 'Student: I considered writing about animals because there is plenty of information, and bikes would make a practical local topic. My project will focus on land. I want to examine how an unused area near the river could be developed without damaging the environment. I''ll include maps, photographs and opinions from residents who live close to the site. It also left enough time and energy for the rest of the day.', '{"source_key":"listening-p1-set017-q009-audio","skill":"listening","part_number":1,"transcript":"Student: I considered writing about animals because there is plenty of information, and bikes would make a practical local topic. My project will focus on land. I want to examine how an unused area near the river could be developed without damaging the environment. I''ll include maps, photographs and opinions from residents who live close to the site. It also left enough time and energy for the rest of the day.","transcript_status":"source_word_comment","word_comment_ids":["216"],"speaker_labels":["Student"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'ea5597f7ef2186cd953f8e6e79ca7029ff5d6b2196c0a1b25d198f0742d46651'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set017-q010-audio', 'Part 1 Question 218 Audio', 'Teacher: You work hard, so I am not simply asking you to study more, and you do not need a long rest from the course. What I want is for you to complete the assignments on time. Late work makes it difficult to give useful feedback before the next task. Plan smaller weekly deadlines and speak to me early if a genuine problem occurs. The alternatives remained possible on another occasion, but not this time.', '{"source_key":"listening-p1-set017-q010-audio","skill":"listening","part_number":1,"transcript":"Teacher: You work hard, so I am not simply asking you to study more, and you do not need a long rest from the course. What I want is for you to complete the assignments on time. Late work makes it difficult to give useful feedback before the next task. Plan smaller weekly deadlines and speak to me early if a genuine problem occurs. The alternatives remained possible on another occasion, but not this time.","transcript_status":"source_word_comment","word_comment_ids":["217"],"speaker_labels":["Teacher"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'f7f90f9178b3bdad676131e18e379577ca674a9a81f5689b23358be5a69849af'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set017-q011-audio', 'Part 1 Question 219 Audio', 'Teacher: Every Tuesday, students do not need to go camping, and a short note is not enough for this course. They must write a report. It should summarise the week''s experiment, explain the results and mention any problems with the method. The report is due before the next lesson, so keep accurate notes while you work rather than trying to remember everything later. The practical details made that option more suitable than either earlier suggestion.', '{"source_key":"listening-p1-set017-q011-audio","skill":"listening","part_number":1,"transcript":"Teacher: Every Tuesday, students do not need to go camping, and a short note is not enough for this course. They must write a report. It should summarise the week''s experiment, explain the results and mention any problems with the method. The report is due before the next lesson, so keep accurate notes while you work rather than trying to remember everything later. The practical details made that option more suitable than either earlier suggestion.","transcript_status":"source_word_comment","word_comment_ids":["218"],"speaker_labels":["Teacher"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'cda52c979c777ed2bc6278fa5f4a743977b887fe16961f5cf26c070524e1b8a8'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set017-q012-audio', 'Part 1 Question 220 Audio', 'Radio caller: The restaurant looked attractive, so I would not describe it as ugly, and it certainly was not too hot. My complaint is that the place was cold. The heating did not seem to work, and several customers kept their coats on during dinner. The food was good, but it was difficult to enjoy the meal while sitting in such an uncomfortable room. Understanding the real cause made it easier to decide what to do next.', '{"source_key":"listening-p1-set017-q012-audio","skill":"listening","part_number":1,"transcript":"Radio caller: The restaurant looked attractive, so I would not describe it as ugly, and it certainly was not too hot. My complaint is that the place was cold. The heating did not seem to work, and several customers kept their coats on during dinner. The food was good, but it was difficult to enjoy the meal while sitting in such an uncomfortable room. Understanding the real cause made it easier to decide what to do next.","transcript_status":"source_word_comment","word_comment_ids":["219"],"speaker_labels":["Radio caller"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'cf2cefee0c6c2b2241137a71216692c7cc745241974f97344929b030c74d7306'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set017-q013-audio', 'Part 1 Question 221 Audio', 'Woman: Lisa and I are not cousins or sisters, although people sometimes assume we are related because we travel and live together. We are best friends. We met at school and have shared a flat for the past two years. We understand each other''s habits well, divide the household jobs fairly and often spend holidays together when our work schedules allow it. Knowing how long they had known each other removed the earlier confusion.', '{"source_key":"listening-p1-set017-q013-audio","skill":"listening","part_number":1,"transcript":"Woman: Lisa and I are not cousins or sisters, although people sometimes assume we are related because we travel and live together. We are best friends. We met at school and have shared a flat for the past two years. We understand each other''s habits well, divide the household jobs fairly and often spend holidays together when our work schedules allow it. Knowing how long they had known each other removed the earlier confusion.","transcript_status":"source_word_comment","word_comment_ids":["220"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '6675f7cf082e25abc28108fa6f3d1b23b2f8d3180b38a89d427677b7dfb854e0'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set018-q001-audio', 'Part 1 Question 222 Audio', 'Man: I worked as a chef when I was younger and later taught history. I do not want to return to either job full-time. What I want to do next is become a writer. I have several story ideas and have started planning a novel. I''ll continue teaching part-time at first so I can earn money while developing a regular writing routine. That option matched the person''s needs more closely than the alternatives.', '{"source_key":"listening-p1-set018-q001-audio","skill":"listening","part_number":1,"transcript":"Man: I worked as a chef when I was younger and later taught history. I do not want to return to either job full-time. What I want to do next is become a writer. I have several story ideas and have started planning a novel. I''ll continue teaching part-time at first so I can earn money while developing a regular writing routine. That option matched the person''s needs more closely than the alternatives.","transcript_status":"source_word_comment","word_comment_ids":["221"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '9fc345e0d9a07952c3969ae4630f87b56af2ed4ea66a270e1922d56ab7b1ac45'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set018-q002-audio', 'Part 1 Question 223 Audio', 'Woman: My manager was not always friendly, and sometimes he was strict because the work required high standards. I liked him because he taught me a lot. He explained how to handle difficult clients, organise priorities and correct mistakes without becoming defensive. The responsibilities he gave me helped me develop confidence and prepared me for the position I have now. The clarification prevented the same misunderstanding from affecting the next decision.', '{"source_key":"listening-p1-set018-q002-audio","skill":"listening","part_number":1,"transcript":"Woman: My manager was not always friendly, and sometimes he was strict because the work required high standards. I liked him because he taught me a lot. He explained how to handle difficult clients, organise priorities and correct mistakes without becoming defensive. The responsibilities he gave me helped me develop confidence and prepared me for the position I have now. The clarification prevented the same misunderstanding from affecting the next decision.","transcript_status":"source_word_comment","word_comment_ids":["222"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '099ec9a5ad7c8275444073e7d77fa936dd5de2dafc0b1de43a02ef2266f51036'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set018-q003-audio', 'Part 1 Question 224 Audio', 'Woman: Many office employees work from nine to five and remain at a desk for most of the day. Being a writer is different because I work at irregular times. Some mornings I start before sunrise, while on other days I write late at night. The schedule depends on deadlines and when I can concentrate, although I still try to keep several hours free for family life.', '{"source_key":"listening-p1-set018-q003-audio","skill":"listening","part_number":1,"transcript":"Woman: Many office employees work from nine to five and remain at a desk for most of the day. Being a writer is different because I work at irregular times. Some mornings I start before sunrise, while on other days I write late at night. The schedule depends on deadlines and when I can concentrate, although I still try to keep several hours free for family life.","transcript_status":"source_word_comment","word_comment_ids":["223"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'cc1f62d33630a8c3bd069c9cc9e841cd50c5b0b896d43b66a80896fb193c1f84'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set018-q004-audio', 'Part 1 Question 225 Audio', 'Receptionist: Today''s list contains two clients from France and three from the UK, which may be why the numbers became confused. There is one American client. Her name is Leslie, and her appointment is at eleven. Please place the correct form on the reception desk and confirm her contact number when she arrives, as the previous record contains an old address. No extra charge or item needed to be added to that figure.', '{"source_key":"listening-p1-set018-q004-audio","skill":"listening","part_number":1,"transcript":"Receptionist: Today''s list contains two clients from France and three from the UK, which may be why the numbers became confused. There is one American client. Her name is Leslie, and her appointment is at eleven. Please place the correct form on the reception desk and confirm her contact number when she arrives, as the previous record contains an old address. No extra charge or item needed to be added to that figure.","transcript_status":"source_word_comment","word_comment_ids":["224"],"speaker_labels":["Receptionist"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'a589f80856e17f3c4122a75033c8c541197df248f384096b9398b1ac22cd1b36'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set018-q005-audio', 'Part 1 Question 226 Audio', 'Girl: Hi, I think I left my bag in your café this afternoon. I paid at the counter, but I definitely had it after that, and I did not sit near the door. Could you look in the corner beside the tall plant? That is where my table was. The bag is small and brown, with a set of keys and a notebook inside. They planned to arrive early enough to avoid any further confusion there.', '{"source_key":"listening-p1-set018-q005-audio","skill":"listening","part_number":1,"transcript":"Girl: Hi, I think I left my bag in your café this afternoon. I paid at the counter, but I definitely had it after that, and I did not sit near the door. Could you look in the corner beside the tall plant? That is where my table was. The bag is small and brown, with a set of keys and a notebook inside. They planned to arrive early enough to avoid any further confusion there.","transcript_status":"source_word_comment","word_comment_ids":["225"],"speaker_labels":["Girl"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '474cc5941ac7606fefed9a9c5ba54200456fa8b4f60627ef85a6119155b0184a'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set018-q006-audio', 'Part 1 Question 227 Audio', 'The school has finally confirmed the date for the parent-teacher meeting. We originally planned to hold it on Friday, but several teachers will be attending a training course later in the week. Wednesday was also considered, although the main hall is already booked for a school performance. So the meeting will take place on Monday. Parents should arrive about ten minutes before their appointment.', '{"source_key":"listening-p1-set018-q006-audio","skill":"listening","part_number":1,"transcript":"The school has finally confirmed the date for the parent-teacher meeting. We originally planned to hold it on Friday, but several teachers will be attending a training course later in the week. Wednesday was also considered, although the main hall is already booked for a school performance. So the meeting will take place on Monday. Parents should arrive about ten minutes before their appointment.","transcript_status":"source_word_comment","word_comment_ids":["226"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '4f71639a42c3367da138dbff285022f972217e147a1e60fae6a12a4dc889f260'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set018-q007-audio', 'Part 1 Question 228 Audio', 'If you''re planning to use public transport regularly, the monthly bus card is probably the best option. The airport card costs twenty-five dollars, while the student card is only fifteen. For most passengers, though, the standard city card costs twenty dollars and allows unlimited journeys within the city centre.', '{"source_key":"listening-p1-set018-q007-audio","skill":"listening","part_number":1,"transcript":"If you''re planning to use public transport regularly, the monthly bus card is probably the best option. The airport card costs twenty-five dollars, while the student card is only fifteen. For most passengers, though, the standard city card costs twenty dollars and allows unlimited journeys within the city centre.","transcript_status":"source_word_comment","word_comment_ids":["227"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '5238d6e644a6dd6ed94c92038a1ed933938fe8c903d0a510378f46e5cfa7df39'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set018-q008-audio', 'Part 1 Question 229 Audio', 'Hello, I''m calling to arrange our lunch meeting. I''d like to confirm the time with you. I''m available at 1:30 p.m., so I think that would be a good time for us to meet. Please let me know if it works for you. Give me a call back when you have a chance.', '{"source_key":"listening-p1-set018-q008-audio","skill":"listening","part_number":1,"transcript":"Hello, I''m calling to arrange our lunch meeting. I''d like to confirm the time with you. I''m available at 1:30 p.m., so I think that would be a good time for us to meet. Please let me know if it works for you. Give me a call back when you have a chance.","transcript_status":"source_word_comment","word_comment_ids":["228"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'a961338844849f9a2a4ceb293ef71efb23c8aaba45ed29a3a2885e1422932244'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set018-q009-audio', 'Part 1 Question 230 Audio', 'I''m really happy that we''ve been invited to the party. It''s going to be held next week at my friend''s house. I think it''ll be a lot of fun, and we can spend some time together and meet new people. I''ll bring some games so everyone can have fun. I think the games will make the party more exciting.', '{"source_key":"listening-p1-set018-q009-audio","skill":"listening","part_number":1,"transcript":"I''m really happy that we''ve been invited to the party. It''s going to be held next week at my friend''s house. I think it''ll be a lot of fun, and we can spend some time together and meet new people. I''ll bring some games so everyone can have fun. I think the games will make the party more exciting.","transcript_status":"source_word_comment","word_comment_ids":["229"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '4ce8bec399937964bf3822b848065aa317208d1b10fad748477b559f19938dbc'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set018-q010-audio', 'Part 1 Question 231 Audio', 'Hi, I''m calling to update you about the store. As you know, the store is closed this week because we''re having some repairs done. It will be closed for a few more days, but everything should be ready next week. The store will open again on Thursday, so please come back to work then. Let me know if you have any', '{"source_key":"listening-p1-set018-q010-audio","skill":"listening","part_number":1,"transcript":"Hi, I''m calling to update you about the store. As you know, the store is closed this week because we''re having some repairs done. It will be closed for a few more days, but everything should be ready next week. The store will open again on Thursday, so please come back to work then. Let me know if you have any","transcript_status":"source_word_comment","word_comment_ids":["230"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '54d01a983a80c125025f50faee8323d8b417036a9777aa1b4fd02f83ee7fffaa'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set018-q011-audio', 'Part 1 Question 232 Audio', 'Woman: I''m looking for a new pair of shoes. I like the blue ones, but they''re a little unusual. The black ones are nice, but they''re boring. Shop Assistant:', '{"source_key":"listening-p1-set018-q011-audio","skill":"listening","part_number":1,"transcript":"Woman: I''m looking for a new pair of shoes. I like the blue ones, but they''re a little unusual. The black ones are nice, but they''re boring. Shop Assistant:","transcript_status":"source_word_comment","word_comment_ids":["231"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '00b474a8fd9bfd94e21d5227c870a2bc47586e238a6fe9212fc0fa4c4f6d3a24'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set018-q012-audio', 'Part 1 Question 233 Audio', 'Man: How''s your new job going? Woman: It''s going well. I''m still getting used to it, but I really like my new colleagues. Man: That''s good to hear. I come to this café often. The coffee here is really good. Woman: The fish looks delicious. Maybe I''ll have that. Man: It does, but most people here usually order the cake. It''s really popular. Woman: Oh, then I''ll have the cake. It sounds good.', '{"source_key":"listening-p1-set018-q012-audio","skill":"listening","part_number":1,"transcript":"Man: How''s your new job going? Woman: It''s going well. I''m still getting used to it, but I really like my new colleagues. Man: That''s good to hear. I come to this café often. The coffee here is really good. Woman: The fish looks delicious. Maybe I''ll have that. Man: It does, but most people here usually order the cake. It''s really popular. Woman: Oh, then I''ll have the cake. It sounds good.","transcript_status":"source_word_comment","word_comment_ids":["232"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '885d99ebd3800cb625a91726fa05e028ea4627b979f9d6dbfaa681dae1fde2eb'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set018-q013-audio', 'Part 1 Question 234 Audio', 'Hi, I''m calling about our meeting today. I''m sorry, but I need to change the time. My brother is coming back from London at 4:30 p.m., so I have to go to the station to pick him up. Could we meet at 5:30 p.m. instead? We can meet somewhere near the station. I hope that''s okay with you. Please let me know.', '{"source_key":"listening-p1-set018-q013-audio","skill":"listening","part_number":1,"transcript":"Hi, I''m calling about our meeting today. I''m sorry, but I need to change the time. My brother is coming back from London at 4:30 p.m., so I have to go to the station to pick him up. Could we meet at 5:30 p.m. instead? We can meet somewhere near the station. I hope that''s okay with you. Please let me know.","transcript_status":"source_word_comment","word_comment_ids":["233"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'd3ef8bd412a03b837c5f2279d119af139e09f5297359a56054e5eff34037e94d'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set019-q001-audio', 'Part 1 Question 235 Audio', 'I used to get up at 8 a.m., but I didn''t have enough time to get ready before going to work. So, I started getting up at 6 a.m. However, I felt really tired during the day. In the end, I decided to get up at 7 a.m. instead. It gives me enough time to get ready, and I don''t feel as tired. I think it''s a good routine for me.', '{"source_key":"listening-p1-set019-q001-audio","skill":"listening","part_number":1,"transcript":"I used to get up at 8 a.m., but I didn''t have enough time to get ready before going to work. So, I started getting up at 6 a.m. However, I felt really tired during the day. In the end, I decided to get up at 7 a.m. instead. It gives me enough time to get ready, and I don''t feel as tired. I think it''s a good routine for me.","transcript_status":"source_word_comment","word_comment_ids":["234"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '752e90b340a429104b1e1fae9345220c48728b2ad40ea32cb272e732dd4321a2'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set019-q002-audio', 'Part 1 Question 236 Audio', 'I used to live in a small house with my wife. It had two bedrooms, but after we had children, we moved to a three-bedroom house because we needed more space. Now, we''ve moved into a new house, and it''s much bigger. It has four bedrooms, so there''s plenty of room for everyone.', '{"source_key":"listening-p1-set019-q002-audio","skill":"listening","part_number":1,"transcript":"I used to live in a small house with my wife. It had two bedrooms, but after we had children, we moved to a three-bedroom house because we needed more space. Now, we''ve moved into a new house, and it''s much bigger. It has four bedrooms, so there''s plenty of room for everyone.","transcript_status":"source_word_comment","word_comment_ids":["235"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '879a1a9d52a51ba43d142932256b9eaa807ce858d93f121f728295671b2c2c18'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set019-q003-audio', 'Part 1 Question 237 Audio', 'Teacher: Is everything going well with your assignment? Are you having any problems? Student: I''m a little worried. I don''t think I can finish it until next week. I chose a topic that''s difficult, and I''m having trouble finding enough information. Teacher: I understand, but you need to finish the assignment by the deadline. You must submit it on time. If you''re having problems with the topic, we can discuss them, but don''t miss the deadline.', '{"source_key":"listening-p1-set019-q003-audio","skill":"listening","part_number":1,"transcript":"Teacher: Is everything going well with your assignment? Are you having any problems? Student: I''m a little worried. I don''t think I can finish it until next week. I chose a topic that''s difficult, and I''m having trouble finding enough information. Teacher: I understand, but you need to finish the assignment by the deadline. You must submit it on time. If you''re having problems with the topic, we can discuss them, but don''t miss the deadline.","transcript_status":"source_word_comment","word_comment_ids":["236"],"speaker_labels":["Teacher"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '4359e548d84764bfb8fc22fc6a6c9e36ec5a5dbd140d33fdc4abc66c29488631'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set019-q004-audio', 'Part 1 Question 238 Audio', 'There were actually some good opportunities in my hometown. The salary was high, and there were good prospects for career development. However, I decided to move abroad because my sister lives there. It means I can be closer to my sister and spend more time with her. That was the main reason I chose to work in another country.', '{"source_key":"listening-p1-set019-q004-audio","skill":"listening","part_number":1,"transcript":"There were actually some good opportunities in my hometown. The salary was high, and there were good prospects for career development. However, I decided to move abroad because my sister lives there. It means I can be closer to my sister and spend more time with her. That was the main reason I chose to work in another country.","transcript_status":"source_word_comment","word_comment_ids":["237"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '64650ef055b355941957f32f0633a18d35fdf9c31b32830bbca20ecba5db6280'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set019-q005-audio', 'Part 1 Question 239 Audio', 'Woman: I think business trips are a nice break from our usual daily routine. Man: I agree. What I enjoy most is getting the chance to learn new ideas and see how other companies work. Woman: Yes, and we can also meet business partners and discuss new opportunities. Man: Exactly. It''s a good way to learn and develop new business ideas.', '{"source_key":"listening-p1-set019-q005-audio","skill":"listening","part_number":1,"transcript":"Woman: I think business trips are a nice break from our usual daily routine. Man: I agree. What I enjoy most is getting the chance to learn new ideas and see how other companies work. Woman: Yes, and we can also meet business partners and discuss new opportunities. Man: Exactly. It''s a good way to learn and develop new business ideas.","transcript_status":"source_word_comment","word_comment_ids":["238"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'c91650d052b5bba676d407f0fb7112ec616d0a166b992ea9205d90eff7458ce8'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set019-q006-audio', 'Part 1 Question 240 Audio', 'Teacher: The assignment does not need to be six pages, and five would still be longer than the limit. It should be four pages, including the introduction and conclusion. The reference list may go on a separate page and will not count. Focus on analysing the evidence rather than repeating background information simply to make the work appear longer. A second check confirmed that no part of the total had been counted twice.', '{"source_key":"listening-p1-set019-q006-audio","skill":"listening","part_number":1,"transcript":"Teacher: The assignment does not need to be six pages, and five would still be longer than the limit. It should be four pages, including the introduction and conclusion. The reference list may go on a separate page and will not count. Focus on analysing the evidence rather than repeating background information simply to make the work appear longer. A second check confirmed that no part of the total had been counted twice.","transcript_status":"source_word_comment","word_comment_ids":["239"],"speaker_labels":["Teacher"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '64b29e08ea70cdf181f2f395232c75dfdb3ab2b5af6a507cfb6a992dfcde3ba8'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set019-q007-audio', 'Part 1 Question 241 Audio', 'Woman: My sister drinks water throughout the day and sometimes orders coffee in the morning. In the evening, though, she usually drinks tea. Coffee keeps her awake, and plain water feels uninteresting with dinner. She makes a weak cup with a little milk and drinks it slowly while watching television or reading before she goes to bed.', '{"source_key":"listening-p1-set019-q007-audio","skill":"listening","part_number":1,"transcript":"Woman: My sister drinks water throughout the day and sometimes orders coffee in the morning. In the evening, though, she usually drinks tea. Coffee keeps her awake, and plain water feels uninteresting with dinner. She makes a weak cup with a little milk and drinks it slowly while watching television or reading before she goes to bed.","transcript_status":"source_word_comment","word_comment_ids":["240"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'caee1198065cfb64642c2c95f533516ec7882666f411d0eab1ab797e0d3e3a8f'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set019-q008-audio', 'Part 1 Question 242 Audio', 'Travel assistant: Door Three is being used for the local coach, and Door Four is for passengers travelling south. To get to Edinburgh, we need to use Door Two. Staff will check tickets there about fifteen minutes before departure. Please keep your luggage with you and stay close to the entrance, because the coach will leave as soon as everyone is on board. The nearby landmarks were useful, although neither was the destination itself.', '{"source_key":"listening-p1-set019-q008-audio","skill":"listening","part_number":1,"transcript":"Travel assistant: Door Three is being used for the local coach, and Door Four is for passengers travelling south. To get to Edinburgh, we need to use Door Two. Staff will check tickets there about fifteen minutes before departure. Please keep your luggage with you and stay close to the entrance, because the coach will leave as soon as everyone is on board. The nearby landmarks were useful, although neither was the destination itself.","transcript_status":"source_word_comment","word_comment_ids":["241"],"speaker_labels":["Travel assistant"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '3503a8b0223b6c923203918391ad8316efa8d117689a196bd036e484b61fb7ff'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set019-q009-audio', 'Part 1 Question 243 Audio', 'Man: I copied 335 3902 from an old address book, but one digit was wrong. The number 333 3029 belongs to another person with a similar name. Mary''s current number is 555 3920. Please call after six because she will be in a meeting during the afternoon. Save the number once she answers so we do not have the same confusion again. The figures became clear once the different products or categories were separated.', '{"source_key":"listening-p1-set019-q009-audio","skill":"listening","part_number":1,"transcript":"Man: I copied 335 3902 from an old address book, but one digit was wrong. The number 333 3029 belongs to another person with a similar name. Mary''s current number is 555 3920. Please call after six because she will be in a meeting during the afternoon. Save the number once she answers so we do not have the same confusion again. The figures became clear once the different products or categories were separated.","transcript_status":"source_word_comment","word_comment_ids":["242"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '9e06578a3006fa6bab8c6033de2ddd8b98508f4074813f82a194c1aef12b1553'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set019-q010-audio', 'Part 1 Question 244 Audio', 'Woman: Friday at seven in the morning was too early for both of us, and Saturday at nine became impossible because of a family appointment. We finally decided to meet at nine a.m. on Sunday. We will wait outside the station and then have breakfast nearby. I''ll send a message before leaving home so we can confirm that the trains are running normally. The updated schedule suited the people involved better than either earlier suggestion.', '{"source_key":"listening-p1-set019-q010-audio","skill":"listening","part_number":1,"transcript":"Woman: Friday at seven in the morning was too early for both of us, and Saturday at nine became impossible because of a family appointment. We finally decided to meet at nine a.m. on Sunday. We will wait outside the station and then have breakfast nearby. I''ll send a message before leaving home so we can confirm that the trains are running normally. The updated schedule suited the people involved better than either earlier suggestion.","transcript_status":"source_word_comment","word_comment_ids":["243"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'f2b487cd2921718f0fc88442f32dec749963301d4442e58ada528323f92c28dc'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set019-q011-audio', 'Part 1 Question 245 Audio', 'Speaker: The countryside is peaceful, and the suburbs usually provide more space for families. I most enjoy living in the city. I like being close to work, shops, theatres and public transport, and I do not need a car for everyday tasks. The streets can be noisy, but having so many activities and services nearby is more important to me than complete The choice fitted the situation better than the other ideas they had discussed.', '{"source_key":"listening-p1-set019-q011-audio","skill":"listening","part_number":1,"transcript":"Speaker: The countryside is peaceful, and the suburbs usually provide more space for families. I most enjoy living in the city. I like being close to work, shops, theatres and public transport, and I do not need a car for everyday tasks. The streets can be noisy, but having so many activities and services nearby is more important to me than complete The choice fitted the situation better than the other ideas they had discussed.","transcript_status":"source_word_comment","word_comment_ids":["244"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'da3e7bb053dd50d7277ba8a35aba093bc899f55e0a9cbc8bc416fd7206c6a6e6'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set019-q012-audio', 'Part 1 Question 246 Audio', 'Man: Hi, I''m not calling to ask for directions, and this is not an invitation to go out. I wanted to tell you that I will be late. Friend: Oh no, what happened? Man: My train has stopped because of a signal problem, and the driver expects a delay of about twenty minutes. Friend: Don''t worry, we''ll wait a bit. Man: Please begin without me if everyone else arrives, and I''ll come straight to the restaurant from the station. Friend: Alright, see you soon!', '{"source_key":"listening-p1-set019-q012-audio","skill":"listening","part_number":1,"transcript":"Man: Hi, I''m not calling to ask for directions, and this is not an invitation to go out. I wanted to tell you that I will be late. Friend: Oh no, what happened? Man: My train has stopped because of a signal problem, and the driver expects a delay of about twenty minutes. Friend: Don''t worry, we''ll wait a bit. Man: Please begin without me if everyone else arrives, and I''ll come straight to the restaurant from the station. Friend: Alright, see you soon!","transcript_status":"source_word_comment","word_comment_ids":["245"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '800f74af7885e57390f58ef90c9d031ee4f938dcc53ff536886cfe976df85e62'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set019-q013-audio', 'Part 1 Question 247 Audio', 'Woman: I returned to the shop because I needed to exchange a shirt. I was not buying a skirt, and the dress I purchased fits perfectly. The shirt looked right in the changing room, but at home I noticed a mark near the sleeve. I would like the same style in a clean condition, rather than a refund, because the size and colour are exactly what I wanted.', '{"source_key":"listening-p1-set019-q013-audio","skill":"listening","part_number":1,"transcript":"Woman: I returned to the shop because I needed to exchange a shirt. I was not buying a skirt, and the dress I purchased fits perfectly. The shirt looked right in the changing room, but at home I noticed a mark near the sleeve. I would like the same style in a clean condition, rather than a refund, because the size and colour are exactly what I wanted.","transcript_status":"source_word_comment","word_comment_ids":["246"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'b072d80cc1bf2af448d821a74c97e36f2ab2af40785ca3f164a8c5e1016904db'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set020-q001-audio', 'Part 1 Question 248 Audio', 'Friend 1: We looked at prices for travelling abroad, and camping would have been a cheap holiday. Instead, we are going to spend the break teaching. We have joined a community programme that supports younger students. I''ll help with English, while my friend will teach basic computer skills. We will work in the mornings and have the afternoons free to explore the area. The practical details made that option more suitable than either earlier suggestion.', '{"source_key":"listening-p1-set020-q001-audio","skill":"listening","part_number":1,"transcript":"Friend 1: We looked at prices for travelling abroad, and camping would have been a cheap holiday. Instead, we are going to spend the break teaching. We have joined a community programme that supports younger students. I''ll help with English, while my friend will teach basic computer skills. We will work in the mornings and have the afternoons free to explore the area. The practical details made that option more suitable than either earlier suggestion.","transcript_status":"source_word_comment","word_comment_ids":["247"],"speaker_labels":["Friend 1"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '10a2864f87ed95e8dc2ec88eb926e43226782743ba38de1d200406975030833d'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set020-q002-audio', 'Part 1 Question 249 Audio', 'Man: The game loads properly, and I can play through most levels and change characters whenever I want. The problem is that it is stopping me from winning. Just before the final stage ends, the screen freezes and the result is not saved. I have tried restarting the console and lowering the graphics settings, but the same fault happens every time I reach that point.', '{"source_key":"listening-p1-set020-q002-audio","skill":"listening","part_number":1,"transcript":"Man: The game loads properly, and I can play through most levels and change characters whenever I want. The problem is that it is stopping me from winning. Just before the final stage ends, the screen freezes and the result is not saved. I have tried restarting the console and lowering the graphics settings, but the same fault happens every time I reach that point.","transcript_status":"source_word_comment","word_comment_ids":["248"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'e55d616ad17a104aac48223d336b1516db6daf9c9e28f3232d343946135d231b'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set020-q003-audio', 'Part 1 Question 250 Audio', 'Student: We measured the tree''s growth and observed how its roots absorbed water, but those were supporting measurements rather than the main purpose. We carried out the experiment to study the effects of pollution. We compared leaves from trees beside a busy road with leaves from a cleaner area, then recorded differences in colour, damage and growth over several weeks. The surrounding facts supported that explanation more strongly than the alternatives.', '{"source_key":"listening-p1-set020-q003-audio","skill":"listening","part_number":1,"transcript":"Student: We measured the tree''s growth and observed how its roots absorbed water, but those were supporting measurements rather than the main purpose. We carried out the experiment to study the effects of pollution. We compared leaves from trees beside a busy road with leaves from a cleaner area, then recorded differences in colour, damage and growth over several weeks. The surrounding facts supported that explanation more strongly than the alternatives.","transcript_status":"source_word_comment","word_comment_ids":["249"],"speaker_labels":["Student"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '3cf037a871fd32e6bfdff002fc11c6d746fe8f6bb473dd5aeb3c312231745337'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set020-q004-audio', 'Part 1 Question 251 Audio', 'Manager: Reducing the budget was discussed, and someone suggested relocating the meeting to a larger office. The main change will be to adjust the schedule. Morning sessions will be shorter, with more time for team discussions in the afternoon. The location and total budget will remain the same. We will test the new timetable for one month before deciding whether to keep it permanently. That option matched the person''s needs more closely than the alternatives.', '{"source_key":"listening-p1-set020-q004-audio","skill":"listening","part_number":1,"transcript":"Manager: Reducing the budget was discussed, and someone suggested relocating the meeting to a larger office. The main change will be to adjust the schedule. Morning sessions will be shorter, with more time for team discussions in the afternoon. The location and total budget will remain the same. We will test the new timetable for one month before deciding whether to keep it permanently. That option matched the person''s needs more closely than the alternatives.","transcript_status":"source_word_comment","word_comment_ids":["250"],"speaker_labels":["Manager"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '35155efcf52892d98de4fc5590258225670121ac16fd17b77bc3ea2bfad7fd6d'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set020-q005-audio', 'Part 1 Question 252 Audio', 'Man: I did not have breakfast at a café, and my walk in the park happened later in the afternoon. In the morning, I went to look at a view from the hill above the town. The sky was clear, so I could see the river and distant mountains. I stayed there for nearly an hour, took photographs and then returned home for breakfast. Nothing else needed to change once the main decision had been made.', '{"source_key":"listening-p1-set020-q005-audio","skill":"listening","part_number":1,"transcript":"Man: I did not have breakfast at a café, and my walk in the park happened later in the afternoon. In the morning, I went to look at a view from the hill above the town. The sky was clear, so I could see the river and distant mountains. I stayed there for nearly an hour, took photographs and then returned home for breakfast. Nothing else needed to change once the main decision had been made.","transcript_status":"source_word_comment","word_comment_ids":["251"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'd60dd013d002a777c6a0a51794fb15d932ce73d7c4febcb9d1fe68b5f4293a41'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set020-q006-audio', 'Part 1 Question 253 Audio', 'Man: I heard water and thought the woman might be swimming, but she is inside the house, and she is not crying. She is cleaning. She has already washed the kitchen floor and is now wiping the windows. The water sound comes from a bucket beside her. She plans to finish the living room before taking a break and going to the shops. The choice fitted the situation better than the other ideas they had discussed.', '{"source_key":"listening-p1-set020-q006-audio","skill":"listening","part_number":1,"transcript":"Man: I heard water and thought the woman might be swimming, but she is inside the house, and she is not crying. She is cleaning. She has already washed the kitchen floor and is now wiping the windows. The water sound comes from a bucket beside her. She plans to finish the living room before taking a break and going to the shops. The choice fitted the situation better than the other ideas they had discussed.","transcript_status":"source_word_comment","word_comment_ids":["252"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '9c9a135b44034dba28c37113e3d985ccb8854577f3a572f1bee9780881cfa400'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set020-q007-audio', 'Part 1 Question 254 Audio', 'Girl: Mum, could you pick me up at the airport? Mother: Of course! Are you alright? Girl: I am happy to be home, and I am certainly tired after the long flight, but the main problem is that I feel sick. I have a headache and an upset stomach, so I do not want to take the crowded bus. Mother: Oh, poor thing! I''ll come right away. Girl: Thank you. I''ll wait near the information desk until you arrive. Mother: Stay warm, I''m on my way.', '{"source_key":"listening-p1-set020-q007-audio","skill":"listening","part_number":1,"transcript":"Girl: Mum, could you pick me up at the airport? Mother: Of course! Are you alright? Girl: I am happy to be home, and I am certainly tired after the long flight, but the main problem is that I feel sick. I have a headache and an upset stomach, so I do not want to take the crowded bus. Mother: Oh, poor thing! I''ll come right away. Girl: Thank you. I''ll wait near the information desk until you arrive. Mother: Stay warm, I''m on my way.","transcript_status":"source_word_comment","word_comment_ids":["253"],"speaker_labels":["Girl"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '63bdff1b50bdb94dc8c928e8a47fd2795030623b33bd020c6048586eb1669152'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set020-q008-audio', 'Part 1 Question 255 Audio', 'Man: I used to ride a motorbike, but I stopped because the traffic felt unsafe. The train is useful on days when my car is being repaired. I usually go to work by car. The office is outside the town and public transport does not arrive early enough for my shift. I leave before rush hour and share the journey with a colleague twice a week.', '{"source_key":"listening-p1-set020-q008-audio","skill":"listening","part_number":1,"transcript":"Man: I used to ride a motorbike, but I stopped because the traffic felt unsafe. The train is useful on days when my car is being repaired. I usually go to work by car. The office is outside the town and public transport does not arrive early enough for my shift. I leave before rush hour and share the journey with a colleague twice a week.","transcript_status":"source_word_comment","word_comment_ids":["254"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '040bf577be52f76e7651ad731abfef24d01565e6886b2fdc437e57ac89723380'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set020-q009-audio', 'Part 1 Question 256 Audio', 'Man: I brought my laptop indoors as soon as it began to rain, and the shirt is hanging safely in the laundry room. What I left in the yard was my shoes. They were muddy after gardening, so I put them beside the back door and forgot about them. I need to collect them before the dog carries one away or the weather becomes wet again.', '{"source_key":"listening-p1-set020-q009-audio","skill":"listening","part_number":1,"transcript":"Man: I brought my laptop indoors as soon as it began to rain, and the shirt is hanging safely in the laundry room. What I left in the yard was my shoes. They were muddy after gardening, so I put them beside the back door and forgot about them. I need to collect them before the dog carries one away or the weather becomes wet again.","transcript_status":"source_word_comment","word_comment_ids":["255"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '93720399b3954ad9829c3c3faeac3801d8d73f7dfdacfd7c3adb83b764edc60b'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set020-q010-audio', 'Part 1 Question 257 Audio', 'Instructor: When the computer is charging, a red light appears near the power socket. A green light shows that the battery is full. The blue light means the computer is switched on. It should remain steady after the system starts. If it flashes repeatedly and the screen stays dark, hold the power button for five seconds and ask technical support for help. After making the decision, the remaining arrangements were straightforward.', '{"source_key":"listening-p1-set020-q010-audio","skill":"listening","part_number":1,"transcript":"Instructor: When the computer is charging, a red light appears near the power socket. A green light shows that the battery is full. The blue light means the computer is switched on. It should remain steady after the system starts. If it flashes repeatedly and the screen stays dark, hold the power button for five seconds and ask technical support for help. After making the decision, the remaining arrangements were straightforward.","transcript_status":"source_word_comment","word_comment_ids":["256"],"speaker_labels":["Instructor"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'c266cf04dfec9dcef89d6dc76e1950ca882b9a5b54994fb5a7be826bf7023c6b'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set020-q011-audio', 'Part 1 Question 258 Audio', 'Woman: I have already sent most of the invitations, and a colleague is organising the informal evening event. My most important task for the conference is giving a formal address. I need to welcome the delegates, introduce the main theme and explain the programme clearly. I''m preparing notes now, but I want the speech to sound natural rather than as if I am reading every word.', '{"source_key":"listening-p1-set020-q011-audio","skill":"listening","part_number":1,"transcript":"Woman: I have already sent most of the invitations, and a colleague is organising the informal evening event. My most important task for the conference is giving a formal address. I need to welcome the delegates, introduce the main theme and explain the programme clearly. I''m preparing notes now, but I want the speech to sound natural rather than as if I am reading every word.","transcript_status":"source_word_comment","word_comment_ids":["257"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '980c2841404b02a95dd6f753852225f03a256b5c002cda2bdbb895563cd0956d'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set020-q012-audio', 'Part 1 Question 259 Audio', 'Building manager: The doors close properly, and the main gate was repaired last month. The windows need attention. Several frames are damaged, and rainwater is entering two rooms on the upper floor. We will replace the worst windows first and repair the others where possible. Work begins on Monday, so staff should move furniture away from the outside walls before the contractors arrive. That option matched the person''s needs more closely than the alternatives.', '{"source_key":"listening-p1-set020-q012-audio","skill":"listening","part_number":1,"transcript":"Building manager: The doors close properly, and the main gate was repaired last month. The windows need attention. Several frames are damaged, and rainwater is entering two rooms on the upper floor. We will replace the worst windows first and repair the others where possible. Work begins on Monday, so staff should move furniture away from the outside walls before the contractors arrive. That option matched the person''s needs more closely than the alternatives.","transcript_status":"source_word_comment","word_comment_ids":["258"],"speaker_labels":["Building manager"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'dd42719455b1cb8e52325c5d787f7de72a139f7ef37127bb3b7fb15f138791f8'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set020-q013-audio', 'Part 1 Question 260 Audio', 'Man: Sea transport remains attractive because ships can carry large at relatively low cost. However, the main influence on its future development will be the increasing use of technology. Smarter navigation, automated ports and better tracking systems should make journeys safer and more efficient. Cost will still matter, but innovation will change how ships are operated and how cargo is managed. Nothing else needed to change once the main decision had been made.', '{"source_key":"listening-p1-set020-q013-audio","skill":"listening","part_number":1,"transcript":"Man: Sea transport remains attractive because ships can carry large at relatively low cost. However, the main influence on its future development will be the increasing use of technology. Smarter navigation, automated ports and better tracking systems should make journeys safer and more efficient. Cost will still matter, but innovation will change how ships are operated and how cargo is managed. Nothing else needed to change once the main decision had been made.","transcript_status":"source_word_comment","word_comment_ids":["259"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '5c9390cc0de4404d94aac03ff168706354ff910301f065f334161a5aabde64f3'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set021-q001-audio', 'Part 1 Question 261 Audio', 'Friend 1: Sarah said she would make the sandwiches, and Tom brought enough drinks for everyone. We brought fruit to the picnic. We chose apples, grapes and a large box of strawberries because they were easy to share and did not need cooking. After lunch, we packed the remaining pieces in a cool bag so they would stay fresh for the journey home. The choice fitted the situation better than the other ideas they had discussed.', '{"source_key":"listening-p1-set021-q001-audio","skill":"listening","part_number":1,"transcript":"Friend 1: Sarah said she would make the sandwiches, and Tom brought enough drinks for everyone. We brought fruit to the picnic. We chose apples, grapes and a large box of strawberries because they were easy to share and did not need cooking. After lunch, we packed the remaining pieces in a cool bag so they would stay fresh for the journey home. The choice fitted the situation better than the other ideas they had discussed.","transcript_status":"source_word_comment","word_comment_ids":["260"],"speaker_labels":["Friend 1"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'e3e92edae801233867032b927acef0fd30718eddf51d373d0b1ae5856568aecd'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set021-q002-audio', 'Part 1 Question 262 Audio', 'Man: The Wi-Fi is working because my phone connects normally, and the printer completed a test page this morning. The computer is not working. It turns on for a few seconds and then shuts down before the system loads. I have checked the cable and tried another power socket. A technician is coming this afternoon, so I will use a colleague''s machine until then. It also left enough time and energy for the rest of the day.', '{"source_key":"listening-p1-set021-q002-audio","skill":"listening","part_number":1,"transcript":"Man: The Wi-Fi is working because my phone connects normally, and the printer completed a test page this morning. The computer is not working. It turns on for a few seconds and then shuts down before the system loads. I have checked the cable and tried another power socket. A technician is coming this afternoon, so I will use a colleague''s machine until then. It also left enough time and energy for the rest of the day.","transcript_status":"source_word_comment","word_comment_ids":["261"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '59d83b76d01e6b72c7beab4dcdf2c9f26fc2c4cfca1ead76a26d09d9543ce2a0'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set021-q003-audio', 'Part 1 Question 263 Audio', 'Announcement: The school is not closing, and the weather warning only affects outdoor sports this afternoon. The main topic is the new library hours. From next Monday, the library will open at eight in the morning and close at seven in the evening on weekdays. Saturday opening will remain unchanged. Students should check the website before visiting during holidays, as different times may apply. The alternatives remained possible on another occasion, but not this time.', '{"source_key":"listening-p1-set021-q003-audio","skill":"listening","part_number":1,"transcript":"Announcement: The school is not closing, and the weather warning only affects outdoor sports this afternoon. The main topic is the new library hours. From next Monday, the library will open at eight in the morning and close at seven in the evening on weekdays. Saturday opening will remain unchanged. Students should check the website before visiting during holidays, as different times may apply. The alternatives remained possible on another occasion, but not this time.","transcript_status":"source_word_comment","word_comment_ids":["262"],"speaker_labels":["Announcement"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'd759f9a6325291949d27761ddbb02605387199ff553328e0a341365e5936a14b'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set021-q004-audio', 'Part 1 Question 264 Audio', 'Teacher: Do not leave your assignment at my office, because I may not be there to record it, and main reception cannot accept coursework. Students should submit their assignments through the online portal. The system will show a confirmation message and send an email after the upload is complete. Keep that message until the work has been marked, and contact technical support immediately if the file fails to upload.', '{"source_key":"listening-p1-set021-q004-audio","skill":"listening","part_number":1,"transcript":"Teacher: Do not leave your assignment at my office, because I may not be there to record it, and main reception cannot accept coursework. Students should submit their assignments through the online portal. The system will show a confirmation message and send an email after the upload is complete. Keep that message until the work has been marked, and contact technical support immediately if the file fails to upload.","transcript_status":"source_word_comment","word_comment_ids":["263"],"speaker_labels":["Teacher"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '23ff3296c457a2d08974657808f075a1b94f6f7037a0467f85ab91538ecab404'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set021-q005-audio', 'Part 1 Question 265 Audio', 'Teacher: Our football practice is usually on Friday evening, but the sports field will be used for a school event this week. We cannot play on Monday morning because you have a science test. Therefore, the practice has been moved to Wednesday afternoon. Please meet outside the changing rooms at four o''clock.', '{"source_key":"listening-p1-set021-q005-audio","skill":"listening","part_number":1,"transcript":"Teacher: Our football practice is usually on Friday evening, but the sports field will be used for a school event this week. We cannot play on Monday morning because you have a science test. Therefore, the practice has been moved to Wednesday afternoon. Please meet outside the changing rooms at four o''clock.","transcript_status":"source_word_comment","word_comment_ids":["264"],"speaker_labels":["Teacher"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'e4fe8bda21a7a86f0b7217e7166f53fb6f00c0a61c69e967ff804f4b4c200f1f'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set021-q006-audio', 'Part 1 Question 266 Audio', 'Woman: I went shopping for a dress yesterday. At first, I tried on a red one, but it was too tight. The assistant then showed me a blue dress, although I did not like its style. In the end, I bought a simple black one. It fits perfectly, and I can wear it to the party next week.', '{"source_key":"listening-p1-set021-q006-audio","skill":"listening","part_number":1,"transcript":"Woman: I went shopping for a dress yesterday. At first, I tried on a red one, but it was too tight. The assistant then showed me a blue dress, although I did not like its style. In the end, I bought a simple black one. It fits perfectly, and I can wear it to the party next week.","transcript_status":"source_word_comment","word_comment_ids":["265"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '7b17d64a7e1a7bbaed014d37561424f44ae693d9f8847bfe833fa1527609fd1e'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set021-q007-audio', 'Part 1 Question 267 Audio', 'Woman: The weather was lovely during my holiday. I originally planned to spend the day at the beach, but it was extremely crowded. I also wanted to visit the local museum, although it was closed for repairs. Instead, I went to a large park near my hotel, walked around the lake and had lunch there.', '{"source_key":"listening-p1-set021-q007-audio","skill":"listening","part_number":1,"transcript":"Woman: The weather was lovely during my holiday. I originally planned to spend the day at the beach, but it was extremely crowded. I also wanted to visit the local museum, although it was closed for repairs. Instead, I went to a large park near my hotel, walked around the lake and had lunch there.","transcript_status":"source_word_comment","word_comment_ids":["266"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'dc83e9cfbd9d407b944450ae9c989f56ce4ad5cfa9b8374da7670cd2751e2a58'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set021-q008-audio', 'Part 1 Question 268 Audio', 'Tour guide: This morning, the bus collected us outside the hotel, but it will not return there this evening. We first planned to meet at the museum entrance, although the road nearby is now closed. Please go to the marketplace instead. The bus will be waiting beside the main gate at six thirty.', '{"source_key":"listening-p1-set021-q008-audio","skill":"listening","part_number":1,"transcript":"Tour guide: This morning, the bus collected us outside the hotel, but it will not return there this evening. We first planned to meet at the museum entrance, although the road nearby is now closed. Please go to the marketplace instead. The bus will be waiting beside the main gate at six thirty.","transcript_status":"source_word_comment","word_comment_ids":["267"],"speaker_labels":["Tour guide"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'afcab3c9dd6289b9d1e056dc9f73a71a29e61159fe2ed2ce1258f23fffef8cab'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set021-q009-audio', 'Part 1 Question 269 Audio', 'Woman: I nearly wrote half past ten in my diary because that''s when Sarah said she would be free. Then I remembered the room is booked for another group from to ten until ten o''clock. Luckily, that still gives us enough time to set everything up. The original schedule hasn''t actually changed, so everyone should be in their seats and ready to begin at past ten.', '{"source_key":"listening-p1-set021-q009-audio","skill":"listening","part_number":1,"transcript":"Woman: I nearly wrote half past ten in my diary because that''s when Sarah said she would be free. Then I remembered the room is booked for another group from to ten until ten o''clock. Luckily, that still gives us enough time to set everything up. The original schedule hasn''t actually changed, so everyone should be in their seats and ready to begin at past ten.","transcript_status":"source_word_comment","word_comment_ids":["268"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'e76d8e45c01ecd1c84df1834cc5fad8b8c6ec314e36f58134f4bef9e37c96afb'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set021-q010-audio', 'Part 1 Question 270 Audio', 'Man: The search itself has gone much better than I expected. I found a place near my office, and after speaking to the bank, it looks as though the mortgage should be manageable. The problem is at home. My wife thinks moving now would be too disruptive for the children, and my parents keep telling us to wait another year. The house is right, and the money is available. I just can''t get everyone to agree.', '{"source_key":"listening-p1-set021-q010-audio","skill":"listening","part_number":1,"transcript":"Man: The search itself has gone much better than I expected. I found a place near my office, and after speaking to the bank, it looks as though the mortgage should be manageable. The problem is at home. My wife thinks moving now would be too disruptive for the children, and my parents keep telling us to wait another year. The house is right, and the money is available. I just can''t get everyone to agree.","transcript_status":"source_word_comment","word_comment_ids":["269"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '4960e3499dca4691a9fadf2108cf0a774508851678a54544c4297ffdd09726fb'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set021-q011-audio', 'Part 1 Question 271 Audio', 'Man: Hi, I''m here already. I got off the bus a few minutes ago and stopped at the bank to get some cash, so don''t wait for me at the station. I''ve crossed the square now. I''m standing outside that large old building where we went to register for the local event last month. There are some steps at the front and a clock above the entrance. I''ll wait here until you arrive.', '{"source_key":"listening-p1-set021-q011-audio","skill":"listening","part_number":1,"transcript":"Man: Hi, I''m here already. I got off the bus a few minutes ago and stopped at the bank to get some cash, so don''t wait for me at the station. I''ve crossed the square now. I''m standing outside that large old building where we went to register for the local event last month. There are some steps at the front and a clock above the entrance. I''ll wait here until you arrive.","transcript_status":"source_word_comment","word_comment_ids":["270"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '637a6e494afed8132750c4283e5c06668e98c242d93f3e867ab1a1afaa5c1b4c'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set021-q012-audio', 'Part 1 Question 272 Audio', 'Customer: I expected the café to be noisy at lunchtime, but it was actually than usual, and my coffee arrived hot. I chose a table in the corner because I needed to finish some work before a meeting. That''s when the trouble started. My laptop connected without any problem, but pages took forever to open, and I couldn''t upload a document at all. In the end, I had to use my phone''s mobile data.', '{"source_key":"listening-p1-set021-q012-audio","skill":"listening","part_number":1,"transcript":"Customer: I expected the café to be noisy at lunchtime, but it was actually than usual, and my coffee arrived hot. I chose a table in the corner because I needed to finish some work before a meeting. That''s when the trouble started. My laptop connected without any problem, but pages took forever to open, and I couldn''t upload a document at all. In the end, I had to use my phone''s mobile data.","transcript_status":"source_word_comment","word_comment_ids":["271"],"speaker_labels":["Customer"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '96fc532ea9486f87e550b490549ef32e4276b08dafe8e81234890b973853809d'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set021-q013-audio', 'Part 1 Question 273 Audio', 'Woman: I almost didn''t go after work because that time of day is usually packed, but when I arrived there were plenty of free machines. I also checked my latest payment, and the membership still costs the same. I''d mainly gone for the yoga session, though. When I reached the studio, several people were waiting outside. One of the staff came over and explained that the instructor had become ill, so we were told there wouldn''t be a session that evening.', '{"source_key":"listening-p1-set021-q013-audio","skill":"listening","part_number":1,"transcript":"Woman: I almost didn''t go after work because that time of day is usually packed, but when I arrived there were plenty of free machines. I also checked my latest payment, and the membership still costs the same. I''d mainly gone for the yoga session, though. When I reached the studio, several people were waiting outside. One of the staff came over and explained that the instructor had become ill, so we were told there wouldn''t be a session that evening.","transcript_status":"source_word_comment","word_comment_ids":["272"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '0f193dc1f810e3a6a9ae11dd6e35685957f2e2625c8f6631e14cc60bd6930c77'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set022-q001-audio', 'Part 1 Question 274 Audio', 'I''m calling about our parent-teacher meeting. We usually have these meetings twice a year. As you''re a new parent, this will be a good chance for us to meet and talk about your son''s progress. You can also ask me any you may have. The meeting will be on Monday at 5:30 p.m. Please come to my classroom. I look forward to meeting you then.', '{"source_key":"listening-p1-set022-q001-audio","skill":"listening","part_number":1,"transcript":"I''m calling about our parent-teacher meeting. We usually have these meetings twice a year. As you''re a new parent, this will be a good chance for us to meet and talk about your son''s progress. You can also ask me any you may have. The meeting will be on Monday at 5:30 p.m. Please come to my classroom. I look forward to meeting you then.","transcript_status":"source_word_comment","word_comment_ids":["273"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '8fac636a745ddce2be0e0fda2fe4d2c51009765cffecc52611e8d3e5f1ce90ba'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set022-q002-audio', 'Part 1 Question 275 Audio', 'Hello, this is Mohamed from the travel company. I''m calling to answer your about our bus card. The bus card costs $20, and this price covers the whole trip. You don''t need to pay any extra fees during the journey. If you have any other about the bus card or the trip, please feel free to contact us.', '{"source_key":"listening-p1-set022-q002-audio","skill":"listening","part_number":1,"transcript":"Hello, this is Mohamed from the travel company. I''m calling to answer your about our bus card. The bus card costs $20, and this price covers the whole trip. You don''t need to pay any extra fees during the journey. If you have any other about the bus card or the trip, please feel free to contact us.","transcript_status":"source_word_comment","word_comment_ids":["274"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'bf0f0f725ff212251dba78e4b288c1fd4a6a150665f4717e35a1e3d9d3402da3'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set022-q003-audio', 'Part 1 Question 276 Audio', 'Woman: Do you still want to meet for lunch tomorrow? Man: Definitely. I have a meeting until one, though. Woman: Shall we say two o''clock, then? Man: That''s a bit late for me. I only need about half an hour to get from the office to the restaurant. Woman: So one thirty? Man: Perfect. I''ll see you there.', '{"source_key":"listening-p1-set022-q003-audio","skill":"listening","part_number":1,"transcript":"Woman: Do you still want to meet for lunch tomorrow? Man: Definitely. I have a meeting until one, though. Woman: Shall we say two o''clock, then? Man: That''s a bit late for me. I only need about half an hour to get from the office to the restaurant. Woman: So one thirty? Man: Perfect. I''ll see you there.","transcript_status":"source_word_comment","word_comment_ids":["275"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'dfad6fbc44a9e034eae41a2f1f71c85efde09248c73687969738a8101c4545f9'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set022-q004-audio', 'Part 1 Question 277 Audio', 'I''m going to Emma''s party on Saturday, and at first I thought I''d take some food with me. But she said she''s already ordered more than enough for everyone. I also offered to bring a speaker, but she''s got music sorted as well. What she really wants is something the whole group can use together after dinner - something fun that can keep everyone entertained for an hour or two. I''ve got a couple of those at home, so I''ll take them with me.', '{"source_key":"listening-p1-set022-q004-audio","skill":"listening","part_number":1,"transcript":"I''m going to Emma''s party on Saturday, and at first I thought I''d take some food with me. But she said she''s already ordered more than enough for everyone. I also offered to bring a speaker, but she''s got music sorted as well. What she really wants is something the whole group can use together after dinner - something fun that can keep everyone entertained for an hour or two. I''ve got a couple of those at home, so I''ll take them with me.","transcript_status":"source_word_comment","word_comment_ids":["276"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '450d493371198d0ce9102d705623859bd3763b3eae5a7cdd7098a6abd72462ee'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set022-q005-audio', 'Part 1 Question 278 Audio', 'Just a notice for customers: the shop will be closed for maintenance at the beginning of this week. We won''t be open on Tuesday or Wednesday while the new flooring is installed. Normal opening hours will begin again on Thursday morning at nine o''clock.', '{"source_key":"listening-p1-set022-q005-audio","skill":"listening","part_number":1,"transcript":"Just a notice for customers: the shop will be closed for maintenance at the beginning of this week. We won''t be open on Tuesday or Wednesday while the new flooring is installed. Normal opening hours will begin again on Thursday morning at nine o''clock.","transcript_status":"source_word_comment","word_comment_ids":["277"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '77f3d3eaa61afcdf70fff6be293c3858fb8e54b013d41c6df79c8ba147fad79f'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set022-q006-audio', 'Part 1 Question 279 Audio', 'Woman: What do you think of these blue shoes? Man: They''re interesting, but the colour is unusual. Woman: Maybe the black ones would be safer. Man: They would, but they''re a bit boring, aren''t they? Woman: True. What about the pair beside them? The brighter ones? Man: Those suit you much better. They''re warm-coloured without looking too unusual. Woman: Yes, I think I''ll buy those.', '{"source_key":"listening-p1-set022-q006-audio","skill":"listening","part_number":1,"transcript":"Woman: What do you think of these blue shoes? Man: They''re interesting, but the colour is unusual. Woman: Maybe the black ones would be safer. Man: They would, but they''re a bit boring, aren''t they? Woman: True. What about the pair beside them? The brighter ones? Man: Those suit you much better. They''re warm-coloured without looking too unusual. Woman: Yes, I think I''ll buy those.","transcript_status":"source_word_comment","word_comment_ids":["278"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'a6a8778c64bc47b9abb8995ddbe0770df27934748e2c1d5dcd31fba45f1b2dd4'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set022-q007-audio', 'Part 1 Question 280 Audio', 'Man: I''m just having coffee. It''s what I normally order here. Woman: The fish looks good today. Man: Are you hungry enough for a full meal? Woman: Not really. I think I''d rather have something sweet. Man: They''ve got chocolate cake and apple pie. Woman: I''ll have the cake, then.', '{"source_key":"listening-p1-set022-q007-audio","skill":"listening","part_number":1,"transcript":"Man: I''m just having coffee. It''s what I normally order here. Woman: The fish looks good today. Man: Are you hungry enough for a full meal? Woman: Not really. I think I''d rather have something sweet. Man: They''ve got chocolate cake and apple pie. Woman: I''ll have the cake, then.","transcript_status":"source_word_comment","word_comment_ids":["279"],"speaker_labels":["Man"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'b6f3ddf39324a2165198aec7b9c5f0e232b4b0737119317cfa3145431914c7cf'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set022-q008-audio', 'Part 1 Question 281 Audio', 'Woman: Could we meet at four thirty? Man: I can''t. I have to collect my brother from the bus station then. He''s coming back from London. Woman: Will five be okay? Man: I might still be on my way back. Woman: Let''s give you another half hour. Man: Yes, five thirty would be much safer.', '{"source_key":"listening-p1-set022-q008-audio","skill":"listening","part_number":1,"transcript":"Woman: Could we meet at four thirty? Man: I can''t. I have to collect my brother from the bus station then. He''s coming back from London. Woman: Will five be okay? Man: I might still be on my way back. Woman: Let''s give you another half hour. Man: Yes, five thirty would be much safer.","transcript_status":"source_word_comment","word_comment_ids":["280"],"speaker_labels":["Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '7740fdd51d0da689f42be92166a3566f2a1951537ea2cc0f1c9b478f4f648e70'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set022-q009-audio', 'Part 1 Question 282 Audio', 'I''ve decided I really need to change my morning routine. Getting up at eight means I''m always rushing and sometimes I don''t even have time for breakfast. I did think about setting my alarm for six, but there''s no chance I''d manage that every day. So I''m going to choose the time exactly between those two. That should give me enough time without making the morning unbearable.', '{"source_key":"listening-p1-set022-q009-audio","skill":"listening","part_number":1,"transcript":"I''ve decided I really need to change my morning routine. Getting up at eight means I''m always rushing and sometimes I don''t even have time for breakfast. I did think about setting my alarm for six, but there''s no chance I''d manage that every day. So I''m going to choose the time exactly between those two. That should give me enough time without making the morning unbearable.","transcript_status":"source_word_comment","word_comment_ids":["281"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '35709d351d6490e9114ccc72bb075ecfc0347167f7309c26bec61ea525dd5656'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set022-q010-audio', 'Part 1 Question 283 Audio', 'The new house is much bigger than our old place. There''s one room downstairs that we''re going to use for guests, and upstairs there are three more rooms where people can sleep. One of those will be ours and the other two will be for the children. It''s definitely more space than we had before.', '{"source_key":"listening-p1-set022-q010-audio","skill":"listening","part_number":1,"transcript":"The new house is much bigger than our old place. There''s one room downstairs that we''re going to use for guests, and upstairs there are three more rooms where people can sleep. One of those will be ours and the other two will be for the children. It''s definitely more space than we had before.","transcript_status":"source_word_comment","word_comment_ids":["282"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '71ee8e45aad0fc537f8bf87d32f0b6c0c78bc4340d870f135de85c1ef235d6a0'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set022-q011-audio', 'Part 1 Question 284 Audio', 'Student: I''m really struggling with this assignment. The topic is much harder than I expected.
Teacher: You can simplify some of the examples if that helps.
Student: Could I change the whole subject? Teacher: I wouldn''t recommend starting again now.
Student:', '{"source_key":"listening-p1-set022-q011-audio","skill":"listening","part_number":1,"transcript":"Student: I''m really struggling with this assignment. The topic is much harder than I expected.\nTeacher: You can simplify some of the examples if that helps.\nStudent: Could I change the whole subject? Teacher: I wouldn''t recommend starting again now.\nStudent:","transcript_status":"source_word_comment","word_comment_ids":["283"],"speaker_labels":["Student","Teacher"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '9e9fa36472d9ee236ff5d34564ecddde3b89f55b1742a62570cd9f912fa3405f'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set022-q012-audio', 'Part 1 Question 285 Audio', 'Interviewer: Why did you decide to take a job overseas? Was it because the salary was better? Woman: No, actually, the pay was almost exactly the same. Interviewer: Was it mainly because you wanted to experience another culture? Woman: That was interesting, but it wasn''t the main reason. My sister had been living there for several years, and before I moved we could only see each other once or twice a year. Taking the job meant we could meet much more often. Interviewer: I can see why that appealed to you.', '{"source_key":"listening-p1-set022-q012-audio","skill":"listening","part_number":1,"transcript":"Interviewer: Why did you decide to take a job overseas? Was it because the salary was better? Woman: No, actually, the pay was almost exactly the same. Interviewer: Was it mainly because you wanted to experience another culture? Woman: That was interesting, but it wasn''t the main reason. My sister had been living there for several years, and before I moved we could only see each other once or twice a year. Taking the job meant we could meet much more often. Interviewer: I can see why that appealed to you.","transcript_status":"source_word_comment","word_comment_ids":["284"],"speaker_labels":["Interviewer"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '4414c7d64433bb0e8bb54bfee9d2b3727a73106e7f32cd51683583d1df6226ef'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p1-set022-q013-audio', 'Part 1 Question 286 Audio', 'People often ask me what I like most about travelling for work. It isn''t the hotels - honestly, after a while they all feel the same - and I certainly don''t enjoy getting up at four in the morning for an early flight. The best part is talking to people from different companies. They often solve problems in ways I haven''t considered before, and I usually return to the office with completely fresh approaches that I can try in my own work.', '{"source_key":"listening-p1-set022-q013-audio","skill":"listening","part_number":1,"transcript":"People often ask me what I like most about travelling for work. It isn''t the hotels - honestly, after a while they all feel the same - and I certainly don''t enjoy getting up at four in the morning for an early flight. The best part is talking to people from different companies. They often solve problems in ways I haven''t considered before, and I usually return to the office with completely fresh approaches that I can try in my own work.","transcript_status":"source_word_comment","word_comment_ids":["285"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'c9bc2a422b57956fc30f5a10422ed7a6b9f19925661dd6800ec9ebbf54f1ce4c'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p2-set001-audio', 'Listening Part 2: Protect the environment 1 Audio', '**Segment 1 — Does not use commercial cleaning products**

Person A: I find the act of giving away old or secondhand items a bit hypocritical. Why do people give away their old things, only to go out and buy the same item but brand new? Not only does this fail to protect the environment, but it also causes double the harm. Personally, I have a way of protecting the environment by not releasing harmful chemicals into it. I do this by not purchasing chemical cleaning solutions. Instead, I make use of natural products like lemons to create my own floor-cleaning solutions.



**Segment 2 — Does not use commercial cleaning products**

Person B: I often don''t have time to think about how to reuse my belongings or clothes, but I don''t want to throw them away because that would be wasteful. So, I think a better way is to donate them to charity organizations or give them to others. Many people are in need of these things, and giving away my old items also makes me feel happier because I''m helping others.



**Segment 3 — Buy environmentally friendly products**

Person C: A good way to protect the environment is by not using plastic bags or by bringing reusable bags when going to the market, which helps reduce the disposal of plastic bags, a material that is difficult to decompose. However, I''m a very busy person and rarely have time to prepare my own bags when going shopping, and I usually drive to buy groceries quickly instead of walking. I guess I can''t protect the environment by not driving. But I have a principle of only buying eco-friendly products, so I think I’m still contributing in a small way to protecting the Earth.



**Segment 4 — Reuse containers for storing food**

Person D: I see that too many people are wasting food containers, as they often throw them away after use, such as glass jars or plastic bottles. I can reuse them to store food and neatly organize them in my refrigerator. Reusing these containers is a very easy way to protect the environment that anyone can do.', '{"source_key":"listening-p2-set001-audio","skill":"listening","part_number":2,"transcript":"**Segment 1 — Does not use commercial cleaning products**\n\nPerson A: I find the act of giving away old or secondhand items a bit hypocritical. Why do people give away their old things, only to go out and buy the same item but brand new? Not only does this fail to protect the environment, but it also causes double the harm. Personally, I have a way of protecting the environment by not releasing harmful chemicals into it. I do this by not purchasing chemical cleaning solutions. Instead, I make use of natural products like lemons to create my own floor-cleaning solutions.\n\n\n\n**Segment 2 — Does not use commercial cleaning products**\n\nPerson B: I often don''t have time to think about how to reuse my belongings or clothes, but I don''t want to throw them away because that would be wasteful. So, I think a better way is to donate them to charity organizations or give them to others. Many people are in need of these things, and giving away my old items also makes me feel happier because I''m helping others.\n\n\n\n**Segment 3 — Buy environmentally friendly products**\n\nPerson C: A good way to protect the environment is by not using plastic bags or by bringing reusable bags when going to the market, which helps reduce the disposal of plastic bags, a material that is difficult to decompose. However, I''m a very busy person and rarely have time to prepare my own bags when going shopping, and I usually drive to buy groceries quickly instead of walking. I guess I can''t protect the environment by not driving. But I have a principle of only buying eco-friendly products, so I think I’m still contributing in a small way to protecting the Earth.\n\n\n\n**Segment 4 — Reuse containers for storing food**\n\nPerson D: I see that too many people are wasting food containers, as they often throw them away after use, such as glass jars or plastic bottles. I can reuse them to store food and neatly organize them in my refrigerator. Reusing these containers is a very easy way to protect the environment that anyone can do.","transcript_status":"source_word_comments","word_comment_ids":["286","287","288","289"],"speaker_labels":["Person A","Person B","Person C","Person D"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '0642ca7a6d7932bfa701e1c4620510a2f61f178ef28d8413f021ca058b56093a'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p2-set002-audio', 'Listening Part 2: Protect the environment 2 Audio', '**Segment 1 — Shopping online**

A: I usually shop online to reduce the need to drive to the supermarket, which produces harmful emissions for the environment. Additionally, I can avoid using plastic bags for groceries when shopping in person. By simply sitting at home and clicking a few buttons, I can buy everything I want without emitting harmful gases from a car.



**Segment 2 — Not driving to work**

B: I used to drive to work for a long period, but then I realized that the excessive use of personal cars contributes significantly to environmental pollution. Therefore, I chose to ride a bicycle to work, which benefits both the environment and my health.



**Segment 3 — Using less electricity**

C: I''m not that into environmental protection and usually just do what’s convenient for me. But my electric bill last month shocked me because it was so expensive, and I realized that I needed to save money. So from now on, I’ll have to manage my electricity use more efficiently.



**Segment 4 — Using less water**

D: I think a lot of people overemphasize protecting the environment by cutting down on personal vehicles, avoiding plastic bags, planting a lot of trees, and so on. But I personally believe we should focus on protecting the environment through small daily actions we often overlook. For example, turning off the water while brushing our teeth or washing our hands. If everyone saves a little water like that, it would add up to a huge amount saved globally.', '{"source_key":"listening-p2-set002-audio","skill":"listening","part_number":2,"transcript":"**Segment 1 — Shopping online**\n\nA: I usually shop online to reduce the need to drive to the supermarket, which produces harmful emissions for the environment. Additionally, I can avoid using plastic bags for groceries when shopping in person. By simply sitting at home and clicking a few buttons, I can buy everything I want without emitting harmful gases from a car.\n\n\n\n**Segment 2 — Not driving to work**\n\nB: I used to drive to work for a long period, but then I realized that the excessive use of personal cars contributes significantly to environmental pollution. Therefore, I chose to ride a bicycle to work, which benefits both the environment and my health.\n\n\n\n**Segment 3 — Using less electricity**\n\nC: I''m not that into environmental protection and usually just do what’s convenient for me. But my electric bill last month shocked me because it was so expensive, and I realized that I needed to save money. So from now on, I’ll have to manage my electricity use more efficiently.\n\n\n\n**Segment 4 — Using less water**\n\nD: I think a lot of people overemphasize protecting the environment by cutting down on personal vehicles, avoiding plastic bags, planting a lot of trees, and so on. But I personally believe we should focus on protecting the environment through small daily actions we often overlook. For example, turning off the water while brushing our teeth or washing our hands. If everyone saves a little water like that, it would add up to a huge amount saved globally.","transcript_status":"source_word_comments","word_comment_ids":["290","291","292","293"],"speaker_labels":["Person A","Person B","Person C","Person D"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'c53af72e667f83afbd9a3a1e65be0230079b1425990e68d687dbd4420b2c1b7a'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p2-set003-audio', 'Listening Part 2: Online shopping Audio', '**Segment 1 — The products are delivered**

A: "I used to be the person who didn’t like shopping online, but ever since I experienced home delivery, I no longer shop in stores. When I shop online, the delivery person brings the package right to my door, even up to my floor, and knocks on my apartment door, so I don’t even need to step outside. I really enjoy this convenience."



**Segment 2 — It is cheaper**

B: "Shopping online has helped me save quite a bit of money. After a few months of online shopping, I was able to save enough to buy a new bicycle. But don''t get me wrong, I haven''t been eating any less or cutting back on the groceries I buy. It''s just that online shopping allows me to compare prices and choose the store with the best deal."



**Segment 3 — It saves time**

C: "I’m a pretty busy person, and I often don’t have enough time because of my hectic work schedule. That’s why I always shop online to save time. This way, I don’t need to go to the store in person, and someone will deliver the items directly to me. Additionally, online shopping is very convenient because, with just a few clicks, I can buy everything I want without having to go from one store to another."



**Segment 4 — There are more choices**

D: "I don''t shop online because it''s cheaper or because of the fast shipping. I shop online because, when browsing online stores, I have a wide range of choices. For the same item, there are many different types and brands for me to choose from and compare, which allows me to pick the one I like the most."', '{"source_key":"listening-p2-set003-audio","skill":"listening","part_number":2,"transcript":"**Segment 1 — The products are delivered**\n\nA: \"I used to be the person who didn’t like shopping online, but ever since I experienced home delivery, I no longer shop in stores. When I shop online, the delivery person brings the package right to my door, even up to my floor, and knocks on my apartment door, so I don’t even need to step outside. I really enjoy this convenience.\"\n\n\n\n**Segment 2 — It is cheaper**\n\nB: \"Shopping online has helped me save quite a bit of money. After a few months of online shopping, I was able to save enough to buy a new bicycle. But don''t get me wrong, I haven''t been eating any less or cutting back on the groceries I buy. It''s just that online shopping allows me to compare prices and choose the store with the best deal.\"\n\n\n\n**Segment 3 — It saves time**\n\nC: \"I’m a pretty busy person, and I often don’t have enough time because of my hectic work schedule. That’s why I always shop online to save time. This way, I don’t need to go to the store in person, and someone will deliver the items directly to me. Additionally, online shopping is very convenient because, with just a few clicks, I can buy everything I want without having to go from one store to another.\"\n\n\n\n**Segment 4 — There are more choices**\n\nD: \"I don''t shop online because it''s cheaper or because of the fast shipping. I shop online because, when browsing online stores, I have a wide range of choices. For the same item, there are many different types and brands for me to choose from and compare, which allows me to pick the one I like the most.\"","transcript_status":"source_word_comments","word_comment_ids":["294","295","296","297"],"speaker_labels":["Person A","Person B","Person C","Person D"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'd62e93022ecae1d31d21541a5d96ab2b8ab0ca4eb6a781e8db29440a172e5ffd'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p2-set004-audio', 'Listening Part 2: Listening to music Audio', '**Segment 1 — To relax**

A: "I see a lot of people listen to music right when they wake up to help them feel alert. But if I listen to music as soon as I wake up, it gives me a headache all day and makes it hard for me to focus on anything. So, I just listen to music to relax when I’m feeling comfortable, not for any other reason."



**Segment 2 — After waking up**

B: "I usually listen to a pop or rock song as soon as I get out of bed in the morning because it helps me wake up instantly. If I don''t listen to music at that moment, I don''t know when I''ll be able to get up and go to work."



**Segment 3 — While singing**

C: "My brothers and friends often say that I have a beautiful voice, so I often sing when I meet them. I usually play music on the TV and hold the remote control, pretending it''s a microphone so I can sing."



**Segment 4 — While studying**

D: "I have a habit of listening to music while studying; it helps me stay motivated and alert while doing my assignments. If I don''t play music, I could fall asleep at any moment, and I''ll study in a discouraged mood."', '{"source_key":"listening-p2-set004-audio","skill":"listening","part_number":2,"transcript":"**Segment 1 — To relax**\n\nA: \"I see a lot of people listen to music right when they wake up to help them feel alert. But if I listen to music as soon as I wake up, it gives me a headache all day and makes it hard for me to focus on anything. So, I just listen to music to relax when I’m feeling comfortable, not for any other reason.\"\n\n\n\n**Segment 2 — After waking up**\n\nB: \"I usually listen to a pop or rock song as soon as I get out of bed in the morning because it helps me wake up instantly. If I don''t listen to music at that moment, I don''t know when I''ll be able to get up and go to work.\"\n\n\n\n**Segment 3 — While singing**\n\nC: \"My brothers and friends often say that I have a beautiful voice, so I often sing when I meet them. I usually play music on the TV and hold the remote control, pretending it''s a microphone so I can sing.\"\n\n\n\n**Segment 4 — While studying**\n\nD: \"I have a habit of listening to music while studying; it helps me stay motivated and alert while doing my assignments. If I don''t play music, I could fall asleep at any moment, and I''ll study in a discouraged mood.\"","transcript_status":"source_word_comments","word_comment_ids":["298","299","300","301"],"speaker_labels":["Person A","Person B","Person C","Person D"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'f1f7cf294a8e304c962d95649cd03079bf1ced3e721f0ccb00c07aa64dd876c8'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p2-set005-audio', 'Listening Part 2: Outdoor activities Audio', '**Segment 1 — horse riding**

A: "My hometown is in the countryside, and we have a very large and beautiful farm. I’ve been learning to ride horses since I was a child, and it’s still my hobby to this day. Whenever I want to relax or enjoy the scenery, I ride my horse along the farm and across the meadows."



**Segment 2 — going for a run**

B: "My husband and I often wake up early and go to a nearby forest for exercise. We usually go jogging in the early morning to stay healthy, and we really enjoy the fresh air and natural scenery in the forest."



**Segment 3 — climbing**

C: "I used to love mountain biking, enjoying the thrill of riding down steep slopes. It was really an amazing and adventurous feeling. However, after an injury from a fall, I became haunted by the fear of crashing and now I''m scared of this sport. But I still love the mountains, so I’ve decided to just go hiking every weekend instead."



**Segment 4 — mountain biking**

D: "My father often encourages me to ride horses because it’s a sport he enjoys. But I’m very afraid of this animal and never want to learn how to ride, even though there’s a riding school near my house. Instead, I prefer mountain biking with my friends to conquer high peaks."', '{"source_key":"listening-p2-set005-audio","skill":"listening","part_number":2,"transcript":"**Segment 1 — horse riding**\n\nA: \"My hometown is in the countryside, and we have a very large and beautiful farm. I’ve been learning to ride horses since I was a child, and it’s still my hobby to this day. Whenever I want to relax or enjoy the scenery, I ride my horse along the farm and across the meadows.\"\n\n\n\n**Segment 2 — going for a run**\n\nB: \"My husband and I often wake up early and go to a nearby forest for exercise. We usually go jogging in the early morning to stay healthy, and we really enjoy the fresh air and natural scenery in the forest.\"\n\n\n\n**Segment 3 — climbing**\n\nC: \"I used to love mountain biking, enjoying the thrill of riding down steep slopes. It was really an amazing and adventurous feeling. However, after an injury from a fall, I became haunted by the fear of crashing and now I''m scared of this sport. But I still love the mountains, so I’ve decided to just go hiking every weekend instead.\"\n\n\n\n**Segment 4 — mountain biking**\n\nD: \"My father often encourages me to ride horses because it’s a sport he enjoys. But I’m very afraid of this animal and never want to learn how to ride, even though there’s a riding school near my house. Instead, I prefer mountain biking with my friends to conquer high peaks.\"","transcript_status":"source_word_comments","word_comment_ids":["302","303","304","305"],"speaker_labels":["Person A","Person B","Person C","Person D"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'd11f090ef3ea90b24bbda08e1f0f445ed6a34cbbead52da73647f4b199c13f82'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p2-set006-audio', 'Listening Part 2: The place to run Audio', '**Segment 1 — in the fitness centre**

A: "My friends often invite me to go jogging on the street, but I find it too dangerous. There’s a lot of traffic, which can be dangerous for people jogging on the street. So, I bought a one-year gym membership and go there to exercise every day."



**Segment 2 — at the seaside**

B: "I see many people wake up early to go jogging and exercise to stay healthy. As for me, I usually walk along the beach simply to relax because there’s a beautiful beach near my house. Every morning, I spend time walking on the white sand; it really helps a lot with my mental well-being."



**Segment 3 — in the street**

C: "I usually wake up early in the morning to exercise, and I choose to jog on the street because of its convenience. I just need to step out of the house, and I can start exercising. However, I have to go jogging early to avoid cyclists. My friends go to the gym to exercise a lot, but I find something artificial about the whole thing."



**Segment 4 — on the running track**

D: "Near my house, there’s a stadium where many people go to exercise. I often run on the track there, and it makes me feel like I’m running more professionally. My personality is quite competitive, so I also time myself and race with my friends there."', '{"source_key":"listening-p2-set006-audio","skill":"listening","part_number":2,"transcript":"**Segment 1 — in the fitness centre**\n\nA: \"My friends often invite me to go jogging on the street, but I find it too dangerous. There’s a lot of traffic, which can be dangerous for people jogging on the street. So, I bought a one-year gym membership and go there to exercise every day.\"\n\n\n\n**Segment 2 — at the seaside**\n\nB: \"I see many people wake up early to go jogging and exercise to stay healthy. As for me, I usually walk along the beach simply to relax because there’s a beautiful beach near my house. Every morning, I spend time walking on the white sand; it really helps a lot with my mental well-being.\"\n\n\n\n**Segment 3 — in the street**\n\nC: \"I usually wake up early in the morning to exercise, and I choose to jog on the street because of its convenience. I just need to step out of the house, and I can start exercising. However, I have to go jogging early to avoid cyclists. My friends go to the gym to exercise a lot, but I find something artificial about the whole thing.\"\n\n\n\n**Segment 4 — on the running track**\n\nD: \"Near my house, there’s a stadium where many people go to exercise. I often run on the track there, and it makes me feel like I’m running more professionally. My personality is quite competitive, so I also time myself and race with my friends there.\"","transcript_status":"source_word_comments","word_comment_ids":["306","307","308","309"],"speaker_labels":["Person A","Person B","Person C","Person D"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'ca75796e8b28ab4b619c6cbaa16c74336c246ffc82e784f3202d093cd3ef81de'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p2-set007-audio', 'Listening Part 2: Do exercise Audio', '**Segment 1 — hate exercising**

A: "My friends often advise me to exercise to maintain a good physique and health. However, I am very busy with a tight work schedule. Even if I weren’t busy, I still wouldn’t like to exercise. I feel uncomfortable as soon as I put on workout clothes. I don’t think exercise is something that suits me."



**Segment 2 — help improve work performance**

B: "I know that working out every day is good for my health and helps me get in shape. But what I''ve found is that exercising actually boosts my productivity a lot and really helps me focus better. So, I always try to squeeze in some exercise before heading to work—it definitely makes me more productive."



**Segment 3 — find exercise tiring**

C: "We’ve all heard about the many benefits of exercising, and I know about them too. My friends often invite me to work out, but after I exercise, I end up feeling extremely exhausted and spend the rest of the day just lying around to recover."



**Segment 4 — has fun when exercising with friends**

D: "I often go to the gym to work out, but what really motivates me to workout is catching up with my friends there, not just for improving my health. Plus, it’s a great way to meet and make new friends. For me, exercising is just another chance to socialize."', '{"source_key":"listening-p2-set007-audio","skill":"listening","part_number":2,"transcript":"**Segment 1 — hate exercising**\n\nA: \"My friends often advise me to exercise to maintain a good physique and health. However, I am very busy with a tight work schedule. Even if I weren’t busy, I still wouldn’t like to exercise. I feel uncomfortable as soon as I put on workout clothes. I don’t think exercise is something that suits me.\"\n\n\n\n**Segment 2 — help improve work performance**\n\nB: \"I know that working out every day is good for my health and helps me get in shape. But what I''ve found is that exercising actually boosts my productivity a lot and really helps me focus better. So, I always try to squeeze in some exercise before heading to work—it definitely makes me more productive.\"\n\n\n\n**Segment 3 — find exercise tiring**\n\nC: \"We’ve all heard about the many benefits of exercising, and I know about them too. My friends often invite me to work out, but after I exercise, I end up feeling extremely exhausted and spend the rest of the day just lying around to recover.\"\n\n\n\n**Segment 4 — has fun when exercising with friends**\n\nD: \"I often go to the gym to work out, but what really motivates me to workout is catching up with my friends there, not just for improving my health. Plus, it’s a great way to meet and make new friends. For me, exercising is just another chance to socialize.\"","transcript_status":"source_word_comments","word_comment_ids":["310","311","312","313"],"speaker_labels":["Person A","Person B","Person C","Person D"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'f658c120089ed7118a9954b2d031f9c2a9da6b3be164350d2278707e73d73a1d'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p2-set008-audio', 'Listening Part 2: The internet Audio', '**Segment 1 — watch films**

A: "I am a big fan of newly released movies, but the cost of going to the cinema is too high. I''m just a student, so I can''t afford to go to the cinema regularly to indulge in my hobby. Therefore, I think the internet is great because it allows me to watch movies for free at home. I save both the time of going to the cinema and a considerable amount of money."



**Segment 2 — communicate with friends**

B: "In today''s digital age, the internet helps us access social media to stay constantly connected with friends. Especially since I have relatives mainly living abroad or in distant cities, the internet has been a great help for my family to stay in touch. We often video call each other to share daily stories."



**Segment 3 — complete assignments**

C: "The internet is a great resource for research, finding materials, and useful information for studying. My friends and I often go to each other''s houses to do homework together. Instead of spending hours trying to figure out how to do our homework, we quickly go online and find the answers."



**Segment 4 — find transport information**

D: "I see that people often use the internet to watch movies, read newspapers, quickly update the news, and so on. But I usually use the internet to find directions and public transport to my friends'' and relatives'' houses. I''m a forgetful person, and I often forget the way, even if I''ve been there a hundred times. So the internet helps me a lot in not getting lost and easily find nearby public transport."', '{"source_key":"listening-p2-set008-audio","skill":"listening","part_number":2,"transcript":"**Segment 1 — watch films**\n\nA: \"I am a big fan of newly released movies, but the cost of going to the cinema is too high. I''m just a student, so I can''t afford to go to the cinema regularly to indulge in my hobby. Therefore, I think the internet is great because it allows me to watch movies for free at home. I save both the time of going to the cinema and a considerable amount of money.\"\n\n\n\n**Segment 2 — communicate with friends**\n\nB: \"In today''s digital age, the internet helps us access social media to stay constantly connected with friends. Especially since I have relatives mainly living abroad or in distant cities, the internet has been a great help for my family to stay in touch. We often video call each other to share daily stories.\"\n\n\n\n**Segment 3 — complete assignments**\n\nC: \"The internet is a great resource for research, finding materials, and useful information for studying. My friends and I often go to each other''s houses to do homework together. Instead of spending hours trying to figure out how to do our homework, we quickly go online and find the answers.\"\n\n\n\n**Segment 4 — find transport information**\n\nD: \"I see that people often use the internet to watch movies, read newspapers, quickly update the news, and so on. But I usually use the internet to find directions and public transport to my friends'' and relatives'' houses. I''m a forgetful person, and I often forget the way, even if I''ve been there a hundred times. So the internet helps me a lot in not getting lost and easily find nearby public transport.\"","transcript_status":"source_word_comments","word_comment_ids":["314","315","316","317"],"speaker_labels":["Person A","Person B","Person C","Person D"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'c70fa0f06527fe219f7a1ba4bef61587884d097b52bacfba943224e15908ca0d'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p2-set009-audio', 'Listening Part 2: The Art Audio', '**Segment 1 — social activity**

A: "I personally don''t like and don''t have a talent for fine arts, especially painting. But I see it as a great way to engage in social charity activities. I''m passionate about teaching children how to draw because I love kids. I''m also part of a volunteer organization that specializes in teaching art to poor children, which makes me very happy."



**Segment 2 — with children**

B: "I think drawing with my children is a great way to understand them better. No matter how busy my work is, I always make time to sit and draw with my kids. This helps us bond more and gives me the chance to talk with them more."



**Segment 3 — as part of their job**

C: "I''ve loved literature, art, and drawing since I was a child. Now, I''m a writer and a comic book creator. In my stories, I occasionally include some illustrations to make the book more vivid and lively."



**Segment 4 — alone**

D: "I''m currently taking a drawing course and I really want to be serious about it. When practicing drawing, I prefer not to draw with friends, even though they often invite me to join them. I want to focus entirely on my work."', '{"source_key":"listening-p2-set009-audio","skill":"listening","part_number":2,"transcript":"**Segment 1 — social activity**\n\nA: \"I personally don''t like and don''t have a talent for fine arts, especially painting. But I see it as a great way to engage in social charity activities. I''m passionate about teaching children how to draw because I love kids. I''m also part of a volunteer organization that specializes in teaching art to poor children, which makes me very happy.\"\n\n\n\n**Segment 2 — with children**\n\nB: \"I think drawing with my children is a great way to understand them better. No matter how busy my work is, I always make time to sit and draw with my kids. This helps us bond more and gives me the chance to talk with them more.\"\n\n\n\n**Segment 3 — as part of their job**\n\nC: \"I''ve loved literature, art, and drawing since I was a child. Now, I''m a writer and a comic book creator. In my stories, I occasionally include some illustrations to make the book more vivid and lively.\"\n\n\n\n**Segment 4 — alone**\n\nD: \"I''m currently taking a drawing course and I really want to be serious about it. When practicing drawing, I prefer not to draw with friends, even though they often invite me to join them. I want to focus entirely on my work.\"","transcript_status":"source_word_comments","word_comment_ids":["318","319","320","321"],"speaker_labels":["Person A","Person B","Person C","Person D"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'e288a36579845e1aca587dbdbd68c70a6ed2e99d19d98eb50ec275b28c5faaf8'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p2-set010-audio', 'Listening Part 2: Travel to work. Audio', '**Segment 1 — travel by bus**

A: "I''m concerned about the Earth and the environment, so I always look for ways to use public transportation, like buses or trains, to reduce harmful emissions. I can''t walk to work because it''s too far from my home, but I always walk to the local market when I need to buy groceries."



**Segment 2 — travel by car**

B: "I had to take driving lessons to be able to drive to work. My mother works along the same route, so we often drive to work together. Occasionally, she takes over the driving, and I''m happy because driving together gives us more time to chat."



**Segment 3 — walk alone**

C: "I used to use my car a lot to get to work. But since I moved closer to the company, I always go there on foot. I have a friend who cycles for 20 minutes every day to work—can you imagine? She must be super fit!"



**Segment 4 — walk with a friend**

D: "I often choose to walk to work to save on gas money and to keep in shape. I usually walk to the company with a close friend. Sometimes we feel really tired but still push ourselves to walk all the way. There are times when we see a bus stop and have to resist the urge to hop on the bus."', '{"source_key":"listening-p2-set010-audio","skill":"listening","part_number":2,"transcript":"**Segment 1 — travel by bus**\n\nA: \"I''m concerned about the Earth and the environment, so I always look for ways to use public transportation, like buses or trains, to reduce harmful emissions. I can''t walk to work because it''s too far from my home, but I always walk to the local market when I need to buy groceries.\"\n\n\n\n**Segment 2 — travel by car**\n\nB: \"I had to take driving lessons to be able to drive to work. My mother works along the same route, so we often drive to work together. Occasionally, she takes over the driving, and I''m happy because driving together gives us more time to chat.\"\n\n\n\n**Segment 3 — walk alone**\n\nC: \"I used to use my car a lot to get to work. But since I moved closer to the company, I always go there on foot. I have a friend who cycles for 20 minutes every day to work—can you imagine? She must be super fit!\"\n\n\n\n**Segment 4 — walk with a friend**\n\nD: \"I often choose to walk to work to save on gas money and to keep in shape. I usually walk to the company with a close friend. Sometimes we feel really tired but still push ourselves to walk all the way. There are times when we see a bus stop and have to resist the urge to hop on the bus.\"","transcript_status":"source_word_comments","word_comment_ids":["322","323","324","325"],"speaker_labels":["Person A","Person B","Person C","Person D"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'ea63045e1f783ffadae17a25d7062e447e08049fd9921e777400518e6c914dbc'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p2-set011-audio', 'Listening Part 2: Studying. Audio', '**Segment 1 — In various places**

A: "I can study in different places, like coffee shops, libraries, or parks. For me, the location isn''t that important because I have good concentration skills."



**Segment 2 — In a quiet place**

B: "I can''t study in very noisy places because I can''t focus on my homework. If I study in a café, I end up not getting anything done. So, I usually study in places such as my room in my house or in my office."



**Segment 3 — With music**

C: "I prefer listening to music while studying. I usually play motivational songs to help keep me alert, especially when studying in the morning. Music is like a cup of coffee, keeping me awake and motivated in my studies."



**Segment 4 — Late at night**

D: "I often can''t focus on studying during the day; I feel tired and sleepy when I have to wake up early and study. So, I usually study at night when everyone in the house is asleep. The quiet atmosphere at night allows me to focus the best and be the most productive."', '{"source_key":"listening-p2-set011-audio","skill":"listening","part_number":2,"transcript":"**Segment 1 — In various places**\n\nA: \"I can study in different places, like coffee shops, libraries, or parks. For me, the location isn''t that important because I have good concentration skills.\"\n\n\n\n**Segment 2 — In a quiet place**\n\nB: \"I can''t study in very noisy places because I can''t focus on my homework. If I study in a café, I end up not getting anything done. So, I usually study in places such as my room in my house or in my office.\"\n\n\n\n**Segment 3 — With music**\n\nC: \"I prefer listening to music while studying. I usually play motivational songs to help keep me alert, especially when studying in the morning. Music is like a cup of coffee, keeping me awake and motivated in my studies.\"\n\n\n\n**Segment 4 — Late at night**\n\nD: \"I often can''t focus on studying during the day; I feel tired and sleepy when I have to wake up early and study. So, I usually study at night when everyone in the house is asleep. The quiet atmosphere at night allows me to focus the best and be the most productive.\"","transcript_status":"source_word_comments","word_comment_ids":["326","327","328","329"],"speaker_labels":["Person A","Person B","Person C","Person D"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'b4b15f3bd2ce96ff1e242b4a9eec8f9674e523f3914b1988d59ecd007260e790'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p2-set012-audio', 'Listening Part 2: Studying (phiên bản 2). Audio', '**Segment 1 — In the coffee shop**

A: "I don''t like studying in very quiet places such as at home or in the library because I get sleepy easily and might even fall asleep while studying. There''s a coffee shop near my house, and I often go there to study because the presence of other people makes me feel more motivated. I find that I achieve higher productivity and efficiency in my studies when I''m there."



**Segment 2 — In the park**

B: "I notice that most people prefer doing their homework in the classroom, but for me, those chairs are way too hard and leave me sore all day. I prefer sitting under the trees in the park to study—it''s cool, and the air is fresh. There''s a famous coffee shop across from where I sit, and they serve really good coffee."



**Segment 3 — On public transport**

C: "The distance from my house to school is 20 km, and it usually takes me an hour to get there. So, when I''m on the train, I use the time to do homework and review the lessons for the day. Some people say that studying like this can be distracting, but I find it very effective for me."



**Segment 4 — At home**

D: "I don''t like studying in very crowded places because I can''t focus well. I usually sit on the sofa in the living room to study. My parents often travel for work, so my house is very quiet."', '{"source_key":"listening-p2-set012-audio","skill":"listening","part_number":2,"transcript":"**Segment 1 — In the coffee shop**\n\nA: \"I don''t like studying in very quiet places such as at home or in the library because I get sleepy easily and might even fall asleep while studying. There''s a coffee shop near my house, and I often go there to study because the presence of other people makes me feel more motivated. I find that I achieve higher productivity and efficiency in my studies when I''m there.\"\n\n\n\n**Segment 2 — In the park**\n\nB: \"I notice that most people prefer doing their homework in the classroom, but for me, those chairs are way too hard and leave me sore all day. I prefer sitting under the trees in the park to study—it''s cool, and the air is fresh. There''s a famous coffee shop across from where I sit, and they serve really good coffee.\"\n\n\n\n**Segment 3 — On public transport**\n\nC: \"The distance from my house to school is 20 km, and it usually takes me an hour to get there. So, when I''m on the train, I use the time to do homework and review the lessons for the day. Some people say that studying like this can be distracting, but I find it very effective for me.\"\n\n\n\n**Segment 4 — At home**\n\nD: \"I don''t like studying in very crowded places because I can''t focus well. I usually sit on the sofa in the living room to study. My parents often travel for work, so my house is very quiet.\"","transcript_status":"source_word_comments","word_comment_ids":["330","331","332","333"],"speaker_labels":["Person A","Person B","Person C","Person D"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'c011f8047b29727c29fbfdc4e1124d9cf1d067997deb20b172fe2634d5776702'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p2-set013-audio', 'Listening Part 2: New museum in town Audio', '**Segment 1 — Finished the visit quickly**

Person A: I was quite excited to see the new museum in town, but when I arrived, I found it smaller than I expected. There were only a few rooms open to visitors, and some exhibitions were still being prepared. I walked through the main displays, took a few photos, and left after about thirty minutes. I thought the museum was interesting, but there was not enough to keep me there for a long time.



**Segment 2 — Got lost during the visit**

Person B: I liked the idea of having a new museum in our town, but my visit was a little frustrating. The building was quite large, and the signs were not very clear. I tried to find the history section, but I ended up walking around the same area several times. In the end, I had to ask a staff member for help because I could not find the correct room.



**Segment 3 — Enjoyed the use of technology**

Person C: For me, the best thing about the new museum was the modern technology. Instead of just reading information on the walls, visitors could use touch screens, audio guides, and even virtual reality to learn about the exhibits. This made the visit much more interesting and enjoyable, especially for young people.



**Segment 4 — Wants to visit again**

Person D: I had a really good time at the new museum, although I could not see everything in one visit. Some parts were very crowded, and I missed one special exhibition because I arrived too late. I think the museum has a lot to offer, so I would definitely like to go back another day and spend more time there.', '{"source_key":"listening-p2-set013-audio","skill":"listening","part_number":2,"transcript":"**Segment 1 — Finished the visit quickly**\n\nPerson A: I was quite excited to see the new museum in town, but when I arrived, I found it smaller than I expected. There were only a few rooms open to visitors, and some exhibitions were still being prepared. I walked through the main displays, took a few photos, and left after about thirty minutes. I thought the museum was interesting, but there was not enough to keep me there for a long time.\n\n\n\n**Segment 2 — Got lost during the visit**\n\nPerson B: I liked the idea of having a new museum in our town, but my visit was a little frustrating. The building was quite large, and the signs were not very clear. I tried to find the history section, but I ended up walking around the same area several times. In the end, I had to ask a staff member for help because I could not find the correct room.\n\n\n\n**Segment 3 — Enjoyed the use of technology**\n\nPerson C: For me, the best thing about the new museum was the modern technology. Instead of just reading information on the walls, visitors could use touch screens, audio guides, and even virtual reality to learn about the exhibits. This made the visit much more interesting and enjoyable, especially for young people.\n\n\n\n**Segment 4 — Wants to visit again**\n\nPerson D: I had a really good time at the new museum, although I could not see everything in one visit. Some parts were very crowded, and I missed one special exhibition because I arrived too late. I think the museum has a lot to offer, so I would definitely like to go back another day and spend more time there.","transcript_status":"source_word_comments","word_comment_ids":["334","335","336","337"],"speaker_labels":["Person A","Person B","Person C","Person D"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'd03a280117b99e030e5a84a0367a9b4ebd01e14422dc108a7251f39e10792840'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p2-set014-audio', 'Listening Part 2: Visiting a new museum (2026) Audio', '**Segment 1 — Finished the visit quickly**

I nearly postponed the museum trip because I had a dentist''s appointment across town. Still, I thought I could squeeze in one gallery before leaving. I scanned the map, hurried past the café, and stopped only long enough to photograph the enormous whale skeleton. When the announcement said the next guided tour would begin in twenty minutes, I was already checking my watch. My friends stayed for the ancient coins exhibition, but I was back outside before they had even reached the second floor.



**Segment 2 — Got lost during the visit**

The building looked simple from outside, but inside it was a maze. I followed a blue arrow for "Local History," went through two glass doors, and somehow arrived back beside the dinosaur model. A guard pointed me upstairs, yet the lift opened in the modern art wing. By then, my sister had sent three messages asking where I was. I finally found her after asking at the information desk. I saw more corridors than exhibits that afternoon.



**Segment 3 — Enjoyed the use of technology**

I expected rows of objects behind glass, so the museum surprised me. At one display, I moved a tablet over an old ship model and watched sailors appear on the screen. In another room, headphones recreated the sounds of a crowded nineteenth-century market. The paintings were impressive, of course, but I spent longest at the interactive tables, trying different languages and zooming into tiny details. That digital side of the museum turned what could have been a visit into something genuinely exciting.



**Segment 4 — Wants to visit again**

My cousin complained that the museum was too crowded, and she was right-we for the space exhibition and missed the final planetarium show. Even so, the few rooms we managed to enter were excellent. I kept noticing doors marked "Members only" and posters for an exhibition opening next month. On the bus home, I checked the museum website and saved the date. One afternoon clearly wasn''t enough, so I''ve already persuaded my brother to come back with me.', '{"source_key":"listening-p2-set014-audio","skill":"listening","part_number":2,"transcript":"**Segment 1 — Finished the visit quickly**\n\nI nearly postponed the museum trip because I had a dentist''s appointment across town. Still, I thought I could squeeze in one gallery before leaving. I scanned the map, hurried past the café, and stopped only long enough to photograph the enormous whale skeleton. When the announcement said the next guided tour would begin in twenty minutes, I was already checking my watch. My friends stayed for the ancient coins exhibition, but I was back outside before they had even reached the second floor.\n\n\n\n**Segment 2 — Got lost during the visit**\n\nThe building looked simple from outside, but inside it was a maze. I followed a blue arrow for \"Local History,\" went through two glass doors, and somehow arrived back beside the dinosaur model. A guard pointed me upstairs, yet the lift opened in the modern art wing. By then, my sister had sent three messages asking where I was. I finally found her after asking at the information desk. I saw more corridors than exhibits that afternoon.\n\n\n\n**Segment 3 — Enjoyed the use of technology**\n\nI expected rows of objects behind glass, so the museum surprised me. At one display, I moved a tablet over an old ship model and watched sailors appear on the screen. In another room, headphones recreated the sounds of a crowded nineteenth-century market. The paintings were impressive, of course, but I spent longest at the interactive tables, trying different languages and zooming into tiny details. That digital side of the museum turned what could have been a visit into something genuinely exciting.\n\n\n\n**Segment 4 — Wants to visit again**\n\nMy cousin complained that the museum was too crowded, and she was right-we for the space exhibition and missed the final planetarium show. Even so, the few rooms we managed to enter were excellent. I kept noticing doors marked \"Members only\" and posters for an exhibition opening next month. On the bus home, I checked the museum website and saved the date. One afternoon clearly wasn''t enough, so I''ve already persuaded my brother to come back with me.","transcript_status":"source_word_comments","word_comment_ids":["338","339","340","341"],"speaker_labels":["Person A","Person B","Person C","Person D"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '3cb17d91c14d54be14841d7e8757742f0380b0e6de11baba6d9b6270fdae02da'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p2-set015-audio', 'Listening Part 2: Doing exercises (2026) Audio', '**Segment 1 — Improve work performance**

At three o''clock, my concentration used to disappear. I''d reread the same email, make silly mistakes, and reach for another coffee. A colleague suggested using half my lunch break for a brisk walk, which sounded like a waste of time. After a week, though, I noticed I was finishing reports earlier and handling difficult clients more calmly. I haven''t become a fitness enthusiast, but I protect that thirty-minute walk now because the rest of my working day goes so much better.



**Segment 2 — Find exercise tiring**

My sister finishes a workout glowing and cheerful. I finish one looking as though I''ve missed the last bus in a thunderstorm. Ten minutes into a class, my legs feel heavy; by the end, even climbing the stairs to my flat seems unreasonable. I keep trying because my doctor says movement is important, and I admit I sleep well afterwards. But that famous burst of energy everyone promises? It has never arrived. Exercise simply drains me.



**Segment 3 — Have fun exercising with others**

Last month, I joined a dance-fitness class only because my neighbour refused to go alone. Neither of us could follow the instructor at first, and we laughed so much that the people behind us started laughing too. Now six of us meet before class, share music, and celebrate whenever someone finally learns a difficult routine. I rarely notice how hard we''re working until the session ends. The company, jokes, and friendly competition are what keep me coming back.



**Segment 4 — Hate exercising**

People keep offering me new ways to "discover the joy" of exercise: swimming, cycling, yoga, even boxing. I''ve tried enough of them to know the problem isn''t the activity. I dislike changing into sports clothes, counting repetitions, sweating, and waking up with sore muscles. A walk to the bakery is fine because it has a useful destination, but exercising just for the sake of it feels like unpaid work. Give me a novel and a comfortable chair instead.', '{"source_key":"listening-p2-set015-audio","skill":"listening","part_number":2,"transcript":"**Segment 1 — Improve work performance**\n\nAt three o''clock, my concentration used to disappear. I''d reread the same email, make silly mistakes, and reach for another coffee. A colleague suggested using half my lunch break for a brisk walk, which sounded like a waste of time. After a week, though, I noticed I was finishing reports earlier and handling difficult clients more calmly. I haven''t become a fitness enthusiast, but I protect that thirty-minute walk now because the rest of my working day goes so much better.\n\n\n\n**Segment 2 — Find exercise tiring**\n\nMy sister finishes a workout glowing and cheerful. I finish one looking as though I''ve missed the last bus in a thunderstorm. Ten minutes into a class, my legs feel heavy; by the end, even climbing the stairs to my flat seems unreasonable. I keep trying because my doctor says movement is important, and I admit I sleep well afterwards. But that famous burst of energy everyone promises? It has never arrived. Exercise simply drains me.\n\n\n\n**Segment 3 — Have fun exercising with others**\n\nLast month, I joined a dance-fitness class only because my neighbour refused to go alone. Neither of us could follow the instructor at first, and we laughed so much that the people behind us started laughing too. Now six of us meet before class, share music, and celebrate whenever someone finally learns a difficult routine. I rarely notice how hard we''re working until the session ends. The company, jokes, and friendly competition are what keep me coming back.\n\n\n\n**Segment 4 — Hate exercising**\n\nPeople keep offering me new ways to \"discover the joy\" of exercise: swimming, cycling, yoga, even boxing. I''ve tried enough of them to know the problem isn''t the activity. I dislike changing into sports clothes, counting repetitions, sweating, and waking up with sore muscles. A walk to the bakery is fine because it has a useful destination, but exercising just for the sake of it feels like unpaid work. Give me a novel and a comfortable chair instead.","transcript_status":"source_word_comments","word_comment_ids":["342","343","344","345"],"speaker_labels":["Person A","Person B","Person C","Person D"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '524378220d5b7c38339fd63a09415a76903e12a7f1385400b7b0ed88de13d196'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p2-set016-audio', 'Listening Part 2: Their protecting the environment (2026) Audio', '**Segment 1 — protects the environment by using less electricity.**

My environmental habit began for a selfish reason: an electricity bill that was almost twice the usual amount. I bought a plug monitor and discovered the old television box was using power all night. Since then, lights go off when a room is empty, laundry waits until there is a full load, and chargers come out of the wall. The lower bill is welcome, but knowing the household is wasting far less energy matters just as much now.



**Segment 2 — protects the environment by not driving to work**

The office car park is visible from my desk, and every morning it fills with one person in each car. I used to be part of that line. Then roadworks turned my twenty-minute journey into an hour, so I tried cycling along the canal instead. It was , cheaper, and surprisingly relaxing. I still own a car for weekend trips, but it stays at home on working days. That single change has cut most of my weekly fuel use.



**Segment 3 — protects the environment by shopping online.**

Going to five different shops every Saturday meant five receipts, several plastic bags, and a lot of driving. Now I keep a list during the week and place one online order from a company that sends groceries in reusable boxes. The delivery van is already serving the whole neighbourhood, so dozens of separate car journeys are avoided. I know internet shopping is not automatically green, especially with urgent single-item deliveries, but combining everything into one order works well for me.



**Segment 4 — protects the environment by using less water.**

During last summer''s dry spell, our town asked everyone to reduce water use. I put a bucket in the shower while it warmed up and used that water on the balcony plants. It felt slightly ridiculous at first, yet the bucket filled faster than I expected. Now I also turn off the tap while brushing my teeth and run the dishwasher only when full. Those small routines continued long after the restrictions ended because wasting clean water no longer feels harmless.', '{"source_key":"listening-p2-set016-audio","skill":"listening","part_number":2,"transcript":"**Segment 1 — protects the environment by using less electricity.**\n\nMy environmental habit began for a selfish reason: an electricity bill that was almost twice the usual amount. I bought a plug monitor and discovered the old television box was using power all night. Since then, lights go off when a room is empty, laundry waits until there is a full load, and chargers come out of the wall. The lower bill is welcome, but knowing the household is wasting far less energy matters just as much now.\n\n\n\n**Segment 2 — protects the environment by not driving to work**\n\nThe office car park is visible from my desk, and every morning it fills with one person in each car. I used to be part of that line. Then roadworks turned my twenty-minute journey into an hour, so I tried cycling along the canal instead. It was , cheaper, and surprisingly relaxing. I still own a car for weekend trips, but it stays at home on working days. That single change has cut most of my weekly fuel use.\n\n\n\n**Segment 3 — protects the environment by shopping online.**\n\nGoing to five different shops every Saturday meant five receipts, several plastic bags, and a lot of driving. Now I keep a list during the week and place one online order from a company that sends groceries in reusable boxes. The delivery van is already serving the whole neighbourhood, so dozens of separate car journeys are avoided. I know internet shopping is not automatically green, especially with urgent single-item deliveries, but combining everything into one order works well for me.\n\n\n\n**Segment 4 — protects the environment by using less water.**\n\nDuring last summer''s dry spell, our town asked everyone to reduce water use. I put a bucket in the shower while it warmed up and used that water on the balcony plants. It felt slightly ridiculous at first, yet the bucket filled faster than I expected. Now I also turn off the tap while brushing my teeth and run the dishwasher only when full. Those small routines continued long after the restrictions ended because wasting clean water no longer feels harmless.","transcript_status":"source_word_comments","word_comment_ids":["346","347","348","349"],"speaker_labels":["Person A","Person B","Person C","Person D"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'd0d6859f845684cf1ae823e9472f397e47718e31aef87a5f1020801b19a19a10'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p2-set017-audio', 'Listening Part 2: Doing arts (2026) Audio', '**Segment 1 — Doing as a social activity**

Our neighbourhood mural started with one blank wall and a box of donated paint. On Saturday morning, children drew outlines, older residents suggested local landmarks, and a professional artist somehow fitted all the ideas together. I painted a terrible-looking tree, but nobody minded; someone turned it into part of a forest. By lunchtime, strangers were sharing brushes and sandwiches. The finished picture is lovely, yet the best part was watching people who had never spoken before create something side by side.



**Segment 2 — Doing arts with children**

When I set up paints for my nieces, I used to demonstrate exactly what they should make. They ignored me, mixed every colour into purple, and turned the paper sideways halfway through. Their pictures were far more imaginative than my neat example. Now I simply cover the table, give them old shirts, and let them lead. We invent stories about each drawing while we work. Making art with them is messy, unpredictable, and easily the most entertaining part of my week.



**Segment 3 — Doing arts as part of the job**

People imagine my design job is just sitting around waiting for inspiration. Yesterday, however, I redrew a restaurant logo seven times because the client wanted it "friendlier but more serious." There are budgets, deadlines, meetings, and files that must be prepared perfectly for printing. I still enjoy choosing colours and turning a rough idea into a strong image, but it is not a private hobby. The artwork has to solve someone else''s problem and be delivered on time.



**Segment 4 — Doing arts alone**

A friend invited me to a weekend painting group, but conversation breaks my concentration. I like shutting the spare-room door, putting my phone face down, and working until I forget what time it is. No one asks what the picture means or suggests a brighter colour. Some evenings I produce nothing worth keeping, and that is fine because nobody is watching. The privacy gives me room to experiment, make mistakes, and follow an idea without explaining it.', '{"source_key":"listening-p2-set017-audio","skill":"listening","part_number":2,"transcript":"**Segment 1 — Doing as a social activity**\n\nOur neighbourhood mural started with one blank wall and a box of donated paint. On Saturday morning, children drew outlines, older residents suggested local landmarks, and a professional artist somehow fitted all the ideas together. I painted a terrible-looking tree, but nobody minded; someone turned it into part of a forest. By lunchtime, strangers were sharing brushes and sandwiches. The finished picture is lovely, yet the best part was watching people who had never spoken before create something side by side.\n\n\n\n**Segment 2 — Doing arts with children**\n\nWhen I set up paints for my nieces, I used to demonstrate exactly what they should make. They ignored me, mixed every colour into purple, and turned the paper sideways halfway through. Their pictures were far more imaginative than my neat example. Now I simply cover the table, give them old shirts, and let them lead. We invent stories about each drawing while we work. Making art with them is messy, unpredictable, and easily the most entertaining part of my week.\n\n\n\n**Segment 3 — Doing arts as part of the job**\n\nPeople imagine my design job is just sitting around waiting for inspiration. Yesterday, however, I redrew a restaurant logo seven times because the client wanted it \"friendlier but more serious.\" There are budgets, deadlines, meetings, and files that must be prepared perfectly for printing. I still enjoy choosing colours and turning a rough idea into a strong image, but it is not a private hobby. The artwork has to solve someone else''s problem and be delivered on time.\n\n\n\n**Segment 4 — Doing arts alone**\n\nA friend invited me to a weekend painting group, but conversation breaks my concentration. I like shutting the spare-room door, putting my phone face down, and working until I forget what time it is. No one asks what the picture means or suggests a brighter colour. Some evenings I produce nothing worth keeping, and that is fine because nobody is watching. The privacy gives me room to experiment, make mistakes, and follow an idea without explaining it.","transcript_status":"source_word_comments","word_comment_ids":["350","351","352","353"],"speaker_labels":["Person A","Person B","Person C","Person D"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'ffbf614726c978967f0c25fdd6e023d8cb55066dc8e1f3906761d0a8310cc639'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p2-set018-audio', 'Listening Part 2: Online shopping (Version 2) (2026) Audio', '**Segment 1 — It saves time**

Thursday used to vanish into errands. I would leave work, in traffic, search three shops for one item, and reach home too late to cook. Now I order household basics from my phone while waiting for a meeting to start. Last week I bought printer ink in under two minutes, whereas finding the right cartridge in town once took an entire afternoon. Convenience matters, but the hours I get back are the real reason I shop this way.



**Segment 2 — It is cheaper**

I wanted a pair of running shoes, but the sports shop price made me put them straight back on the shelf. That evening I found the same model online, added a seasonal code, and paid twenty-five pounds less. I usually check delivery costs and return policies because a supposed bargain can become expensive. Still, comparing several sellers on one screen makes it much easier to spot a genuine deal, and my budget benefits from that.



**Segment 3 — Products are delivered**

Buying a bookshelf sounds simple until you try carrying one onto a crowded bus. I learned that lesson with a small desk and promised myself never again. These days, bulky orders arrive at the entrance to my building, and the driver even calls if I am not home. I could probably find some items slightly cheaper in town, but avoiding the lifting and transport is worth more to me. The doorstep service is the advantage I notice most.



**Segment 4 — There are more choices**

My feet are an awkward size: one shop may have the right length but only in black, while another has bright colours in every size except mine. Online, I can search dozens of brands and filter by size, material, and style before I look at the price. Sometimes the amount of choice becomes overwhelming, and I open far too many tabs. Even so, I would rather compare twenty suitable pairs than settle for the only pair left on a local shelf.', '{"source_key":"listening-p2-set018-audio","skill":"listening","part_number":2,"transcript":"**Segment 1 — It saves time**\n\nThursday used to vanish into errands. I would leave work, in traffic, search three shops for one item, and reach home too late to cook. Now I order household basics from my phone while waiting for a meeting to start. Last week I bought printer ink in under two minutes, whereas finding the right cartridge in town once took an entire afternoon. Convenience matters, but the hours I get back are the real reason I shop this way.\n\n\n\n**Segment 2 — It is cheaper**\n\nI wanted a pair of running shoes, but the sports shop price made me put them straight back on the shelf. That evening I found the same model online, added a seasonal code, and paid twenty-five pounds less. I usually check delivery costs and return policies because a supposed bargain can become expensive. Still, comparing several sellers on one screen makes it much easier to spot a genuine deal, and my budget benefits from that.\n\n\n\n**Segment 3 — Products are delivered**\n\nBuying a bookshelf sounds simple until you try carrying one onto a crowded bus. I learned that lesson with a small desk and promised myself never again. These days, bulky orders arrive at the entrance to my building, and the driver even calls if I am not home. I could probably find some items slightly cheaper in town, but avoiding the lifting and transport is worth more to me. The doorstep service is the advantage I notice most.\n\n\n\n**Segment 4 — There are more choices**\n\nMy feet are an awkward size: one shop may have the right length but only in black, while another has bright colours in every size except mine. Online, I can search dozens of brands and filter by size, material, and style before I look at the price. Sometimes the amount of choice becomes overwhelming, and I open far too many tabs. Even so, I would rather compare twenty suitable pairs than settle for the only pair left on a local shelf.","transcript_status":"source_word_comments","word_comment_ids":["354","355","356","357"],"speaker_labels":["Person A","Person B","Person C","Person D"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '77035e875b8c39ec9991eaee8420eb2b5484c13c06625addcca5122093a07377'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p2-set019-audio', 'Listening Part 2: Studying habit (2026) Audio', '**Segment 1 — Prefer to study late at night**

At eight in the evening, our house is still noisy: dinner plates, phone calls, and my little brother practising the trumpet badly. Around eleven, everything changes. The doors close, traffic outside fades, and nobody interrupts to ask where a charger is. I make tea, spread my notes across the kitchen table, and often work until one. It is not the healthiest schedule, perhaps, but those late hours are when difficult ideas finally stay in my head.



**Segment 2 — Prefer to study at various places**

If I sit at the same desk for several days, my attention begins to wander. I use the library for essays, a lively café for reading, and the park when I need to memorise vocabulary aloud without disturbing anyone. Before exams, I sometimes book an empty classroom. Friends say changing location wastes time, but each place gives a different kind of energy. I choose the setting according to the task rather than having one permanent study spot.



**Segment 3 — Prefer to study with music**

Silence makes every tiny sound seem enormous-the clock, the fridge, someone closing a door upstairs. A low instrumental playlist covers those distractions without pulling me away from the page. Songs with lyrics are dangerous because I start following the words, so I save them for breaks. When the same study playlist begins, my brain seems to recognise that it is time to work. Headphones and music have become as necessary as my notebook.



**Segment 4 — Prefer to study in a quiet place**

I once tried revising in a café because everyone said the background noise was relaxing. In forty minutes, I learned a stranger''s weekend plans, watched four drinks being made, and completed half a paragraph. Now I use a small room at the back of the library where phones must be silent. There is no music, no conversation, and almost nothing to look at. It sounds dull, but that emptiness is exactly what lets me concentrate.', '{"source_key":"listening-p2-set019-audio","skill":"listening","part_number":2,"transcript":"**Segment 1 — Prefer to study late at night**\n\nAt eight in the evening, our house is still noisy: dinner plates, phone calls, and my little brother practising the trumpet badly. Around eleven, everything changes. The doors close, traffic outside fades, and nobody interrupts to ask where a charger is. I make tea, spread my notes across the kitchen table, and often work until one. It is not the healthiest schedule, perhaps, but those late hours are when difficult ideas finally stay in my head.\n\n\n\n**Segment 2 — Prefer to study at various places**\n\nIf I sit at the same desk for several days, my attention begins to wander. I use the library for essays, a lively café for reading, and the park when I need to memorise vocabulary aloud without disturbing anyone. Before exams, I sometimes book an empty classroom. Friends say changing location wastes time, but each place gives a different kind of energy. I choose the setting according to the task rather than having one permanent study spot.\n\n\n\n**Segment 3 — Prefer to study with music**\n\nSilence makes every tiny sound seem enormous-the clock, the fridge, someone closing a door upstairs. A low instrumental playlist covers those distractions without pulling me away from the page. Songs with lyrics are dangerous because I start following the words, so I save them for breaks. When the same study playlist begins, my brain seems to recognise that it is time to work. Headphones and music have become as necessary as my notebook.\n\n\n\n**Segment 4 — Prefer to study in a quiet place**\n\nI once tried revising in a café because everyone said the background noise was relaxing. In forty minutes, I learned a stranger''s weekend plans, watched four drinks being made, and completed half a paragraph. Now I use a small room at the back of the library where phones must be silent. There is no music, no conversation, and almost nothing to look at. It sounds dull, but that emptiness is exactly what lets me concentrate.","transcript_status":"source_word_comments","word_comment_ids":["358","359","360","361"],"speaker_labels":["Person A","Person B","Person C","Person D"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '4bdb0e4deb7f68bb78fef9033f4d50bcb25872df192e8b558c27484235bae0c2'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p2-set020-audio', 'Listening Part 2: Their journey to work (2026) Audio', '**Segment 1 — Walk with friends**

At 7:40 each morning, three of us meet beside the bakery. The direct route to the office takes twenty minutes, although we often choose the riverside path and arrive five minutes later. One friend brings coffee, another gives us the latest neighbourhood news, and I mostly listen until I am properly awake. Rain occasionally sends us onto the bus, but walking together has become part of our friendship rather than simply a way of reaching work.



**Segment 2 — Go by bus**

Driving would be faster before seven, but I am never organised enough to leave that early. By eight, the roads are blocked and parking near the office costs a fortune. The number 26 stops almost outside my flat, so I board with a travel card and read the news until my stop. It is not always comfortable-schoolchildren fill every seat on Mondays-but I can let someone else deal with the traffic.



**Segment 3 — Walk alone**

My colleague lives two streets away and keeps suggesting we travel together. The truth is that the forty-minute walk is the only part of my day. At home, two children need breakfast; at work, meetings begin the moment I enter. Between those worlds, I put my phone away and follow the canal path by myself. I sometimes greet dog walkers, but I do not arrange company. Solitude is the point of the journey.



**Segment 4 — Drive car**

The train station is closer than my garage, yet the train requires two changes and frequently leaves me standing in the rain. With my own vehicle, I can drop my daughter at school, carry equipment for work, and take a different road when traffic is bad. Fuel and parking are expensive, so I share the journey with a colleague twice a week. Even with those costs, having the car gives my complicated mornings the flexibility they need.', '{"source_key":"listening-p2-set020-audio","skill":"listening","part_number":2,"transcript":"**Segment 1 — Walk with friends**\n\nAt 7:40 each morning, three of us meet beside the bakery. The direct route to the office takes twenty minutes, although we often choose the riverside path and arrive five minutes later. One friend brings coffee, another gives us the latest neighbourhood news, and I mostly listen until I am properly awake. Rain occasionally sends us onto the bus, but walking together has become part of our friendship rather than simply a way of reaching work.\n\n\n\n**Segment 2 — Go by bus**\n\nDriving would be faster before seven, but I am never organised enough to leave that early. By eight, the roads are blocked and parking near the office costs a fortune. The number 26 stops almost outside my flat, so I board with a travel card and read the news until my stop. It is not always comfortable-schoolchildren fill every seat on Mondays-but I can let someone else deal with the traffic.\n\n\n\n**Segment 3 — Walk alone**\n\nMy colleague lives two streets away and keeps suggesting we travel together. The truth is that the forty-minute walk is the only part of my day. At home, two children need breakfast; at work, meetings begin the moment I enter. Between those worlds, I put my phone away and follow the canal path by myself. I sometimes greet dog walkers, but I do not arrange company. Solitude is the point of the journey.\n\n\n\n**Segment 4 — Drive car**\n\nThe train station is closer than my garage, yet the train requires two changes and frequently leaves me standing in the rain. With my own vehicle, I can drop my daughter at school, carry equipment for work, and take a different road when traffic is bad. Fuel and parking are expensive, so I share the journey with a colleague twice a week. Even with those costs, having the car gives my complicated mornings the flexibility they need.","transcript_status":"source_word_comments","word_comment_ids":["362","363","364","365"],"speaker_labels":["Person A","Person B","Person C","Person D"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '32e58d55a142ede82a60df79d82703b2897d4a90b9f3c05fefed1cb657255c62'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p2-set021-audio', 'Listening Part 2: Shopping online (2026) Audio', '**Segment 1 — products are delivered**

After breaking my ankle, ordinary shopping became a military operation: crutches, taxis, and someone to carry the bags upstairs. A neighbour showed me how to order groceries, and two hours later a driver placed everything beside my kitchen counter. My ankle healed months ago, but the habit remained. I still visit markets for fresh fruit, yet washing powder, bottled drinks, and other heavy items come to me. Home delivery changed online shopping from an option into my default.



**Segment 2 — it is cheaper**

My brother buys the first thing he sees; I treat shopping like detective work. I leave an item in the basket, search for vouchers, compare three sites, and check whether postage cancels the saving. It paid off when I furnished my room: the lamp, chair, and shelves all cost less online than the local shop''s sale prices. The process takes patience, but finding the lowest total feels like winning a small competition.



**Segment 3 — it saves time**

I run a small bakery and finish after most shops have closed. Before internet shopping, Saturday morning was lost to buying packaging, cleaning supplies, and ingredients I had forgotten. Now I place orders after midnight while the ovens cool. It may not sound exciting, but getting those errands off my weekend has given me time to see friends again. The biggest benefit is not comfort or price; it is recovering hours that work used to steal.



**Segment 4 — it has more choices**

I collect old film posters, which is a hopeless hobby if you only search local shops. Online marketplaces connect me with sellers in tiny towns and even other countries. One week I found ten versions of the same poster, each from a different cinema release. I have to inspect photographs carefully because condition varies, but the range is extraordinary. A physical shop might offer one lucky discovery; the internet gives me an entire world of possibilities.', '{"source_key":"listening-p2-set021-audio","skill":"listening","part_number":2,"transcript":"**Segment 1 — products are delivered**\n\nAfter breaking my ankle, ordinary shopping became a military operation: crutches, taxis, and someone to carry the bags upstairs. A neighbour showed me how to order groceries, and two hours later a driver placed everything beside my kitchen counter. My ankle healed months ago, but the habit remained. I still visit markets for fresh fruit, yet washing powder, bottled drinks, and other heavy items come to me. Home delivery changed online shopping from an option into my default.\n\n\n\n**Segment 2 — it is cheaper**\n\nMy brother buys the first thing he sees; I treat shopping like detective work. I leave an item in the basket, search for vouchers, compare three sites, and check whether postage cancels the saving. It paid off when I furnished my room: the lamp, chair, and shelves all cost less online than the local shop''s sale prices. The process takes patience, but finding the lowest total feels like winning a small competition.\n\n\n\n**Segment 3 — it saves time**\n\nI run a small bakery and finish after most shops have closed. Before internet shopping, Saturday morning was lost to buying packaging, cleaning supplies, and ingredients I had forgotten. Now I place orders after midnight while the ovens cool. It may not sound exciting, but getting those errands off my weekend has given me time to see friends again. The biggest benefit is not comfort or price; it is recovering hours that work used to steal.\n\n\n\n**Segment 4 — it has more choices**\n\nI collect old film posters, which is a hopeless hobby if you only search local shops. Online marketplaces connect me with sellers in tiny towns and even other countries. One week I found ten versions of the same poster, each from a different cinema release. I have to inspect photographs carefully because condition varies, but the range is extraordinary. A physical shop might offer one lucky discovery; the internet gives me an entire world of possibilities.","transcript_status":"source_word_comments","word_comment_ids":["366","367","368","369"],"speaker_labels":["Person A","Person B","Person C","Person D"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '1c610a62a6ee93825300080f75f72b78352fb352ba8ce09ae77c1d9250f6ad85'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p2-set022-audio', 'Listening Part 2: Protecting the environment (2026) Audio', '**Segment 1 — Shopping online**

My nearest large supermarket is twelve kilometres away. I used to make that journey whenever we ran out of one or two things, which was wasteful and expensive. Now the family adds items to a shared digital list, and I place one delivery order each week. The van already serves several houses on our road, so my separate car trips have almost vanished. I avoid express deliveries and combine purchases, making online ordering the greener option in our situation.



**Segment 2 — Not driving to work**

The final kilometre to my office used to take longer than the first ten because everyone was searching for parking. I tried the train, then discovered the station was close enough to cycle to. Now the car remains at home Monday to Friday. I arrive without traffic frustration, spend less on fuel, and get some movement before sitting at a desk. One commuting decision solved three problems at once.



**Segment 3 — Using less electricity**

Our smart meter became an unexpected family game. The children run around checking which light was left on, and I compare today''s energy use with yesterday''s. We lowered the heating slightly, stopped using the tumble dryer on sunny days, and replaced two ancient bulbs. The numbers on the screen drop immediately, which makes the effect visible. What began as a way to reduce bills has turned into a household effort to consume less power.



**Segment 4 — Using less water**

I noticed the garden hose was using drinking water to do a job rain could handle. We installed a barrel beneath the roof gutter, and one storm filled it completely. That supply now waters the vegetables and cleans muddy tools. Inside, I take shorter showers and repair dripping taps Water once seemed endless because it always arrived when I turned a handle; collecting and measuring it changed that attitude.', '{"source_key":"listening-p2-set022-audio","skill":"listening","part_number":2,"transcript":"**Segment 1 — Shopping online**\n\nMy nearest large supermarket is twelve kilometres away. I used to make that journey whenever we ran out of one or two things, which was wasteful and expensive. Now the family adds items to a shared digital list, and I place one delivery order each week. The van already serves several houses on our road, so my separate car trips have almost vanished. I avoid express deliveries and combine purchases, making online ordering the greener option in our situation.\n\n\n\n**Segment 2 — Not driving to work**\n\nThe final kilometre to my office used to take longer than the first ten because everyone was searching for parking. I tried the train, then discovered the station was close enough to cycle to. Now the car remains at home Monday to Friday. I arrive without traffic frustration, spend less on fuel, and get some movement before sitting at a desk. One commuting decision solved three problems at once.\n\n\n\n**Segment 3 — Using less electricity**\n\nOur smart meter became an unexpected family game. The children run around checking which light was left on, and I compare today''s energy use with yesterday''s. We lowered the heating slightly, stopped using the tumble dryer on sunny days, and replaced two ancient bulbs. The numbers on the screen drop immediately, which makes the effect visible. What began as a way to reduce bills has turned into a household effort to consume less power.\n\n\n\n**Segment 4 — Using less water**\n\nI noticed the garden hose was using drinking water to do a job rain could handle. We installed a barrel beneath the roof gutter, and one storm filled it completely. That supply now waters the vegetables and cleans muddy tools. Inside, I take shorter showers and repair dripping taps Water once seemed endless because it always arrived when I turned a handle; collecting and measuring it changed that attitude.","transcript_status":"source_word_comments","word_comment_ids":["370","371","372","373"],"speaker_labels":["Person A","Person B","Person C","Person D"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '932788614cf67e7bdf6ecc914ef2debb3544a9d022014c61d37303a73110ecae'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p2-set023-audio', 'Listening Part 2: Running Audio', '**Segment 1 — prefer running in the street**

A treadmill tells you exactly what will happen: the belt moves, the wall stays still, and every minute feels identical. Outside, the city keeps changing. I weave past commuters, climb the hill by the theatre, and use shop windows to check my posture. Traffic means I have to stay alert, so I choose roads and run early. The pavement is not perfect, but the movement and unpredictability of the streets keep me interested.



**Segment 2 — at the seaside**

I time my run for low tide. The sand near the water becomes firm enough to move , while the softer parts make my legs work harder. Waves cover the noise of my breathing, gulls circle overhead, and there is always a cool breeze on the return journey. I own a gym membership for rainy days, but nothing indoors matches the feeling of finishing beside the sea and walking straight into the water.



**Segment 3 — on the running track**

Before a race, guessing distance is useless. I need to know whether my fourth kilometre was slower than my first, so I train at the stadium. Each lap is measured, the surface is even, and my coach can watch without cycling behind me. It can feel repetitive, especially after twenty laps, but that repetition reveals every weakness in my pace. For serious sessions, the track gives me information no scenic route can provide.



**Segment 4 — in the fitness center**

Winter defeated my outdoor routine. Darkness arrived before I left work, rain soaked my shoes, and icy paths made speed training unsafe. I joined the centre opposite my office and discovered I could run, stretch, and shower before going home. The treadmill is less beautiful than the park, but I can control the incline and never cancel because of weather. During the week, that reliable indoor setup is exactly what I need.', '{"source_key":"listening-p2-set023-audio","skill":"listening","part_number":2,"transcript":"**Segment 1 — prefer running in the street**\n\nA treadmill tells you exactly what will happen: the belt moves, the wall stays still, and every minute feels identical. Outside, the city keeps changing. I weave past commuters, climb the hill by the theatre, and use shop windows to check my posture. Traffic means I have to stay alert, so I choose roads and run early. The pavement is not perfect, but the movement and unpredictability of the streets keep me interested.\n\n\n\n**Segment 2 — at the seaside**\n\nI time my run for low tide. The sand near the water becomes firm enough to move , while the softer parts make my legs work harder. Waves cover the noise of my breathing, gulls circle overhead, and there is always a cool breeze on the return journey. I own a gym membership for rainy days, but nothing indoors matches the feeling of finishing beside the sea and walking straight into the water.\n\n\n\n**Segment 3 — on the running track**\n\nBefore a race, guessing distance is useless. I need to know whether my fourth kilometre was slower than my first, so I train at the stadium. Each lap is measured, the surface is even, and my coach can watch without cycling behind me. It can feel repetitive, especially after twenty laps, but that repetition reveals every weakness in my pace. For serious sessions, the track gives me information no scenic route can provide.\n\n\n\n**Segment 4 — in the fitness center**\n\nWinter defeated my outdoor routine. Darkness arrived before I left work, rain soaked my shoes, and icy paths made speed training unsafe. I joined the centre opposite my office and discovered I could run, stretch, and shower before going home. The treadmill is less beautiful than the park, but I can control the incline and never cancel because of weather. During the week, that reliable indoor setup is exactly what I need.","transcript_status":"source_word_comments","word_comment_ids":["374","375","376","377"],"speaker_labels":["Person A","Person B","Person C","Person D"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'e0a14bc1148a8e5cb4dc813378e3b473ec3ad41d0819c5bfa6d02a9cbc17bb6c'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p2-set024-audio', 'Listening Part 2: Their purposes of using the Internet (2026) Audio', '**Segment 1 — watch film**

Friday night is my private cinema night. I dim the lights, make popcorn, and search streaming sites for something I have not seen. Sometimes I read reviews for twenty minutes and then choose an old favourite anyway. I use email for work and social media occasionally, but those feel like chores. The part of the internet I genuinely look forward to is having thousands of films available without leaving the sofa.



**Segment 2 — communicate with friends**

Our friendship group now lives in four countries. Meeting in person requires months of planning, yet on Sunday evenings we all open the same video-call link. Someone cooks, someone is still commuting, and one friend usually forgets the time difference. We share ordinary details that would never justify an international phone call. For me, online access matters most because it keeps distant friendships feeling like everyday relationships.



**Segment 3 — complete school assignments**

The school library has excellent books, but they close at five and my best working time starts after dinner. Online databases let me find journal articles, check facts, and watch explanations when a textbook makes no sense. I also upload finished work through the class portal before midnight. Entertainment sites are tempting, so I use an app that blocks them for an hour. Without the internet, completing coursework from home would be far more difficult.



**Segment 4 — find transport information**

I can remember a face for years and forget a bus number in five minutes. Before leaving anywhere, I check the route online, save the platform, and take a screenshot in case the signal disappears. Real-time updates have rescued me from cancelled trains more than once. Friends use the internet mainly for messages and videos; I open it most often when I need to know how to get somewhere and when the next service leaves.', '{"source_key":"listening-p2-set024-audio","skill":"listening","part_number":2,"transcript":"**Segment 1 — watch film**\n\nFriday night is my private cinema night. I dim the lights, make popcorn, and search streaming sites for something I have not seen. Sometimes I read reviews for twenty minutes and then choose an old favourite anyway. I use email for work and social media occasionally, but those feel like chores. The part of the internet I genuinely look forward to is having thousands of films available without leaving the sofa.\n\n\n\n**Segment 2 — communicate with friends**\n\nOur friendship group now lives in four countries. Meeting in person requires months of planning, yet on Sunday evenings we all open the same video-call link. Someone cooks, someone is still commuting, and one friend usually forgets the time difference. We share ordinary details that would never justify an international phone call. For me, online access matters most because it keeps distant friendships feeling like everyday relationships.\n\n\n\n**Segment 3 — complete school assignments**\n\nThe school library has excellent books, but they close at five and my best working time starts after dinner. Online databases let me find journal articles, check facts, and watch explanations when a textbook makes no sense. I also upload finished work through the class portal before midnight. Entertainment sites are tempting, so I use an app that blocks them for an hour. Without the internet, completing coursework from home would be far more difficult.\n\n\n\n**Segment 4 — find transport information**\n\nI can remember a face for years and forget a bus number in five minutes. Before leaving anywhere, I check the route online, save the platform, and take a screenshot in case the signal disappears. Real-time updates have rescued me from cancelled trains more than once. Friends use the internet mainly for messages and videos; I open it most often when I need to know how to get somewhere and when the next service leaves.","transcript_status":"source_word_comments","word_comment_ids":["378","379","380","381"],"speaker_labels":["Person A","Person B","Person C","Person D"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'adfdb9633dd2f629da0cf670c0d511d2c71e180dfdb2e038cb0ea02e79b2adda'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p2-set025-audio', 'Listening Part 2: When they like listening to music (2026) Audio', '**Segment 1 — To relax**

There is a particular moment after work when conversation feels impossible. I put my bag down, lower the lights, and play something slow-usually piano or acoustic guitar. I do not sing along or answer messages; I simply let the day become Music during exercise is too distracting for me, and mornings need silence. Its real value comes in that evening half-hour when my shoulders finally drop and my thoughts stop racing.



**Segment 2 — While studying**

My revision playlist has no words and, according to my brother, no memorable tunes either. That is intentional. A steady background sound stops me checking every noise in the house, but lyrics would steal my attention from the page. I press play when I open my notes and stop it during breaks. Over time, those tracks have become a signal: once they begin, I settle down and work.



**Segment 3 — While singing**

I do not listen passively for long. The moment a chorus arrives, I am holding a hairbrush like a microphone and trying to copy the singer''s breathing. I slow difficult sections down, repeat them, and record myself to hear where the notes go wrong. On the bus, I prefer podcasts, and while studying I need Songs matter most when I can use them to practise my own voice.



**Segment 4 — After waking up**

My alarm is technically music because an ordinary beep puts me in a terrible mood. The first song starts softly, then the playlist becomes brighter while I open the curtains and make breakfast. By the time the third track finishes, I am usually dressed. I rarely play music late at night; it keeps me awake. Its most useful job is pulling me out of sleep and giving the morning some energy.', '{"source_key":"listening-p2-set025-audio","skill":"listening","part_number":2,"transcript":"**Segment 1 — To relax**\n\nThere is a particular moment after work when conversation feels impossible. I put my bag down, lower the lights, and play something slow-usually piano or acoustic guitar. I do not sing along or answer messages; I simply let the day become Music during exercise is too distracting for me, and mornings need silence. Its real value comes in that evening half-hour when my shoulders finally drop and my thoughts stop racing.\n\n\n\n**Segment 2 — While studying**\n\nMy revision playlist has no words and, according to my brother, no memorable tunes either. That is intentional. A steady background sound stops me checking every noise in the house, but lyrics would steal my attention from the page. I press play when I open my notes and stop it during breaks. Over time, those tracks have become a signal: once they begin, I settle down and work.\n\n\n\n**Segment 3 — While singing**\n\nI do not listen passively for long. The moment a chorus arrives, I am holding a hairbrush like a microphone and trying to copy the singer''s breathing. I slow difficult sections down, repeat them, and record myself to hear where the notes go wrong. On the bus, I prefer podcasts, and while studying I need Songs matter most when I can use them to practise my own voice.\n\n\n\n**Segment 4 — After waking up**\n\nMy alarm is technically music because an ordinary beep puts me in a terrible mood. The first song starts softly, then the playlist becomes brighter while I open the curtains and make breakfast. By the time the third track finishes, I am usually dressed. I rarely play music late at night; it keeps me awake. Its most useful job is pulling me out of sleep and giving the morning some energy.","transcript_status":"source_word_comments","word_comment_ids":["382","383","384","385"],"speaker_labels":["Person A","Person B","Person C","Person D"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '29de04f72d7db8a0d9e4583497413ca193125db992251042429b853855994019'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p2-set026-audio', 'Listening Part 2: Protecting the environment (Version 2) (2026) Audio', '**Segment 1 — Does not use commercial cleaning products**

The supermarket cleaning aisle smells so strong that it makes my eyes water. Worse, every product comes in another plastic bottle. I began making one simple spray from vinegar, water, and citrus peel, expecting it to be a temporary experiment. It cleaned the kitchen surprisingly well, so I added baking soda for tougher jobs. I still buy soap, of course, but the specialised chemical cleaners have disappeared from my cupboard and from my shopping list.



**Segment 2 — Give away used items**

My wardrobe was full, yet I wore the same ten things. Rather than throw the rest away, I organised a free clothes table at our community centre. A teenager chose my old winter coat, and another family took bedding we no longer needed. They later brought toys for someone else to collect. Passing things on creates a useful circle: one person''s clutter becomes another person''s solution, with no new product needing to be made.



**Segment 3 — Buy environmentally friendly products**

I cannot control how every factory operates, but I can decide which ones receive my money. Before buying, I now check whether packaging is recyclable, materials are responsibly sourced, and replacement parts are available. Last month I chose a repairable kettle over a cheaper sealed model. It may last longer and create less waste. Shopping this way takes more thought, but it turns an ordinary purchase into support for better production.



**Segment 4 — Reuse containers for storing food**

Sunday cooking once ended with a bin full of tubs and jars. I started washing them instead: yoghurt pots hold chopped herbs, glass jars store soup, and takeaway containers carry lunches to work. I label everything because frozen tomato sauce and strawberry puree look alarmingly similar. The system saves money and reduces single-use packaging. More importantly, it makes me pause before treating a perfectly useful container as rubbish.', '{"source_key":"listening-p2-set026-audio","skill":"listening","part_number":2,"transcript":"**Segment 1 — Does not use commercial cleaning products**\n\nThe supermarket cleaning aisle smells so strong that it makes my eyes water. Worse, every product comes in another plastic bottle. I began making one simple spray from vinegar, water, and citrus peel, expecting it to be a temporary experiment. It cleaned the kitchen surprisingly well, so I added baking soda for tougher jobs. I still buy soap, of course, but the specialised chemical cleaners have disappeared from my cupboard and from my shopping list.\n\n\n\n**Segment 2 — Give away used items**\n\nMy wardrobe was full, yet I wore the same ten things. Rather than throw the rest away, I organised a free clothes table at our community centre. A teenager chose my old winter coat, and another family took bedding we no longer needed. They later brought toys for someone else to collect. Passing things on creates a useful circle: one person''s clutter becomes another person''s solution, with no new product needing to be made.\n\n\n\n**Segment 3 — Buy environmentally friendly products**\n\nI cannot control how every factory operates, but I can decide which ones receive my money. Before buying, I now check whether packaging is recyclable, materials are responsibly sourced, and replacement parts are available. Last month I chose a repairable kettle over a cheaper sealed model. It may last longer and create less waste. Shopping this way takes more thought, but it turns an ordinary purchase into support for better production.\n\n\n\n**Segment 4 — Reuse containers for storing food**\n\nSunday cooking once ended with a bin full of tubs and jars. I started washing them instead: yoghurt pots hold chopped herbs, glass jars store soup, and takeaway containers carry lunches to work. I label everything because frozen tomato sauce and strawberry puree look alarmingly similar. The system saves money and reduces single-use packaging. More importantly, it makes me pause before treating a perfectly useful container as rubbish.","transcript_status":"source_word_comments","word_comment_ids":["386","387","388","389"],"speaker_labels":["Person A","Person B","Person C","Person D"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '38e023e2e7a48372837be5d5dd04bc64d35a3978c95667cf45b7c6a699ebddc3'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p2-set027-audio', 'Listening Part 2: Protecting the environment (Version 3) (2026) Audio', '**Segment 1 — Give away used items**

When we moved, I counted six lamps, three chairs, and boxes of clothes we no longer used. Hiring a rubbish collection would have been easiest, but most of it was perfectly good. I posted photographs in a neighbourhood group, and by Sunday everything had new owners, including a student delighted with the old desk. Nothing earned me money, yet seeing useful objects leave in people''s hands rather than a truck felt far better.



**Segment 2 — Buy environmentally friendly products**

I used to choose shampoo by smell and washing-up liquid by price. Then our local river was closed after pollution levels rose, and I started reading labels. Now I look for refillable bottles, recycled packaging, and ingredients that break down safely. These products sometimes cost a little more, so I buy fewer of them and use them carefully. My shopping basket is a small thing, but it supports companies making less damaging choices.



**Segment 3 — Reuse containers for storing food**

My grandmother never threw away a glass jar; I used to tease her cupboard full of them. Now my kitchen looks remarkably similar. Coffee jars hold rice, takeaway boxes carry lunches, and small containers organise herbs in the freezer. Reusing them means I buy fewer plastic bags and can actually see what food I have, so less gets forgotten. Grandmother calls it common sense, not environmentalism, and perhaps she is right.



**Segment 4 — Does not use commercial cleaning products**

The warning labels on bathroom cleaners began to bother me-open the window, wear gloves, keep away from children. I wondered why something used in my home needed so many hazards. After some experiments, I found that diluted vinegar handles glass, baking soda cleans the sink, and lemon removes unpleasant smells. I no longer bring home rows of brightly coloured chemical bottles. The homemade mixtures are simpler, cheaper, and much kinder to what goes down the drain.', '{"source_key":"listening-p2-set027-audio","skill":"listening","part_number":2,"transcript":"**Segment 1 — Give away used items**\n\nWhen we moved, I counted six lamps, three chairs, and boxes of clothes we no longer used. Hiring a rubbish collection would have been easiest, but most of it was perfectly good. I posted photographs in a neighbourhood group, and by Sunday everything had new owners, including a student delighted with the old desk. Nothing earned me money, yet seeing useful objects leave in people''s hands rather than a truck felt far better.\n\n\n\n**Segment 2 — Buy environmentally friendly products**\n\nI used to choose shampoo by smell and washing-up liquid by price. Then our local river was closed after pollution levels rose, and I started reading labels. Now I look for refillable bottles, recycled packaging, and ingredients that break down safely. These products sometimes cost a little more, so I buy fewer of them and use them carefully. My shopping basket is a small thing, but it supports companies making less damaging choices.\n\n\n\n**Segment 3 — Reuse containers for storing food**\n\nMy grandmother never threw away a glass jar; I used to tease her cupboard full of them. Now my kitchen looks remarkably similar. Coffee jars hold rice, takeaway boxes carry lunches, and small containers organise herbs in the freezer. Reusing them means I buy fewer plastic bags and can actually see what food I have, so less gets forgotten. Grandmother calls it common sense, not environmentalism, and perhaps she is right.\n\n\n\n**Segment 4 — Does not use commercial cleaning products**\n\nThe warning labels on bathroom cleaners began to bother me-open the window, wear gloves, keep away from children. I wondered why something used in my home needed so many hazards. After some experiments, I found that diluted vinegar handles glass, baking soda cleans the sink, and lemon removes unpleasant smells. I no longer bring home rows of brightly coloured chemical bottles. The homemade mixtures are simpler, cheaper, and much kinder to what goes down the drain.","transcript_status":"source_word_comments","word_comment_ids":["390","391","392","393"],"speaker_labels":["Person A","Person B","Person C","Person D"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '37c9b6573004eb375f8085863be8e58011e5edce1e4d9ebf1ec792ae2c2c18b1'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p2-set028-audio', 'Listening Part 2: Online shopping (Version 2) (2026) Audio', '**Segment 1 — The products are delivered**

My apartment is on the fifth floor and the lift has been broken twice this year. Carrying a month''s supply of pet food upstairs convinced me to order it online. The courier brings the heavy box to my door, and I no longer plan shopping around who can help me lift it. I still enjoy browsing local shops for small things, but for regular bulky purchases, the arrival at home is the feature that wins.



**Segment 2 — It is cheaper**

I keep a spreadsheet for major purchases, which my friends find excessive. It includes the shop price, online price, delivery fee, and any cashback. When I bought headphones, the first website looked cheapest until postage was added; another seller offered a code and free delivery. The final saving paid for a concert ticket. Online shopping rewards careful comparison, and that lower total is why I use it.



**Segment 3 — It saves time**

During exam season, leaving campus for shopping breaks my whole rhythm. I might spend forty minutes travelling to town just to discover the item is unavailable. Ordering online takes a few minutes between study sessions, and I can collect the parcel from reception later. Delivery is convenient, but the important difference is what does not disappear: an afternoon that I can use for revision, cooking, or sleep.



**Segment 4 — There are more choices**

Local furniture shops assume everyone wants grey, white, or brown. I was searching for a narrow green chair that would fit beside a bookshelf, and no showroom had one. Online filters produced hundreds, including different fabrics, leg styles, and exact measurements. Too many options can delay a decision, but at least the right item exists somewhere. That breadth matters more to me than discounts or next-day delivery.', '{"source_key":"listening-p2-set028-audio","skill":"listening","part_number":2,"transcript":"**Segment 1 — The products are delivered**\n\nMy apartment is on the fifth floor and the lift has been broken twice this year. Carrying a month''s supply of pet food upstairs convinced me to order it online. The courier brings the heavy box to my door, and I no longer plan shopping around who can help me lift it. I still enjoy browsing local shops for small things, but for regular bulky purchases, the arrival at home is the feature that wins.\n\n\n\n**Segment 2 — It is cheaper**\n\nI keep a spreadsheet for major purchases, which my friends find excessive. It includes the shop price, online price, delivery fee, and any cashback. When I bought headphones, the first website looked cheapest until postage was added; another seller offered a code and free delivery. The final saving paid for a concert ticket. Online shopping rewards careful comparison, and that lower total is why I use it.\n\n\n\n**Segment 3 — It saves time**\n\nDuring exam season, leaving campus for shopping breaks my whole rhythm. I might spend forty minutes travelling to town just to discover the item is unavailable. Ordering online takes a few minutes between study sessions, and I can collect the parcel from reception later. Delivery is convenient, but the important difference is what does not disappear: an afternoon that I can use for revision, cooking, or sleep.\n\n\n\n**Segment 4 — There are more choices**\n\nLocal furniture shops assume everyone wants grey, white, or brown. I was searching for a narrow green chair that would fit beside a bookshelf, and no showroom had one. Online filters produced hundreds, including different fabrics, leg styles, and exact measurements. Too many options can delay a decision, but at least the right item exists somewhere. That breadth matters more to me than discounts or next-day delivery.","transcript_status":"source_word_comments","word_comment_ids":["394","395","396","397"],"speaker_labels":["Person A","Person B","Person C","Person D"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '47377328b4046bb967baf57d9cdc56f5c5273b03a5c9159f1dfdd49b758ce4ed'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p2-set029-audio', 'Listening Part 2: Listening to music (2026) Audio', '**Segment 1 — To relax**

My train home is crowded, but headphones create a small private room around me. I choose slow music, look out of the window, and let conversations fade into the background. By my stop, the day''s problems feel less urgent. I cannot use music while reading because I follow the melody instead of the words, and loud morning songs irritate me. I save it for the moments when I need to unwind.



**Segment 2 — After waking up**

Before I discovered morning playlists, I pressed the snooze button three or four times. Now the speaker starts with a song I love at seven, and I have to cross the room to turn it up. I dance badly while making coffee, which is ridiculous but effective. At other times of day I may prefer silence; immediately after sleep, however, music does the job that alarms and motivation never managed.



**Segment 3 — While singing**

Our family karaoke machine was meant for parties, but I use it nearly every evening. I play the original track once, then remove the lead vocal and try the song myself. Sometimes I send a recording to my choir teacher for feedback. Background music while working only distracts me, so I do not keep it on casually. I listen closely when I am about to sing, because the song becomes a lesson.



**Segment 4 — While studying**

A silent study room makes me aware of every page turning. A crowded room is worse. Soft electronic music through headphones sits between those extremes and creates a steady wall of sound. I avoid familiar songs because memories come with them, and I never use shuffle-the sudden change breaks my focus. That carefully chosen music accompanies essays, revision, and almost every long assignment I complete.', '{"source_key":"listening-p2-set029-audio","skill":"listening","part_number":2,"transcript":"**Segment 1 — To relax**\n\nMy train home is crowded, but headphones create a small private room around me. I choose slow music, look out of the window, and let conversations fade into the background. By my stop, the day''s problems feel less urgent. I cannot use music while reading because I follow the melody instead of the words, and loud morning songs irritate me. I save it for the moments when I need to unwind.\n\n\n\n**Segment 2 — After waking up**\n\nBefore I discovered morning playlists, I pressed the snooze button three or four times. Now the speaker starts with a song I love at seven, and I have to cross the room to turn it up. I dance badly while making coffee, which is ridiculous but effective. At other times of day I may prefer silence; immediately after sleep, however, music does the job that alarms and motivation never managed.\n\n\n\n**Segment 3 — While singing**\n\nOur family karaoke machine was meant for parties, but I use it nearly every evening. I play the original track once, then remove the lead vocal and try the song myself. Sometimes I send a recording to my choir teacher for feedback. Background music while working only distracts me, so I do not keep it on casually. I listen closely when I am about to sing, because the song becomes a lesson.\n\n\n\n**Segment 4 — While studying**\n\nA silent study room makes me aware of every page turning. A crowded room is worse. Soft electronic music through headphones sits between those extremes and creates a steady wall of sound. I avoid familiar songs because memories come with them, and I never use shuffle-the sudden change breaks my focus. That carefully chosen music accompanies essays, revision, and almost every long assignment I complete.","transcript_status":"source_word_comments","word_comment_ids":["398","399","400","401"],"speaker_labels":["Person A","Person B","Person C","Person D"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'c572aa06c2abc0d51be971c4b2691b1eb48023717ea8504414b5264dcfeefb52'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p2-set030-audio', 'Listening Part 2: Outdoor activities (2026) Audio', '**Segment 1 — horse riding**

The horse I ride is called Pepper, and she knows the route better than I do. We leave the stable, cross a shallow stream, and follow a path through the fields. Cycling is faster and hiking is easier to organise, but neither involves learning to communicate with an animal that has its own mood and opinions. That partnership is what keeps me returning to the riding centre every weekend.



**Segment 2 — going for a run**

My job keeps me indoors under artificial light, so after work I need movement and open sky. I lace up beside the office and follow a five-kilometre route around the lake. Some days I run ; on others I slow down and watch the birds. I tried joining a gym, but staring at a wall while exercising felt wrong. Running outside clears my head in a way no machine has managed.



**Segment 3 — hiking**

After my mountain-bike accident, I was reluctant to return to steep trails. I still missed the views, though, so a friend suggested reaching them on foot. Walking uphill takes longer and lacks the rush of cycling, but I notice wildflowers, old paths, and places I used to race past. The mountains are still part of my weekends; I simply explore them now with boots and a backpack.



**Segment 4 — mountain biking**

Horse riding looks elegant until a large horse turns its head toward me; then I remember how nervous animals make me. My friends and I prefer machines we can repair ourselves. We load our bikes onto a van, climb forest tracks, and race down muddy slopes. It is demanding, occasionally frightening, and guaranteed to cover us in dirt. That combination is exactly why mountain biking appeals to me.', '{"source_key":"listening-p2-set030-audio","skill":"listening","part_number":2,"transcript":"**Segment 1 — horse riding**\n\nThe horse I ride is called Pepper, and she knows the route better than I do. We leave the stable, cross a shallow stream, and follow a path through the fields. Cycling is faster and hiking is easier to organise, but neither involves learning to communicate with an animal that has its own mood and opinions. That partnership is what keeps me returning to the riding centre every weekend.\n\n\n\n**Segment 2 — going for a run**\n\nMy job keeps me indoors under artificial light, so after work I need movement and open sky. I lace up beside the office and follow a five-kilometre route around the lake. Some days I run ; on others I slow down and watch the birds. I tried joining a gym, but staring at a wall while exercising felt wrong. Running outside clears my head in a way no machine has managed.\n\n\n\n**Segment 3 — hiking**\n\nAfter my mountain-bike accident, I was reluctant to return to steep trails. I still missed the views, though, so a friend suggested reaching them on foot. Walking uphill takes longer and lacks the rush of cycling, but I notice wildflowers, old paths, and places I used to race past. The mountains are still part of my weekends; I simply explore them now with boots and a backpack.\n\n\n\n**Segment 4 — mountain biking**\n\nHorse riding looks elegant until a large horse turns its head toward me; then I remember how nervous animals make me. My friends and I prefer machines we can repair ourselves. We load our bikes onto a van, climb forest tracks, and race down muddy slopes. It is demanding, occasionally frightening, and guaranteed to cover us in dirt. That combination is exactly why mountain biking appeals to me.","transcript_status":"source_word_comments","word_comment_ids":["402","403","404","405"],"speaker_labels":["Person A","Person B","Person C","Person D"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '01b8131f2f9ead4e1e71f08df9b02830d182798acbe7f5f72f36cf9f31957ed1'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p2-set031-audio', 'Listening Part 2: Places to run (2026) Audio', '**Segment 1 — in the fitness centre**

The weather forecast used to decide whether I exercised. Heat, rain, or darkness each provided a good excuse. Then I joined a centre near the station. Inside, I can choose a treadmill, set a precise pace, and move straight to strength training afterwards. I miss outdoor scenery sometimes, but consistency matters more. A controlled indoor space means the session happens regardless of what is falling from the sky.



**Segment 2 — at the seaside**

I leave my shoes beside the door and start just before sunrise. The promenade is nearly empty, fishing boats are returning, and the air smells of salt. On calm days I run on firm sand; when the tide is high, I use the path above the beach. Hills might improve my fitness more , but the sea makes me want to go out, and that is what sustains a routine.



**Segment 3 — in the street**

There is a park fifteen minutes away, yet travelling there makes a short run feel like an expedition. I prefer stepping outside and beginning immediately. My route uses residential roads, a shopping street before it gets busy, and a hill near the station. I wear reflective clothing and avoid rush hour because cars are the obvious disadvantage. Even so, the convenience of running through my own streets keeps the habit simple.



**Segment 4 — on the running track**

I am training for ten kilometres and need honest numbers. GPS can lose signal beneath trees, but the stadium lane never changes: twenty-five laps means ten kilometres. The surface is forgiving, there are no traffic lights, and I can leave water beside the start line. Scenic routes are more enjoyable, but when I am testing pace or racing a friend, measured laps on the track are far more useful.', '{"source_key":"listening-p2-set031-audio","skill":"listening","part_number":2,"transcript":"**Segment 1 — in the fitness centre**\n\nThe weather forecast used to decide whether I exercised. Heat, rain, or darkness each provided a good excuse. Then I joined a centre near the station. Inside, I can choose a treadmill, set a precise pace, and move straight to strength training afterwards. I miss outdoor scenery sometimes, but consistency matters more. A controlled indoor space means the session happens regardless of what is falling from the sky.\n\n\n\n**Segment 2 — at the seaside**\n\nI leave my shoes beside the door and start just before sunrise. The promenade is nearly empty, fishing boats are returning, and the air smells of salt. On calm days I run on firm sand; when the tide is high, I use the path above the beach. Hills might improve my fitness more , but the sea makes me want to go out, and that is what sustains a routine.\n\n\n\n**Segment 3 — in the street**\n\nThere is a park fifteen minutes away, yet travelling there makes a short run feel like an expedition. I prefer stepping outside and beginning immediately. My route uses residential roads, a shopping street before it gets busy, and a hill near the station. I wear reflective clothing and avoid rush hour because cars are the obvious disadvantage. Even so, the convenience of running through my own streets keeps the habit simple.\n\n\n\n**Segment 4 — on the running track**\n\nI am training for ten kilometres and need honest numbers. GPS can lose signal beneath trees, but the stadium lane never changes: twenty-five laps means ten kilometres. The surface is forgiving, there are no traffic lights, and I can leave water beside the start line. Scenic routes are more enjoyable, but when I am testing pace or racing a friend, measured laps on the track are far more useful.","transcript_status":"source_word_comments","word_comment_ids":["406","407","408","409"],"speaker_labels":["Person A","Person B","Person C","Person D"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '21406897223172841b75d8b77f78ed9dec27363c40b4b8e50ac1edc825707d59'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p2-set032-audio', 'Listening Part 2: Doing exercise (2026) Audio', '**Segment 1 — hate exercising**

My flatmate has signed me up for three trial classes this year. I left spinning after twelve minutes, spent yoga watching the clock, and discovered that boxing gloves smell terrible. She says I simply haven''t found the right activity. I think I have found the right conclusion. I understand the health arguments, but forcing myself through a workout makes me miserable. I would rather walk somewhere useful than exercise because a schedule tells me to.



**Segment 2 — help improve work performance**

On days when I go straight from bed to my desk, even simple decisions feel slow. A short swim before work changes that. By nine, I am alert, patient in meetings, and much less likely to postpone difficult tasks. The benefit surprised me because I originally joined the pool for my back. My posture improved, but the real reason I keep the early alarm is how much sharper and more productive the working day becomes.



**Segment 3 — find exercise tiring**

Everyone at the running club talks about the wonderful feeling afterwards. Afterwards, I am usually lying on the floor wondering who moved the stairs farther away. Even gentle sessions leave my muscles heavy for the rest of the day. I have learned to exercise in the evening so I can sleep rather than struggle through work. I continue for health reasons, but energy is certainly not what it gives me.



**Segment 4 — has fun when exercising with friends**

I used to avoid the gym because rows of silent people on machines felt depressing. Then colleagues invited me to their Thursday circuit. We complain together, invent ridiculous team names, and celebrate finishing each round as though we won a championship. The exercises themselves are still hard, yet the hour passes because someone is always joking or encouraging me. Friendship turned a duty into an event I genuinely anticipate.', '{"source_key":"listening-p2-set032-audio","skill":"listening","part_number":2,"transcript":"**Segment 1 — hate exercising**\n\nMy flatmate has signed me up for three trial classes this year. I left spinning after twelve minutes, spent yoga watching the clock, and discovered that boxing gloves smell terrible. She says I simply haven''t found the right activity. I think I have found the right conclusion. I understand the health arguments, but forcing myself through a workout makes me miserable. I would rather walk somewhere useful than exercise because a schedule tells me to.\n\n\n\n**Segment 2 — help improve work performance**\n\nOn days when I go straight from bed to my desk, even simple decisions feel slow. A short swim before work changes that. By nine, I am alert, patient in meetings, and much less likely to postpone difficult tasks. The benefit surprised me because I originally joined the pool for my back. My posture improved, but the real reason I keep the early alarm is how much sharper and more productive the working day becomes.\n\n\n\n**Segment 3 — find exercise tiring**\n\nEveryone at the running club talks about the wonderful feeling afterwards. Afterwards, I am usually lying on the floor wondering who moved the stairs farther away. Even gentle sessions leave my muscles heavy for the rest of the day. I have learned to exercise in the evening so I can sleep rather than struggle through work. I continue for health reasons, but energy is certainly not what it gives me.\n\n\n\n**Segment 4 — has fun when exercising with friends**\n\nI used to avoid the gym because rows of silent people on machines felt depressing. Then colleagues invited me to their Thursday circuit. We complain together, invent ridiculous team names, and celebrate finishing each round as though we won a championship. The exercises themselves are still hard, yet the hour passes because someone is always joking or encouraging me. Friendship turned a duty into an event I genuinely anticipate.","transcript_status":"source_word_comments","word_comment_ids":["410","411","412","413"],"speaker_labels":["Person A","Person B","Person C","Person D"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '8be5c5bd02319d09cee46af1c31d92bcd4a37fee1fdaee571e1fd26734b29b6f'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p2-set033-audio', 'Listening Part 2: The Internet (2026) Audio', '**Segment 1 — watch films**

Cinema tickets in my town now cost almost as much as dinner. I still go for big releases with friends, but most evenings I use a streaming service and connect the laptop to our old projector. My brother makes popcorn, we argue about what to choose, and the living room becomes our private cinema. I use the internet for plenty of practical things, yet watching films is the activity that takes most of my free time online.



**Segment 2 — communicate with friends**

My grandmother refused video calls at first because she thought the camera would stay on forever. Now she calls every Wednesday and carries the tablet around the garden to show me new flowers. Messages are useful, but seeing her face makes the distance feel smaller. News, shopping, and entertainment are all available online; none matters to me as much as maintaining conversations with people I cannot visit often.



**Segment 3 — complete assignments**

Our history teacher gave us a project on a building that no longer exists. The textbook offered one paragraph, but online archives had maps, newspaper reports, and photographs from several decades. My group shared links in a document and built the presentation without meeting in person. Of course, we had to check reliable sources rather than copy the first result. The internet''s main role in my life is helping turn school tasks into completed work.



**Segment 4 — find transport information**

A cancelled bus once left me outside a station for ninety minutes because I had not checked the service notice. Since then, I open a journey-planning app before every unfamiliar trip. It compares trains and buses, shows walking connections, and warns me when a platform changes. I rarely use social media, and films are easier on television. Online transport information, however, prevents real problems, so that is what I rely on most.', '{"source_key":"listening-p2-set033-audio","skill":"listening","part_number":2,"transcript":"**Segment 1 — watch films**\n\nCinema tickets in my town now cost almost as much as dinner. I still go for big releases with friends, but most evenings I use a streaming service and connect the laptop to our old projector. My brother makes popcorn, we argue about what to choose, and the living room becomes our private cinema. I use the internet for plenty of practical things, yet watching films is the activity that takes most of my free time online.\n\n\n\n**Segment 2 — communicate with friends**\n\nMy grandmother refused video calls at first because she thought the camera would stay on forever. Now she calls every Wednesday and carries the tablet around the garden to show me new flowers. Messages are useful, but seeing her face makes the distance feel smaller. News, shopping, and entertainment are all available online; none matters to me as much as maintaining conversations with people I cannot visit often.\n\n\n\n**Segment 3 — complete assignments**\n\nOur history teacher gave us a project on a building that no longer exists. The textbook offered one paragraph, but online archives had maps, newspaper reports, and photographs from several decades. My group shared links in a document and built the presentation without meeting in person. Of course, we had to check reliable sources rather than copy the first result. The internet''s main role in my life is helping turn school tasks into completed work.\n\n\n\n**Segment 4 — find transport information**\n\nA cancelled bus once left me outside a station for ninety minutes because I had not checked the service notice. Since then, I open a journey-planning app before every unfamiliar trip. It compares trains and buses, shows walking connections, and warns me when a platform changes. I rarely use social media, and films are easier on television. Online transport information, however, prevents real problems, so that is what I rely on most.","transcript_status":"source_word_comments","word_comment_ids":["414","415","416","417"],"speaker_labels":["Person A","Person B","Person C","Person D"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'b8adca31372750aa8a34422efaf2e080f16e5f93975936f6e0acec3ea8c114f6'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p2-set034-audio', 'Listening Part 2: Art (2026) Audio', '**Segment 1 — social activity**

I joined a printmaking workshop without knowing anyone. By the end of the first evening, four of us were sharing ink, comparing mistakes, and planning a small exhibition in the café next door. The prints were individual, but the process was wonderfully communal; one person''s failed pattern often inspired another person''s idea. I enjoy the objects we produce, yet the real attraction is having a reason to gather, talk, and make something with other people.



**Segment 2 — with children**

Children never ask whether blue trees are realistic. They paint them, add orange rain, and explain an entire world before an adult has chosen a pencil. I volunteer at a Saturday club, laying out materials and helping with scissors, but I try not to control the result. Their confidence reminds me to take art less seriously. Working beside them is noisy and chaotic, and it constantly refreshes my own imagination.



**Segment 3 — as part of their job**

Every chapter of the educational book I edit needs illustrations. I sketch diagrams, discuss changes with the writer, and adjust colours so they remain clear when printed. Sometimes I would rather draw whatever interests me, but the image must support the text and meet a deadline. Art is woven into my working week, complete with feedback and revisions. It is creative, certainly, but it also has a practical purpose and a client.



**Segment 4 — alone**

Group workshops make me compare every line with the person beside me. At home, that pressure disappears. I put on an old shirt, clear the kitchen table, and draw for hours without showing anyone. Some pages are ugly experiments that go straight into a drawer. That secrecy is valuable: I can change direction, abandon an idea, or make something deeply personal without an audience waiting for an explanation.', '{"source_key":"listening-p2-set034-audio","skill":"listening","part_number":2,"transcript":"**Segment 1 — social activity**\n\nI joined a printmaking workshop without knowing anyone. By the end of the first evening, four of us were sharing ink, comparing mistakes, and planning a small exhibition in the café next door. The prints were individual, but the process was wonderfully communal; one person''s failed pattern often inspired another person''s idea. I enjoy the objects we produce, yet the real attraction is having a reason to gather, talk, and make something with other people.\n\n\n\n**Segment 2 — with children**\n\nChildren never ask whether blue trees are realistic. They paint them, add orange rain, and explain an entire world before an adult has chosen a pencil. I volunteer at a Saturday club, laying out materials and helping with scissors, but I try not to control the result. Their confidence reminds me to take art less seriously. Working beside them is noisy and chaotic, and it constantly refreshes my own imagination.\n\n\n\n**Segment 3 — as part of their job**\n\nEvery chapter of the educational book I edit needs illustrations. I sketch diagrams, discuss changes with the writer, and adjust colours so they remain clear when printed. Sometimes I would rather draw whatever interests me, but the image must support the text and meet a deadline. Art is woven into my working week, complete with feedback and revisions. It is creative, certainly, but it also has a practical purpose and a client.\n\n\n\n**Segment 4 — alone**\n\nGroup workshops make me compare every line with the person beside me. At home, that pressure disappears. I put on an old shirt, clear the kitchen table, and draw for hours without showing anyone. Some pages are ugly experiments that go straight into a drawer. That secrecy is valuable: I can change direction, abandon an idea, or make something deeply personal without an audience waiting for an explanation.","transcript_status":"source_word_comments","word_comment_ids":["418","419","420","421"],"speaker_labels":["Person A","Person B","Person C","Person D"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'e88721525762701e6f40cc6383f3f3a5cbcee841f5db18e503f1a99897aecf83'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p2-set035-audio', 'Listening Part 2: Transportation to work (2026) Audio', '**Segment 1 — travel by bus**

The bus is not glamorous, but it is predictable. The stop sits opposite my building, the route ends beside the office, and a monthly pass costs less than parking for a week. I usually stand during the first ten minutes, then find a seat after the school stop. Cycling would be healthier, though the main road feels unsafe. Letting the bus carry me through the morning traffic is the practical choice I make every day.



**Segment 2 — travel by car**

My work involves visiting two sites and carrying a case of testing equipment. Public transport can reach each place, but not in the order I need, and the equipment is awkward on a crowded train. Driving lets me leave early, change plans, and collect my son on the return journey. I dislike fuel prices and avoid unnecessary trips, yet for this particular routine, the car is less a luxury than a mobile tool.



**Segment 3 — walk alone**

Moving closer to the office changed my mornings completely. Instead of checking traffic reports, I step out with a coffee and follow a street for fifteen minutes. Colleagues sometimes offer lifts, but I decline unless the weather is extreme. Walking by myself gives me time to organise my thoughts before conversations begin. It is a short journey, though the silence between home and work has become surprisingly important.



**Segment 4 — walk with a friend**

Maya and I discovered we lived on neighbouring roads after complaining about the same delayed bus. Now we meet at the corner and walk the final three kilometres together. She sets a pace; I remember umbrellas and bring coffee. On difficult mornings, one of us would probably choose the bus alone, but neither wants to disappoint the other. The shared journey keeps us active and turns commuting into regular catch-up time.', '{"source_key":"listening-p2-set035-audio","skill":"listening","part_number":2,"transcript":"**Segment 1 — travel by bus**\n\nThe bus is not glamorous, but it is predictable. The stop sits opposite my building, the route ends beside the office, and a monthly pass costs less than parking for a week. I usually stand during the first ten minutes, then find a seat after the school stop. Cycling would be healthier, though the main road feels unsafe. Letting the bus carry me through the morning traffic is the practical choice I make every day.\n\n\n\n**Segment 2 — travel by car**\n\nMy work involves visiting two sites and carrying a case of testing equipment. Public transport can reach each place, but not in the order I need, and the equipment is awkward on a crowded train. Driving lets me leave early, change plans, and collect my son on the return journey. I dislike fuel prices and avoid unnecessary trips, yet for this particular routine, the car is less a luxury than a mobile tool.\n\n\n\n**Segment 3 — walk alone**\n\nMoving closer to the office changed my mornings completely. Instead of checking traffic reports, I step out with a coffee and follow a street for fifteen minutes. Colleagues sometimes offer lifts, but I decline unless the weather is extreme. Walking by myself gives me time to organise my thoughts before conversations begin. It is a short journey, though the silence between home and work has become surprisingly important.\n\n\n\n**Segment 4 — walk with a friend**\n\nMaya and I discovered we lived on neighbouring roads after complaining about the same delayed bus. Now we meet at the corner and walk the final three kilometres together. She sets a pace; I remember umbrellas and bring coffee. On difficult mornings, one of us would probably choose the bus alone, but neither wants to disappoint the other. The shared journey keeps us active and turns commuting into regular catch-up time.","transcript_status":"source_word_comments","word_comment_ids":["422","423","424","425"],"speaker_labels":["Person A","Person B","Person C","Person D"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'f5b104e2e5c4e61e3f88abbb428f32b665cf2b037b149a3d0cd6379368a31417'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p2-set036-audio', 'Listening Part 2: Studying (Version 2) (2026) Audio', '**Segment 1 — In various places**

My concentration depends more on the task than the address. I read theory on the train, write essays in the library, review flashcards in a café, and practise presentations while walking through the park. Staying in one place too long makes me restless, whereas changing surroundings gives each activity a fresh start. I carry a small charger and headphones, so almost any table or bench can become a temporary study area.



**Segment 2 — In a quiet place**

My friends revise together and claim the discussion helps. In our sessions, discussion usually becomes gossip within ten minutes. I work better in the silent section upstairs, where even unwrapping food earns angry looks. With no conversation to follow and no music playing, I can hold a complicated argument in my head. I meet friends after studying, but the learning itself needs a place with almost no noise.



**Segment 3 — With music**

I created one playlist for each subject during my first year. Piano means mathematics, gentle electronic music means reading, and film soundtracks mean essay writing. The categories are unnecessary, perhaps, but the routine settles me I keep the volume low and avoid lyrics. Complete silence makes me restless, while loud songs become entertainment. A carefully chosen background track sits at the level where my attention works best.



**Segment 4 — Late at night**

Daytime belongs to everyone else: deliveries, phone calls, traffic, and requests from family. After midnight, the house finally feels like mine. I can solve a problem without someone opening the door halfway through. I tried waking early instead, but my mind remained foggy until breakfast. Late-night study is not ideal before an eight-o''clock class, so I plan it carefully, yet it remains the period when I produce my strongest work.', '{"source_key":"listening-p2-set036-audio","skill":"listening","part_number":2,"transcript":"**Segment 1 — In various places**\n\nMy concentration depends more on the task than the address. I read theory on the train, write essays in the library, review flashcards in a café, and practise presentations while walking through the park. Staying in one place too long makes me restless, whereas changing surroundings gives each activity a fresh start. I carry a small charger and headphones, so almost any table or bench can become a temporary study area.\n\n\n\n**Segment 2 — In a quiet place**\n\nMy friends revise together and claim the discussion helps. In our sessions, discussion usually becomes gossip within ten minutes. I work better in the silent section upstairs, where even unwrapping food earns angry looks. With no conversation to follow and no music playing, I can hold a complicated argument in my head. I meet friends after studying, but the learning itself needs a place with almost no noise.\n\n\n\n**Segment 3 — With music**\n\nI created one playlist for each subject during my first year. Piano means mathematics, gentle electronic music means reading, and film soundtracks mean essay writing. The categories are unnecessary, perhaps, but the routine settles me I keep the volume low and avoid lyrics. Complete silence makes me restless, while loud songs become entertainment. A carefully chosen background track sits at the level where my attention works best.\n\n\n\n**Segment 4 — Late at night**\n\nDaytime belongs to everyone else: deliveries, phone calls, traffic, and requests from family. After midnight, the house finally feels like mine. I can solve a problem without someone opening the door halfway through. I tried waking early instead, but my mind remained foggy until breakfast. Late-night study is not ideal before an eight-o''clock class, so I plan it carefully, yet it remains the period when I produce my strongest work.","transcript_status":"source_word_comments","word_comment_ids":["426","427","428","429"],"speaker_labels":["Person A","Person B","Person C","Person D"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '4160862d84e5072d6a83d16ddfcaf9b88f24b94884e2b901135616852a013318'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p2-set037-audio', 'Listening Part 2: Studying (2026) Audio', '**Segment 1 — In the coffee shop**

The café owner knows my order before I reach the counter. I choose the table near the back-not beside the noisy coffee machine, but close enough to feel the room''s energy. At home, I find chores; in the library, the silence makes me sleepy. The gentle movement of people coming and going somehow keeps me alert. One cup can last two hours, and that small public space has become my most reliable place to study.



**Segment 2 — In the park**

My biology notes make more sense outdoors. I sit beneath the large fig tree, spread papers across a picnic blanket, and take a short walk whenever an idea becomes stuck. Children and dogs create some noise, but it is distant and irregular, not the constant conversation of a café. Weather is the obvious limitation. On dry afternoons, though, the park gives me fresh air and enough calm to work for hours.



**Segment 3 — On public transport**

The train journey to college takes fifty-five minutes, which used to disappear into scrolling on my phone. Now I download readings beforehand and use the same seat table whenever possible. I cannot write neatly while the carriage moves, but flashcards, recorded lectures, and short articles work well. By the time I arrive, one task is already finished. Commuting has become a moving study session rather than dead time.



**Segment 4 — At home**

I tried every fashionable study location before admitting the obvious: my own dining table works best. The kettle is nearby, the chair suits my back, and all my books are within reach. I put my phone in another room and ask the family not to interrupt for an hour. Home can contain distractions, but it also gives me control over light, temperature, and breaks. With a little discipline, it is the place where I settle most deeply.', '{"source_key":"listening-p2-set037-audio","skill":"listening","part_number":2,"transcript":"**Segment 1 — In the coffee shop**\n\nThe café owner knows my order before I reach the counter. I choose the table near the back-not beside the noisy coffee machine, but close enough to feel the room''s energy. At home, I find chores; in the library, the silence makes me sleepy. The gentle movement of people coming and going somehow keeps me alert. One cup can last two hours, and that small public space has become my most reliable place to study.\n\n\n\n**Segment 2 — In the park**\n\nMy biology notes make more sense outdoors. I sit beneath the large fig tree, spread papers across a picnic blanket, and take a short walk whenever an idea becomes stuck. Children and dogs create some noise, but it is distant and irregular, not the constant conversation of a café. Weather is the obvious limitation. On dry afternoons, though, the park gives me fresh air and enough calm to work for hours.\n\n\n\n**Segment 3 — On public transport**\n\nThe train journey to college takes fifty-five minutes, which used to disappear into scrolling on my phone. Now I download readings beforehand and use the same seat table whenever possible. I cannot write neatly while the carriage moves, but flashcards, recorded lectures, and short articles work well. By the time I arrive, one task is already finished. Commuting has become a moving study session rather than dead time.\n\n\n\n**Segment 4 — At home**\n\nI tried every fashionable study location before admitting the obvious: my own dining table works best. The kettle is nearby, the chair suits my back, and all my books are within reach. I put my phone in another room and ask the family not to interrupt for an hour. Home can contain distractions, but it also gives me control over light, temperature, and breaks. With a little discipline, it is the place where I settle most deeply.","transcript_status":"source_word_comments","word_comment_ids":["430","431","432","433"],"speaker_labels":["Person A","Person B","Person C","Person D"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'ce6e5d6b734e8e1b958dd2bf48842e1735000eeb8f0d63e9e30f7bf4c417c2e9'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p2-set038-audio', 'Listening Part 2: Restaurant experiences Audio', '**Segment 1 — Was still hungry after dinner**

I''d been meaning to try this restaurant for ages because several people at work had recommended it. The meal itself was actually very good, and I especially liked the dessert. The only problem was the amount of food they served. When I left, I felt as though I''d only had a light snack rather than a full evening meal. I even stopped at a convenience store on the way home to get something else to eat. For the price, I expected a little more.



**Segment 2 — Ordered the wrong dish**

My friend had told me that this place was well known for one particular chicken dish, so that was what I planned to have. Unfortunately, the restaurant was very busy and I didn''t pay enough attention when the waiter came to our table. It wasn''t until my meal arrived that I realised I''d pointed to the item just below the one I actually wanted. I decided not to send it back because it looked good, and in fact I really enjoyed it. Still, I''ll have to return if I want to find out why everyone talks about the chicken.



**Segment 3 — Met a successful staff member**

We went to a recently opened restaurant near the city centre. While we were waiting for our table, one of the employees started chatting to us. I assumed she was just a regular member of staff, but later one of my friends recognised her photograph on a display near the entrance. Apparently, she had won a national prize for her work in hospitality earlier that year. She was very modest about it and never mentioned the prize herself.



**Segment 4 — Enjoyed a live performance**

At first, I thought the evening would be fairly ordinary. The restaurant was comfortable and the food was good, but nothing really stood out. Then, just as we were finishing the main course, the lights near one end of the room were lowered and a man sat down at the large piano we had noticed earlier. He played for about half an hour, and everyone stopped talking to pay attention. We hadn''t expected any entertainment, so it turned out to be the most memorable part of the evening.', '{"source_key":"listening-p2-set038-audio","skill":"listening","part_number":2,"transcript":"**Segment 1 — Was still hungry after dinner**\n\nI''d been meaning to try this restaurant for ages because several people at work had recommended it. The meal itself was actually very good, and I especially liked the dessert. The only problem was the amount of food they served. When I left, I felt as though I''d only had a light snack rather than a full evening meal. I even stopped at a convenience store on the way home to get something else to eat. For the price, I expected a little more.\n\n\n\n**Segment 2 — Ordered the wrong dish**\n\nMy friend had told me that this place was well known for one particular chicken dish, so that was what I planned to have. Unfortunately, the restaurant was very busy and I didn''t pay enough attention when the waiter came to our table. It wasn''t until my meal arrived that I realised I''d pointed to the item just below the one I actually wanted. I decided not to send it back because it looked good, and in fact I really enjoyed it. Still, I''ll have to return if I want to find out why everyone talks about the chicken.\n\n\n\n**Segment 3 — Met a successful staff member**\n\nWe went to a recently opened restaurant near the city centre. While we were waiting for our table, one of the employees started chatting to us. I assumed she was just a regular member of staff, but later one of my friends recognised her photograph on a display near the entrance. Apparently, she had won a national prize for her work in hospitality earlier that year. She was very modest about it and never mentioned the prize herself.\n\n\n\n**Segment 4 — Enjoyed a live performance**\n\nAt first, I thought the evening would be fairly ordinary. The restaurant was comfortable and the food was good, but nothing really stood out. Then, just as we were finishing the main course, the lights near one end of the room were lowered and a man sat down at the large piano we had noticed earlier. He played for about half an hour, and everyone stopped talking to pay attention. We hadn''t expected any entertainment, so it turned out to be the most memorable part of the evening.","transcript_status":"source_word_comments","word_comment_ids":["434","435","436","437"],"speaker_labels":["Person A","Person B","Person C","Person D"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'deeabee2163cbc33cb1badd68a2792434436fbc81ed9412e0b866e32de1878c0'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p2-set039-audio', 'Listening Part 2: Restaurant experience Audio', '**Segment 1 — was still hungry after dinner**

I went to a restaurant last weekend, but I had never read any reviews about it before. The food was good, but the portions were really small. I was still hungry after dinner, so I had to make a sandwich when I got home. I don''t think I''ll ever go back there again.



**Segment 2 — ordered the wrong dish**

I went to this restaurant with a friend last weekend because we had heard that it was popular. There were many different dishes on the menu, but the restaurant was especially famous for its chicken. I wanted to try it, but I was in a hurry and accidentally ordered the wrong dish. Luckily, the food I got was still really tasty, so I enjoyed it anyway. However, I''d like to come back another time and try the famous chicken dish.



**Segment 3 — met a successful staff member**

I visited a new restaurant last weekend with my friends. The food was really good, and the atmosphere was relaxing. While we were waiting for our meal, I started talking to one of the staff members. She was very friendly and told me about her work at the restaurant. She also mentioned that she had recently received an award for her work there. I thought it was really interesting to hear about her experience.



**Segment 4 — watched a nice performance**

I visited this restaurant with a few friends last Saturday evening. When we walked in, I immediately noticed a large piano near the dining area. I thought it was part of the new decoration, but later I found out that someone was going to play it during dinner. After we finished our food, a musician started playing some beautiful songs. We really enjoyed sitting there and listening to the music. It made the evening much more enjoyable.', '{"source_key":"listening-p2-set039-audio","skill":"listening","part_number":2,"transcript":"**Segment 1 — was still hungry after dinner**\n\nI went to a restaurant last weekend, but I had never read any reviews about it before. The food was good, but the portions were really small. I was still hungry after dinner, so I had to make a sandwich when I got home. I don''t think I''ll ever go back there again.\n\n\n\n**Segment 2 — ordered the wrong dish**\n\nI went to this restaurant with a friend last weekend because we had heard that it was popular. There were many different dishes on the menu, but the restaurant was especially famous for its chicken. I wanted to try it, but I was in a hurry and accidentally ordered the wrong dish. Luckily, the food I got was still really tasty, so I enjoyed it anyway. However, I''d like to come back another time and try the famous chicken dish.\n\n\n\n**Segment 3 — met a successful staff member**\n\nI visited a new restaurant last weekend with my friends. The food was really good, and the atmosphere was relaxing. While we were waiting for our meal, I started talking to one of the staff members. She was very friendly and told me about her work at the restaurant. She also mentioned that she had recently received an award for her work there. I thought it was really interesting to hear about her experience.\n\n\n\n**Segment 4 — watched a nice performance**\n\nI visited this restaurant with a few friends last Saturday evening. When we walked in, I immediately noticed a large piano near the dining area. I thought it was part of the new decoration, but later I found out that someone was going to play it during dinner. After we finished our food, a musician started playing some beautiful songs. We really enjoyed sitting there and listening to the music. It made the evening much more enjoyable.","transcript_status":"source_word_comments","word_comment_ids":["438","439","440","441"],"speaker_labels":["Person A","Person B","Person C","Person D"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'df234f6fa51223a0b558be8cd4607ae6025edf9d59d14757ed2427da9af89e28'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p2-set040-audio', 'Listening Part 2: Sport Audio', '**Segment 1 — plays in a team sport**

A solo run depends entirely on my own motivation, which is unreliable on cold mornings. Basketball is different. If I miss training, four teammates notice immediately. During a match, every decision connects to someone else: I pass, screen, defend, and trust another player to cover space. Winning feels shared, and even losing gives us something to analyse together. That cooperation is the reason team sport suits me.



**Segment 2 — spends time in the water**

On land I am clumsy, but in a pool everything feels smoother. I swim before breakfast three times a week, counting lengths until the lifeguard changes shifts. Summer adds trips to the lake, where I can stay in for hours. Friends invite me to football and running, yet I never enjoy the heat or impact. Give me water, goggles, and a clear lane, and I am completely at home.



**Segment 3 — plays in the street**

Our neighbourhood had no sports ground, so two drain covers became goalposts and parked cars became the boundaries. We learned to stop the ball whenever a vehicle appeared and continued the match immediately afterwards. I now play at a proper club, but Sunday games still happen outside my parents'' house with whoever is available. The street is where I first learned football and where it still feels most joyful.



**Segment 4 — does sports with animals**

Riding is not simply sitting while the horse does the work. My legs, balance, and timing are active every second, and the animal responds to tiny changes I make. Building trust with a nervous horse can take weeks, which makes progress especially rewarding. I enjoy many outdoor sports, but none asks me to cooperate with another living creature in the same way.', '{"source_key":"listening-p2-set040-audio","skill":"listening","part_number":2,"transcript":"**Segment 1 — plays in a team sport**\n\nA solo run depends entirely on my own motivation, which is unreliable on cold mornings. Basketball is different. If I miss training, four teammates notice immediately. During a match, every decision connects to someone else: I pass, screen, defend, and trust another player to cover space. Winning feels shared, and even losing gives us something to analyse together. That cooperation is the reason team sport suits me.\n\n\n\n**Segment 2 — spends time in the water**\n\nOn land I am clumsy, but in a pool everything feels smoother. I swim before breakfast three times a week, counting lengths until the lifeguard changes shifts. Summer adds trips to the lake, where I can stay in for hours. Friends invite me to football and running, yet I never enjoy the heat or impact. Give me water, goggles, and a clear lane, and I am completely at home.\n\n\n\n**Segment 3 — plays in the street**\n\nOur neighbourhood had no sports ground, so two drain covers became goalposts and parked cars became the boundaries. We learned to stop the ball whenever a vehicle appeared and continued the match immediately afterwards. I now play at a proper club, but Sunday games still happen outside my parents'' house with whoever is available. The street is where I first learned football and where it still feels most joyful.\n\n\n\n**Segment 4 — does sports with animals**\n\nRiding is not simply sitting while the horse does the work. My legs, balance, and timing are active every second, and the animal responds to tiny changes I make. Building trust with a nervous horse can take weeks, which makes progress especially rewarding. I enjoy many outdoor sports, but none asks me to cooperate with another living creature in the same way.","transcript_status":"source_word_comments","word_comment_ids":["442","443","444","445"],"speaker_labels":["Person A","Person B","Person C","Person D"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '8baf2e14c42c2a4521686791be455749e7f854326260b310bc4e0e6d89d9f21c'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p2-set041-audio', 'Listening Part 2: Reading books (2026) Audio', '**Segment 1 — read when travelling to school**

At home, my phone always wins. On the school bus, however, the signal disappears through two villages, so I open a book instead. The journey lasts about thirty-five minutes-long enough for a chapter, short enough that I rarely become tired of it. I keep a paperback in the front pocket of my bag and leave my textbooks elsewhere. Most of my voluntary reading now happens between my stop and the school gates.



**Segment 2 — don''t have time to read**

Three unopened novels sit beside my bed, each bought with sincere plans. Then homework runs late, football practice moves to an extra evening, and my younger brother needs help. When I finally lie down, reading two pages feels impossible. Weekends are filled with family errands and friends. I still like books and keep collecting recommendations; what I lack is a free, awake hour in which to enjoy them.



**Segment 3 — read on their beds**

Reading on transport makes me dizzy, and the living room television interrupts every sentence. My bed solves both problems. I prop up the pillows, use a small lamp, and read until my eyes begin closing. Sometimes that is ten minutes; on holidays it can be two hours. The routine also helps me stop looking at screens before sleep. My bedroom is not the most imaginative location, but it is where books actually get finished.



**Segment 4 — prefer another activity to reading books**

I understand why people love novels, and I enjoy a good story when a teacher assigns one. Free time is different. I would rather meet friends for basketball, repair my bike, or watch a match. Reading asks me to sit still after a whole day at a desk, which feels like more school. Books are not unpleasant; they simply lose whenever I can choose an activity with movement and other people.', '{"source_key":"listening-p2-set041-audio","skill":"listening","part_number":2,"transcript":"**Segment 1 — read when travelling to school**\n\nAt home, my phone always wins. On the school bus, however, the signal disappears through two villages, so I open a book instead. The journey lasts about thirty-five minutes-long enough for a chapter, short enough that I rarely become tired of it. I keep a paperback in the front pocket of my bag and leave my textbooks elsewhere. Most of my voluntary reading now happens between my stop and the school gates.\n\n\n\n**Segment 2 — don''t have time to read**\n\nThree unopened novels sit beside my bed, each bought with sincere plans. Then homework runs late, football practice moves to an extra evening, and my younger brother needs help. When I finally lie down, reading two pages feels impossible. Weekends are filled with family errands and friends. I still like books and keep collecting recommendations; what I lack is a free, awake hour in which to enjoy them.\n\n\n\n**Segment 3 — read on their beds**\n\nReading on transport makes me dizzy, and the living room television interrupts every sentence. My bed solves both problems. I prop up the pillows, use a small lamp, and read until my eyes begin closing. Sometimes that is ten minutes; on holidays it can be two hours. The routine also helps me stop looking at screens before sleep. My bedroom is not the most imaginative location, but it is where books actually get finished.\n\n\n\n**Segment 4 — prefer another activity to reading books**\n\nI understand why people love novels, and I enjoy a good story when a teacher assigns one. Free time is different. I would rather meet friends for basketball, repair my bike, or watch a match. Reading asks me to sit still after a whole day at a desk, which feels like more school. Books are not unpleasant; they simply lose whenever I can choose an activity with movement and other people.","transcript_status":"source_word_comments","word_comment_ids":["446","447","448","449"],"speaker_labels":["Person A","Person B","Person C","Person D"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'aa059a7f41600808cbacf5db495c2d488741213a48e7725635347a98961b43a2'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p2-set042-audio', 'Listening Part 2: Reading books (2026) Audio', '**Segment 1 — read when travelling to school**

I used to read a lot in my bedroom when I was younger, especially before going to sleep. But these days, I don''t really read at home anymore because my phone is always next to me. The only time I read properly is on the bus in the morning. My journey to school takes about thirty minutes, so I usually bring a novel with me and read a few pages before class.



**Segment 2 — don''t have time to read**

I actually enjoy books, and I''ve got two new ones on my desk right now. Sometimes I even put one beside my bed, thinking I''ll read it before I sleep. But most evenings I''m too tired after homework, football practice, and helping my parents. On weekends, I often plan to read, but something else always comes up. So, at the moment, I hardly read at all.



**Segment 3 — read on their beds**

Some of my friends read on the train or bus, but I can''t do that because it makes me feel a bit sick. I also don''t like reading in the living room because the TV is usually on. For me, the best place is my bed. I read there almost every night, even if it''s only for ten minutes. It helps me relax and forget about school for a while.



**Segment 4 — prefer another activity to reading books**

My parents keep telling me that reading is important, and I agree with them, really. I sometimes read short stories for school, and I can finish them if I have to. But when I have free time, I''d much rather play basketball or watch videos about sports. Books are okay, but they don''t excite me as much as doing something active with my friends.', '{"source_key":"listening-p2-set042-audio","skill":"listening","part_number":2,"transcript":"**Segment 1 — read when travelling to school**\n\nI used to read a lot in my bedroom when I was younger, especially before going to sleep. But these days, I don''t really read at home anymore because my phone is always next to me. The only time I read properly is on the bus in the morning. My journey to school takes about thirty minutes, so I usually bring a novel with me and read a few pages before class.\n\n\n\n**Segment 2 — don''t have time to read**\n\nI actually enjoy books, and I''ve got two new ones on my desk right now. Sometimes I even put one beside my bed, thinking I''ll read it before I sleep. But most evenings I''m too tired after homework, football practice, and helping my parents. On weekends, I often plan to read, but something else always comes up. So, at the moment, I hardly read at all.\n\n\n\n**Segment 3 — read on their beds**\n\nSome of my friends read on the train or bus, but I can''t do that because it makes me feel a bit sick. I also don''t like reading in the living room because the TV is usually on. For me, the best place is my bed. I read there almost every night, even if it''s only for ten minutes. It helps me relax and forget about school for a while.\n\n\n\n**Segment 4 — prefer another activity to reading books**\n\nMy parents keep telling me that reading is important, and I agree with them, really. I sometimes read short stories for school, and I can finish them if I have to. But when I have free time, I''d much rather play basketball or watch videos about sports. Books are okay, but they don''t excite me as much as doing something active with my friends.","transcript_status":"source_word_comments","word_comment_ids":["450","451","452","453"],"speaker_labels":["Person A","Person B","Person C","Person D"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'aa80c221e5815ad49f923d75b54c13a4f9fc137747ceca65f478f19b2584e402'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p2-set043-audio', 'Listening Part 2: Discussing their restaurant experiences Audio', '**Segment 1 — was still hungry after dinner**

I went to a new Italian restaurant with my friends last Friday. The place looked lovely, and the waiter recommended the chef''s special pasta. It tasted good, but the portion was really small. We also shared a salad and some bread, but when I got home, I still had to make myself a sandwich. So, overall, the food was nice, but it definitely wasn''t enough for me.



**Segment 2 — paid a high price**

My family chose a seafood restaurant near the beach for my dad''s birthday. The view was amazing, and the dishes were fresh, especially the grilled fish. However, I was shocked when the bill arrived. We didn''t order that much, but everything cost more than I expected. The service was fine, but I don''t think I''d go back unless it was a very special occasion.



**Segment 3 — met the helpful staff**

I had dinner at a small Japanese restaurant yesterday. At first, I couldn''t understand the menu because many dishes had unfamiliar names. Luckily, one of the staff members came over and explained everything patiently. She even suggested a dish without peanuts because I told her I had an allergy. The food was good, but what I appreciated most was how kind and helpful the staff were.



**Segment 4 — watched a perfect performance**

Last weekend, I went to a restaurant that had live music in the evening. The food was ordinary, and honestly, the drinks were a little expensive. But the singer and the band were fantastic. They played beautifully, and everyone in the restaurant stopped talking just to listen. It felt like a mini concert, and I couldn''t find a single mistake in their performance.', '{"source_key":"listening-p2-set043-audio","skill":"listening","part_number":2,"transcript":"**Segment 1 — was still hungry after dinner**\n\nI went to a new Italian restaurant with my friends last Friday. The place looked lovely, and the waiter recommended the chef''s special pasta. It tasted good, but the portion was really small. We also shared a salad and some bread, but when I got home, I still had to make myself a sandwich. So, overall, the food was nice, but it definitely wasn''t enough for me.\n\n\n\n**Segment 2 — paid a high price**\n\nMy family chose a seafood restaurant near the beach for my dad''s birthday. The view was amazing, and the dishes were fresh, especially the grilled fish. However, I was shocked when the bill arrived. We didn''t order that much, but everything cost more than I expected. The service was fine, but I don''t think I''d go back unless it was a very special occasion.\n\n\n\n**Segment 3 — met the helpful staff**\n\nI had dinner at a small Japanese restaurant yesterday. At first, I couldn''t understand the menu because many dishes had unfamiliar names. Luckily, one of the staff members came over and explained everything patiently. She even suggested a dish without peanuts because I told her I had an allergy. The food was good, but what I appreciated most was how kind and helpful the staff were.\n\n\n\n**Segment 4 — watched a perfect performance**\n\nLast weekend, I went to a restaurant that had live music in the evening. The food was ordinary, and honestly, the drinks were a little expensive. But the singer and the band were fantastic. They played beautifully, and everyone in the restaurant stopped talking just to listen. It felt like a mini concert, and I couldn''t find a single mistake in their performance.","transcript_status":"source_word_comments","word_comment_ids":["454","455","456","457"],"speaker_labels":["Person A","Person B","Person C","Person D"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'e6eaad41cb315836788cc4dd6e9adf8d6ed106ac12cd7be0c77a53bb56305683'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p2-set044-audio', 'Listening Part 2: Shopping Habits (2026) Audio', '**Segment 1 — has limited time for shopping**

I used to enjoy browsing different shops, but work now takes up most of my week. When I need groceries or household items, I prepare a list and choose one place where I can buy everything. I rarely stop to look at displays or compare products for long. If the trip cannot be completed , I normally postpone it or place an order during my lunch break.



**Segment 2 — tries to save money**

I almost never buy an item as soon as I see it. Before deciding, I compare prices across several shops, check delivery charges and search for discount codes. For expensive purchases, I may wait until a seasonal sale begins. Occasionally, the product sells out before I order it, but I would still rather miss a bargain than discover that I paid much more than necessary.



**Segment 3 — considers the environmental impact**

I once chose products mainly because they were cheap or attractive. Now I also notice how much packaging they use and whether the materials can be recycled. When possible, I choose refillable containers, second-hand clothes or goods made locally. I am not perfect and still buy imported products sometimes, but I have become more aware that ordinary shopping choices can affect the world beyond my home.



**Segment 4 — shops only on the internet**

I cannot remember the last time I spent an afternoon inside a shopping centre. I use several apps to order food, clothes and household products, usually while I am at home or travelling. Not being able to examine an item first can be inconvenient, especially with clothing. Even so, I continue to order everything digitally and have it delivered rather than visiting a store myself.', '{"source_key":"listening-p2-set044-audio","skill":"listening","part_number":2,"transcript":"**Segment 1 — has limited time for shopping**\n\nI used to enjoy browsing different shops, but work now takes up most of my week. When I need groceries or household items, I prepare a list and choose one place where I can buy everything. I rarely stop to look at displays or compare products for long. If the trip cannot be completed , I normally postpone it or place an order during my lunch break.\n\n\n\n**Segment 2 — tries to save money**\n\nI almost never buy an item as soon as I see it. Before deciding, I compare prices across several shops, check delivery charges and search for discount codes. For expensive purchases, I may wait until a seasonal sale begins. Occasionally, the product sells out before I order it, but I would still rather miss a bargain than discover that I paid much more than necessary.\n\n\n\n**Segment 3 — considers the environmental impact**\n\nI once chose products mainly because they were cheap or attractive. Now I also notice how much packaging they use and whether the materials can be recycled. When possible, I choose refillable containers, second-hand clothes or goods made locally. I am not perfect and still buy imported products sometimes, but I have become more aware that ordinary shopping choices can affect the world beyond my home.\n\n\n\n**Segment 4 — shops only on the internet**\n\nI cannot remember the last time I spent an afternoon inside a shopping centre. I use several apps to order food, clothes and household products, usually while I am at home or travelling. Not being able to examine an item first can be inconvenient, especially with clothing. Even so, I continue to order everything digitally and have it delivered rather than visiting a store myself.","transcript_status":"source_word_comments","word_comment_ids":["458","459","460","461"],"speaker_labels":["Person A","Person B","Person C","Person D"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'f4dd3d77e0ffdff29b0861c332d4d5044044c1de22cc615c2551155d0460b2bf'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p3-set001-audio', 'Listening Part 3: Changes in the workplace Audio', 'W: I''m thinking about switching to another job.
M: Why? Your current job is very stable.
W: I think I should try my hand at different fields. The jobs I take should only last around 1-2 years. I don''t like staying too long in one job or with one company; that would be really boring. Nowadays, many companies offer temporary jobs, which allows me to try out different fields.
M: Oh, but if you stay longer at one company, they might offer you more opportunities for career advancement. I always want to stay long-term with a company that suits me.
W: Nowadays, young people who have just graduated from university are very talented and have many qualifications. I''m afraid that if I stick with one job and don''t change to accumulate knowledge in various fields, it will be hard to compete with these young, talented people.
M: We also need to consider job satisfaction. If we do well, we need to be encouraged and motivated. That helps employees feel that their efforts and contributions to the company are worthwhile.
W: You''re absolutely right, I couldn''t agree more. In this age of technological advancement, many jobs have been replaced by machines. More and more people are losing their jobs due to the development of technology and engineering. I think this is a concerning issue.
M: I don''t think so. Technology is helping us do our work more quickly, easily, and conveniently than ever. If we know how to leverage technology in our jobs, productivity will increase significantly, which in turn helps develop the economy and society.', '{"source_key":"listening-p3-set001-audio","skill":"listening","part_number":3,"transcript":"W: I''m thinking about switching to another job.\nM: Why? Your current job is very stable.\nW: I think I should try my hand at different fields. The jobs I take should only last around 1-2 years. I don''t like staying too long in one job or with one company; that would be really boring. Nowadays, many companies offer temporary jobs, which allows me to try out different fields.\nM: Oh, but if you stay longer at one company, they might offer you more opportunities for career advancement. I always want to stay long-term with a company that suits me.\nW: Nowadays, young people who have just graduated from university are very talented and have many qualifications. I''m afraid that if I stick with one job and don''t change to accumulate knowledge in various fields, it will be hard to compete with these young, talented people.\nM: We also need to consider job satisfaction. If we do well, we need to be encouraged and motivated. That helps employees feel that their efforts and contributions to the company are worthwhile.\nW: You''re absolutely right, I couldn''t agree more. In this age of technological advancement, many jobs have been replaced by machines. More and more people are losing their jobs due to the development of technology and engineering. I think this is a concerning issue.\nM: I don''t think so. Technology is helping us do our work more quickly, easily, and conveniently than ever. If we know how to leverage technology in our jobs, productivity will increase significantly, which in turn helps develop the economy and society.","transcript_status":"source_word_comment","word_comment_ids":["462"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '998e5634199e503f61d3e6e29a001c5dc6cae8a42c68f43c6bf2d4a77ca6083c'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p3-set002-audio', 'Listening Part 3: Beauty Audio', 'W: Hi, what are you reading?
M: I''m reading an article about the concept of beauty.
W: Oh really, that sounds interesting. Beauty is something that can''t be defined because everyone has a different perspective on it, right?
M: Actually, people have quite similar perspectives on beauty. We always prefer beautiful things and are drawn to them.
W: Beauty in the past and now is very different. The older generation might see traditional things as beautiful, while the younger generation considers unique and unconventional things as beautiful. So, not everyone has the same view on beauty.
M: Beauty can be found in many places we wouldn''t expect, or even within something considered ugly, there''s always some beauty present. So, nothing in the world is entirely ugly.
W: Exactly. That''s why the definition of beauty is constantly changing. In a few decades, people might find things beautiful that we once considered ugly.
M: That''s one perspective. Let''s wait and see how it changes.', '{"source_key":"listening-p3-set002-audio","skill":"listening","part_number":3,"transcript":"W: Hi, what are you reading?\nM: I''m reading an article about the concept of beauty.\nW: Oh really, that sounds interesting. Beauty is something that can''t be defined because everyone has a different perspective on it, right?\nM: Actually, people have quite similar perspectives on beauty. We always prefer beautiful things and are drawn to them.\nW: Beauty in the past and now is very different. The older generation might see traditional things as beautiful, while the younger generation considers unique and unconventional things as beautiful. So, not everyone has the same view on beauty.\nM: Beauty can be found in many places we wouldn''t expect, or even within something considered ugly, there''s always some beauty present. So, nothing in the world is entirely ugly.\nW: Exactly. That''s why the definition of beauty is constantly changing. In a few decades, people might find things beautiful that we once considered ugly.\nM: That''s one perspective. Let''s wait and see how it changes.","transcript_status":"source_word_comment","word_comment_ids":["463"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '9e2c265ba9e6c029a46cde7a3a08819911bdad24a340cfc55189e4e05dacdcd3'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p3-set003-audio', 'Listening Part 3: Actors Audio', 'W: What do you think about casting actors before casting them?

M: I think it''s absolutely necessary and the most important thing because it determines whether the actor is suitable for the role or not.

W: I understand that auditions are important. But if we only rely on a 15 to 20 minute audition, that short period of time cannot really show us the actor''s full potential.

M: That''s a good point. So I think it''s better to let actors perform freestyle, not relying on the script, so that they can improvise, thereby clearly showing their acting skills.

W: But actors often respond best to a good script. And they also need a script provided by the director and directed to act according to the script. Actors can’t always act freely.

M: What do you think about stage actors moving to film acting?

W: I think they are two completely different fields. When I was studying acting in college, stage acting and film acting were two completely separate subjects. They require different skills and qualities from the actor. So, it’s not easy to move from stage acting to film acting and vice versa.

M: That’s right. These are two very different forms of acting and they require different skills from the actor. However, as actors, I think we all need encouragement and support from the audience.

W: I completely agree. Actors need praise and feedback to feel recognized for their efforts and contributions.', '{"source_key":"listening-p3-set003-audio","skill":"listening","part_number":3,"transcript":"W: What do you think about casting actors before casting them?\n\nM: I think it''s absolutely necessary and the most important thing because it determines whether the actor is suitable for the role or not.\n\nW: I understand that auditions are important. But if we only rely on a 15 to 20 minute audition, that short period of time cannot really show us the actor''s full potential.\n\nM: That''s a good point. So I think it''s better to let actors perform freestyle, not relying on the script, so that they can improvise, thereby clearly showing their acting skills.\n\nW: But actors often respond best to a good script. And they also need a script provided by the director and directed to act according to the script. Actors can’t always act freely.\n\nM: What do you think about stage actors moving to film acting?\n\nW: I think they are two completely different fields. When I was studying acting in college, stage acting and film acting were two completely separate subjects. They require different skills and qualities from the actor. So, it’s not easy to move from stage acting to film acting and vice versa.\n\nM: That’s right. These are two very different forms of acting and they require different skills from the actor. However, as actors, I think we all need encouragement and support from the audience.\n\nW: I completely agree. Actors need praise and feedback to feel recognized for their efforts and contributions.","transcript_status":"source_word_comment","word_comment_ids":["464"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '2b0fea6468256adddd61ced6af919aa0d2c671a141ba5e5710cea78e3f7a0811'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p3-set004-audio', 'Listening Part 3: Information and technology Audio', 'Audio recording for Listening Part 3: Information and technology Audio', '{"source_key":"listening-p3-set004-audio","skill":"listening","part_number":3,"transcript":null,"transcript_status":"missing_source_comment","word_comment_ids":[],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '1575fceda6cd8ffe0d7b705cb98a20164e873d4f150a16d0247f229e22f55670'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p3-set005-audio', 'Listening Part 3: The Internet (2026) Audio', 'W: You know, I really feel there''s too much information on the Internet. It can be overwhelming sometimes. It''s hard to know what''s credible.
M: Honestly, I think it''s more about how we search for information. Finding what we need online requires certain skills. We need to know how to filter through all that content.
W: Definitely! If you don''t know how to search properly, you can easily get lost in all that noise.
M: And I believe the Internet affects the way we think. With so much information available, we often skim rather than think deeply about topics.
W: That''s an interesting point. I hadn''t thought about that. But I do see how the constant scrolling and instant answers can make young people less patient.
M: Exactly! They expect instant results. It''s like waiting for anything has become a challenge.
W: Right! So, while the Internet offers us a wealth of knowledge, it can also reduce our patience and tolerance.', '{"source_key":"listening-p3-set005-audio","skill":"listening","part_number":3,"transcript":"W: You know, I really feel there''s too much information on the Internet. It can be overwhelming sometimes. It''s hard to know what''s credible.\nM: Honestly, I think it''s more about how we search for information. Finding what we need online requires certain skills. We need to know how to filter through all that content.\nW: Definitely! If you don''t know how to search properly, you can easily get lost in all that noise.\nM: And I believe the Internet affects the way we think. With so much information available, we often skim rather than think deeply about topics.\nW: That''s an interesting point. I hadn''t thought about that. But I do see how the constant scrolling and instant answers can make young people less patient.\nM: Exactly! They expect instant results. It''s like waiting for anything has become a challenge.\nW: Right! So, while the Internet offers us a wealth of knowledge, it can also reduce our patience and tolerance.","transcript_status":"source_word_comment","word_comment_ids":["465"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '172bc3cf5409d6f07223ec9e89d2521322042a46b5642a89e06e00a339936f97'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p3-set006-audio', 'Listening Part 3: Politics (2026) Audio', 'W: Did you hear the callers on the youth council programme last night? Half of them were under twenty-five, and they were making sharper points than some of the older guests.
M: I did. At the community forum last month, the front rows were full of students. Young people clearly see politics as something that affects rent, transport, and education, not as a distant subject.
W: Social media has helped create that change. A short clip from a council meeting can reach thousands of people before the evening news, and campaigns can organise volunteers almost overnight.
M: It changes campaign communication, but I would not say it changes politics itself, and I would not rely on it for understanding. I am more impressed that people now read long-form reports, compare newspapers, and check official data.
W: So you think the public is better informed than before?
M: Overall, yes. There is still misinformation, but people have more tools and many are learning to verify claims.
W: Another encouraging sign is the number of women standing in local elections. Our district used to have one female candidate; this year there are seven.
M: That is a real improvement. Political institutions make better decisions when women are present in greater numbers.
W: And younger voters can see leadership that looks more like the society it represents.', '{"source_key":"listening-p3-set006-audio","skill":"listening","part_number":3,"transcript":"W: Did you hear the callers on the youth council programme last night? Half of them were under twenty-five, and they were making sharper points than some of the older guests.\nM: I did. At the community forum last month, the front rows were full of students. Young people clearly see politics as something that affects rent, transport, and education, not as a distant subject.\nW: Social media has helped create that change. A short clip from a council meeting can reach thousands of people before the evening news, and campaigns can organise volunteers almost overnight.\nM: It changes campaign communication, but I would not say it changes politics itself, and I would not rely on it for understanding. I am more impressed that people now read long-form reports, compare newspapers, and check official data.\nW: So you think the public is better informed than before?\nM: Overall, yes. There is still misinformation, but people have more tools and many are learning to verify claims.\nW: Another encouraging sign is the number of women standing in local elections. Our district used to have one female candidate; this year there are seven.\nM: That is a real improvement. Political institutions make better decisions when women are present in greater numbers.\nW: And younger voters can see leadership that looks more like the society it represents.","transcript_status":"source_word_comment","word_comment_ids":["466"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'f32bc0d9cd26ec0a818e8bde1766da719ff349b0f2f64b4a0a5693b3800d9734'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p3-set007-audio', 'Listening Part 3: University education (2026) Audio', 'W: That looks interesting. What are you up to?
M: Oh, I just came across this interesting report about universities and how they''re evolving in the digital age. It talked about the impact of the internet, student experiences, curriculum choices, and even competition between institutions. It got me thinking, there''s so much to unpack when it comes to how education is changing, don''t you think?
W: Yeah, I''ve been reading about similar things lately. It''s amazing how different opinions can be on what makes a good university experience. I think we can both agree that the internet has made education more accessible. It''s great how people from different backgrounds can now access higher education without being physically on campus.
M: Absolutely, I agree with that. It''s a game-changer for those who can''t afford to relocate or attend in person. But I still believe that social interactions are a crucial part of university life. Online education can never truly replace the friendships, group work, and networking that happen in a physical setting.
W: Hmm, I''m not so sure. While social interactions can be important, I think online learning allows students to focus more on their studies without all the distractions of campus life. Not everyone benefits from that kind of environment.
W: To be honest, I''m not a fan of having too many options in the curriculum. A diverse curriculum sounds good in theory, but it can overwhelm students and make it harder for them to focus on the core subjects they really need.
M: That''s one way to look at it, but I think universities provide a unique space for students to develop their social skills alongside their academic ones. Another thing I''m really in favor of is encouraging competition between universities. When universities compete, it drives innovation and pushes them to offer better resources.
W: I disagree there. Competition can sometimes lead to universities focusing too much on rankings and flashy features instead of the of education. It can become more about marketing than genuine improvement.
M: That''s a fair concern. But competition also forces universities to constantly improve, which can benefit students in the long run.', '{"source_key":"listening-p3-set007-audio","skill":"listening","part_number":3,"transcript":"W: That looks interesting. What are you up to?\nM: Oh, I just came across this interesting report about universities and how they''re evolving in the digital age. It talked about the impact of the internet, student experiences, curriculum choices, and even competition between institutions. It got me thinking, there''s so much to unpack when it comes to how education is changing, don''t you think?\nW: Yeah, I''ve been reading about similar things lately. It''s amazing how different opinions can be on what makes a good university experience. I think we can both agree that the internet has made education more accessible. It''s great how people from different backgrounds can now access higher education without being physically on campus.\nM: Absolutely, I agree with that. It''s a game-changer for those who can''t afford to relocate or attend in person. But I still believe that social interactions are a crucial part of university life. Online education can never truly replace the friendships, group work, and networking that happen in a physical setting.\nW: Hmm, I''m not so sure. While social interactions can be important, I think online learning allows students to focus more on their studies without all the distractions of campus life. Not everyone benefits from that kind of environment.\nW: To be honest, I''m not a fan of having too many options in the curriculum. A diverse curriculum sounds good in theory, but it can overwhelm students and make it harder for them to focus on the core subjects they really need.\nM: That''s one way to look at it, but I think universities provide a unique space for students to develop their social skills alongside their academic ones. Another thing I''m really in favor of is encouraging competition between universities. When universities compete, it drives innovation and pushes them to offer better resources.\nW: I disagree there. Competition can sometimes lead to universities focusing too much on rankings and flashy features instead of the of education. It can become more about marketing than genuine improvement.\nM: That''s a fair concern. But competition also forces universities to constantly improve, which can benefit students in the long run.","transcript_status":"source_word_comment","word_comment_ids":["467"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '12922c4d5a3fda933dcda1bb0888f712f294b5029a11f79fb3e3fb835ef28a37'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p3-set008-audio', 'Listening Part 3: Urban farming (2026) Audio', 'M: I''ve been reading a report on urban farming and its potential impact on city life. It''s fascinating how cities are starting to embrace this concept to tackle issues like food security and environmental sustainability. It got me thinking about how this could reshape urban living.
W: I find the idea of urban farming intriguing too, but I believe living space is more important than farming space. People need proper homes to thrive.
M: I understand that perspective, but I have to say, farming space in urban areas is really appealing. It brings a bit of nature into the city and can enhance the overall environment.
W: I agree with that. Urban farming does have a lot of visual and ecological benefits. However, we really need to focus on the fact that there''s a pressing need for more food in our cities. That should be a priority.
M: That''s a valid point, but I think farming space will also benefit the urban economy. It creates jobs and stimulates local businesses, which is essential for growth.
W: I see where you''re coming from, but while boosting the economy is great, we can''t overlook the immediate need for more food. Urban farming can help, but it shouldn''t replace the need for larger-scale solutions to food shortages.
M: I agree that food scarcity is a serious issue, but if we can implement urban farming effectively, it can definitely contribute to alleviating that problem while also strengthening the economy.', '{"source_key":"listening-p3-set008-audio","skill":"listening","part_number":3,"transcript":"M: I''ve been reading a report on urban farming and its potential impact on city life. It''s fascinating how cities are starting to embrace this concept to tackle issues like food security and environmental sustainability. It got me thinking about how this could reshape urban living.\nW: I find the idea of urban farming intriguing too, but I believe living space is more important than farming space. People need proper homes to thrive.\nM: I understand that perspective, but I have to say, farming space in urban areas is really appealing. It brings a bit of nature into the city and can enhance the overall environment.\nW: I agree with that. Urban farming does have a lot of visual and ecological benefits. However, we really need to focus on the fact that there''s a pressing need for more food in our cities. That should be a priority.\nM: That''s a valid point, but I think farming space will also benefit the urban economy. It creates jobs and stimulates local businesses, which is essential for growth.\nW: I see where you''re coming from, but while boosting the economy is great, we can''t overlook the immediate need for more food. Urban farming can help, but it shouldn''t replace the need for larger-scale solutions to food shortages.\nM: I agree that food scarcity is a serious issue, but if we can implement urban farming effectively, it can definitely contribute to alleviating that problem while also strengthening the economy.","transcript_status":"source_word_comment","word_comment_ids":["468"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '8d8aa3228ea8f435943de34652b783d2f5b55f9e4271645953db084e87efcd7f'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p3-set009-audio', 'Listening Part 3: Auditions Audio', 'M: You know, I''ve always believed that auditions are the most important part of an actor''s career. I mean, that''s where the magic happens. It doesn''t matter how great you are in rehearsals or even in the final performance; if you can''t nail that audition, you''re not getting anywhere.
W: Yeah, but it''s not just about the audition. I''ve seen actors who can absolutely shine when they''re given the right material to work with. Strong scripts really bring out the best in them. If the writing is weak, even a talented actor might struggle to connect. I think actors respond best when they feel inspired by what''s on the page.
M: That''s true, but whether it''s a strong script or a weak one, they still have to nail that first audition to even get the chance to perform, right?
W: Sure, the audition is key, but once they''re in, the script can make or break their performance. It''s a balance between both.
M: I agree with that. But I also think there''s a huge difference between theatre acting and movie acting. The two require completely different skill sets. In theatre, you have to project and be larger than life, whereas in movies, it''s all about subtlety, keeping everything smaller and more contained.
W: Absolutely! They''re such different worlds. The way you use your body, your voice, and even how you interact with your fellow actors is completely different depending on whether you''re on stage or in front of a camera.
M: Right, and that''s why actors deserve as much praise as possible. They''re constantly shifting between styles and adapting to new roles. It''s tough!
W: Couldn''t agree more. Whether it''s theatre or film, acting is such an emotional and demanding job. Encouragement and praise go a long way. Actors need to feel appreciated for all the work they put in.', '{"source_key":"listening-p3-set009-audio","skill":"listening","part_number":3,"transcript":"M: You know, I''ve always believed that auditions are the most important part of an actor''s career. I mean, that''s where the magic happens. It doesn''t matter how great you are in rehearsals or even in the final performance; if you can''t nail that audition, you''re not getting anywhere.\nW: Yeah, but it''s not just about the audition. I''ve seen actors who can absolutely shine when they''re given the right material to work with. Strong scripts really bring out the best in them. If the writing is weak, even a talented actor might struggle to connect. I think actors respond best when they feel inspired by what''s on the page.\nM: That''s true, but whether it''s a strong script or a weak one, they still have to nail that first audition to even get the chance to perform, right?\nW: Sure, the audition is key, but once they''re in, the script can make or break their performance. It''s a balance between both.\nM: I agree with that. But I also think there''s a huge difference between theatre acting and movie acting. The two require completely different skill sets. In theatre, you have to project and be larger than life, whereas in movies, it''s all about subtlety, keeping everything smaller and more contained.\nW: Absolutely! They''re such different worlds. The way you use your body, your voice, and even how you interact with your fellow actors is completely different depending on whether you''re on stage or in front of a camera.\nM: Right, and that''s why actors deserve as much praise as possible. They''re constantly shifting between styles and adapting to new roles. It''s tough!\nW: Couldn''t agree more. Whether it''s theatre or film, acting is such an emotional and demanding job. Encouragement and praise go a long way. Actors need to feel appreciated for all the work they put in.","transcript_status":"source_word_comment","word_comment_ids":["469"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '57b2d1e0f2199a78403515019d3dc2c202a381e516d2faf51c0166211db83efd'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p3-set010-audio', 'Listening Part 3: Community Design (2026) Audio', 'W: The renovated square felt completely different during yesterday''s market. Before the changes, people hurried across it. Now the curved benches and wide paths almost make strangers slow down and speak.
M: I noticed that too. My son started playing near the fountain, and within minutes three families were sharing toys. Design can influence behaviour more than I expected.
W: That is why I support shared courtyards, gardens, and places where people naturally meet.
M: They create opportunities, yes, but they do not create trust overnight. In my apartment building, it took months before neighbours stopped giving each other polite smiles and began offering real help.
W: Community can develop faster in a workplace, though. Teams spend every day solving problems together.
M: Perhaps, but work relationships feel different to me.
W: I do not think the difference is fundamental. Whether people meet through an office, a sports club, or a neighbourhood group, a community is still built on belonging, support, and shared responsibility.
M: I would separate professional and social communities, but technology has certainly blurred those boundaries.
W: Definitely. Our local parenting group began online during the floods, and members still exchange childcare and emergency information.
M: My closest photography group is also online. Some of us have never met, yet we critique each other''s work every week.
W: So technology has changed not only where communities meet, but how they begin.', '{"source_key":"listening-p3-set010-audio","skill":"listening","part_number":3,"transcript":"W: The renovated square felt completely different during yesterday''s market. Before the changes, people hurried across it. Now the curved benches and wide paths almost make strangers slow down and speak.\nM: I noticed that too. My son started playing near the fountain, and within minutes three families were sharing toys. Design can influence behaviour more than I expected.\nW: That is why I support shared courtyards, gardens, and places where people naturally meet.\nM: They create opportunities, yes, but they do not create trust overnight. In my apartment building, it took months before neighbours stopped giving each other polite smiles and began offering real help.\nW: Community can develop faster in a workplace, though. Teams spend every day solving problems together.\nM: Perhaps, but work relationships feel different to me.\nW: I do not think the difference is fundamental. Whether people meet through an office, a sports club, or a neighbourhood group, a community is still built on belonging, support, and shared responsibility.\nM: I would separate professional and social communities, but technology has certainly blurred those boundaries.\nW: Definitely. Our local parenting group began online during the floods, and members still exchange childcare and emergency information.\nM: My closest photography group is also online. Some of us have never met, yet we critique each other''s work every week.\nW: So technology has changed not only where communities meet, but how they begin.","transcript_status":"source_word_comment","word_comment_ids":["470"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '7409677ade8616b52ab1cf10ee4646746f62107b8c7cc64dbd676cf0f7ec107d'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p3-set011-audio', 'Listening Part 3: Changes in the workplace (2026) Audio', 'M: Since the merger, every department seems determined to replace its systems, reporting lines, and even job titles at once. Some continuity is essential, or employees lose the routines that keep the organisation functioning.
W: I understand the need for stability, but people should not confuse routine with security. Three colleagues were promised long-term roles last year and were still made redundant. Job security simply cannot always be guaranteed now.
M: I still think responsible employers can offer reasonable stability. The factor that certainly matters, though, is satisfaction. When people find meaning in the work itself, they are more willing to cope with change.
W: I agree completely. A higher salary may attract someone, but feeling respected and useful is often what keeps them.
M: Our design team stayed through the merger because they still believed in the product.
W: Whereas the sales team left after managers stopped listening to them.
M: Technology may at least make the transition worthwhile. Better automation can reduce waste, help small firms compete, and raise productivity across many industries.
W: It can also remove roles and increase pressure, so I would not call every technological change positive.
M: Not every individual change, no. But for the wider economy, innovation creates new services and opportunities that old systems cannot provide.
W: Provided organisations help workers adapt rather than treating them as disposable.', '{"source_key":"listening-p3-set011-audio","skill":"listening","part_number":3,"transcript":"M: Since the merger, every department seems determined to replace its systems, reporting lines, and even job titles at once. Some continuity is essential, or employees lose the routines that keep the organisation functioning.\nW: I understand the need for stability, but people should not confuse routine with security. Three colleagues were promised long-term roles last year and were still made redundant. Job security simply cannot always be guaranteed now.\nM: I still think responsible employers can offer reasonable stability. The factor that certainly matters, though, is satisfaction. When people find meaning in the work itself, they are more willing to cope with change.\nW: I agree completely. A higher salary may attract someone, but feeling respected and useful is often what keeps them.\nM: Our design team stayed through the merger because they still believed in the product.\nW: Whereas the sales team left after managers stopped listening to them.\nM: Technology may at least make the transition worthwhile. Better automation can reduce waste, help small firms compete, and raise productivity across many industries.\nW: It can also remove roles and increase pressure, so I would not call every technological change positive.\nM: Not every individual change, no. But for the wider economy, innovation creates new services and opportunities that old systems cannot provide.\nW: Provided organisations help workers adapt rather than treating them as disposable.","transcript_status":"source_word_comment","word_comment_ids":["471"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '2376e66cfdbd84a9a8e0448177c9cdc351b470faa0d16af29399dd11df671a00'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p3-set012-audio', 'Listening Part 3: Information technology Audio', 'M: Hi, what have you been studying lately?
W: Oh, I''m still studying technology and information systems. It''s a really hot topic these days.
M: That''s a fascinating field. I still can''t imagine the future of humanity alongside technology. I think within the next hundred years, humans won''t be able to keep up with the pace of information technology development.
W: I believe that the younger generation and future generations will become increasingly smarter, and they''ll discover even more amazing things about information technology to benefit society.
M: But if technology advances too much and becomes too sophisticated, won''t that cause a lot of people to lose their jobs? Many industries could be replaced by machines and robots. In the future, machines might even be smarter than humans.
W: I think machines are just there to support humans in their work; they can''t replace us or be smarter than us. If machines and robots are involved in the work process, they will make our jobs less strenuous and improve efficiency. This, in turn, will drive continuous economic and social development alongside technological advancements.
M: However, as we use more technology and share more personal data online, I think more should be done to protect individual privacy.
W: I agree. Protecting privacy is essential in this digital age, and people should have more control over their personal information.', '{"source_key":"listening-p3-set012-audio","skill":"listening","part_number":3,"transcript":"M: Hi, what have you been studying lately?\nW: Oh, I''m still studying technology and information systems. It''s a really hot topic these days.\nM: That''s a fascinating field. I still can''t imagine the future of humanity alongside technology. I think within the next hundred years, humans won''t be able to keep up with the pace of information technology development.\nW: I believe that the younger generation and future generations will become increasingly smarter, and they''ll discover even more amazing things about information technology to benefit society.\nM: But if technology advances too much and becomes too sophisticated, won''t that cause a lot of people to lose their jobs? Many industries could be replaced by machines and robots. In the future, machines might even be smarter than humans.\nW: I think machines are just there to support humans in their work; they can''t replace us or be smarter than us. If machines and robots are involved in the work process, they will make our jobs less strenuous and improve efficiency. This, in turn, will drive continuous economic and social development alongside technological advancements.\nM: However, as we use more technology and share more personal data online, I think more should be done to protect individual privacy.\nW: I agree. Protecting privacy is essential in this digital age, and people should have more control over their personal information.","transcript_status":"source_word_comment","word_comment_ids":["472"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '40588c6042231a281bede08edb0339c430299dc0051bf5914aee3492f22933e7'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p3-set013-audio', 'Listening Part 3: Singers and music (2026) Audio', 'W: The teenagers in tonight''s choir kept talking about the singer who funded their music room. That is why I think singers can be good role models. Their choices can encourage young fans to practise, volunteer, or speak confidently.
M: Some can, though fame alone does not make anyone worth copying.
W: Of course not. I mean artists who use their influence responsibly, not every celebrity with a microphone.
M: Musical taste is too personal for universal heroes anyway. My favourite singer sounds powerful to me and unbearable to my brother.
W: Exactly. Our preferences come from memory, culture, age, and personality. There is no objective playlist that everyone should love.
M: Yet I still think music itself is a universal language. At an international festival, people may not share vocabulary, but rhythm and melody allow them to respond together.
W: I am less certain. Cultural meanings can be very different, even if people enjoy the same beat.
M: Films rely on that shared emotional response all the time.
W: They also show how music can manipulate feelings. A harmless character seems threatening when low strings begin.
M: And an ordinary product can feel exciting in an advertisement because of the soundtrack.
W: So on that point we agree. Music does not merely accompany emotion; it can actively steer it.', '{"source_key":"listening-p3-set013-audio","skill":"listening","part_number":3,"transcript":"W: The teenagers in tonight''s choir kept talking about the singer who funded their music room. That is why I think singers can be good role models. Their choices can encourage young fans to practise, volunteer, or speak confidently.\nM: Some can, though fame alone does not make anyone worth copying.\nW: Of course not. I mean artists who use their influence responsibly, not every celebrity with a microphone.\nM: Musical taste is too personal for universal heroes anyway. My favourite singer sounds powerful to me and unbearable to my brother.\nW: Exactly. Our preferences come from memory, culture, age, and personality. There is no objective playlist that everyone should love.\nM: Yet I still think music itself is a universal language. At an international festival, people may not share vocabulary, but rhythm and melody allow them to respond together.\nW: I am less certain. Cultural meanings can be very different, even if people enjoy the same beat.\nM: Films rely on that shared emotional response all the time.\nW: They also show how music can manipulate feelings. A harmless character seems threatening when low strings begin.\nM: And an ordinary product can feel exciting in an advertisement because of the soundtrack.\nW: So on that point we agree. Music does not merely accompany emotion; it can actively steer it.","transcript_status":"source_word_comment","word_comment_ids":["473"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '6d3cc3b1e3347680a704a486310e0538fec6743a4960dcfa0d8a8a05a997d828'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p3-set014-audio', 'Listening Part 3: Beauty (2026) Audio', 'M: Look at these portraits from the 1990s. Different photographers, yet the faces, poses, and body shapes are remarkably similar. People often share the same idea of what beauty should look like.
W: I think that similarity was imposed by magazines rather than genuinely shared by everyone, and the next room proves that ideas change over time. The eyebrows, clothing, and hairstyles praised thirty years ago are already returning after being mocked for years.
M: The repeated styles make me think beauty ideals are more stable than they appear. Still, the most beautiful photograph here is not a portrait at all; it is that cracked bus shelter reflecting the sunrise.
W: I love that one. Beauty often appears in unlikely places, including rust on a wall, a tired person''s laugh, and shadows across an empty factory.
M: Perhaps photographers train us to notice what everyone else walks past.
W: And society is beginning to notice different kinds of people too. Traditional beauty standards are going to change as unedited images and more varied faces become visible.
M: Or the internet may simply create a new uniform standard.
W: It might, but younger audiences are challenging old rules about age, skin, body size, and gender.
M: I hope they keep the freedom to disagree about beauty.
W: That disagreement is evidence that the definition is still evolving.', '{"source_key":"listening-p3-set014-audio","skill":"listening","part_number":3,"transcript":"M: Look at these portraits from the 1990s. Different photographers, yet the faces, poses, and body shapes are remarkably similar. People often share the same idea of what beauty should look like.\nW: I think that similarity was imposed by magazines rather than genuinely shared by everyone, and the next room proves that ideas change over time. The eyebrows, clothing, and hairstyles praised thirty years ago are already returning after being mocked for years.\nM: The repeated styles make me think beauty ideals are more stable than they appear. Still, the most beautiful photograph here is not a portrait at all; it is that cracked bus shelter reflecting the sunrise.\nW: I love that one. Beauty often appears in unlikely places, including rust on a wall, a tired person''s laugh, and shadows across an empty factory.\nM: Perhaps photographers train us to notice what everyone else walks past.\nW: And society is beginning to notice different kinds of people too. Traditional beauty standards are going to change as unedited images and more varied faces become visible.\nM: Or the internet may simply create a new uniform standard.\nW: It might, but younger audiences are challenging old rules about age, skin, body size, and gender.\nM: I hope they keep the freedom to disagree about beauty.\nW: That disagreement is evidence that the definition is still evolving.","transcript_status":"source_word_comment","word_comment_ids":["474"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '5b4c5c6341ba4637f7535b7c8d9170ec48835460a54e20a966ebcd59364d947d'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p3-set015-audio', 'Listening Part 3: The arts (2026) Audio', 'W: The gallery ticket costs more than my weekly food budget. People say art belongs to everyone, but in practice it is suitable mainly for the privileged few who have money and free time.
M: I would not say art is only for privileged people; street art, libraries, and free performances already exist. Even so, public investment matters. The government should fund museums, libraries, street performances, and community workshops instead of leaving culture entirely to the market.
W: I am not convinced government funding is the main answer. Schools matter even earlier. My first visit to a theatre at age nine changed what I thought I could do.
M: Same for me. Children should encounter painting, music, dance, and drama before they decide that art is not for them.
W: Not only the children whose parents can pay for lessons.
M: Agreed. And I think access will expand in the future. Digital archives, low-cost creative software, and virtual exhibitions already let people see work that used to be hidden in private collections.
W: Online access is convenient, but I do not think it will make art genuinely accessible by itself. It cannot replace standing in front of an original painting.
M: No, but it can be the first doorway. Someone who discovers an artist on a phone may later visit a gallery or join a class.
W: Provided that doorway is not locked behind another subscription.
M: That brings us back to public investment and genuine access.', '{"source_key":"listening-p3-set015-audio","skill":"listening","part_number":3,"transcript":"W: The gallery ticket costs more than my weekly food budget. People say art belongs to everyone, but in practice it is suitable mainly for the privileged few who have money and free time.\nM: I would not say art is only for privileged people; street art, libraries, and free performances already exist. Even so, public investment matters. The government should fund museums, libraries, street performances, and community workshops instead of leaving culture entirely to the market.\nW: I am not convinced government funding is the main answer. Schools matter even earlier. My first visit to a theatre at age nine changed what I thought I could do.\nM: Same for me. Children should encounter painting, music, dance, and drama before they decide that art is not for them.\nW: Not only the children whose parents can pay for lessons.\nM: Agreed. And I think access will expand in the future. Digital archives, low-cost creative software, and virtual exhibitions already let people see work that used to be hidden in private collections.\nW: Online access is convenient, but I do not think it will make art genuinely accessible by itself. It cannot replace standing in front of an original painting.\nM: No, but it can be the first doorway. Someone who discovers an artist on a phone may later visit a gallery or join a class.\nW: Provided that doorway is not locked behind another subscription.\nM: That brings us back to public investment and genuine access.","transcript_status":"source_word_comment","word_comment_ids":["475"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '7a98d7c7bf2d11c395cdf702d06ebfbf4d67d2a2ba0a48baac389631e0489127'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p3-set016-audio', 'Listening Part 3: Children and young people with technology (2026) Audio', 'M: I''ve been thinking about how children and teenagers use technology these days. Many of them seem really interested in learning through computers, tablets, and educational apps. Digital tools can make lessons feel more active and enjoyable.
W: I agree. Students often become more motivated when technology is used in class. Interactive games, videos, and online exercises can make learning more exciting for them.
M: However, I do worry that too much technology can affect their communication skills. Some children are comfortable sending messages online, but they find it harder to speak to people face to face.
W: Yes, I''ve noticed that too. Some young people can write online, but when they have to talk directly to classmates or adults, they may feel nervous or unsure.
W: Another problem is that many families don''t really know how to manage children''s technology use at home. Parents may not know how long children should spend online or what kinds of websites are suitable. I think families need more guidance.
M: I''m not sure families always need outside help. I think children themselves can learn to control their online behaviour if they are taught properly. With the right education, they can learn when to stop using screens and how to communicate responsibly online. **Explanation summary** *Both speakers say children are interested in learning through technology and can struggle with face-to-face communication. The woman says families need more guidance to manage children''s technology use at home, while the man says children can learn to regulate their own online behaviour responsibly.*', '{"source_key":"listening-p3-set016-audio","skill":"listening","part_number":3,"transcript":"M: I''ve been thinking about how children and teenagers use technology these days. Many of them seem really interested in learning through computers, tablets, and educational apps. Digital tools can make lessons feel more active and enjoyable.\nW: I agree. Students often become more motivated when technology is used in class. Interactive games, videos, and online exercises can make learning more exciting for them.\nM: However, I do worry that too much technology can affect their communication skills. Some children are comfortable sending messages online, but they find it harder to speak to people face to face.\nW: Yes, I''ve noticed that too. Some young people can write online, but when they have to talk directly to classmates or adults, they may feel nervous or unsure.\nW: Another problem is that many families don''t really know how to manage children''s technology use at home. Parents may not know how long children should spend online or what kinds of websites are suitable. I think families need more guidance.\nM: I''m not sure families always need outside help. I think children themselves can learn to control their online behaviour if they are taught properly. With the right education, they can learn when to stop using screens and how to communicate responsibly online. **Explanation summary** *Both speakers say children are interested in learning through technology and can struggle with face-to-face communication. The woman says families need more guidance to manage children''s technology use at home, while the man says children can learn to regulate their own online behaviour responsibly.*","transcript_status":"source_word_comment","word_comment_ids":["476"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'f6e7071099fa362f426ad560c6c7c3f178debb1b342330ec91ec137d291b02e6'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p3-set017-audio', 'Listening Part 3: A new environmental volunteer program (2026) Audio', 'M: I''ve read several articles about the new environmental volunteer program, and I think the media has exaggerated its benefits. The project sounds useful, but it won''t completely change the city in just a few weeks.
W: I agree. The media often makes these programs sound bigger than they really are. Volunteers can help clean parks and streets, but one program cannot solve every environmental problem.
W: In fact, I think littering will always be a problem. Some people simply don''t care about public spaces, no matter how many volunteers clean them. That''s why I believe punishment is the most effective solution. If people have to pay fines, they will think twice before throwing rubbish on the ground.
M: I''m not sure punishment is the best answer. Education and community activities can also change people''s habits over time. And I don''t think volunteers'' personal motivations affect the outcome of the program. Some may join because they care about the environment, while others may want experience for their resume, but if they collect rubbish and improve public spaces, the result is still positive.
W: Maybe, but I still think fines are necessary. Without strict punishment, many people will continue littering because they know there are no serious consequences. **Explanation summary** *Both speakers say the media exaggerates the benefits of the program. The woman says littering will always be a problem and believes punishment is the most effective solution. The man says volunteers'' motivations do not affect the useful outcome of the program.*', '{"source_key":"listening-p3-set017-audio","skill":"listening","part_number":3,"transcript":"M: I''ve read several articles about the new environmental volunteer program, and I think the media has exaggerated its benefits. The project sounds useful, but it won''t completely change the city in just a few weeks.\nW: I agree. The media often makes these programs sound bigger than they really are. Volunteers can help clean parks and streets, but one program cannot solve every environmental problem.\nW: In fact, I think littering will always be a problem. Some people simply don''t care about public spaces, no matter how many volunteers clean them. That''s why I believe punishment is the most effective solution. If people have to pay fines, they will think twice before throwing rubbish on the ground.\nM: I''m not sure punishment is the best answer. Education and community activities can also change people''s habits over time. And I don''t think volunteers'' personal motivations affect the outcome of the program. Some may join because they care about the environment, while others may want experience for their resume, but if they collect rubbish and improve public spaces, the result is still positive.\nW: Maybe, but I still think fines are necessary. Without strict punishment, many people will continue littering because they know there are no serious consequences. **Explanation summary** *Both speakers say the media exaggerates the benefits of the program. The woman says littering will always be a problem and believes punishment is the most effective solution. The man says volunteers'' motivations do not affect the useful outcome of the program.*","transcript_status":"source_word_comment","word_comment_ids":["477"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '6c0dd91c8f17f9a3982d9d8f6d2e7460f76260f5911824599bf01e1769748e43'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p3-set018-audio', 'Listening Part 3: The Internet (Version 2) (2026) Audio', 'W: These days, I feel there is too much information on the internet. Sometimes when I look for something online, I don''t know which result is useful or reliable.
M: I completely agree. There is so much information available that it can become confusing. A simple search can give thousands of results, and many of them are not very helpful.
M: That''s why I think using the internet properly requires real skills. People need to know how to search carefully, compare sources, and check whether information is trustworthy.
W: That''s an interesting point. I suppose many people don''t think carefully enough about how they search online.
M: The internet is also changing the way we think. Because we see so many opinions and answers, we often compare information instead of thinking deeply.
W: Yes, I agree. People don''t accept information in the same way as before. They read different views online and then decide what they believe.
M: Another issue is that the internet has made people less patient. We expect answers immediately because everything appears so online.
W: Exactly. When people are used to instant results, waiting for anything can feel difficult. **Explanation summary** *Both speakers say there is too much information online. The man specifically says using the internet requires search and evaluation skills. Both agree that the internet changes how people think and makes people less patient.*', '{"source_key":"listening-p3-set018-audio","skill":"listening","part_number":3,"transcript":"W: These days, I feel there is too much information on the internet. Sometimes when I look for something online, I don''t know which result is useful or reliable.\nM: I completely agree. There is so much information available that it can become confusing. A simple search can give thousands of results, and many of them are not very helpful.\nM: That''s why I think using the internet properly requires real skills. People need to know how to search carefully, compare sources, and check whether information is trustworthy.\nW: That''s an interesting point. I suppose many people don''t think carefully enough about how they search online.\nM: The internet is also changing the way we think. Because we see so many opinions and answers, we often compare information instead of thinking deeply.\nW: Yes, I agree. People don''t accept information in the same way as before. They read different views online and then decide what they believe.\nM: Another issue is that the internet has made people less patient. We expect answers immediately because everything appears so online.\nW: Exactly. When people are used to instant results, waiting for anything can feel difficult. **Explanation summary** *Both speakers say there is too much information online. The man specifically says using the internet requires search and evaluation skills. Both agree that the internet changes how people think and makes people less patient.*","transcript_status":"source_word_comment","word_comment_ids":["478"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '4b578eb837972139caeb424dfb25faadf0d930e9ac18d4714092c204c9673856'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p3-set019-audio', 'Listening Part 3: Local Cultural Differences (2026) Audio', 'M: Have you ever noticed how different local cultures can be, even within the same country?
W: Yes, definitely. Food, festivals, customs, and even everyday behaviour can change a lot from one region to another. In my opinion, language is the biggest difficulty when people try to understand a local culture. Regional dialects and accents can make communication really confusing.
M: I see what you mean, but I don''t think language is always the biggest problem. Sometimes values, traditions, and social rules are even harder to understand.
W: That''s true. I''m also worried that globalisation is changing local traditions. International trends are becoming more popular, and some traditional customs are slowly disappearing.
M: I agree with that. Globalisation is definitely changing people''s lifestyles. Local traditions are not as strong as they used to be in many places.
M: What concerns me most is that the younger generation does not seem to care as much about traditional culture. Many young people are more interested in global music, fashion, and online trends than in their own local heritage.
W: I''m not completely sure about that. Some young people still feel proud of their roots and take part in cultural festivals or family traditions.
M: Maybe, but I still think visiting places in person is the most effective way to learn about different cultures. When you travel somewhere, talk to local people, try the food, and see the traditions yourself, you understand much more than by only reading about it.
W: Travelling is helpful, but I think online materials, books, and cultural events can also teach people a lot. **Explanation summary** *The woman says language is the biggest difficulty in understanding local culture. Both speakers agree globalisation is changing local traditions. The man says young people care less about traditional culture and that visiting places in person is the most effective way to learn about cultural differences.*', '{"source_key":"listening-p3-set019-audio","skill":"listening","part_number":3,"transcript":"M: Have you ever noticed how different local cultures can be, even within the same country?\nW: Yes, definitely. Food, festivals, customs, and even everyday behaviour can change a lot from one region to another. In my opinion, language is the biggest difficulty when people try to understand a local culture. Regional dialects and accents can make communication really confusing.\nM: I see what you mean, but I don''t think language is always the biggest problem. Sometimes values, traditions, and social rules are even harder to understand.\nW: That''s true. I''m also worried that globalisation is changing local traditions. International trends are becoming more popular, and some traditional customs are slowly disappearing.\nM: I agree with that. Globalisation is definitely changing people''s lifestyles. Local traditions are not as strong as they used to be in many places.\nM: What concerns me most is that the younger generation does not seem to care as much about traditional culture. Many young people are more interested in global music, fashion, and online trends than in their own local heritage.\nW: I''m not completely sure about that. Some young people still feel proud of their roots and take part in cultural festivals or family traditions.\nM: Maybe, but I still think visiting places in person is the most effective way to learn about different cultures. When you travel somewhere, talk to local people, try the food, and see the traditions yourself, you understand much more than by only reading about it.\nW: Travelling is helpful, but I think online materials, books, and cultural events can also teach people a lot. **Explanation summary** *The woman says language is the biggest difficulty in understanding local culture. Both speakers agree globalisation is changing local traditions. The man says young people care less about traditional culture and that visiting places in person is the most effective way to learn about cultural differences.*","transcript_status":"source_word_comment","word_comment_ids":["479"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '43c72a9e1dcf2e297f04fcad667c7da9e4f1e5b6fe17ac6827f4b05eba8246d5'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p3-set020-audio', 'Listening Part 3: Urban farming (Version 2) (2026) Audio', 'W: Hey Carlos, have you read the article about urban farming?
M: Urban farming? What exactly is it?
W: Well, it''s about growing food in urban areas, like on rooftops or unused spaces to help address food supply issues in cities.
M: You mean farming in cities? How could that even work? Cities are already overcrowded. There isn''t enough space for housing, let alone farming. Urban farming will take up land that could be used for accommodation.
W: I think it might work. More people from rural areas are moving to cities, and food has become a critical issue. It''s vital that we adapt over time.
M: That''s exactly my point. Where are all these people supposed to live?
W: You don''t have to take urban farming literally. It''s not about large-scale farming right away. Small changes are necessary. Over time, we need to find ways to balance ecological and economic needs.
M: Sure, I support green initiatives, but they need to be practical. How can this approach actually work?
W: Unused spaces that are too small for housing can be converted into farming areas. If done right, this could be both beneficial and visually attractive, like turning them into green spaces or local parks.
M: I still think it could have negative effects, especially on rural areas where traditional farmers might lose their jobs if urban farming takes over.
W: You should think of it as a supplement, not a replacement. For rural areas, producing vegetables closer to where they''re consumed can actually be beneficial. It saves on transportation costs and uses resources more efficiently.
M: But this is mostly about food, right? I don''t think urban farming can solve the problem of scarcity. Cities just can''t realistically support large-scale farming. Rural farming is still a more practical option.
W: That''s true, and I agree. But changes need to happen. Sooner or later, urban farming will become a key trend for the future. **Explanation summary** *The man argues that housing space is more important because cities are overcrowded and urban farming could take land for accommodation. The woman supports urban farming as useful and attractive, says it can save transportation costs and resources, and both speakers discuss food scarcity as a real issue.*', '{"source_key":"listening-p3-set020-audio","skill":"listening","part_number":3,"transcript":"W: Hey Carlos, have you read the article about urban farming?\nM: Urban farming? What exactly is it?\nW: Well, it''s about growing food in urban areas, like on rooftops or unused spaces to help address food supply issues in cities.\nM: You mean farming in cities? How could that even work? Cities are already overcrowded. There isn''t enough space for housing, let alone farming. Urban farming will take up land that could be used for accommodation.\nW: I think it might work. More people from rural areas are moving to cities, and food has become a critical issue. It''s vital that we adapt over time.\nM: That''s exactly my point. Where are all these people supposed to live?\nW: You don''t have to take urban farming literally. It''s not about large-scale farming right away. Small changes are necessary. Over time, we need to find ways to balance ecological and economic needs.\nM: Sure, I support green initiatives, but they need to be practical. How can this approach actually work?\nW: Unused spaces that are too small for housing can be converted into farming areas. If done right, this could be both beneficial and visually attractive, like turning them into green spaces or local parks.\nM: I still think it could have negative effects, especially on rural areas where traditional farmers might lose their jobs if urban farming takes over.\nW: You should think of it as a supplement, not a replacement. For rural areas, producing vegetables closer to where they''re consumed can actually be beneficial. It saves on transportation costs and uses resources more efficiently.\nM: But this is mostly about food, right? I don''t think urban farming can solve the problem of scarcity. Cities just can''t realistically support large-scale farming. Rural farming is still a more practical option.\nW: That''s true, and I agree. But changes need to happen. Sooner or later, urban farming will become a key trend for the future. **Explanation summary** *The man argues that housing space is more important because cities are overcrowded and urban farming could take land for accommodation. The woman supports urban farming as useful and attractive, says it can save transportation costs and resources, and both speakers discuss food scarcity as a real issue.*","transcript_status":"source_word_comment","word_comment_ids":["480"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'd7c07691d91d372b774419d8f7fb0fb0735314b1fc601aa2cf3ed2ececa7920e'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p3-set021-audio', 'Listening Part 3: Actors (Version 3) (2026) Audio', 'M: The festival audience applauded the final performance, but the director told us the actor nearly lost the role at the first audition. That proves how important auditions are; they can determine an entire career in ten minutes.
W: Or it proves how unreliable they are. She became convincing only after working with the screenplay, and strong, engaging writing gave her emotional detail that the audition extract lacked.
M: Still, without a memorable audition she would never have entered rehearsal.
W: I accept that it opens the door, but the script shapes what happens after the door opens.
M: The panel also discussed her move from theatre to film. She had to reduce every gesture because screen acting and stage acting are genuinely different crafts.
W: Absolutely. On stage, breath and movement must reach hundreds of people; on film, the camera can detect tension in a fingertip.
M: That versatility deserves more recognition. Actors are expected to transform physically, learn accents, handle rejection, and remain emotionally available.
W: I agree. Audiences often praise the director and forget the performer who repeats a painful scene twelve times.
M: Good acting should be recognised, not treated as effortless.
W: And praise should include disciplined supporting actors, not only stars. **Explanation summary** *User-provided Part 3 topic version for Actors ( version 3 ). Check the statement-level explanations for the final speaker mapping.*', '{"source_key":"listening-p3-set021-audio","skill":"listening","part_number":3,"transcript":"M: The festival audience applauded the final performance, but the director told us the actor nearly lost the role at the first audition. That proves how important auditions are; they can determine an entire career in ten minutes.\nW: Or it proves how unreliable they are. She became convincing only after working with the screenplay, and strong, engaging writing gave her emotional detail that the audition extract lacked.\nM: Still, without a memorable audition she would never have entered rehearsal.\nW: I accept that it opens the door, but the script shapes what happens after the door opens.\nM: The panel also discussed her move from theatre to film. She had to reduce every gesture because screen acting and stage acting are genuinely different crafts.\nW: Absolutely. On stage, breath and movement must reach hundreds of people; on film, the camera can detect tension in a fingertip.\nM: That versatility deserves more recognition. Actors are expected to transform physically, learn accents, handle rejection, and remain emotionally available.\nW: I agree. Audiences often praise the director and forget the performer who repeats a painful scene twelve times.\nM: Good acting should be recognised, not treated as effortless.\nW: And praise should include disciplined supporting actors, not only stars. **Explanation summary** *User-provided Part 3 topic version for Actors ( version 3 ). Check the statement-level explanations for the final speaker mapping.*","transcript_status":"source_word_comment","word_comment_ids":["481"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '5ad5d5a3db0e20c77273482a7b0497f59d9539413591c1ef1326215f7c7ac9d9'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p3-set022-audio', 'Listening Part 3: Actors (Version 1) (2026) Audio', 'W: The school cast looked terrified before today''s try-outs. Do you really believe an audition is the most important part of an actor''s career?
M: For professional work, yes. It may be unfair, but the audition is where an actor first convinces someone to take a risk on them. Without that opportunity, later talent stays invisible.
W: I watched one student freeze during the monologue and then become excellent when we gave her the full scene. Actors often respond best to strong scripts because context gives them something real to play.
M: A good script helps, though they still need technique.
W: Of course. We should also teach them that theatre acting and screen acting are not interchangeable.
M: Definitely. In the hall, they need a clear voice and larger movement. For the video project, the microphone and close-up allow much smaller choices.
W: One boy kept projecting to the back wall while the camera was centimetres from his face.
M: Learning both styles is demanding, which is why actors deserve more praise and recognition.
W: I agree completely. They are judged publicly while doing emotionally difficult work.
M: Even these students deserve encouragement after facing a panel.
W: Then let us give notes carefully and praise the risks they took. **Explanation summary** *User-provided Part 3 topic version for Actors ( version 1 ). Check the statement-level explanations for the final speaker mapping.*', '{"source_key":"listening-p3-set022-audio","skill":"listening","part_number":3,"transcript":"W: The school cast looked terrified before today''s try-outs. Do you really believe an audition is the most important part of an actor''s career?\nM: For professional work, yes. It may be unfair, but the audition is where an actor first convinces someone to take a risk on them. Without that opportunity, later talent stays invisible.\nW: I watched one student freeze during the monologue and then become excellent when we gave her the full scene. Actors often respond best to strong scripts because context gives them something real to play.\nM: A good script helps, though they still need technique.\nW: Of course. We should also teach them that theatre acting and screen acting are not interchangeable.\nM: Definitely. In the hall, they need a clear voice and larger movement. For the video project, the microphone and close-up allow much smaller choices.\nW: One boy kept projecting to the back wall while the camera was centimetres from his face.\nM: Learning both styles is demanding, which is why actors deserve more praise and recognition.\nW: I agree completely. They are judged publicly while doing emotionally difficult work.\nM: Even these students deserve encouragement after facing a panel.\nW: Then let us give notes carefully and praise the risks they took. **Explanation summary** *User-provided Part 3 topic version for Actors ( version 1 ). Check the statement-level explanations for the final speaker mapping.*","transcript_status":"source_word_comment","word_comment_ids":["482"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '7f932384da21a6586fe11129258db2c823a4255d2868ddc5ef68ab3268984b31'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p3-set023-audio', 'Listening Part 3: Politics (Version 3) (2026) Audio', 'W: The student debate was packed last night. A few years ago we could hardly fill one classroom; now young people line up to discuss housing, climate policy, and voting rights.
M: I noticed the same change in my seminars. Politics has become personal to students because they connect public decisions with their own futures.
W: Live streams have helped. Social media changes politics by allowing a small campus campaign to reach people far beyond the university.
M: It also rewards dramatic slogans. I think people are better informed today mainly because more of them read evidence, use fact-checking services, and compare serious sources.
W: Those habits are important, but social platforms can still reveal issues traditional media ignores.
M: They can reveal them without explaining them.
W: Fair criticism. At least representation is improving. Three of the four debate teams were led by women.
M: And more women are pursuing political careers nationally too. That gives younger students examples they did not have before.
W: It also changes which experiences enter public discussion.
M: Agreed. Greater participation from women is not a temporary trend; it strengthens politics. **Explanation summary** *User-provided Part 3 topic version for Politics ( version 3 ). Check the statement-level explanations for the final speaker mapping.*', '{"source_key":"listening-p3-set023-audio","skill":"listening","part_number":3,"transcript":"W: The student debate was packed last night. A few years ago we could hardly fill one classroom; now young people line up to discuss housing, climate policy, and voting rights.\nM: I noticed the same change in my seminars. Politics has become personal to students because they connect public decisions with their own futures.\nW: Live streams have helped. Social media changes politics by allowing a small campus campaign to reach people far beyond the university.\nM: It also rewards dramatic slogans. I think people are better informed today mainly because more of them read evidence, use fact-checking services, and compare serious sources.\nW: Those habits are important, but social platforms can still reveal issues traditional media ignores.\nM: They can reveal them without explaining them.\nW: Fair criticism. At least representation is improving. Three of the four debate teams were led by women.\nM: And more women are pursuing political careers nationally too. That gives younger students examples they did not have before.\nW: It also changes which experiences enter public discussion.\nM: Agreed. Greater participation from women is not a temporary trend; it strengthens politics. **Explanation summary** *User-provided Part 3 topic version for Politics ( version 3 ). Check the statement-level explanations for the final speaker mapping.*","transcript_status":"source_word_comment","word_comment_ids":["483"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '4687531d5d81322b0892b6f16085fde15021aa32a04116d6fc776bce1b28204a'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p3-set024-audio', 'Listening Part 3: Politics (Version 2) (2026) Audio', 'W: My niece spent the weekend canvassing for a local candidate. At her age I avoided every political conversation, but young people now seem genuinely interested.
M: My son is the same. He asked us to discuss the transport budget over dinner, which has never happened in this family.
W: Much of that interest begins on social media. Candidates respond to voters in short videos, volunteers organise through group chats, and political stories spread before breakfast.
M: Campaigning has always adapted to new media, so I would not say social media changes politics itself. I think people are now better informed because good podcasts, newsletters, and public databases explain issues in greater depth.
W: Provided they choose reliable ones.
M: Yes. Better access does not automatically mean better understanding.
W: Another difference from our youth is the visibility of women in politics. My niece follows several female mayors and says leadership no longer looks like one type of person.
M: That is encouraging. More women are entering politics, and parties are finally treating that as normal rather than exceptional.
W: There is still a long way to go.
M: Of course, but the direction is clear.
W: And young voters are helping push it forward. **Explanation summary** *User-provided Part 3 topic version for Politics ( version 2 ). Check the statement-level explanations for the final speaker mapping.*', '{"source_key":"listening-p3-set024-audio","skill":"listening","part_number":3,"transcript":"W: My niece spent the weekend canvassing for a local candidate. At her age I avoided every political conversation, but young people now seem genuinely interested.\nM: My son is the same. He asked us to discuss the transport budget over dinner, which has never happened in this family.\nW: Much of that interest begins on social media. Candidates respond to voters in short videos, volunteers organise through group chats, and political stories spread before breakfast.\nM: Campaigning has always adapted to new media, so I would not say social media changes politics itself. I think people are now better informed because good podcasts, newsletters, and public databases explain issues in greater depth.\nW: Provided they choose reliable ones.\nM: Yes. Better access does not automatically mean better understanding.\nW: Another difference from our youth is the visibility of women in politics. My niece follows several female mayors and says leadership no longer looks like one type of person.\nM: That is encouraging. More women are entering politics, and parties are finally treating that as normal rather than exceptional.\nW: There is still a long way to go.\nM: Of course, but the direction is clear.\nW: And young voters are helping push it forward. **Explanation summary** *User-provided Part 3 topic version for Politics ( version 2 ). Check the statement-level explanations for the final speaker mapping.*","transcript_status":"source_word_comment","word_comment_ids":["484"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '7bad04c8c9bcff4ca2ebbc81cd40195a928f4e533843f12a20d1c8841e8ea92d'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p3-set025-audio', 'Listening Part 3: Politics (Version 1) (2026) Audio', 'M: The crowd outside the campaign hall was unexpectedly young. Students were interviewing candidates and registering first-time voters.
W: Yes, political interest among young people is much stronger than it was when we were at school.
M: Social media has changed politics enormously. The rally filled up because one volunteer''s video was shared thousands of times, and the candidate answered criticism online before the newspaper even printed it.
W: I do not think that changes politics itself; it mainly changes publicity, and it can flatten complicated policies into slogans.
M: True, though it gives ordinary supporters a way to organise.
W: I am more impressed by how well informed many voters have become. During the public session, people cited budgets, compared earlier promises, and challenged misleading statistics.
M: They had clearly done their homework.
W: Another welcome change is the number of women running for office.
M: Absolutely. More women are pursuing politics, and that broadens both leadership styles and policy priorities.
W: The panel tonight was evenly balanced for the first time.
M: I hope that soon nobody considers that remarkable. **Explanation summary** *User-provided Part 3 topic version for Politics ( version 1 ). Check the statement-level explanations for the final speaker mapping.*', '{"source_key":"listening-p3-set025-audio","skill":"listening","part_number":3,"transcript":"M: The crowd outside the campaign hall was unexpectedly young. Students were interviewing candidates and registering first-time voters.\nW: Yes, political interest among young people is much stronger than it was when we were at school.\nM: Social media has changed politics enormously. The rally filled up because one volunteer''s video was shared thousands of times, and the candidate answered criticism online before the newspaper even printed it.\nW: I do not think that changes politics itself; it mainly changes publicity, and it can flatten complicated policies into slogans.\nM: True, though it gives ordinary supporters a way to organise.\nW: I am more impressed by how well informed many voters have become. During the public session, people cited budgets, compared earlier promises, and challenged misleading statistics.\nM: They had clearly done their homework.\nW: Another welcome change is the number of women running for office.\nM: Absolutely. More women are pursuing politics, and that broadens both leadership styles and policy priorities.\nW: The panel tonight was evenly balanced for the first time.\nM: I hope that soon nobody considers that remarkable. **Explanation summary** *User-provided Part 3 topic version for Politics ( version 1 ). Check the statement-level explanations for the final speaker mapping.*","transcript_status":"source_word_comment","word_comment_ids":["485"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '9200c4d52d9fc5257519b036000383a960f39d7b6b1790e0df97e9277782befb'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p3-set026-audio', 'Listening Part 3: Urban Farming (Version 4) (2026) Audio', 'W: Our building committee wants a greenhouse on the roof, and the architect has brought three designs for tonight''s meeting.
M: Before we admire drawings, remember that the city lacks affordable homes. Housing space is more important than farming space, even if rooftop gardens sound fashionable.
W: This roof cannot legally support apartments, but it can support lightweight growing beds. The best design includes trees, seating, and a small market, so it would make the block far more attractive.
M: I doubt a greenhouse would make the building more attractive for long; poorly maintained beds could look worse than the empty roof.
W: The cooperative would sell herbs to cafés and employ two residents. It could help the local economy as well as reduce food transport.
M: Two jobs are not an economic revolution.
W: No, and the greenhouse will not solve food shortages by itself.
M: On that we agree. A roof cannot feed an entire district.
W: It can still demonstrate one practical use for wasted space.
M: As long as nobody presents it as a substitute for housing or rural agriculture.
W: Then the proposal should describe it as a small local supplement, not a miracle cure. **Explanation summary** *User-provided Part 3 topic version for Urban Farming ( version 4 ). Check the statement-level explanations for the final speaker mapping.*', '{"source_key":"listening-p3-set026-audio","skill":"listening","part_number":3,"transcript":"W: Our building committee wants a greenhouse on the roof, and the architect has brought three designs for tonight''s meeting.\nM: Before we admire drawings, remember that the city lacks affordable homes. Housing space is more important than farming space, even if rooftop gardens sound fashionable.\nW: This roof cannot legally support apartments, but it can support lightweight growing beds. The best design includes trees, seating, and a small market, so it would make the block far more attractive.\nM: I doubt a greenhouse would make the building more attractive for long; poorly maintained beds could look worse than the empty roof.\nW: The cooperative would sell herbs to cafés and employ two residents. It could help the local economy as well as reduce food transport.\nM: Two jobs are not an economic revolution.\nW: No, and the greenhouse will not solve food shortages by itself.\nM: On that we agree. A roof cannot feed an entire district.\nW: It can still demonstrate one practical use for wasted space.\nM: As long as nobody presents it as a substitute for housing or rural agriculture.\nW: Then the proposal should describe it as a small local supplement, not a miracle cure. **Explanation summary** *User-provided Part 3 topic version for Urban Farming ( version 4 ). Check the statement-level explanations for the final speaker mapping.*","transcript_status":"source_word_comment","word_comment_ids":["486"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'f077e2af76648bd7d48cb0911503c5155eb808e2f413da2ac12038a1b3275c45'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p3-set027-audio', 'Listening Part 3: Urban Farming (Version 3) (2026) Audio', 'M: The documentary crew wants to film an urban farm on the abandoned railway yard. From the bridge, the rows of vegetables already make the area look less neglected.
W: It is pleasant, but I still believe housing space matters more. The waiting list for homes is growing, and the yard is one of the few large sites left.
M: Only part of it is suitable for building. The contaminated section can support raised beds, public paths, and trees.
W: In that case, I agree the farm could make the district more attractive. It would replace fences and rubbish with a space people can actually use.
M: It may also help the local economy. The project plans to train residents, supply street markets, and rent stalls to small food businesses.
W: I am not convinced those jobs and stalls would last, and nobody should claim the project can meet the city''s food demand.
M: Certainly not. Urban farming cannot solve shortages by itself.
W: We agree there. It should complement rural producers and supermarkets, not replace them.
M: That distinction would make a good ending for the documentary.
W: Especially if the film also shows the housing debate rather than presenting a perfect green solution. **Explanation summary** *User-provided Part 3 topic version for Urban Farming ( version 3 ). Check the statement-level explanations for the final speaker mapping.*', '{"source_key":"listening-p3-set027-audio","skill":"listening","part_number":3,"transcript":"M: The documentary crew wants to film an urban farm on the abandoned railway yard. From the bridge, the rows of vegetables already make the area look less neglected.\nW: It is pleasant, but I still believe housing space matters more. The waiting list for homes is growing, and the yard is one of the few large sites left.\nM: Only part of it is suitable for building. The contaminated section can support raised beds, public paths, and trees.\nW: In that case, I agree the farm could make the district more attractive. It would replace fences and rubbish with a space people can actually use.\nM: It may also help the local economy. The project plans to train residents, supply street markets, and rent stalls to small food businesses.\nW: I am not convinced those jobs and stalls would last, and nobody should claim the project can meet the city''s food demand.\nM: Certainly not. Urban farming cannot solve shortages by itself.\nW: We agree there. It should complement rural producers and supermarkets, not replace them.\nM: That distinction would make a good ending for the documentary.\nW: Especially if the film also shows the housing debate rather than presenting a perfect green solution. **Explanation summary** *User-provided Part 3 topic version for Urban Farming ( version 3 ). Check the statement-level explanations for the final speaker mapping.*","transcript_status":"source_word_comment","word_comment_ids":["487"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '8bbd24f4cebf7e4f77a9faf5a25e0fb8b4adad2e458c86cd1c125db915449b70'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p3-set028-audio', 'Listening Part 3: Urban Farming (Version 1) (2026) Audio', 'M: After last year''s flood, the multistorey car park has remained half empty. The mayor now wants to turn the top levels into growing spaces.
W: I would rather see the whole structure replaced with housing. People need secure homes more urgently than tomatoes grown above a car park.
M: Demolition would take years, while lightweight beds could be installed within weeks. The proposal also includes shaded walkways and a café overlooking the river.
W: I visited a similar project abroad, and I admit it made an unattractive building feel welcoming. If the public can enter freely, it could improve the area''s appearance.
M: The organisers also plan a weekend market. Local food businesses could buy directly, and residents could earn money from training and sales.
W: I doubt a weekend market would create a meaningful economic benefit, and the numbers should be checked carefully.
M: Of course. It will not solve food shortages by itself.
W: No urban project could. The growing area is too small, and cities still depend on rural farms.
M: Then perhaps it is worth doing for several modest benefits rather than one impossible promise.
W: Possibly, but housing must remain the first priority in any future redevelopment. **Explanation summary** *User-provided Part 3 topic version for Urban Farming ( version 1 ). Check the statement-level explanations for the final speaker mapping.*', '{"source_key":"listening-p3-set028-audio","skill":"listening","part_number":3,"transcript":"M: After last year''s flood, the multistorey car park has remained half empty. The mayor now wants to turn the top levels into growing spaces.\nW: I would rather see the whole structure replaced with housing. People need secure homes more urgently than tomatoes grown above a car park.\nM: Demolition would take years, while lightweight beds could be installed within weeks. The proposal also includes shaded walkways and a café overlooking the river.\nW: I visited a similar project abroad, and I admit it made an unattractive building feel welcoming. If the public can enter freely, it could improve the area''s appearance.\nM: The organisers also plan a weekend market. Local food businesses could buy directly, and residents could earn money from training and sales.\nW: I doubt a weekend market would create a meaningful economic benefit, and the numbers should be checked carefully.\nM: Of course. It will not solve food shortages by itself.\nW: No urban project could. The growing area is too small, and cities still depend on rural farms.\nM: Then perhaps it is worth doing for several modest benefits rather than one impossible promise.\nW: Possibly, but housing must remain the first priority in any future redevelopment. **Explanation summary** *User-provided Part 3 topic version for Urban Farming ( version 1 ). Check the statement-level explanations for the final speaker mapping.*","transcript_status":"source_word_comment","word_comment_ids":["488"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'f422db41384835ddfb1dad29a71370bee3d620e3f52431dc675df6bc76a556d2'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p3-set029-audio', 'Listening Part 3: Environmental Volunteer Program (Version 1) (2026) Audio', 'M: The newspaper headline called the volunteer clean-up "a new beginning for the entire city." I was at the canal that day, and the media definitely exaggerated what one small programme achieved.
W: I helped with the photography, and I agree. The article showed the cleanest section and cropped out the rubbish still floating beyond the bridge.
M: That is why I think littering will always be a problem. Some people leave cups beside an empty bin because they assume somebody else will deal with them.
W: I am less pessimistic. Public habits can improve if facilities and education improve.
M: Perhaps, but good intentions are not enough.
W: The volunteers did useful work regardless of their intentions. Some wanted references, some wanted publicity, and some cared deeply about the environment. Their motivations did not affect the final number of bags collected.
M: They may affect whether the programme survives.
W: Yes, but not the outcome of that particular day.
M: To reduce the problem permanently, punishment is the most effective approach. A serious fine changes behaviour faster than another friendly slogan.
W: Fines can help, but they may simply move littering to places with fewer officers.
M: Then enforcement must be consistent.
W: And education must continue beside it. **Explanation summary** *User-provided Part 3 topic version for Environmental Volunteer Program ( version 1 ). Check the statement-level explanations for the final speaker mapping.*', '{"source_key":"listening-p3-set029-audio","skill":"listening","part_number":3,"transcript":"M: The newspaper headline called the volunteer clean-up \"a new beginning for the entire city.\" I was at the canal that day, and the media definitely exaggerated what one small programme achieved.\nW: I helped with the photography, and I agree. The article showed the cleanest section and cropped out the rubbish still floating beyond the bridge.\nM: That is why I think littering will always be a problem. Some people leave cups beside an empty bin because they assume somebody else will deal with them.\nW: I am less pessimistic. Public habits can improve if facilities and education improve.\nM: Perhaps, but good intentions are not enough.\nW: The volunteers did useful work regardless of their intentions. Some wanted references, some wanted publicity, and some cared deeply about the environment. Their motivations did not affect the final number of bags collected.\nM: They may affect whether the programme survives.\nW: Yes, but not the outcome of that particular day.\nM: To reduce the problem permanently, punishment is the most effective approach. A serious fine changes behaviour faster than another friendly slogan.\nW: Fines can help, but they may simply move littering to places with fewer officers.\nM: Then enforcement must be consistent.\nW: And education must continue beside it. **Explanation summary** *User-provided Part 3 topic version for Environmental Volunteer Program ( version 1 ). Check the statement-level explanations for the final speaker mapping.*","transcript_status":"source_word_comment","word_comment_ids":["489"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '9e3d069e7167b0c7a82f2ca9a0d1d4665f01406a3766c53ecbe30ed76002c601'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p3-set030-audio', 'Listening Part 3: Beauty (Version 2) (2026) Audio', 'W: The advertising team rejected three faces because they did not match the "clean beauty" reference board. They call that look universal, but I think it is a corporate template rather than something people genuinely agree on.
M: That suggests people share surprisingly similar ideas about beauty, especially when brands repeat the same face until it feels normal.
W: But those ideas are temporary. Look at old campaigns. Features once hidden are now highlighted, while yesterday''s fashionable look already feels dated. Beauty standards change over time.
M: I am not convinced standards truly change; advertising may simply rotate one narrow rule into another.
W: During the location shoot, my favourite image was not a model at all. It was an elderly cleaner arranging bright bottles beside a broken window.
M: I saw that photograph. Beauty can appear in unlikely places, especially when nobody is performing for the camera.
W: Exactly. I think traditional ideas of beauty are going to change further as audiences demand age, disability, texture, and ordinary bodies in public images.
M: Brands may follow only because difference now sells.
W: Commercial motives do not cancel the effect. Repeated images can widen what people accept.
M: As long as a new trend does not become another rigid formula.
W: That is why the goal should be variety, not a replacement standard. **Explanation summary** *User-provided Part 3 topic version for Beauty ( version 2 ). Check the statement-level explanations for the final speaker mapping.*', '{"source_key":"listening-p3-set030-audio","skill":"listening","part_number":3,"transcript":"W: The advertising team rejected three faces because they did not match the \"clean beauty\" reference board. They call that look universal, but I think it is a corporate template rather than something people genuinely agree on.\nM: That suggests people share surprisingly similar ideas about beauty, especially when brands repeat the same face until it feels normal.\nW: But those ideas are temporary. Look at old campaigns. Features once hidden are now highlighted, while yesterday''s fashionable look already feels dated. Beauty standards change over time.\nM: I am not convinced standards truly change; advertising may simply rotate one narrow rule into another.\nW: During the location shoot, my favourite image was not a model at all. It was an elderly cleaner arranging bright bottles beside a broken window.\nM: I saw that photograph. Beauty can appear in unlikely places, especially when nobody is performing for the camera.\nW: Exactly. I think traditional ideas of beauty are going to change further as audiences demand age, disability, texture, and ordinary bodies in public images.\nM: Brands may follow only because difference now sells.\nW: Commercial motives do not cancel the effect. Repeated images can widen what people accept.\nM: As long as a new trend does not become another rigid formula.\nW: That is why the goal should be variety, not a replacement standard. **Explanation summary** *User-provided Part 3 topic version for Beauty ( version 2 ). Check the statement-level explanations for the final speaker mapping.*","transcript_status":"source_word_comment","word_comment_ids":["490"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'c1d6b30838f8fa728c9e41bfbc661e758430629ca3e27ba647d16d69d217aa93'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p3-set031-audio', 'Listening Part 3: Beauty (Version 1) (2026) Audio', 'W: This fashion archive is full of surprises. The guide called a tiny waist timeless, but the next display celebrates broad shoulders, and the one after that praises a completely different shape.
M: Those apparent changes are superficial. People within each period still share similar ideas about beauty. Portrait painters, magazines, and clothing makers all repeat the same ideal until society recognises it.
W: For a while. Then the ideal changes. Beauty standards move with economics, technology, and social values, not with some permanent rule.
M: The most beautiful object here might be that repaired work coat. It was never designed to be elegant.
W: I agree. The faded stitching and handwritten name make it more moving than the formal dresses. Beauty can be found in unlikely places because history gives ordinary things meaning.
M: Museums are good at changing how we look.
W: Society is changing too. Traditional ideas about beauty are going to become less powerful as people see more ages, cultures, and identities represented.
M: I doubt traditional ideas will lose much influence; humans will probably continue forming the same shared preferences.
W: Shared preferences are fine. The problem begins when one preference is treated as a rule for everybody. **Explanation summary** *User-provided Part 3 topic version for Beauty ( version 1 ). Check the statement-level explanations for the final speaker mapping.*', '{"source_key":"listening-p3-set031-audio","skill":"listening","part_number":3,"transcript":"W: This fashion archive is full of surprises. The guide called a tiny waist timeless, but the next display celebrates broad shoulders, and the one after that praises a completely different shape.\nM: Those apparent changes are superficial. People within each period still share similar ideas about beauty. Portrait painters, magazines, and clothing makers all repeat the same ideal until society recognises it.\nW: For a while. Then the ideal changes. Beauty standards move with economics, technology, and social values, not with some permanent rule.\nM: The most beautiful object here might be that repaired work coat. It was never designed to be elegant.\nW: I agree. The faded stitching and handwritten name make it more moving than the formal dresses. Beauty can be found in unlikely places because history gives ordinary things meaning.\nM: Museums are good at changing how we look.\nW: Society is changing too. Traditional ideas about beauty are going to become less powerful as people see more ages, cultures, and identities represented.\nM: I doubt traditional ideas will lose much influence; humans will probably continue forming the same shared preferences.\nW: Shared preferences are fine. The problem begins when one preference is treated as a rule for everybody. **Explanation summary** *User-provided Part 3 topic version for Beauty ( version 1 ). Check the statement-level explanations for the final speaker mapping.*","transcript_status":"source_word_comment","word_comment_ids":["491"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'bf949ea1659325b57fc0991658cadc8d3c699c01401b5cc51587758512957a13'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p3-set032-audio', 'Listening Part 3: University And Technology (Version 3) (2026) Audio', 'W: The university wants us to design a degree that students can complete from three countries without moving. That would have been impossible when we studied.
M: It is a strong example of how the internet makes education more accessible. Students with jobs, disabilities, or family responsibilities can join without relocating.
W: And international students can attend guest lectures that were once limited to one campus.
M: Access is valuable, but social interaction remains essential to university life. Students need disagreement, teamwork, informal conversation, and professional networks, not only recorded lectures.
W: Some online groups form real connections, though the course design must deliberately create them.
M: Exactly; they should not be treated as an optional extra.
W: I am more concerned about the proposed list of forty elective modules. A diverse curriculum is not always beneficial. Too many unrelated choices can prevent students from developing depth.
M: Advisers can guide them. I would rather offer variety than force everyone through one path.
W: How do you feel about the dean''s plan to compare our results publicly with other universities?
M: I support it. Competition between universities should be encouraged because it pushes institutions to improve teaching and student services.
W: Unless they start teaching to the ranking.
M: That risk needs regulation, not the removal of competition. **Explanation summary** *User-provided Part 3 topic version for University And Technology ( version 3 ). Check the statement-level explanations for the final speaker mapping.*', '{"source_key":"listening-p3-set032-audio","skill":"listening","part_number":3,"transcript":"W: The university wants us to design a degree that students can complete from three countries without moving. That would have been impossible when we studied.\nM: It is a strong example of how the internet makes education more accessible. Students with jobs, disabilities, or family responsibilities can join without relocating.\nW: And international students can attend guest lectures that were once limited to one campus.\nM: Access is valuable, but social interaction remains essential to university life. Students need disagreement, teamwork, informal conversation, and professional networks, not only recorded lectures.\nW: Some online groups form real connections, though the course design must deliberately create them.\nM: Exactly; they should not be treated as an optional extra.\nW: I am more concerned about the proposed list of forty elective modules. A diverse curriculum is not always beneficial. Too many unrelated choices can prevent students from developing depth.\nM: Advisers can guide them. I would rather offer variety than force everyone through one path.\nW: How do you feel about the dean''s plan to compare our results publicly with other universities?\nM: I support it. Competition between universities should be encouraged because it pushes institutions to improve teaching and student services.\nW: Unless they start teaching to the ranking.\nM: That risk needs regulation, not the removal of competition. **Explanation summary** *User-provided Part 3 topic version for University And Technology ( version 3 ). Check the statement-level explanations for the final speaker mapping.*","transcript_status":"source_word_comment","word_comment_ids":["492"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'ba167018851a6a45e23089d3a01efb0d60928725300727980ba07343716dd416'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p3-set033-audio', 'Listening Part 3: University And Technology (Version 1) (2026) Audio', 'M: These university brochures all promise online lectures, international modules, and flexible study. At least the internet has genuinely made education more accessible.
W: I agree. My cousin can study from her island and keep caring for her father instead of moving to the capital.
M: The brochure treats campus life as a luxury, though.
W: I would call social interaction essential. Students learn to negotiate, cooperate, and form friendships through daily contact. A university experience made entirely of screens would feel incomplete.
M: Online communities can provide some of that, but perhaps not as naturally.
W: Exactly.
M: I dislike the huge curriculum offered here. A diverse curriculum is not always a good thing; students can collect fashionable modules without building a coherent foundation.
W: That depends on academic advising. I am interested in the competition between these universities. Each one has improved laboratories and support because it wants to attract applicants.
M: Competition can encourage wasteful advertising.
W: It can, but it also prevents institutions from assuming students have no alternative. I think competition should be encouraged, with transparent standards.
M: So we agree on access, but not on how much choice and competition education needs.
W: That is probably the most realistic conclusion. **Explanation summary** *User-provided Part 3 topic version for University And Technology ( version 1 ). Check the statement-level explanations for the final speaker mapping.*', '{"source_key":"listening-p3-set033-audio","skill":"listening","part_number":3,"transcript":"M: These university brochures all promise online lectures, international modules, and flexible study. At least the internet has genuinely made education more accessible.\nW: I agree. My cousin can study from her island and keep caring for her father instead of moving to the capital.\nM: The brochure treats campus life as a luxury, though.\nW: I would call social interaction essential. Students learn to negotiate, cooperate, and form friendships through daily contact. A university experience made entirely of screens would feel incomplete.\nM: Online communities can provide some of that, but perhaps not as naturally.\nW: Exactly.\nM: I dislike the huge curriculum offered here. A diverse curriculum is not always a good thing; students can collect fashionable modules without building a coherent foundation.\nW: That depends on academic advising. I am interested in the competition between these universities. Each one has improved laboratories and support because it wants to attract applicants.\nM: Competition can encourage wasteful advertising.\nW: It can, but it also prevents institutions from assuming students have no alternative. I think competition should be encouraged, with transparent standards.\nM: So we agree on access, but not on how much choice and competition education needs.\nW: That is probably the most realistic conclusion. **Explanation summary** *User-provided Part 3 topic version for University And Technology ( version 1 ). Check the statement-level explanations for the final speaker mapping.*","transcript_status":"source_word_comment","word_comment_ids":["493"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'be993aac62e0b29277b5e2264f5cf37fb4214945ef504aa9405f61fd97d14aef'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p3-set034-audio', 'Listening Part 3: The Arts (Version 2) (2026) Audio', 'M: The new private gallery charges so much that ordinary families will never enter. In situations like this, art really is suitable only for a privileged few.
W: That gallery is only one example, so I would not say art itself belongs only to the privileged. Still, public culture should not depend on wealthy collectors. The government ought to invest more in arts centres, festivals, and free exhibitions.
M: You trust government committees more than I do.
W: I trust public access more than exclusive membership.
M: At least we agree that children should experience art early. My school had no music room, and I assumed creativity was something other families did.
W: The same happened to me. Early exposure gives children permission to experiment before embarrassment and exam pressure take over.
M: Do you think access will actually improve?
W: Yes. In the future, art will become more accessible through community studios, digital collections, and tools that let people create without expensive equipment.
M: Technology can distribute images, but it does not guarantee understanding.
W: No, which is why investment in teachers and local spaces still matters.
M: Then perhaps the problem is not whether art is naturally exclusive, but who pays to open the door.
W: Exactly, and society can choose to open it wider. **Explanation summary** *User-provided Part 3 topic version for The Arts ( version 2 ). Check the statement-level explanations for the final speaker mapping.*', '{"source_key":"listening-p3-set034-audio","skill":"listening","part_number":3,"transcript":"M: The new private gallery charges so much that ordinary families will never enter. In situations like this, art really is suitable only for a privileged few.\nW: That gallery is only one example, so I would not say art itself belongs only to the privileged. Still, public culture should not depend on wealthy collectors. The government ought to invest more in arts centres, festivals, and free exhibitions.\nM: You trust government committees more than I do.\nW: I trust public access more than exclusive membership.\nM: At least we agree that children should experience art early. My school had no music room, and I assumed creativity was something other families did.\nW: The same happened to me. Early exposure gives children permission to experiment before embarrassment and exam pressure take over.\nM: Do you think access will actually improve?\nW: Yes. In the future, art will become more accessible through community studios, digital collections, and tools that let people create without expensive equipment.\nM: Technology can distribute images, but it does not guarantee understanding.\nW: No, which is why investment in teachers and local spaces still matters.\nM: Then perhaps the problem is not whether art is naturally exclusive, but who pays to open the door.\nW: Exactly, and society can choose to open it wider. **Explanation summary** *User-provided Part 3 topic version for The Arts ( version 2 ). Check the statement-level explanations for the final speaker mapping.*","transcript_status":"source_word_comment","word_comment_ids":["494"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '75449ac770cd0fa73f1653fbc4059325a417e9d94b635e29c3d9add7bd381264'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p3-set035-audio', 'Listening Part 3: The Arts (Version 1) (2026) Audio', 'W: The community theatre says everyone is welcome, but tickets, transport, and childcare make that promise unrealistic. Art is still mainly suitable for privileged people with spare money and time.
M: I would not call art mainly a privilege; people create songs, stories, and images without entering a theatre. Still, public policy should remove practical barriers. The government should invest more in the arts, especially outside major cities.
W: I would rather rely on local groups than government programmes. Funding buildings is not enough if people feel the building is not for them.
M: That is why children should be exposed to art early. A child who performs, paints, or visits a museum at school is less likely to see culture as somebody else''s world.
W: I agree. My daughter was nervous before her first workshop, and now she writes scenes for her friends.
M: Those early experiences can last for life.
W: But what about adults who missed them?
M: Technology will make art more accessible in the future. Local performances can be streamed, archives can be opened, and inexpensive tools can support new creators.
W: That helps, although live participation still needs affordable spaces.
M: Of course. Digital access should expand the audience, not justify closing theatres.
W: Then schools, local groups, and technology all have roles.
M: Different doors into the same house. **Explanation summary** *User-provided Part 3 topic version for The Arts ( version 1 ). Check the statement-level explanations for the final speaker mapping.*', '{"source_key":"listening-p3-set035-audio","skill":"listening","part_number":3,"transcript":"W: The community theatre says everyone is welcome, but tickets, transport, and childcare make that promise unrealistic. Art is still mainly suitable for privileged people with spare money and time.\nM: I would not call art mainly a privilege; people create songs, stories, and images without entering a theatre. Still, public policy should remove practical barriers. The government should invest more in the arts, especially outside major cities.\nW: I would rather rely on local groups than government programmes. Funding buildings is not enough if people feel the building is not for them.\nM: That is why children should be exposed to art early. A child who performs, paints, or visits a museum at school is less likely to see culture as somebody else''s world.\nW: I agree. My daughter was nervous before her first workshop, and now she writes scenes for her friends.\nM: Those early experiences can last for life.\nW: But what about adults who missed them?\nM: Technology will make art more accessible in the future. Local performances can be streamed, archives can be opened, and inexpensive tools can support new creators.\nW: That helps, although live participation still needs affordable spaces.\nM: Of course. Digital access should expand the audience, not justify closing theatres.\nW: Then schools, local groups, and technology all have roles.\nM: Different doors into the same house. **Explanation summary** *User-provided Part 3 topic version for The Arts ( version 1 ). Check the statement-level explanations for the final speaker mapping.*","transcript_status":"source_word_comment","word_comment_ids":["495"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '413272d5964ff060d4e233368912c7f13b396fb4f07f3cb6e8a12b7419a2438e'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p3-set036-audio', 'Listening Part 3: Music And Singer (Version 3) (2026) Audio', 'W: The documentary follows a singer who returned to her old school and paid for instruments. Watching the students, I can understand why singers can be good role models for young people.
M: That was generous, but one carefully filmed act does not make singers reliable role models; documentaries select the most flattering parts of a life.
W: True, but responsible artists can still demonstrate discipline and generosity.
M: Our editor hates her music.
W: Taste in music is highly personal. I love her voice, you prefer jazz, and the editor listens to electronic noise.
M: Exactly. Musical taste is highly personal because a song carries memories that another listener does not share.
W: Does that weaken the idea that music crosses cultures?
M: Not for me. Music is a universal language because rhythm, tension, and release can communicate before anyone translates the words.
W: I think cultural knowledge still matters, so I would not go that far.
M: Fair enough. But our film proves that music can manipulate feelings. The same classroom scene feels hopeful with piano and uncomfortable with low electronic sounds.
W: Absolutely. We tested both versions, and viewers described completely different emotions.
M: That power is why filmmakers choose soundtracks so carefully.
W: And why audiences should notice when music is guiding their judgement. **Explanation summary** *User-provided Part 3 topic version for Music And Singer ( version 3 ). Check the statement-level explanations for the final speaker mapping.*', '{"source_key":"listening-p3-set036-audio","skill":"listening","part_number":3,"transcript":"W: The documentary follows a singer who returned to her old school and paid for instruments. Watching the students, I can understand why singers can be good role models for young people.\nM: That was generous, but one carefully filmed act does not make singers reliable role models; documentaries select the most flattering parts of a life.\nW: True, but responsible artists can still demonstrate discipline and generosity.\nM: Our editor hates her music.\nW: Taste in music is highly personal. I love her voice, you prefer jazz, and the editor listens to electronic noise.\nM: Exactly. Musical taste is highly personal because a song carries memories that another listener does not share.\nW: Does that weaken the idea that music crosses cultures?\nM: Not for me. Music is a universal language because rhythm, tension, and release can communicate before anyone translates the words.\nW: I think cultural knowledge still matters, so I would not go that far.\nM: Fair enough. But our film proves that music can manipulate feelings. The same classroom scene feels hopeful with piano and uncomfortable with low electronic sounds.\nW: Absolutely. We tested both versions, and viewers described completely different emotions.\nM: That power is why filmmakers choose soundtracks so carefully.\nW: And why audiences should notice when music is guiding their judgement. **Explanation summary** *User-provided Part 3 topic version for Music And Singer ( version 3 ). Check the statement-level explanations for the final speaker mapping.*","transcript_status":"source_word_comment","word_comment_ids":["496"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'eb58752b121fb9f22b6f25741a1ddbfba99157cb49840a5e680cd8ccd4b3d389'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p3-set037-audio', 'Listening Part 3: Music And Singer (Version 2) (2026) Audio', 'W: You have changed the radio station six times since we left the city.
M: Because musical taste is highly personal. Your cheerful pop songs make me tired, while this old blues recording keeps me awake.
W: I was about to say the opposite, but I do not think taste is purely personal; families, age groups, and cultures shape what we learn to enjoy. Does that mean music cannot connect people?
M: No. I still think music is a universal language. At the wedding in Morocco, I understood none of the lyrics, yet the rhythm told everyone when to clap and dance.
W: Maybe, but shared movement does not mean shared meaning.
M: Meaning can differ while emotion still travels.
W: How do you feel about singers as role models? My niece copied a singer''s charity challenge and raised money for an animal shelter.
M: That is a good outcome, but I would not automatically treat celebrities as examples for children.
W: Neither would I, though some use their influence responsibly.
M: The music makes an ordinary car sound like an adventure.
W: Yes, and the sad song in that radio appeal makes listeners feel guilty. Music can manipulate emotions very effectively.
M: We definitely agree there.
W: Fine. Keep the blues, but only until the next service station. **Explanation summary** *User-provided Part 3 topic version for Music And Singer ( version 2 ). Check the statement-level explanations for the final speaker mapping.*', '{"source_key":"listening-p3-set037-audio","skill":"listening","part_number":3,"transcript":"W: You have changed the radio station six times since we left the city.\nM: Because musical taste is highly personal. Your cheerful pop songs make me tired, while this old blues recording keeps me awake.\nW: I was about to say the opposite, but I do not think taste is purely personal; families, age groups, and cultures shape what we learn to enjoy. Does that mean music cannot connect people?\nM: No. I still think music is a universal language. At the wedding in Morocco, I understood none of the lyrics, yet the rhythm told everyone when to clap and dance.\nW: Maybe, but shared movement does not mean shared meaning.\nM: Meaning can differ while emotion still travels.\nW: How do you feel about singers as role models? My niece copied a singer''s charity challenge and raised money for an animal shelter.\nM: That is a good outcome, but I would not automatically treat celebrities as examples for children.\nW: Neither would I, though some use their influence responsibly.\nM: The music makes an ordinary car sound like an adventure.\nW: Yes, and the sad song in that radio appeal makes listeners feel guilty. Music can manipulate emotions very effectively.\nM: We definitely agree there.\nW: Fine. Keep the blues, but only until the next service station. **Explanation summary** *User-provided Part 3 topic version for Music And Singer ( version 2 ). Check the statement-level explanations for the final speaker mapping.*","transcript_status":"source_word_comment","word_comment_ids":["497"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '789e3d7164a4939a6a2380afcc12332fbda9617fbbd7d7f791a211cb338934da'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p3-set038-audio', 'Listening Part 3: Music And Singer (Version 1) (2026) Audio', 'M: The charity concert organiser wants a famous singer to visit the children''s ward. I think singers can be excellent role models when they show young fans that success can include generosity.
W: Possibly, although the children may admire the fame more than the generosity.
M: That depends on how the visit is presented.
W: My concern is the playlist. You chose rock, but musical taste is highly personal. Some children will want dance music, others traditional songs, and some may prefer silence.
M: We can invite requests.
W: Good. Music can still connect them even when they do not share a language. I see it as a universal language because melody communicates comfort without explanation.
M: I am not sure it is completely universal; cultural associations can change the message.
W: They can, but the basic human response remains.
M: The hospital psychologist also warned us not to use overly sad songs.
W: That makes sense. Music can manipulate people''s feelings, especially when they are already vulnerable.
M: Yes. An uplifting song can create courage, while the wrong one can deepen fear.
W: So we should use that power carefully rather than pretending the concert is emotionally neutral. **Explanation summary** *User-provided Part 3 topic version for Music And Singer ( version 1 ). Check the statement-level explanations for the final speaker mapping.*', '{"source_key":"listening-p3-set038-audio","skill":"listening","part_number":3,"transcript":"M: The charity concert organiser wants a famous singer to visit the children''s ward. I think singers can be excellent role models when they show young fans that success can include generosity.\nW: Possibly, although the children may admire the fame more than the generosity.\nM: That depends on how the visit is presented.\nW: My concern is the playlist. You chose rock, but musical taste is highly personal. Some children will want dance music, others traditional songs, and some may prefer silence.\nM: We can invite requests.\nW: Good. Music can still connect them even when they do not share a language. I see it as a universal language because melody communicates comfort without explanation.\nM: I am not sure it is completely universal; cultural associations can change the message.\nW: They can, but the basic human response remains.\nM: The hospital psychologist also warned us not to use overly sad songs.\nW: That makes sense. Music can manipulate people''s feelings, especially when they are already vulnerable.\nM: Yes. An uplifting song can create courage, while the wrong one can deepen fear.\nW: So we should use that power carefully rather than pretending the concert is emotionally neutral. **Explanation summary** *User-provided Part 3 topic version for Music And Singer ( version 1 ). Check the statement-level explanations for the final speaker mapping.*","transcript_status":"source_word_comment","word_comment_ids":["498"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '8f7205f097897b9138b44934067ab3917abe9bed2e6ed4c729b89d6137e81967'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p3-set039-audio', 'Listening Part 3: The Local Central ( version 1 ) Audio', 'M: The local centre has only one exhibition room, so repeating the usual farming tools and old photographs would waste the opportunity. Exhibitions should be different and diverse-oral histories one month, contemporary craft the next, then work from recent migrants.
W: Variety is useful, but I am more worried about what those exhibitions would reveal. Traditional customs are gradually losing their significance. My nieces know the festival costumes but not why they are worn.
M: Some customs change rather than disappear.
W: The harvest festival may disappear in the near future. Attendance has fallen for five years, and the youngest volunteers are already in their forties.
M: That sounds serious, but a centre could help renew interest.
W: Only if young people are involved before adulthood.
M: Schools are important in shaping future generations. Teachers can connect local history with music, food, design, and family stories.
W: I completely agree. A single school project can send children home inviting grandparents to share stories that nobody has heard for years.
M: Then the centre should partner with schools rather than wait for students to visit independently.
W: And give them space to reinterpret tradition, not just memorise it. **Explanation summary** *User-provided Part 3 topic version for The Local Central ( version 1 ). Check the statement-level explanations for the final speaker mapping.*', '{"source_key":"listening-p3-set039-audio","skill":"listening","part_number":3,"transcript":"M: The local centre has only one exhibition room, so repeating the usual farming tools and old photographs would waste the opportunity. Exhibitions should be different and diverse-oral histories one month, contemporary craft the next, then work from recent migrants.\nW: Variety is useful, but I am more worried about what those exhibitions would reveal. Traditional customs are gradually losing their significance. My nieces know the festival costumes but not why they are worn.\nM: Some customs change rather than disappear.\nW: The harvest festival may disappear in the near future. Attendance has fallen for five years, and the youngest volunteers are already in their forties.\nM: That sounds serious, but a centre could help renew interest.\nW: Only if young people are involved before adulthood.\nM: Schools are important in shaping future generations. Teachers can connect local history with music, food, design, and family stories.\nW: I completely agree. A single school project can send children home inviting grandparents to share stories that nobody has heard for years.\nM: Then the centre should partner with schools rather than wait for students to visit independently.\nW: And give them space to reinterpret tradition, not just memorise it. **Explanation summary** *User-provided Part 3 topic version for The Local Central ( version 1 ). Check the statement-level explanations for the final speaker mapping.*","transcript_status":"source_word_comment","word_comment_ids":["499"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'edd3104ac174207228a8848b35eb832a9ac7189ea0a517e2868b3aa1705a3725'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p3-set040-audio', 'Listening Part 3: The Local Central ( version 2 ) ( 2026 ) Audio', 'W: The heritage fair committee has collected dozens of objects, but right now every table looks the same.
M: Then the exhibitions need to be different and diverse. One area could use sound recordings, another could recreate a shop, and another could let visitors handle replicas instead of reading labels.
W: I am less concerned about variety than meaning. Traditional customs are gradually losing significance because people encounter them as static objects rather than living practices.
M: I agree. Even I recognised the wedding drum but could not explain the ceremony it belonged to.
W: The winter lantern festival worries me most. With fewer organisers and rising costs, I think it will disappear in the near future.
M: I hope not. A smaller festival might survive in a new form.
W: Perhaps, but waiting for volunteers will not be enough. Schools are important in shaping future generations, and they should teach children how these events connect to local identity.
M: I do not think schools should carry that role. Families and community groups, rather than classrooms, should shape children''s connection to tradition.
W: Certainly. I am saying schools should take the lead because they can reach every child.
M: Then the centre should invite young visitors directly instead of relying on classrooms to do the work.', '{"source_key":"listening-p3-set040-audio","skill":"listening","part_number":3,"transcript":"W: The heritage fair committee has collected dozens of objects, but right now every table looks the same.\nM: Then the exhibitions need to be different and diverse. One area could use sound recordings, another could recreate a shop, and another could let visitors handle replicas instead of reading labels.\nW: I am less concerned about variety than meaning. Traditional customs are gradually losing significance because people encounter them as static objects rather than living practices.\nM: I agree. Even I recognised the wedding drum but could not explain the ceremony it belonged to.\nW: The winter lantern festival worries me most. With fewer organisers and rising costs, I think it will disappear in the near future.\nM: I hope not. A smaller festival might survive in a new form.\nW: Perhaps, but waiting for volunteers will not be enough. Schools are important in shaping future generations, and they should teach children how these events connect to local identity.\nM: I do not think schools should carry that role. Families and community groups, rather than classrooms, should shape children''s connection to tradition.\nW: Certainly. I am saying schools should take the lead because they can reach every child.\nM: Then the centre should invite young visitors directly instead of relying on classrooms to do the work.","transcript_status":"source_word_comment","word_comment_ids":["500"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '3f5b6813875abf779b00d87c24da101cee81ddee6bd28335e94f4f4541c9e377'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p3-set041-audio', 'Listening Part 3: Local Cultural Differences - Version 2 (2026) Audio', 'M: Have you ever noticed how different local cultures can be, and how easily people end up misunderstanding local customs and traditions?
W: Yes, absolutely. People misinterpret regional traditions all the time, which causes a lot of confusion.
M: True. But don''t you think the media sometimes exaggerate the extent of cultural differences? Most places share similar core values anyway.
W: I completely agree with you on that. They always blow things out of proportion for drama.
M: And it''s not just a social issue. Look at the corporate world - international businesses frequently struggle with cultural differences during global expansion.
M: Anyway, with all these changes happening, do you think local heritage will completely disappear?
W: Not really. I think traditional customs and local practices are more likely to adapt and survive through modern technology.', '{"source_key":"listening-p3-set041-audio","skill":"listening","part_number":3,"transcript":"M: Have you ever noticed how different local cultures can be, and how easily people end up misunderstanding local customs and traditions?\nW: Yes, absolutely. People misinterpret regional traditions all the time, which causes a lot of confusion.\nM: True. But don''t you think the media sometimes exaggerate the extent of cultural differences? Most places share similar core values anyway.\nW: I completely agree with you on that. They always blow things out of proportion for drama.\nM: And it''s not just a social issue. Look at the corporate world - international businesses frequently struggle with cultural differences during global expansion.\nM: Anyway, with all these changes happening, do you think local heritage will completely disappear?\nW: Not really. I think traditional customs and local practices are more likely to adapt and survive through modern technology.","transcript_status":"source_word_comment","word_comment_ids":["501"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'f612c15741ee036f69e8458016c61b10ce7c0b51284f5a5e612b21908b1c47d4'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p3-set042-audio', 'Listening Part 3: Homeschooling (2026) Audio', 'W: I understand why home education appeals to some parents. In a large class, even a good teacher has to move at a pace that suits most pupils. At home, a child can spend longer on difficult subjects and move faster through material they already understand.
M: That may improve academic progress, but I worry about what happens beyond lessons. School teaches children to cooperate, manage disagreements, and build relationships with people from different backgrounds. A weekly sports club may help, but it is not the same as spending every day with classmates.
W: Perhaps, although homeschooled children are not automatically isolated. They can join music groups, community projects, and online classes. A flexible timetable can also support children with health conditions, families who travel, or young people training seriously in sport.
M: Flexibility is useful, but parents need time, patience, and enough subject knowledge. Good intentions do not always produce effective teaching.
W: I agree. I would not present homeschooling as a solution for every household.
M: Nor would I reject it completely. Its success depends on the child''s needs, the support available, and the of the education.', '{"source_key":"listening-p3-set042-audio","skill":"listening","part_number":3,"transcript":"W: I understand why home education appeals to some parents. In a large class, even a good teacher has to move at a pace that suits most pupils. At home, a child can spend longer on difficult subjects and move faster through material they already understand.\nM: That may improve academic progress, but I worry about what happens beyond lessons. School teaches children to cooperate, manage disagreements, and build relationships with people from different backgrounds. A weekly sports club may help, but it is not the same as spending every day with classmates.\nW: Perhaps, although homeschooled children are not automatically isolated. They can join music groups, community projects, and online classes. A flexible timetable can also support children with health conditions, families who travel, or young people training seriously in sport.\nM: Flexibility is useful, but parents need time, patience, and enough subject knowledge. Good intentions do not always produce effective teaching.\nW: I agree. I would not present homeschooling as a solution for every household.\nM: Nor would I reject it completely. Its success depends on the child''s needs, the support available, and the of the education.","transcript_status":"source_word_comment","word_comment_ids":["502"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '8d008ca37ad28469f3b1ae181053c208e5f33a1bea721edb4f77bc543d08db37'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p3-set043-audio', 'Listening Part 3: Work Business / Business and Cultural Audio', 'W: Many people assume that a new business needs a large amount of money to succeed. However, a friend of mine started a small design company in her spare room. She used borrowed computers and had very little start-up capital. By concentrating on one service and listening carefully to customers, she managed to open two branches within two years.
M: That is an impressive achievement, but I would be cautious about expanding so Without enough money in reserve, a delayed payment or an unexpected bill could prevent a company from paying its employees. In my view, a business should establish some financial security before opening another branch.
W: That is a reasonable point. Companies also need to consider cultural differences when entering a foreign market. Communication styles vary widely. A direct comment may appear honest and efficient in one country but rude in another.
M: I completely agree. Understanding local customs helps businesses gain trust and avoid unnecessary misunderstandings. Companies should listen to local employees rather than depending on broad stereotypes.
W: Workplace culture is important inside the company too. A less formal atmosphere can make junior employees feel comfortable enough to raise concerns before minor issues develop into serious problems.
M: Possibly, although employees still need clear responsibilities as the company grows.
W: Certainly. Open communication and a clear structure can exist together.', '{"source_key":"listening-p3-set043-audio","skill":"listening","part_number":3,"transcript":"W: Many people assume that a new business needs a large amount of money to succeed. However, a friend of mine started a small design company in her spare room. She used borrowed computers and had very little start-up capital. By concentrating on one service and listening carefully to customers, she managed to open two branches within two years.\nM: That is an impressive achievement, but I would be cautious about expanding so Without enough money in reserve, a delayed payment or an unexpected bill could prevent a company from paying its employees. In my view, a business should establish some financial security before opening another branch.\nW: That is a reasonable point. Companies also need to consider cultural differences when entering a foreign market. Communication styles vary widely. A direct comment may appear honest and efficient in one country but rude in another.\nM: I completely agree. Understanding local customs helps businesses gain trust and avoid unnecessary misunderstandings. Companies should listen to local employees rather than depending on broad stereotypes.\nW: Workplace culture is important inside the company too. A less formal atmosphere can make junior employees feel comfortable enough to raise concerns before minor issues develop into serious problems.\nM: Possibly, although employees still need clear responsibilities as the company grows.\nW: Certainly. Open communication and a clear structure can exist together.","transcript_status":"source_word_comment","word_comment_ids":["503"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '90753b896f3f0e18776b15dc87ab77ae9160c3f151964b7f97c77cf8cd774af7'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p3-set044-audio', 'Listening Part 3: Homeschooling – Version 2 (2026) Audio', 'W: One advantage of homeschooling is that learning does not have to be limited to a classroom. Parents can use museums, local events, or practical activities as part of a child''s education. For some children, connecting lessons with real situations can make difficult ideas easier to understand.
M: That can be valuable, although I think parents sometimes underestimate how demanding home education can become. Planning lessons is only one part of it. They also have to check progress, find appropriate materials, and recognise when a child needs help that they themselves cannot provide.
W: That''s true. On the other hand, studying at home can be particularly helpful for children who find the normal school environment difficult. A setting and fewer interruptions may allow them to work with greater confidence, especially if they need more time to process information.
M: My other concern is that children need experience dealing with people outside their immediate family. They will eventually have to work with others, accept different opinions, and cope with situations they cannot completely control.
W: Certainly, although school is not the only place where those skills can develop. Homeschooling families can arrange regular activities with other children, but parents do need to make a deliberate effort to create those opportunities.
M: Exactly. So I think the important is not simply whether homeschooling is good or bad. Families have to consider what the individual child requires and whether they have the resources to meet those needs.
W: Yes. What works extremely well for one child could be completely unsuitable for another.', '{"source_key":"listening-p3-set044-audio","skill":"listening","part_number":3,"transcript":"W: One advantage of homeschooling is that learning does not have to be limited to a classroom. Parents can use museums, local events, or practical activities as part of a child''s education. For some children, connecting lessons with real situations can make difficult ideas easier to understand.\nM: That can be valuable, although I think parents sometimes underestimate how demanding home education can become. Planning lessons is only one part of it. They also have to check progress, find appropriate materials, and recognise when a child needs help that they themselves cannot provide.\nW: That''s true. On the other hand, studying at home can be particularly helpful for children who find the normal school environment difficult. A setting and fewer interruptions may allow them to work with greater confidence, especially if they need more time to process information.\nM: My other concern is that children need experience dealing with people outside their immediate family. They will eventually have to work with others, accept different opinions, and cope with situations they cannot completely control.\nW: Certainly, although school is not the only place where those skills can develop. Homeschooling families can arrange regular activities with other children, but parents do need to make a deliberate effort to create those opportunities.\nM: Exactly. So I think the important is not simply whether homeschooling is good or bad. Families have to consider what the individual child requires and whether they have the resources to meet those needs.\nW: Yes. What works extremely well for one child could be completely unsuitable for another.","transcript_status":"source_word_comment","word_comment_ids":["504"],"speaker_labels":["Man","Woman"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '22f20f690c9c81376652c3c3b63ee3b2ae72c166885d6d8d74d118cbf8dfad69'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set001-audio', 'Listening Part 4: A newly released novel (2026) Audio', 'Good evening. Tonight I''m reviewing James Parker''s latest novel, Shadow in the Night. Readers who know Parker from gentle romances such as Whispers of the Heart may be surprised. The new book leaves those love stories behind and moves into suspense, secrets, and psychological tension. In other words, it represents a clear departure from his earlier work rather than simply being another soft romantic novel. The change is ambitious, and several scenes are genuinely gripping, although not every critic believes the mystery is handled equally well. Some fans want Parker to continue writing thrillers, while others would prefer him to return immediately to romance. I would not recommend either extreme. Before beginning his next book, he should study the reviewers'' comments carefully and decide which elements worked and which did not. Their advice could help him combine emotional depth with a stronger, more controlled plot. Whatever direction he chooses, this novel proves that he is willing to experiment rather than repeat a familiar formula.', '{"source_key":"listening-p4-set001-audio","skill":"listening","part_number":4,"transcript":"Good evening. Tonight I''m reviewing James Parker''s latest novel, Shadow in the Night. Readers who know Parker from gentle romances such as Whispers of the Heart may be surprised. The new book leaves those love stories behind and moves into suspense, secrets, and psychological tension. In other words, it represents a clear departure from his earlier work rather than simply being another soft romantic novel. The change is ambitious, and several scenes are genuinely gripping, although not every critic believes the mystery is handled equally well. Some fans want Parker to continue writing thrillers, while others would prefer him to return immediately to romance. I would not recommend either extreme. Before beginning his next book, he should study the reviewers'' comments carefully and decide which elements worked and which did not. Their advice could help him combine emotional depth with a stronger, more controlled plot. Whatever direction he chooses, this novel proves that he is willing to experiment rather than repeat a familiar formula.","transcript_status":"source_word_comment","word_comment_ids":["505"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '3e31ce4646e8f23cdc301f401a1c291285e3ebbf2187297d2c44b9538c2ae20f'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set002-audio', 'Listening Part 4: Professionalism at work (2026) Audio', 'Good morning. When people hear the word professionalism, they often think first about formal clothes, impressive language, or creating a polished image. Those things may influence how others see us, but they are not the centre of professional behaviour. In my view, the foundation is maintaining a positive attitude: being approachable, open-minded, dependable, and willing to help when colleagues face difficulties. Such an attitude may create a better working environment and make a good impression, but those are results rather than the main principle itself. We should also remember that professionalism is not a fixed concept. Forty years ago, it was commonly associated with strict rules, hierarchy, and appearance. Today, workplaces expect adaptability, cultural awareness, digital confidence, and the ability to cooperate with people from different backgrounds. As technology and working patterns continue to develop, our understanding of professionalism is changing too. It would therefore be a mistake to assume that the definition is exactly the same as it was in the past or that it will never change again.', '{"source_key":"listening-p4-set002-audio","skill":"listening","part_number":4,"transcript":"Good morning. When people hear the word professionalism, they often think first about formal clothes, impressive language, or creating a polished image. Those things may influence how others see us, but they are not the centre of professional behaviour. In my view, the foundation is maintaining a positive attitude: being approachable, open-minded, dependable, and willing to help when colleagues face difficulties. Such an attitude may create a better working environment and make a good impression, but those are results rather than the main principle itself. We should also remember that professionalism is not a fixed concept. Forty years ago, it was commonly associated with strict rules, hierarchy, and appearance. Today, workplaces expect adaptability, cultural awareness, digital confidence, and the ability to cooperate with people from different backgrounds. As technology and working patterns continue to develop, our understanding of professionalism is changing too. It would therefore be a mistake to assume that the definition is exactly the same as it was in the past or that it will never change again.","transcript_status":"source_word_comment","word_comment_ids":["506"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '14b7fbff0a869a2424a80cd7cf6b2dcb870b86ba0d3cfa73d98aea791d474fcc'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set003-audio', 'Listening Part 4: Writer''s block (2026) Audio', 'When I was writing my latest novel, I tried almost every piece of advice people give to writers. Some friends suggested writing for fifteen or twenty minutes every single day, while others said I simply needed a perfectly room. Both ideas can help, but neither suited me consistently. What made the biggest difference was creating dedicated periods for writing and protecting those periods from meetings, messages, and household tasks. I did not write at exactly the same hour every day; instead, I chose longer blocks that matched my energy and working style. The most difficult stage came when I experienced serious writer''s block. I kept telling myself that a professional writer should solve the problem alone, so I refused to seek advice from others. Looking back, that is what I regret most. I did not ignore an editor''s feedback, and the problem was not that I lacked a plan. I simply waited too long before speaking to fellow writers and mentors, whose outside perspective might have helped me move forward much sooner.', '{"source_key":"listening-p4-set003-audio","skill":"listening","part_number":4,"transcript":"When I was writing my latest novel, I tried almost every piece of advice people give to writers. Some friends suggested writing for fifteen or twenty minutes every single day, while others said I simply needed a perfectly room. Both ideas can help, but neither suited me consistently. What made the biggest difference was creating dedicated periods for writing and protecting those periods from meetings, messages, and household tasks. I did not write at exactly the same hour every day; instead, I chose longer blocks that matched my energy and working style. The most difficult stage came when I experienced serious writer''s block. I kept telling myself that a professional writer should solve the problem alone, so I refused to seek advice from others. Looking back, that is what I regret most. I did not ignore an editor''s feedback, and the problem was not that I lacked a plan. I simply waited too long before speaking to fellow writers and mentors, whose outside perspective might have helped me move forward much sooner.","transcript_status":"source_word_comment","word_comment_ids":["507"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '66957c5e44bdda026688a45bdf148711a4f83ece94a2f8176e20d6a7132ae2ac'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set004-audio', 'Listening Part 4: Work from home (2026) Audio', 'Before I began working from home, I imagined that it would be completely peaceful. I thought the absence of colleagues chatting nearby would mean there were no distractions at all. In reality, the interruptions simply changed: laundry, deliveries, dishes, and family members can be just as distracting as an office conversation. I still enjoy controlling my schedule and avoiding the daily commute, but overall the experience has not been as good as I expected. The loneliness is more noticeable than I anticipated, and although video calls are useful, I would never say they are better than face-to-face discussion. People often ask whether they need a large, expensive home office. They do not; a well-organised corner can be enough. What matters more is self-motivation, clear boundaries, and the type of person you are. Some workers become highly productive at home, while others struggle without routine and social contact. So the success of remote work depends largely on an individual''s situation and personality, not on one universal rule.', '{"source_key":"listening-p4-set004-audio","skill":"listening","part_number":4,"transcript":"Before I began working from home, I imagined that it would be completely peaceful. I thought the absence of colleagues chatting nearby would mean there were no distractions at all. In reality, the interruptions simply changed: laundry, deliveries, dishes, and family members can be just as distracting as an office conversation. I still enjoy controlling my schedule and avoiding the daily commute, but overall the experience has not been as good as I expected. The loneliness is more noticeable than I anticipated, and although video calls are useful, I would never say they are better than face-to-face discussion. People often ask whether they need a large, expensive home office. They do not; a well-organised corner can be enough. What matters more is self-motivation, clear boundaries, and the type of person you are. Some workers become highly productive at home, while others struggle without routine and social contact. So the success of remote work depends largely on an individual''s situation and personality, not on one universal rule.","transcript_status":"source_word_comment","word_comment_ids":["508"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'c879560f26ae2b66e75833a9aded1a199025417f3af620695e439f6a109ea3b8'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set005-audio', 'Listening Part 4: The importance of sleep (2026) Audio', 'Sleep advice appears everywhere now, from television programmes to social media posts. Some reports suggest that everyone needs exactly the same number of hours, while others warn that modern sleep has collapsed completely. In my opinion, the media often overemphasise the subject, turning small research findings into alarming headlines. That does not mean sleep is unimportant, but the public conversation can create unnecessary anxiety. For practical improvement, experts repeatedly return to one basic point: blocking out noise and light is the key to sleeping well. A dark, room helps the brain reduce stimulation and makes it easier to enter deeper stages of sleep. A comfortable bed may help, and getting enough rest obviously matters, but neither statement is as specific as the environmental advice. Young people are sometimes criticised for using phones late at night, yet that is not the main public attitude I am discussing. The larger problem is that sleep has become so heavily discussed that people may start worrying about every imperfect night instead of developing calm, consistent habits.', '{"source_key":"listening-p4-set005-audio","skill":"listening","part_number":4,"transcript":"Sleep advice appears everywhere now, from television programmes to social media posts. Some reports suggest that everyone needs exactly the same number of hours, while others warn that modern sleep has collapsed completely. In my opinion, the media often overemphasise the subject, turning small research findings into alarming headlines. That does not mean sleep is unimportant, but the public conversation can create unnecessary anxiety. For practical improvement, experts repeatedly return to one basic point: blocking out noise and light is the key to sleeping well. A dark, room helps the brain reduce stimulation and makes it easier to enter deeper stages of sleep. A comfortable bed may help, and getting enough rest obviously matters, but neither statement is as specific as the environmental advice. Young people are sometimes criticised for using phones late at night, yet that is not the main public attitude I am discussing. The larger problem is that sleep has become so heavily discussed that people may start worrying about every imperfect night instead of developing calm, consistent habits.","transcript_status":"source_word_comment","word_comment_ids":["509"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '5012ef70668b4f9b457ead7394620ed15f6c500b4fba51fae018bb8d4b241802'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set006-audio', 'Listening Part 4: Television series (2026) Audio', 'When Mystery City first appeared on television, it did not need weeks to build an audience. The opening episode caught viewers'' attention from the start with a missing-person case, an unexpected confession, and a final scene that immediately encouraged discussion online. The programme was not overlooked by critics, and there is no evidence that early investment was the central issue. In fact, reviews and social-media reactions helped turn it into one of the network''s most talked-about releases. Its value goes beyond entertainment. The channel had previously struggled to attract younger viewers and people who normally used only streaming services. Because of the series, many of those people created accounts, explored other programmes, and became new subscribers. That means the show can help the network reach new customers. A further season may eventually be produced, but that is still speculation rather than the main potential identified by the speaker. Nor is the series chiefly important because it offers young filmmakers a new style to copy. Its strongest commercial effect is the way it expands the network''s audience.', '{"source_key":"listening-p4-set006-audio","skill":"listening","part_number":4,"transcript":"When Mystery City first appeared on television, it did not need weeks to build an audience. The opening episode caught viewers'' attention from the start with a missing-person case, an unexpected confession, and a final scene that immediately encouraged discussion online. The programme was not overlooked by critics, and there is no evidence that early investment was the central issue. In fact, reviews and social-media reactions helped turn it into one of the network''s most talked-about releases. Its value goes beyond entertainment. The channel had previously struggled to attract younger viewers and people who normally used only streaming services. Because of the series, many of those people created accounts, explored other programmes, and became new subscribers. That means the show can help the network reach new customers. A further season may eventually be produced, but that is still speculation rather than the main potential identified by the speaker. Nor is the series chiefly important because it offers young filmmakers a new style to copy. Its strongest commercial effect is the way it expands the network''s audience.","transcript_status":"source_word_comment","word_comment_ids":["510"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '06ad600c9e0033a7a3ed118707770cdf63f029ab1ac97f3528cc33560ef40a6d'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set007-audio', 'Listening Part 4: Advertising and sponsoring (2026) Audio', 'Advertising can introduce a product or programme to people who might otherwise never discover it, but constant promotion also has a negative side. Television networks sometimes repeat trailers so frequently that viewers become tired of a series before they have even watched it. In that sense, series can be damaged by overexposure: excessive publicity replaces curiosity with irritation. Repetition can certainly be annoying, but the broader issue is the harm done to the programme''s image, not the claim that advertising costs as much as producing a film. Sponsorship in sport creates a different risk. A company may gain visibility by attaching its name to a tournament, yet it also becomes associated with whatever happens there. If athletes cheat, organisers behave badly, or a scandal dominates the event, the sponsor''s campaign can generate negative publicity for the sport itself. Advertising may sometimes attract fans or support ticket and merchandise sales, but those positive possibilities do not remove the reputational danger. Companies should therefore consider not only how many people will see a campaign, but also what kind of association the public may remember.', '{"source_key":"listening-p4-set007-audio","skill":"listening","part_number":4,"transcript":"Advertising can introduce a product or programme to people who might otherwise never discover it, but constant promotion also has a negative side. Television networks sometimes repeat trailers so frequently that viewers become tired of a series before they have even watched it. In that sense, series can be damaged by overexposure: excessive publicity replaces curiosity with irritation. Repetition can certainly be annoying, but the broader issue is the harm done to the programme''s image, not the claim that advertising costs as much as producing a film. Sponsorship in sport creates a different risk. A company may gain visibility by attaching its name to a tournament, yet it also becomes associated with whatever happens there. If athletes cheat, organisers behave badly, or a scandal dominates the event, the sponsor''s campaign can generate negative publicity for the sport itself. Advertising may sometimes attract fans or support ticket and merchandise sales, but those positive possibilities do not remove the reputational danger. Companies should therefore consider not only how many people will see a campaign, but also what kind of association the public may remember.","transcript_status":"source_word_comment","word_comment_ids":["511"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'ca59eb50acfb22e788711d14854684f8b47ac6ffe4a9c483391334b461e72e4b'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set008-audio', 'Listening Part 4: A newly released movie (2026) Audio', 'The Silver Horizon is visually impressive, and its locations are carefully chosen, so the setting is not the problem. The original cast also remained in place throughout production. What disappointed me was the dialogue, which often sounds unrealistic. Characters who are supposed to be close friends speak in stiff, formal sentences, and an emotional exchange between the hero and his mentor feels more like a rehearsed stage scene than a natural conversation. This weakness repeatedly pulls the audience out of the story. I believe the problem reflects a wider change in the film industry. Studios increasingly demand scripts that can be completed , adjusted to current trends, and approved by several marketing departments. Those modern industry pressures are negatively influencing script production because writers have less time to develop believable voices and layered relationships. I am not predicting that technology will replace actors, and simply inventing more plot ideas would not solve the underlying issue. The industry needs to give writers sufficient time and creative space; otherwise, even attractive films will continue to feel rushed and emotionally unconvincing.', '{"source_key":"listening-p4-set008-audio","skill":"listening","part_number":4,"transcript":"The Silver Horizon is visually impressive, and its locations are carefully chosen, so the setting is not the problem. The original cast also remained in place throughout production. What disappointed me was the dialogue, which often sounds unrealistic. Characters who are supposed to be close friends speak in stiff, formal sentences, and an emotional exchange between the hero and his mentor feels more like a rehearsed stage scene than a natural conversation. This weakness repeatedly pulls the audience out of the story. I believe the problem reflects a wider change in the film industry. Studios increasingly demand scripts that can be completed , adjusted to current trends, and approved by several marketing departments. Those modern industry pressures are negatively influencing script production because writers have less time to develop believable voices and layered relationships. I am not predicting that technology will replace actors, and simply inventing more plot ideas would not solve the underlying issue. The industry needs to give writers sufficient time and creative space; otherwise, even attractive films will continue to feel rushed and emotionally unconvincing.","transcript_status":"source_word_comment","word_comment_ids":["512"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'e0142a9c0534310844a7afd872be886c3e63c3de706a0efe0307f33a4a9fb7f6'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set009-audio', 'Listening Part 4: A new restaurant (2026) Audio', 'I recently visited La Bella Bistro, a restaurant with an attractive location and a warm-looking dining room. The ingredients seemed fresh enough, and nothing suggested that the chef lacked experience. Unfortunately, the service was not good. I waited a long time before anyone took my order, water arrived only after I asked twice, and the staff appeared too busy to explain the menu. When they finally spoke to us, the interaction felt rushed and impersonal. This matters more than ever because customers can now order good food at home with very little effort. A restaurant cannot compete with online delivery merely by offering organic ingredients or handing people a ready-made package. Its real advantage is the human experience. Guests should feel valued and welcome from the moment they enter: a friendly greeting, attentive service, and genuine interest can turn an ordinary meal into an occasion. La Bella Bistro already has a pleasant setting and acceptable food, but unless it improves the way customers are treated, people may decide that staying home is easier and more enjoyable.', '{"source_key":"listening-p4-set009-audio","skill":"listening","part_number":4,"transcript":"I recently visited La Bella Bistro, a restaurant with an attractive location and a warm-looking dining room. The ingredients seemed fresh enough, and nothing suggested that the chef lacked experience. Unfortunately, the service was not good. I waited a long time before anyone took my order, water arrived only after I asked twice, and the staff appeared too busy to explain the menu. When they finally spoke to us, the interaction felt rushed and impersonal. This matters more than ever because customers can now order good food at home with very little effort. A restaurant cannot compete with online delivery merely by offering organic ingredients or handing people a ready-made package. Its real advantage is the human experience. Guests should feel valued and welcome from the moment they enter: a friendly greeting, attentive service, and genuine interest can turn an ordinary meal into an occasion. La Bella Bistro already has a pleasant setting and acceptable food, but unless it improves the way customers are treated, people may decide that staying home is easier and more enjoyable.","transcript_status":"source_word_comment","word_comment_ids":["513"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '77f24e1ab25fa4f3644a3bf24fea57818831645d7be1ea4eb59cf0f6b5fd4415'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set010-audio', 'Listening Part 4: Famous writers (2026) Audio', 'Today I want to compare two influential writers who came from different countries and did not work in exactly the same genre. Academics have certainly not overlooked them; both have been studied for decades, and there is no useful basis for claiming that one was simply less successful than the other. What is particularly interesting is their literary relationship. They make references to each other''s work, sometimes borrowing an image, responding to an idea, or mentioning a character that readers recognise from the other author. These connections show mutual respect and create an additional layer for informed readers. Their writing, however, is rarely straightforward. Symbols, unreliable narrators, and indirect arguments mean that the meanings are not always easily identified. A reader may understand the basic story on the first reading but miss the social or philosophical message underneath it. Their reputation may indeed extend beyond the original audience, but that is not the feature being emphasised here. The central point is that interpretation requires patience, comparison, and sometimes more than one reading.', '{"source_key":"listening-p4-set010-audio","skill":"listening","part_number":4,"transcript":"Today I want to compare two influential writers who came from different countries and did not work in exactly the same genre. Academics have certainly not overlooked them; both have been studied for decades, and there is no useful basis for claiming that one was simply less successful than the other. What is particularly interesting is their literary relationship. They make references to each other''s work, sometimes borrowing an image, responding to an idea, or mentioning a character that readers recognise from the other author. These connections show mutual respect and create an additional layer for informed readers. Their writing, however, is rarely straightforward. Symbols, unreliable narrators, and indirect arguments mean that the meanings are not always easily identified. A reader may understand the basic story on the first reading but miss the social or philosophical message underneath it. Their reputation may indeed extend beyond the original audience, but that is not the feature being emphasised here. The central point is that interpretation requires patience, comparison, and sometimes more than one reading.","transcript_status":"source_word_comment","word_comment_ids":["514"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '6bf0b37227afab57cd6527c738b3f66c5ae35f5a4335eaeb265c93d1a993a79f'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set011-audio', 'Listening Part 4: Sports in education Audio', 'Schools often discuss sport as though competition were automatically beneficial. Supporters say tournaments can attract investment or help identify future professional athletes, but those are not my main concerns. Constantly ranking children and comparing one student with another can cause harmful effects. A child who is repeatedly treated as a loser may avoid physical activity altogether, while even successful students can become anxious about performance. This does not mean schools should remove sport. On the contrary, physical activity teaches cooperation, communication, resilience, and healthy habits that ordinary classroom lessons cannot provide. My advice is to use sport to provide students with balance in their lives. Academic work demands long periods of concentration and sitting, so movement and social activity offer an essential counterweight. I am not arguing that sport must become a rigid mandatory subject in every circumstance, nor should schools keep students focused only on academic subjects. The better approach is to reduce unnecessary comparison, create inclusive activities, and allow sport to support physical, social, and emotional development.', '{"source_key":"listening-p4-set011-audio","skill":"listening","part_number":4,"transcript":"Schools often discuss sport as though competition were automatically beneficial. Supporters say tournaments can attract investment or help identify future professional athletes, but those are not my main concerns. Constantly ranking children and comparing one student with another can cause harmful effects. A child who is repeatedly treated as a loser may avoid physical activity altogether, while even successful students can become anxious about performance. This does not mean schools should remove sport. On the contrary, physical activity teaches cooperation, communication, resilience, and healthy habits that ordinary classroom lessons cannot provide. My advice is to use sport to provide students with balance in their lives. Academic work demands long periods of concentration and sitting, so movement and social activity offer an essential counterweight. I am not arguing that sport must become a rigid mandatory subject in every circumstance, nor should schools keep students focused only on academic subjects. The better approach is to reduce unnecessary comparison, create inclusive activities, and allow sport to support physical, social, and emotional development.","transcript_status":"source_word_comment","word_comment_ids":["515"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '11cf8e5d852c655780ddf8bed3a00505550402cc9d24952471fb5f8a99d715a5'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set012-audio', 'Listening Part 4: A regional development plan (2026) Audio', 'The proposed Regional Development Plan has received criticism from both residents and council members. Local people are not objecting because the plan creates more parks or offers free transport; neither proposal is actually included. Their main complaint is that it does not do enough to promote alternatives to driving. Most of the budget is directed toward wider roads and new parking areas, while only a small number of bus routes, cycle lanes, and pedestrian zones are planned. Residents fear this will increase car use rather than reduce it. The council has raised a second problem concerning land. Several empty industrial sites and unused buildings already exist near the city centre, but the proposal would expand construction onto land outside the current urban area. Officials argue that this is wasteful and that the plan is not making efficient use of existing land. The project has not yet exceeded its budget, and excessive public support is certainly not the difficulty. Its challenge is to redesign development so that current urban space is used sensibly and transport choices are genuinely broadened.* **Explanation** *The residents oppose the plan because it still focuses too much on cars and roads instead of encouraging buses, cycling, and walking. The city council is also concerned that the proposal expands into land outside the city instead of making sensible use of empty or unused land that already exists in the city centre.', '{"source_key":"listening-p4-set012-audio","skill":"listening","part_number":4,"transcript":"The proposed Regional Development Plan has received criticism from both residents and council members. Local people are not objecting because the plan creates more parks or offers free transport; neither proposal is actually included. Their main complaint is that it does not do enough to promote alternatives to driving. Most of the budget is directed toward wider roads and new parking areas, while only a small number of bus routes, cycle lanes, and pedestrian zones are planned. Residents fear this will increase car use rather than reduce it. The council has raised a second problem concerning land. Several empty industrial sites and unused buildings already exist near the city centre, but the proposal would expand construction onto land outside the current urban area. Officials argue that this is wasteful and that the plan is not making efficient use of existing land. The project has not yet exceeded its budget, and excessive public support is certainly not the difficulty. Its challenge is to redesign development so that current urban space is used sensibly and transport choices are genuinely broadened.* **Explanation** *The residents oppose the plan because it still focuses too much on cars and roads instead of encouraging buses, cycling, and walking. The city council is also concerned that the proposal expands into land outside the city instead of making sensible use of empty or unused land that already exists in the city centre.","transcript_status":"source_word_comment","word_comment_ids":["516"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'cbe10b099e38e23e17806c6b625dd7adf09d73327c633cda088db92d2349ec24'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set013-audio', 'Listening Part 4: Life after university (2026) Audio', 'Life after university involves more than finding a first salary. During education, many decisions are made within a clear system of courses, deadlines, and advice. After graduation, young adults gradually become more independent in making decisions about where to live, which opportunities to accept, and what kind of career suits them. Stress about job seeking is common, but the important change is not simply increased anxiety, nor do graduates usually continue with the same academic routine. They have to judge competing priorities for themselves. The labour market also presents a practical challenge: it is becoming more competitive. A degree remains valuable, but many applicants may hold similar , so employers also examine communication skills, work experience, adaptability, and attitude. Networking opportunities and attractive benefits exist in some industries, but they are not universal characteristics of graduate employment. New graduates should therefore remain open-minded, research different roles, and be ready to explain what makes them distinctive rather than assuming that a alone will secure a position.', '{"source_key":"listening-p4-set013-audio","skill":"listening","part_number":4,"transcript":"Life after university involves more than finding a first salary. During education, many decisions are made within a clear system of courses, deadlines, and advice. After graduation, young adults gradually become more independent in making decisions about where to live, which opportunities to accept, and what kind of career suits them. Stress about job seeking is common, but the important change is not simply increased anxiety, nor do graduates usually continue with the same academic routine. They have to judge competing priorities for themselves. The labour market also presents a practical challenge: it is becoming more competitive. A degree remains valuable, but many applicants may hold similar , so employers also examine communication skills, work experience, adaptability, and attitude. Networking opportunities and attractive benefits exist in some industries, but they are not universal characteristics of graduate employment. New graduates should therefore remain open-minded, research different roles, and be ready to explain what makes them distinctive rather than assuming that a alone will secure a position.","transcript_status":"source_word_comment","word_comment_ids":["517"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '2de084e3212b2edea6f1b09cfc06b45ab18c11f83ff880977d7009e6f125a441'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set014-audio', 'Listening Part 4: A promotion campaign for a product (2026) Audio', 'PowerBoost, a new fitness supplement, has received plenty of attention, but its promotion campaign is creating problems. The advertisements use exaggerated claims, promising dramatic improvements in strength and endurance within only a few days. This is not mainly a case of outdated advertising or targeting the wrong market; the campaign clearly reaches people interested in fitness. The difficulty is that the promise is much stronger than the evidence, so disappointed buyers may lose trust in the company. PowerBoost also struggles to stand out on shop shelves. Its price is close to competing products, and it is already widely available, which rules out high cost and poor distribution as the main causes. The real issue is that it is too similar to many existing products. Its ingredients, packaging, and stated benefits resemble dozens of other supplements, leaving customers unsure why they should choose it. The company needs more honest language and a genuinely distinctive feature rather than louder claims. Otherwise, attention may be brief and the campaign could damage the brand instead of building it.', '{"source_key":"listening-p4-set014-audio","skill":"listening","part_number":4,"transcript":"PowerBoost, a new fitness supplement, has received plenty of attention, but its promotion campaign is creating problems. The advertisements use exaggerated claims, promising dramatic improvements in strength and endurance within only a few days. This is not mainly a case of outdated advertising or targeting the wrong market; the campaign clearly reaches people interested in fitness. The difficulty is that the promise is much stronger than the evidence, so disappointed buyers may lose trust in the company. PowerBoost also struggles to stand out on shop shelves. Its price is close to competing products, and it is already widely available, which rules out high cost and poor distribution as the main causes. The real issue is that it is too similar to many existing products. Its ingredients, packaging, and stated benefits resemble dozens of other supplements, leaving customers unsure why they should choose it. The company needs more honest language and a genuinely distinctive feature rather than louder claims. Otherwise, attention may be brief and the campaign could damage the brand instead of building it.","transcript_status":"source_word_comment","word_comment_ids":["518"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '736c46fb14b39d5cb34085c38cbe46aafadf2251ecd334400fa5a23070acd2ce'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set015-audio', 'Listening Part 4: Managing financial spending (2026) Audio', 'Good afternoon. People often try to save by waiting until the end of the month and putting aside whatever remains. The problem is that unexpected expenses usually consume that money first. A more reliable method is to save a fixed amount regularly, for example by arranging an automatic monthly transfer as soon as income arrives. It does not need to be a huge daily payment, and using credit cards is not a saving strategy; credit can easily hide how much has actually been spent. Consistency matters more than one dramatic sacrifice. Managing money also becomes easier when people seek guidance. Someone with experience, such as a financial adviser, a knowledgeable family member, or a trusted mentor, can identify mistakes that a beginner may not notice. Keeping every saving in a single account is not always suitable, and avoiding long-term planning would make future goals harder to achieve. People can manage money more successfully when they get advice from people who have experience, review their decisions, and adjust their habits. Saving successfully is therefore a combination of regular action and informed advice.', '{"source_key":"listening-p4-set015-audio","skill":"listening","part_number":4,"transcript":"Good afternoon. People often try to save by waiting until the end of the month and putting aside whatever remains. The problem is that unexpected expenses usually consume that money first. A more reliable method is to save a fixed amount regularly, for example by arranging an automatic monthly transfer as soon as income arrives. It does not need to be a huge daily payment, and using credit cards is not a saving strategy; credit can easily hide how much has actually been spent. Consistency matters more than one dramatic sacrifice. Managing money also becomes easier when people seek guidance. Someone with experience, such as a financial adviser, a knowledgeable family member, or a trusted mentor, can identify mistakes that a beginner may not notice. Keeping every saving in a single account is not always suitable, and avoiding long-term planning would make future goals harder to achieve. People can manage money more successfully when they get advice from people who have experience, review their decisions, and adjust their habits. Saving successfully is therefore a combination of regular action and informed advice.","transcript_status":"source_word_comment","word_comment_ids":["519"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '848134860c1a835e3ba1e03df1364d77569aff515c20b1b0a9171ba73f5ac578'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set016-audio', 'Listening Part 4: Security cameras (2026) Audio', 'Several colleagues became nervous when security cameras were installed in our office. They felt constantly watched and assumed management no longer trusted them. I understand the reaction, but I think people are unnecessarily worried about the cameras. They are placed in shared areas such as entrances, corridors, and storage rooms, not in private spaces. Their purpose is to discourage theft, clarify what happened during an accident, and protect both employees and visitors. It is not true that most people are unaware of the cameras; everyone knows they are there. Nor am I arguing for complete coverage of every corner. Appropriate limits and clear policies are important. Once staff understand the purpose, they should feel reassured about the cameras'' presence rather than intimidated by it. A recording helped us recover a missing bag last year, and it also showed that an employee had not caused an incident for which he was initially blamed. Cameras are not useful only after something goes wrong; their visibility can prevent problems as well. Used responsibly, they support safety without becoming unnecessary surveillance.', '{"source_key":"listening-p4-set016-audio","skill":"listening","part_number":4,"transcript":"Several colleagues became nervous when security cameras were installed in our office. They felt constantly watched and assumed management no longer trusted them. I understand the reaction, but I think people are unnecessarily worried about the cameras. They are placed in shared areas such as entrances, corridors, and storage rooms, not in private spaces. Their purpose is to discourage theft, clarify what happened during an accident, and protect both employees and visitors. It is not true that most people are unaware of the cameras; everyone knows they are there. Nor am I arguing for complete coverage of every corner. Appropriate limits and clear policies are important. Once staff understand the purpose, they should feel reassured about the cameras'' presence rather than intimidated by it. A recording helped us recover a missing bag last year, and it also showed that an employee had not caused an incident for which he was initially blamed. Cameras are not useful only after something goes wrong; their visibility can prevent problems as well. Used responsibly, they support safety without becoming unnecessary surveillance.","transcript_status":"source_word_comment","word_comment_ids":["520"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '326d0d05ebf825310a6c767875461c862217d7e8ab63c0d4a5f087290996035a'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set017-audio', 'Listening Part 4: A book about a life of a scientist (2026) Audio', 'I have just finished a biography of the physicist Elena Maric, and the writing makes it genuinely exciting to read. The author does not turn the book into a technical textbook, even when discussing difficult theories. Instead, scientific discoveries are connected to personal conflicts, travel, and moments of doubt, so the reader understands why each breakthrough mattered. Complex ideas are explained in simple language, which means the overall content has been written for a general audience. Experts may still appreciate the historical detail, but specialist knowledge is not required. The book is therefore very different from a work focused only on equations or laboratory procedures. Some biographies become dry because they list dates without creating a story; this one avoids that problem by combining clear explanation with strong narrative movement. It has already attracted readers who would not normally choose a science book. Its success shows that accuracy and accessibility do not have to be opposites: a writer can respect the subject while still making the life and ideas of a scientist understandable and engaging.', '{"source_key":"listening-p4-set017-audio","skill":"listening","part_number":4,"transcript":"I have just finished a biography of the physicist Elena Maric, and the writing makes it genuinely exciting to read. The author does not turn the book into a technical textbook, even when discussing difficult theories. Instead, scientific discoveries are connected to personal conflicts, travel, and moments of doubt, so the reader understands why each breakthrough mattered. Complex ideas are explained in simple language, which means the overall content has been written for a general audience. Experts may still appreciate the historical detail, but specialist knowledge is not required. The book is therefore very different from a work focused only on equations or laboratory procedures. Some biographies become dry because they list dates without creating a story; this one avoids that problem by combining clear explanation with strong narrative movement. It has already attracted readers who would not normally choose a science book. Its success shows that accuracy and accessibility do not have to be opposites: a writer can respect the subject while still making the life and ideas of a scientist understandable and engaging.","transcript_status":"source_word_comment","word_comment_ids":["521"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '85a0114959327c36ae20cbba2453b3c3d34872cf05088f460d3728b847d6ef42'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set018-audio', 'Listening Part 4: A research into happiness (2026) Audio', 'Good morning, listeners. A recent study on happiness has received enormous media attention, but much of the coverage has not been accurate. Several headlines reduced a complicated set of findings to claims such as "one habit guarantees happiness," even though the researchers made no such promise. The study has certainly not been ignored, and it would be wrong to say that reporting has been consistently reliable. Sensational summaries have left many readers with a distorted impression of what the evidence actually shows. There is a second limitation to remember. Researchers can identify patterns involving relationships, health, work, and security, but it is unlikely that they will find one conclusive answer that applies to every person. This does not mean individuals cannot find personal happiness, nor does it prevent the subject from being discussed in the media. It simply reflects the fact that happiness is influenced by values, culture, circumstances, and personality. Instead of searching for a universal formula, people should treat research as guidance and consider which findings are relevant to their own lives.', '{"source_key":"listening-p4-set018-audio","skill":"listening","part_number":4,"transcript":"Good morning, listeners. A recent study on happiness has received enormous media attention, but much of the coverage has not been accurate. Several headlines reduced a complicated set of findings to claims such as \"one habit guarantees happiness,\" even though the researchers made no such promise. The study has certainly not been ignored, and it would be wrong to say that reporting has been consistently reliable. Sensational summaries have left many readers with a distorted impression of what the evidence actually shows. There is a second limitation to remember. Researchers can identify patterns involving relationships, health, work, and security, but it is unlikely that they will find one conclusive answer that applies to every person. This does not mean individuals cannot find personal happiness, nor does it prevent the subject from being discussed in the media. It simply reflects the fact that happiness is influenced by values, culture, circumstances, and personality. Instead of searching for a universal formula, people should treat research as guidance and consider which findings are relevant to their own lives.","transcript_status":"source_word_comment","word_comment_ids":["522"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '1ada64032c8c6cbd0a6581e636172610440b6d7f7c0ce84d1ad397cf1fc0c2d3'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set019-audio', 'Listening Part 4: Setting goals (2026) Audio', 'Short-term goals are sometimes criticised for being rigid. People imagine that once a target is written down, every other opportunity must be ignored. In practice, a short-term goal can help people adjust their priorities when circumstances change. If work suddenly becomes busy, for example, a plan to exercise five times a week can be revised to three realistic sessions rather than abandoned completely. That flexibility is different from having no direction at all. Goal setting also helps prevent mistakes. Clear objectives encourage people to think ahead, notice conflicts, and choose actions that support the result they actually want. Too many poorly organised goals may cause confusion, but that is a problem of selection, not proof that planning itself is harmful. Goals can create opportunities, yet the point I am stressing is their role in reducing careless decisions. A useful system combines direction with regular review: decide what matters, break it into manageable steps, and change those steps when new information appears. The goal guides decisions without becoming a prison.', '{"source_key":"listening-p4-set019-audio","skill":"listening","part_number":4,"transcript":"Short-term goals are sometimes criticised for being rigid. People imagine that once a target is written down, every other opportunity must be ignored. In practice, a short-term goal can help people adjust their priorities when circumstances change. If work suddenly becomes busy, for example, a plan to exercise five times a week can be revised to three realistic sessions rather than abandoned completely. That flexibility is different from having no direction at all. Goal setting also helps prevent mistakes. Clear objectives encourage people to think ahead, notice conflicts, and choose actions that support the result they actually want. Too many poorly organised goals may cause confusion, but that is a problem of selection, not proof that planning itself is harmful. Goals can create opportunities, yet the point I am stressing is their role in reducing careless decisions. A useful system combines direction with regular review: decide what matters, break it into manageable steps, and change those steps when new information appears. The goal guides decisions without becoming a prison.","transcript_status":"source_word_comment","word_comment_ids":["523"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'd3fddfb2fa2bb3c182bea94895d77b920d80844f489639327e55ef3f5f46ef41'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set020-audio', 'Listening Part 4: A new guide (2026) Audio', 'This new guidebook does more than list famous monuments and opening times. It encourages readers to leave the standard tourist route, speak with local people, and try activities connected to the culture of each place. Stories from residents, walking challenges, and suggestions for small neighbourhood businesses make the journey feel like an adventure. The book is not focused solely on historical landmarks, and although its unusual layout requires a little attention at first, I would not describe it as difficult to navigate. Its strongest appeal is generational. The guide seems particularly suitable for younger travellers who value personal experiences, local contact, and discoveries they can shape themselves. That does not mean only experienced travellers can use it, and it is certainly not outdated or irrelevant. Older readers may enjoy it too, but the tone, design, and emphasis clearly match the interests of a particular generation more strongly than a traditional guide does. It offers an alternative for travellers who want memories and connections rather than simply photographs of the most familiar sights.', '{"source_key":"listening-p4-set020-audio","skill":"listening","part_number":4,"transcript":"This new guidebook does more than list famous monuments and opening times. It encourages readers to leave the standard tourist route, speak with local people, and try activities connected to the culture of each place. Stories from residents, walking challenges, and suggestions for small neighbourhood businesses make the journey feel like an adventure. The book is not focused solely on historical landmarks, and although its unusual layout requires a little attention at first, I would not describe it as difficult to navigate. Its strongest appeal is generational. The guide seems particularly suitable for younger travellers who value personal experiences, local contact, and discoveries they can shape themselves. That does not mean only experienced travellers can use it, and it is certainly not outdated or irrelevant. Older readers may enjoy it too, but the tone, design, and emphasis clearly match the interests of a particular generation more strongly than a traditional guide does. It offers an alternative for travellers who want memories and connections rather than simply photographs of the most familiar sights.","transcript_status":"source_word_comment","word_comment_ids":["524"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '13ea71203a7a7e4b3bd1b7b97c35d96a9fa19e48f6c8d8e9742cb355a5d58892'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set021-audio', 'Listening Part 4: A break from studying (2026) Audio', 'After finishing school, I did not go directly to college because I was not ready to start higher education. My grades were sufficient, and although tuition was a concern, money was not the main reason for delaying. I felt exhausted by years of examinations and wanted time to decide what I actually hoped to study. I chose to travel for two years, but the purpose was not simply to avoid education or to travel without direction. I wanted to become more independent. During the trip, I worked temporary jobs, arranged accommodation, managed a limited budget, and solved problems without relying on my family. Those experiences made me more confident and also clarified the subjects that interested me. By the time I returned, university felt like a decision I had made for myself rather than the automatic next step expected by other people. A break from study can become wasted time if it has no purpose, but in my case travelling developed responsibility and prepared me to approach higher education with greater maturity.', '{"source_key":"listening-p4-set021-audio","skill":"listening","part_number":4,"transcript":"After finishing school, I did not go directly to college because I was not ready to start higher education. My grades were sufficient, and although tuition was a concern, money was not the main reason for delaying. I felt exhausted by years of examinations and wanted time to decide what I actually hoped to study. I chose to travel for two years, but the purpose was not simply to avoid education or to travel without direction. I wanted to become more independent. During the trip, I worked temporary jobs, arranged accommodation, managed a limited budget, and solved problems without relying on my family. Those experiences made me more confident and also clarified the subjects that interested me. By the time I returned, university felt like a decision I had made for myself rather than the automatic next step expected by other people. A break from study can become wasted time if it has no purpose, but in my case travelling developed responsibility and prepared me to approach higher education with greater maturity.","transcript_status":"source_word_comment","word_comment_ids":["525"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'b4f073b2b5fa7a7dfde2e30dc49316eb222e0fe6ee2125aede7f0274660b7827'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set022-audio', 'Listening Part 4: Learning and development Audio', 'In fast-moving industries, professional development cannot be reduced to memorising information or following instructions that never change. The real aim is to learn how to work effectively. That means identifying high-impact tasks, organising processes clearly, and judging whether an activity produces a useful result rather than simply keeping us busy. Working independently can sometimes be valuable, but refusing all guidance is inefficient, and strict fixed instructions may become outdated. Effectiveness provides a foundation, yet it is not enough for long-term progress. People also need to be willing to experiment. Trying a new workflow, testing an unfamiliar tool, or approaching a problem from a different angle may lead to failure at first, but those attempts create learning that routine cannot provide. Maintaining a predictable daily pattern feels safe, and avoiding risk may prevent small mistakes, but both can limit innovation. Professionals who remain relevant are usually those who combine disciplined work with curiosity: they evaluate results, learn from unsuccessful trials, and keep adjusting their methods as the industry develops.', '{"source_key":"listening-p4-set022-audio","skill":"listening","part_number":4,"transcript":"In fast-moving industries, professional development cannot be reduced to memorising information or following instructions that never change. The real aim is to learn how to work effectively. That means identifying high-impact tasks, organising processes clearly, and judging whether an activity produces a useful result rather than simply keeping us busy. Working independently can sometimes be valuable, but refusing all guidance is inefficient, and strict fixed instructions may become outdated. Effectiveness provides a foundation, yet it is not enough for long-term progress. People also need to be willing to experiment. Trying a new workflow, testing an unfamiliar tool, or approaching a problem from a different angle may lead to failure at first, but those attempts create learning that routine cannot provide. Maintaining a predictable daily pattern feels safe, and avoiding risk may prevent small mistakes, but both can limit innovation. Professionals who remain relevant are usually those who combine disciplined work with curiosity: they evaluate results, learn from unsuccessful trials, and keep adjusting their methods as the industry develops.","transcript_status":"source_word_comment","word_comment_ids":["526"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '0257af61d6cad949274814ed2aec15bd1e7ee44c88a475154a55cf14a2745182'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set023-audio', 'Listening Part 4: The history of railways Audio', 'The railway network entered a serious crisis during the middle of the twentieth century. Passenger numbers fell as private cars became more common, while freight companies increasingly chose trucks. The major problem was financial: the railways were not making enough money to cover wages, maintenance, fuel, and the replacement of ageing equipment. A shortage of engineers created difficulties in some regions, and bad weather occasionally damaged tracks, but neither was the central threat to the whole system. Faced with falling revenue, the leader in charge could have suspended services or sold major assets. Instead, he decided to continue policies that had already been implemented. Management maintained existing routes, pricing, and investment priorities in the hope that economic conditions would improve. This cautious decision avoided immediate disruption, but it also delayed modernisation. Critics later argued that preserving the status allowed competitors to move further ahead. The episode illustrates how an organisation can recognise a financial problem yet still respond by repeating familiar policies rather than making the structural changes that the situation may require.', '{"source_key":"listening-p4-set023-audio","skill":"listening","part_number":4,"transcript":"The railway network entered a serious crisis during the middle of the twentieth century. Passenger numbers fell as private cars became more common, while freight companies increasingly chose trucks. The major problem was financial: the railways were not making enough money to cover wages, maintenance, fuel, and the replacement of ageing equipment. A shortage of engineers created difficulties in some regions, and bad weather occasionally damaged tracks, but neither was the central threat to the whole system. Faced with falling revenue, the leader in charge could have suspended services or sold major assets. Instead, he decided to continue policies that had already been implemented. Management maintained existing routes, pricing, and investment priorities in the hope that economic conditions would improve. This cautious decision avoided immediate disruption, but it also delayed modernisation. Critics later argued that preserving the status allowed competitors to move further ahead. The episode illustrates how an organisation can recognise a financial problem yet still respond by repeating familiar policies rather than making the structural changes that the situation may require.","transcript_status":"source_word_comment","word_comment_ids":["527"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '2f1b143b7eb036ecd7748f24aa0859c2af3973e77b9bcac81faa51c225b6e6fb'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set024-audio', 'Listening Part 4: The environment Audio', 'Protecting the environment can sound like a task only governments and large industries can influence, but everyday behaviour matters as well. People should make a daily effort to recycle, reduce unnecessary waste, and use energy carefully. These actions are more realistic than demanding that all factories move to rural areas or that every private vehicle be replaced immediately by an electric bicycle. One household''s contribution may appear small, but millions of repeated choices can reduce pressure on natural resources. At the same time, individual habits cannot excuse destructive activity on a larger scale. Deforestation removes habitats and weakens forests that absorb carbon and regulate water. Human activities like this harm nature and contribute to climate change and health problems, especially when smoke, flooding, or poor water affects nearby communities. They do not create stronger ecosystems, and any short-term economic benefit must be weighed against long-term damage. Environmental protection therefore requires both personal consistency and serious action against practices that destroy the systems on which communities depend.', '{"source_key":"listening-p4-set024-audio","skill":"listening","part_number":4,"transcript":"Protecting the environment can sound like a task only governments and large industries can influence, but everyday behaviour matters as well. People should make a daily effort to recycle, reduce unnecessary waste, and use energy carefully. These actions are more realistic than demanding that all factories move to rural areas or that every private vehicle be replaced immediately by an electric bicycle. One household''s contribution may appear small, but millions of repeated choices can reduce pressure on natural resources. At the same time, individual habits cannot excuse destructive activity on a larger scale. Deforestation removes habitats and weakens forests that absorb carbon and regulate water. Human activities like this harm nature and contribute to climate change and health problems, especially when smoke, flooding, or poor water affects nearby communities. They do not create stronger ecosystems, and any short-term economic benefit must be weighed against long-term damage. Environmental protection therefore requires both personal consistency and serious action against practices that destroy the systems on which communities depend.","transcript_status":"source_word_comment","word_comment_ids":["528"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '59b42aec347ccd0bb9c59b4d26404d2db0c0c03e34478dbd301663caf11c474a'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set025-audio', 'Listening Part 4: Building design Audio', 'Modern buildings are often immediately recognisable because they are closely associated with contemporary cityscapes. Glass walls, straight lines, steel frames, and limited decoration connect them visually with business districts and rapidly developing urban centres. They are not notable for prioritising traditional materials, and they are certainly not mainly constructed in rural environments. Their appearance reflects the wider identity of the modern city. Yet this consistency creates a problem. Many new buildings display a lack of ambition. Developers frequently choose designs that are cheap, to approve, and easy to reproduce, rather than exploring bold forms or imaginative public spaces. As a result, one office block may look almost identical to another in a different country. This does not represent the peak of architectural innovation, nor does it show a strong commitment to maximising green areas. Practical requirements are unavoidable, but efficiency should not become an excuse for visual sameness. Cities need buildings that function well while also responding creatively to local history, climate, and community life.', '{"source_key":"listening-p4-set025-audio","skill":"listening","part_number":4,"transcript":"Modern buildings are often immediately recognisable because they are closely associated with contemporary cityscapes. Glass walls, straight lines, steel frames, and limited decoration connect them visually with business districts and rapidly developing urban centres. They are not notable for prioritising traditional materials, and they are certainly not mainly constructed in rural environments. Their appearance reflects the wider identity of the modern city. Yet this consistency creates a problem. Many new buildings display a lack of ambition. Developers frequently choose designs that are cheap, to approve, and easy to reproduce, rather than exploring bold forms or imaginative public spaces. As a result, one office block may look almost identical to another in a different country. This does not represent the peak of architectural innovation, nor does it show a strong commitment to maximising green areas. Practical requirements are unavoidable, but efficiency should not become an excuse for visual sameness. Cities need buildings that function well while also responding creatively to local history, climate, and community life.","transcript_status":"source_word_comment","word_comment_ids":["529"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'ee866a0f6ef0eceefed6b5e66f9a56a32e1d4012632739beb619f1f41e3f7768'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set026-audio', 'Listening Part 4: Concentration Audio', 'People often treat concentration as a test of personal discipline. When attention disappears, they blame themselves and assume that trying harder will solve the problem. Individual effort does matter, but research suggests that concentration depends mostly on the environment. Lighting, background noise, temperature, phone notifications, and even the arrangement of a desk can either support or interrupt sustained attention. External distractions are part of that environment, but the issue is broader than a single noise or interruption. Another fact is commonly missed: concentration has limits. The brain cannot maintain the same of focus for endless hours, yet many people work without breaks because they believe stopping shows weakness. In reality, people often fail to consider the limits of concentration. They do not consistently recognise those limits, and most have not mastered the skill of managing them. After a certain point, errors increase and productivity falls. A sensible approach is to improve the physical setting, protect periods of focused work, and take deliberate breaks before mental energy is completely exhausted.', '{"source_key":"listening-p4-set026-audio","skill":"listening","part_number":4,"transcript":"People often treat concentration as a test of personal discipline. When attention disappears, they blame themselves and assume that trying harder will solve the problem. Individual effort does matter, but research suggests that concentration depends mostly on the environment. Lighting, background noise, temperature, phone notifications, and even the arrangement of a desk can either support or interrupt sustained attention. External distractions are part of that environment, but the issue is broader than a single noise or interruption. Another fact is commonly missed: concentration has limits. The brain cannot maintain the same of focus for endless hours, yet many people work without breaks because they believe stopping shows weakness. In reality, people often fail to consider the limits of concentration. They do not consistently recognise those limits, and most have not mastered the skill of managing them. After a certain point, errors increase and productivity falls. A sensible approach is to improve the physical setting, protect periods of focused work, and take deliberate breaks before mental energy is completely exhausted.","transcript_status":"source_word_comment","word_comment_ids":["530"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'd522d71fa99f4ed10d73a1593ecb655da67b53051bf97dfb647559a4513ecdad'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set027-audio', 'Listening Part 4: Customers in business Audio', 'Companies often identify a small group of important customers, sometimes called key accounts. Their value goes far beyond making one large purchase. They provide steady revenue, influence other buyers through recommendations, and offer feedback that helps a business improve its services. They do not normally hire or train the company''s employees, and even the strongest customer cannot guarantee that stock prices will never fall. Their importance comes from a combination of income, advocacy, and useful information. Businesses must also accept that customer behaviour is unpredictable. Preferences can change because of technology, economic pressure, or a new competitor. The correct response is not to reduce marketing automatically or standardise every product while ignoring individual needs. Companies should monitor customer habits and update their services when necessary. This may involve adjusting communication, redesigning a feature, or introducing a more flexible delivery option. A firm that listens and adapts can preserve trust, whereas a rigid company may continue offering something the market no longer values. Customer relationships therefore require both appreciation and continuous attention.', '{"source_key":"listening-p4-set027-audio","skill":"listening","part_number":4,"transcript":"Companies often identify a small group of important customers, sometimes called key accounts. Their value goes far beyond making one large purchase. They provide steady revenue, influence other buyers through recommendations, and offer feedback that helps a business improve its services. They do not normally hire or train the company''s employees, and even the strongest customer cannot guarantee that stock prices will never fall. Their importance comes from a combination of income, advocacy, and useful information. Businesses must also accept that customer behaviour is unpredictable. Preferences can change because of technology, economic pressure, or a new competitor. The correct response is not to reduce marketing automatically or standardise every product while ignoring individual needs. Companies should monitor customer habits and update their services when necessary. This may involve adjusting communication, redesigning a feature, or introducing a more flexible delivery option. A firm that listens and adapts can preserve trust, whereas a rigid company may continue offering something the market no longer values. Customer relationships therefore require both appreciation and continuous attention.","transcript_status":"source_word_comment","word_comment_ids":["531"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'ff46d9d9d5a41d3c65eab7309acd66bb438b75930d76e8f173d59b78e7189405'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set028-audio', 'Listening Part 4: Team motivation Audio', 'When a team''s project falls behind schedule, the visible problem may be a missed deadline, but the psychological effect can be more serious. Team members often lose confidence. They begin their own judgement and may hesitate before making decisions that previously felt routine. They do not usually become more assured, and starting the entire project again is rarely the first response. A leader must therefore rebuild belief without pretending that the setback did not happen. Some managers increase the budget or monitor each person more closely, but money and surveillance do not automatically restore motivation. In my experience, the most effective step is to set a realistic goal. An attainable objective gives the team evidence that progress is possible and creates a clear next action. Focusing only on individual performance can damage cooperation, while an unnecessarily large budget may introduce pressure without solving the real issue. Once the group reaches a realistic milestone, confidence begins to return, and more demanding goals can be introduced gradually. Motivation grows when people can see a credible path forward.', '{"source_key":"listening-p4-set028-audio","skill":"listening","part_number":4,"transcript":"When a team''s project falls behind schedule, the visible problem may be a missed deadline, but the psychological effect can be more serious. Team members often lose confidence. They begin their own judgement and may hesitate before making decisions that previously felt routine. They do not usually become more assured, and starting the entire project again is rarely the first response. A leader must therefore rebuild belief without pretending that the setback did not happen. Some managers increase the budget or monitor each person more closely, but money and surveillance do not automatically restore motivation. In my experience, the most effective step is to set a realistic goal. An attainable objective gives the team evidence that progress is possible and creates a clear next action. Focusing only on individual performance can damage cooperation, while an unnecessarily large budget may introduce pressure without solving the real issue. Once the group reaches a realistic milestone, confidence begins to return, and more demanding goals can be introduced gradually. Motivation grows when people can see a credible path forward.","transcript_status":"source_word_comment","word_comment_ids":["532"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'e1ed05c2d3619e78f2db9179f093f1e6710aad4c606296787cfe47f4591c924b'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set029-audio', 'Listening Part 4: Travelling and Reading Audio', 'My brother travels frequently, but not because he wants to escape his job or produce impressive photographs for social media. He finds travelling meaningful because it brings him joy and gives him opportunities to learn about different cultures. He stays with local families when possible, attends community events, and asks about ordinary routines rather than visiting only famous attractions. The value lies in seeing how other people organise their lives and reconsidering assumptions he previously treated as universal. In that respect, travelling is similar to reading a book. Both can help people discover new worlds and grow as a person. A novel may introduce an unfamiliar society through imagination, while a journey provides direct experience, but each expands perspective. Neither activity is mandatory for academic success, and reading certainly does not require the physical endurance of a cycling expedition. What they share is the ability to move someone beyond a narrow personal viewpoint. After a thoughtful book or a meaningful trip, the world often appears more complex, and the individual returns with new rather than simple answers.', '{"source_key":"listening-p4-set029-audio","skill":"listening","part_number":4,"transcript":"My brother travels frequently, but not because he wants to escape his job or produce impressive photographs for social media. He finds travelling meaningful because it brings him joy and gives him opportunities to learn about different cultures. He stays with local families when possible, attends community events, and asks about ordinary routines rather than visiting only famous attractions. The value lies in seeing how other people organise their lives and reconsidering assumptions he previously treated as universal. In that respect, travelling is similar to reading a book. Both can help people discover new worlds and grow as a person. A novel may introduce an unfamiliar society through imagination, while a journey provides direct experience, but each expands perspective. Neither activity is mandatory for academic success, and reading certainly does not require the physical endurance of a cycling expedition. What they share is the ability to move someone beyond a narrow personal viewpoint. After a thoughtful book or a meaningful trip, the world often appears more complex, and the individual returns with new rather than simple answers.","transcript_status":"source_word_comment","word_comment_ids":["533"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'df32e9daa2d0cf2e883cb45e912a5794fe24e3f2fd613476d2c568326d22747a'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set030-audio', 'Listening Part 4: A nutritionist''s career Audio', 'People sometimes assume I became a nutritionist after working in a hospital or after taking a position at a health centre. My path began earlier. I became a nutritionist while completing my biology degree, when a research project on diet and metabolism convinced me to specialise. The degree provided the scientific foundation, and I later gained practical experience in clinical settings, but those jobs were not the moment the career began. Public recognition came in an unexpected way. It was not the result of inventing a new food, and I had not yet appeared on a famous television programme. I became well known after helping people solve dietary problems through a telephone helpline. Callers asked about allergies, weight management, and affordable meals, and my explanations were shared widely because they were practical and easy to understand. Television invitations followed later. The experience taught me that professional reputation can grow from useful public service rather than from publicity alone. People remembered the advice because it addressed real problems in their everyday lives.', '{"source_key":"listening-p4-set030-audio","skill":"listening","part_number":4,"transcript":"People sometimes assume I became a nutritionist after working in a hospital or after taking a position at a health centre. My path began earlier. I became a nutritionist while completing my biology degree, when a research project on diet and metabolism convinced me to specialise. The degree provided the scientific foundation, and I later gained practical experience in clinical settings, but those jobs were not the moment the career began. Public recognition came in an unexpected way. It was not the result of inventing a new food, and I had not yet appeared on a famous television programme. I became well known after helping people solve dietary problems through a telephone helpline. Callers asked about allergies, weight management, and affordable meals, and my explanations were shared widely because they were practical and easy to understand. Television invitations followed later. The experience taught me that professional reputation can grow from useful public service rather than from publicity alone. People remembered the advice because it addressed real problems in their everyday lives.","transcript_status":"source_word_comment","word_comment_ids":["534"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '4dd0d31ce702850f9afb1b0edbf1127ce6e2932c8ce5ec3695f163bc9e2fcbe7'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set031-audio', 'Listening Part 4: Viral video Audio', 'A recent online video became extremely popular, and many observers assumed that celebrities or a huge marketing budget must have been responsible. Neither explanation is accurate. What makes the video stand out is its production technique. The camera movement appears effortless, the editing creates a surprising change of perspective, and the sound is timed so precisely that viewers often replay the clip to understand how it was made. These technical choices give a simple idea the of a professional short film. Strong production alone, however, does not guarantee that a video will spread. According to the reviewer, videos become more successful when they are released at the right time. This particular clip appeared during a public conversation that made its theme immediately relevant. It did not follow a long-term trend mechanically, and translation into several languages was not necessary because the story was mainly visual. Online success combines with timing: creators need something distinctive, but they must also understand when an audience is most ready to notice, discuss, and share it.', '{"source_key":"listening-p4-set031-audio","skill":"listening","part_number":4,"transcript":"A recent online video became extremely popular, and many observers assumed that celebrities or a huge marketing budget must have been responsible. Neither explanation is accurate. What makes the video stand out is its production technique. The camera movement appears effortless, the editing creates a surprising change of perspective, and the sound is timed so precisely that viewers often replay the clip to understand how it was made. These technical choices give a simple idea the of a professional short film. Strong production alone, however, does not guarantee that a video will spread. According to the reviewer, videos become more successful when they are released at the right time. This particular clip appeared during a public conversation that made its theme immediately relevant. It did not follow a long-term trend mechanically, and translation into several languages was not necessary because the story was mainly visual. Online success combines with timing: creators need something distinctive, but they must also understand when an audience is most ready to notice, discuss, and share it.","transcript_status":"source_word_comment","word_comment_ids":["535"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '35a757be61925b9d1eee410642da08d0ee29266cf964876d364ef8565f5498af'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set032-audio', 'Listening Part 4: Business strategy Audio', 'Identifying the correct market is one of the first serious decisions a company makes. The benefit is not that competitors disappear or that lower standards become acceptable. A clear target market helps the company focus resources and avoid wasting time on areas where demand is weak. Staff can design relevant products, choose suitable communication channels, and direct research toward customers who are genuinely likely to buy. Without that focus, even a large budget may be spread too thinly to achieve useful results. Profitability is equally important, but it is often misunderstood as a sign that research and competitive analysis are no longer necessary. In fact, profitability proves that a company can cover its costs and strengthen its position in the market. It provides money for improvement, resilience during difficult periods, and future investment. It does not allow managers to ignore competitors. A profitable firm must still monitor change and protect the reasons customers choose it. Market selection and profitability therefore support each other: one concentrates effort, while the other confirms that the strategy can survive financially.', '{"source_key":"listening-p4-set032-audio","skill":"listening","part_number":4,"transcript":"Identifying the correct market is one of the first serious decisions a company makes. The benefit is not that competitors disappear or that lower standards become acceptable. A clear target market helps the company focus resources and avoid wasting time on areas where demand is weak. Staff can design relevant products, choose suitable communication channels, and direct research toward customers who are genuinely likely to buy. Without that focus, even a large budget may be spread too thinly to achieve useful results. Profitability is equally important, but it is often misunderstood as a sign that research and competitive analysis are no longer necessary. In fact, profitability proves that a company can cover its costs and strengthen its position in the market. It provides money for improvement, resilience during difficult periods, and future investment. It does not allow managers to ignore competitors. A profitable firm must still monitor change and protect the reasons customers choose it. Market selection and profitability therefore support each other: one concentrates effort, while the other confirms that the strategy can survive financially.","transcript_status":"source_word_comment","word_comment_ids":["536"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '29129c6f73d466df99c2f7b0e018fb570025b5d70dcf3dec0fd7a75999c22ac2'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set033-audio', 'Listening Part 4: Industry of Making Music (2026) Audio', 'A long career in music depends on more than winning awards or collecting a large number of fans. Audiences change, fashions disappear, and early publicity can fade very The key is an artist''s belief in her musical instincts. A performer who understands her own sound can adapt without copying every temporary trend. That confidence does not mean refusing advice; it means knowing which suggestions support the music and which would weaken its identity. The current industry makes that confidence difficult to develop because performers find it hard to get started. Digital platforms allow anyone to upload a song, but they also create overwhelming competition. New musicians must attract attention among thousands of releases while learning production, promotion, and live performance at the same time. It is not easier than ever to become genuinely established, and most artists are not simply returning to traditional styles. Success may arrive suddenly online, but building a sustainable career still requires opportunity, patience, and a clear creative direction. Trusting musical judgement helps an artist continue when early recognition is limited.', '{"source_key":"listening-p4-set033-audio","skill":"listening","part_number":4,"transcript":"A long career in music depends on more than winning awards or collecting a large number of fans. Audiences change, fashions disappear, and early publicity can fade very The key is an artist''s belief in her musical instincts. A performer who understands her own sound can adapt without copying every temporary trend. That confidence does not mean refusing advice; it means knowing which suggestions support the music and which would weaken its identity. The current industry makes that confidence difficult to develop because performers find it hard to get started. Digital platforms allow anyone to upload a song, but they also create overwhelming competition. New musicians must attract attention among thousands of releases while learning production, promotion, and live performance at the same time. It is not easier than ever to become genuinely established, and most artists are not simply returning to traditional styles. Success may arrive suddenly online, but building a sustainable career still requires opportunity, patience, and a clear creative direction. Trusting musical judgement helps an artist continue when early recognition is limited.","transcript_status":"source_word_comment","word_comment_ids":["537"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'cd924d510850a986c3d3c8cf666cc35a230aec56012ada052348bf37ecff515e'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set034-audio', 'Listening Part 4: Productivity (2026) Audio', 'People searching for greater productivity often respond by extending the working day. Longer hours can increase output briefly, but fatigue eventually reduces and creates mistakes. The most reliable way to maximise productivity is effective time management. This involves identifying priorities, dividing large tasks into manageable stages, and protecting time for work that requires concentration. Planning does not need to remove flexibility; it should make deliberate change easier. The difficulty is that productivity strategies require effort to use effectively. A calendar, task system, or weekly review produces no benefit if it is ignored after several days. These methods are not limited to students, and most can be implemented without expensive equipment. The challenge is consistency: people must review commitments, say no to lower-value activity, and continue using a system even when work becomes busy. Productivity is therefore not a clever trick that removes effort. Good management directs effort toward the right task and prevents energy from being lost through confusion, repetition, or constant switching.', '{"source_key":"listening-p4-set034-audio","skill":"listening","part_number":4,"transcript":"People searching for greater productivity often respond by extending the working day. Longer hours can increase output briefly, but fatigue eventually reduces and creates mistakes. The most reliable way to maximise productivity is effective time management. This involves identifying priorities, dividing large tasks into manageable stages, and protecting time for work that requires concentration. Planning does not need to remove flexibility; it should make deliberate change easier. The difficulty is that productivity strategies require effort to use effectively. A calendar, task system, or weekly review produces no benefit if it is ignored after several days. These methods are not limited to students, and most can be implemented without expensive equipment. The challenge is consistency: people must review commitments, say no to lower-value activity, and continue using a system even when work becomes busy. Productivity is therefore not a clever trick that removes effort. Good management directs effort toward the right task and prevents energy from being lost through confusion, repetition, or constant switching.","transcript_status":"source_word_comment","word_comment_ids":["538"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '2fa436b7c959a86845c7e930af0762bee79ce2f22f65e75e5d1048e6d2bb9059'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set035-audio', 'Listening Part 4: Podcast Discussion (2026) Audio', 'The new podcast contained thoughtful interviews, and the episodes were not unusually long. Its failure came from a different source: the creators did not promote the show effectively. They uploaded each episode and assumed listeners would discover it automatically, but they rarely shared short clips, contacted related communities, or explained clearly what made the programme distinctive. As a result, even people who might have enjoyed the content did not know it existed. This example should not lead us to dismiss podcasting. In my view, it is a great way to build a community. Regular episodes allow hosts and listeners to develop an ongoing conversation, especially when audiences can send , suggest topics, or respond to one another. Podcasting is not only useful for entertainment; it can support education, professional discussion, and shared interests. Nor is it a waste of time when the purpose and audience are clear. The lesson is that good content and community potential are not enough by themselves. Creators must also make the programme visible and invite people into the conversation.', '{"source_key":"listening-p4-set035-audio","skill":"listening","part_number":4,"transcript":"The new podcast contained thoughtful interviews, and the episodes were not unusually long. Its failure came from a different source: the creators did not promote the show effectively. They uploaded each episode and assumed listeners would discover it automatically, but they rarely shared short clips, contacted related communities, or explained clearly what made the programme distinctive. As a result, even people who might have enjoyed the content did not know it existed. This example should not lead us to dismiss podcasting. In my view, it is a great way to build a community. Regular episodes allow hosts and listeners to develop an ongoing conversation, especially when audiences can send , suggest topics, or respond to one another. Podcasting is not only useful for entertainment; it can support education, professional discussion, and shared interests. Nor is it a waste of time when the purpose and audience are clear. The lesson is that good content and community potential are not enough by themselves. Creators must also make the programme visible and invite people into the conversation.","transcript_status":"source_word_comment","word_comment_ids":["539"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '51b6f59a55f97e2154cd0b8bad9935485b9d0e6b0951f0bd2f50242ad175a29b'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set036-audio', 'Listening Part 4: A musician''s career (2026) Audio', 'The singer we are discussing has performed for more than forty years. Fans have recently speculated about a new album or collaborations with younger artists, but he has rejected both ideas. After a final concert next month, he will probably retire from singing. He says he wants a life away from touring, recording deadlines, and constant public attention. Retirement does not mean he regrets choosing music, and he does not claim that success arrived too early. Looking back, however, he believes he could have been more successful. There were periods when poor management, long gaps between releases, and his own unwillingness to adapt limited his audience. He remains proud of several albums and of the listeners who stayed with him, but he recognises that some opportunities were missed. This is not a bitter judgement. He describes a rewarding career while honestly admitting that stronger decisions might have taken it further. His final performances are therefore both a celebration and a thoughtful ending, rather than preparation for another major project.* **Explanation** *The speaker says the singer has no plans to return to the studio and will probably stop singing professionally after his final concert. Looking back, the speaker also says he achieved a lot, but not as much as he could have, because he never became as famous internationally as some critics expected.', '{"source_key":"listening-p4-set036-audio","skill":"listening","part_number":4,"transcript":"The singer we are discussing has performed for more than forty years. Fans have recently speculated about a new album or collaborations with younger artists, but he has rejected both ideas. After a final concert next month, he will probably retire from singing. He says he wants a life away from touring, recording deadlines, and constant public attention. Retirement does not mean he regrets choosing music, and he does not claim that success arrived too early. Looking back, however, he believes he could have been more successful. There were periods when poor management, long gaps between releases, and his own unwillingness to adapt limited his audience. He remains proud of several albums and of the listeners who stayed with him, but he recognises that some opportunities were missed. This is not a bitter judgement. He describes a rewarding career while honestly admitting that stronger decisions might have taken it further. His final performances are therefore both a celebration and a thoughtful ending, rather than preparation for another major project.* **Explanation** *The speaker says the singer has no plans to return to the studio and will probably stop singing professionally after his final concert. Looking back, the speaker also says he achieved a lot, but not as much as he could have, because he never became as famous internationally as some critics expected.","transcript_status":"source_word_comment","word_comment_ids":["540"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'a537d9eee2356d50a39aac0c7ca446c1cfca3b604aa71ffb8c1da78feb879317'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set037-audio', 'Listening Part 4: Making Plans (2026) Audio', 'Planning is useful because it helps people make decisions. When several options appear, a plan provides priorities against which each choice can be judged. It does not make life completely predictable, and it certainly does not reduce the need to communicate with other people. Instead, it gives a reason for choosing one action over another and prevents every new request from becoming an emergency. The difficulty is that planning requires you to set yourself certain limits. Time, money, and attention are finite, so accepting one commitment usually means refusing or delaying another. Some people dislike this because limits can feel restrictive, but without them a plan becomes a list of wishes rather than a workable guide. Planning does not only apply in professional situations, and it need not discourage all risk. A good plan can include experimentation and revision. The important point is to recognise constraints honestly, choose what matters most, and update the plan when circumstances change. Decisions become clearer when priorities and limits are visible.', '{"source_key":"listening-p4-set037-audio","skill":"listening","part_number":4,"transcript":"Planning is useful because it helps people make decisions. When several options appear, a plan provides priorities against which each choice can be judged. It does not make life completely predictable, and it certainly does not reduce the need to communicate with other people. Instead, it gives a reason for choosing one action over another and prevents every new request from becoming an emergency. The difficulty is that planning requires you to set yourself certain limits. Time, money, and attention are finite, so accepting one commitment usually means refusing or delaying another. Some people dislike this because limits can feel restrictive, but without them a plan becomes a list of wishes rather than a workable guide. Planning does not only apply in professional situations, and it need not discourage all risk. A good plan can include experimentation and revision. The important point is to recognise constraints honestly, choose what matters most, and update the plan when circumstances change. Decisions become clearer when priorities and limits are visible.","transcript_status":"source_word_comment","word_comment_ids":["541"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '8ad8e21a0ddc190ed253372df22f5fb3a17363f91c19e9aaf7f316df3c022d5b'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set038-audio', 'Listening Part 4: The Sport (Version 2) (2026) Audio', 'Debates about school sport often focus on health, but organised competition can teach another kind of lesson. In my view, sports competitions prepare students for a competitive work environment. Young people experience pressure, learn to recover after disappointment, and discover that preparation influences performance. This is not primarily about attracting international sponsorship or selecting athletes for national teams. The educational value lies in learning how to compete responsibly without treating one result as a judgement of personal worth. Schools should nevertheless avoid allowing competition to dominate student life. My broader advice is that school sport should provide students with balance in their lives. Academic subjects demand concentration and individual assessment, whereas physical activity offers movement, teamwork, and a different source of achievement. I am not recommending a strict graduation requirement for every student, and restricting activity to protect academic performance would remove that benefit. A thoughtful programme includes competitive opportunities while also offering inclusive participation. Students need both challenge and recovery, and sport can support that balance when success is defined more widely than winning.', '{"source_key":"listening-p4-set038-audio","skill":"listening","part_number":4,"transcript":"Debates about school sport often focus on health, but organised competition can teach another kind of lesson. In my view, sports competitions prepare students for a competitive work environment. Young people experience pressure, learn to recover after disappointment, and discover that preparation influences performance. This is not primarily about attracting international sponsorship or selecting athletes for national teams. The educational value lies in learning how to compete responsibly without treating one result as a judgement of personal worth. Schools should nevertheless avoid allowing competition to dominate student life. My broader advice is that school sport should provide students with balance in their lives. Academic subjects demand concentration and individual assessment, whereas physical activity offers movement, teamwork, and a different source of achievement. I am not recommending a strict graduation requirement for every student, and restricting activity to protect academic performance would remove that benefit. A thoughtful programme includes competitive opportunities while also offering inclusive participation. Students need both challenge and recovery, and sport can support that balance when success is defined more widely than winning.","transcript_status":"source_word_comment","word_comment_ids":["542"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '4ec74161a5af7a14c1c68fb181f805f3bf42914dcd17dd9d0a987236c3cf4dcd'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set039-audio', 'Listening Part 4: The Sport (Version 3) (2026) Audio', 'School sport is sometimes discussed only in terms of winning matches, but its most direct benefit is broader: it helps promote students'' overall health. Regular physical activity supports fitness, sleep, concentration, and emotional well-being. It is not designed to reduce physical effort, and its purpose should not be confused with academic competition. Students who move regularly may actually return to classroom work with greater energy. Sport also provides balance. School life can become dominated by examinations, homework, and hours spent sitting. Training or playing with a team introduces movement, social contact, and a different form of progress. That does not mean students should specialise at an extreme level or place individual success above the group. The strongest programmes allow different abilities to participate and connect physical development with cooperation. Balance is achieved when sport supports study rather than competing with it for every available hour. Schools should therefore treat physical activity as part of a healthy educational experience, not merely as preparation for elite competition.', '{"source_key":"listening-p4-set039-audio","skill":"listening","part_number":4,"transcript":"School sport is sometimes discussed only in terms of winning matches, but its most direct benefit is broader: it helps promote students'' overall health. Regular physical activity supports fitness, sleep, concentration, and emotional well-being. It is not designed to reduce physical effort, and its purpose should not be confused with academic competition. Students who move regularly may actually return to classroom work with greater energy. Sport also provides balance. School life can become dominated by examinations, homework, and hours spent sitting. Training or playing with a team introduces movement, social contact, and a different form of progress. That does not mean students should specialise at an extreme level or place individual success above the group. The strongest programmes allow different abilities to participate and connect physical development with cooperation. Balance is achieved when sport supports study rather than competing with it for every available hour. Schools should therefore treat physical activity as part of a healthy educational experience, not merely as preparation for elite competition.","transcript_status":"source_word_comment","word_comment_ids":["543"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '93860fa5a27fb8c552f861f501faa8a7c53624274a325cf446c6c8b45d19818f'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set040-audio', 'Listening Part 4: Television Series (Version 3) (2026) Audio', 'The drama series North Harbour had experienced actors and a promising subject, but the premiere failed to engage the audience from the start. The opening episode introduced too many unexplained events, and viewers had little reason to care about the central character before the first major crisis occurred. The failure was not caused by an enormous celebrity marketing budget, nor was the story adapted from a famous novel. The problem was the confusing beginning. Later episodes improved, yet the broadcaster created another difficulty by promoting the programme everywhere. Trailers appeared repeatedly between shows, interviews filled entertainment pages, and plot images circulated long before episodes were shown. The reviewer argues that series are damaged by overexposure. When audiences see the same material constantly, curiosity can turn into irritation, and surprises lose their effect. Inconsistent production or limited casting diversity may be valid concerns in other programmes, but they are not the criticism made here. A series needs enough promotion to be noticed, but not so much that viewers feel exhausted before the story has a chance to develop.', '{"source_key":"listening-p4-set040-audio","skill":"listening","part_number":4,"transcript":"The drama series North Harbour had experienced actors and a promising subject, but the premiere failed to engage the audience from the start. The opening episode introduced too many unexplained events, and viewers had little reason to care about the central character before the first major crisis occurred. The failure was not caused by an enormous celebrity marketing budget, nor was the story adapted from a famous novel. The problem was the confusing beginning. Later episodes improved, yet the broadcaster created another difficulty by promoting the programme everywhere. Trailers appeared repeatedly between shows, interviews filled entertainment pages, and plot images circulated long before episodes were shown. The reviewer argues that series are damaged by overexposure. When audiences see the same material constantly, curiosity can turn into irritation, and surprises lose their effect. Inconsistent production or limited casting diversity may be valid concerns in other programmes, but they are not the criticism made here. A series needs enough promotion to be noticed, but not so much that viewers feel exhausted before the story has a chance to develop.","transcript_status":"source_word_comment","word_comment_ids":["544"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '3937ccdff339e24a9e7ae4ac5509b26a9d563be8719b6c7f07be898a977fbe8c'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set041-audio', 'Listening Part 4: Advertising And Sponsoring (Version 3) (2026) Audio', 'Advertising remains important even in a world of recommendations and social media. A well-designed campaign helps to reach new customers by introducing a product to people outside the company''s existing audience. Its main purpose is not to reduce production costs, and digital media has not made advertising automatically ineffective. The channels have changed, but businesses still need a way to become visible. Sponsorship in sport is more complicated. It can provide money and attention, yet advertising arrangements are not always good for sports fans. Commercial breaks may interrupt events, ticketing decisions may favour sponsors, and excessive branding can make supporters feel that tradition has been replaced by marketing. Sponsorship certainly does not guarantee that a team will win, and major campaigns are not limited to local amateur events. The expert''s point is not that all advertising should disappear from sport. Rather, organisers should ask whether commercial activity improves the experience or begins to control it. Financial support is valuable, but fans, athletes, and the identity of the sport should remain more important than the sponsor''s demand for visibility.', '{"source_key":"listening-p4-set041-audio","skill":"listening","part_number":4,"transcript":"Advertising remains important even in a world of recommendations and social media. A well-designed campaign helps to reach new customers by introducing a product to people outside the company''s existing audience. Its main purpose is not to reduce production costs, and digital media has not made advertising automatically ineffective. The channels have changed, but businesses still need a way to become visible. Sponsorship in sport is more complicated. It can provide money and attention, yet advertising arrangements are not always good for sports fans. Commercial breaks may interrupt events, ticketing decisions may favour sponsors, and excessive branding can make supporters feel that tradition has been replaced by marketing. Sponsorship certainly does not guarantee that a team will win, and major campaigns are not limited to local amateur events. The expert''s point is not that all advertising should disappear from sport. Rather, organisers should ask whether commercial activity improves the experience or begins to control it. Financial support is valuable, but fans, athletes, and the identity of the sport should remain more important than the sponsor''s demand for visibility.","transcript_status":"source_word_comment","word_comment_ids":["545"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'edf4291d18e3d5930484f25995fe336b5a8ac695cc3b203604d6f36ba7dad11e'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set042-audio', 'Listening Part 4: Regional Development Plan (Version 2) (2026) Audio', 'The revised Regional Development Plan proposes new housing and road capacity, but one major criticism remains: it does not provide enough alternatives to driving. Several neighbourhoods would receive wider roads, yet the plan contains only limited bus improvements and disconnected cycle routes. The objection is not about international loans or an exclusive focus on cities rather than rural areas. Residents want practical options that reduce dependence on private cars. This weakness is likely to create a second challenge. The plan may meet resistance from local communities, particularly those facing increased traffic, construction, or the loss of open land without receiving better public transport in return. The legal framework has already been established, and no confirmed shortage of engineers has been identified. Public meetings show that opposition is based on the content of the proposal rather than a technical delay. If planners want support, they will need to consult affected neighbourhoods and demonstrate that walking, cycling, and public transport are genuine parts of the design. Ignoring those concerns could slow approval even if the engineering work is possible.', '{"source_key":"listening-p4-set042-audio","skill":"listening","part_number":4,"transcript":"The revised Regional Development Plan proposes new housing and road capacity, but one major criticism remains: it does not provide enough alternatives to driving. Several neighbourhoods would receive wider roads, yet the plan contains only limited bus improvements and disconnected cycle routes. The objection is not about international loans or an exclusive focus on cities rather than rural areas. Residents want practical options that reduce dependence on private cars. This weakness is likely to create a second challenge. The plan may meet resistance from local communities, particularly those facing increased traffic, construction, or the loss of open land without receiving better public transport in return. The legal framework has already been established, and no confirmed shortage of engineers has been identified. Public meetings show that opposition is based on the content of the proposal rather than a technical delay. If planners want support, they will need to consult affected neighbourhoods and demonstrate that walking, cycling, and public transport are genuine parts of the design. Ignoring those concerns could slow approval even if the engineering work is possible.","transcript_status":"source_word_comment","word_comment_ids":["546"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'd5199e979b1e8ae09fe5ce810060739798945215a72455dbfbbd6b5add52ac0a'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set043-audio', 'Listening Part 4: Criticism Of The New Novel (Version 2) (2026) Audio', 'The latest novel is uneven, but its plot is very strong. Events are carefully connected, tension increases at the right moments, and the final chapters resolve details introduced much earlier. This narrative control is what makes the ending feel complete; it was not mainly the result of advice from a famous editor, and the book was not simply finished faster than previous work. The may be awkwardly expressed, but the speaker''s judgement is clear: the strength lies in the plot. Some readers nevertheless criticise the novel for being very similar to the author''s other books. The setting has changed and several names are new, yet the central conflict, character types, and final revelation follow a familiar pattern. Their complaint is not about academic vocabulary or the physical of the hardback edition. Loyal fans may enjoy recognising the author''s usual formula, while other readers want greater risk and originality. The novel therefore succeeds as a controlled story but may not convince those hoping to see a genuinely new direction.', '{"source_key":"listening-p4-set043-audio","skill":"listening","part_number":4,"transcript":"The latest novel is uneven, but its plot is very strong. Events are carefully connected, tension increases at the right moments, and the final chapters resolve details introduced much earlier. This narrative control is what makes the ending feel complete; it was not mainly the result of advice from a famous editor, and the book was not simply finished faster than previous work. The may be awkwardly expressed, but the speaker''s judgement is clear: the strength lies in the plot. Some readers nevertheless criticise the novel for being very similar to the author''s other books. The setting has changed and several names are new, yet the central conflict, character types, and final revelation follow a familiar pattern. Their complaint is not about academic vocabulary or the physical of the hardback edition. Loyal fans may enjoy recognising the author''s usual formula, while other readers want greater risk and originality. The novel therefore succeeds as a controlled story but may not convince those hoping to see a genuinely new direction.","transcript_status":"source_word_comment","word_comment_ids":["547"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '0b5752cc08f70a1c3c9f4c7ed952229fa9f8154376ce11a79cc397efa9735703'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set044-audio', 'Listening Part 4: Criticism Of The New Novel (Version 3) (2026) Audio', 'The novel has attracted attention for its ambitious setting, but many readers struggle to connect with the characters. The problem is not that there are too many central figures or that their motivations are explained too clearly. Rather, the characters are difficult to relate to. Their reactions often feel distant from ordinary experience, and important emotional decisions happen without enough believable preparation. Readers understand what the characters do, yet they do not always understand them as people. The storyline has also received criticism because it lacks originality. The novel uses a familiar missing-person mystery, a secret family history, and a final revelation that resembles several recent bestsellers. The plot is not especially complex for a general audience, and experts have not mainly complained that every twist is predictable. Their broader concern is that the story depends too heavily on established patterns. Stronger character development might still have made the familiar structure satisfying, but the combination of distant characters and an unoriginal storyline prevents the novel from creating the emotional impact its setting initially promises.', '{"source_key":"listening-p4-set044-audio","skill":"listening","part_number":4,"transcript":"The novel has attracted attention for its ambitious setting, but many readers struggle to connect with the characters. The problem is not that there are too many central figures or that their motivations are explained too clearly. Rather, the characters are difficult to relate to. Their reactions often feel distant from ordinary experience, and important emotional decisions happen without enough believable preparation. Readers understand what the characters do, yet they do not always understand them as people. The storyline has also received criticism because it lacks originality. The novel uses a familiar missing-person mystery, a secret family history, and a final revelation that resembles several recent bestsellers. The plot is not especially complex for a general audience, and experts have not mainly complained that every twist is predictable. Their broader concern is that the story depends too heavily on established patterns. Stronger character development might still have made the familiar structure satisfying, but the combination of distant characters and an unoriginal storyline prevents the novel from creating the emotional impact its setting initially promises.","transcript_status":"source_word_comment","word_comment_ids":["548"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '851dbaa1b52838ae9cb420cd30f7cd3ac11fce129ee0593947b0efea8e3cd2ac'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set045-audio', 'Listening Part 4: Advertising and sponsoring (Version 2) (2026) Audio', 'Advertising is sometimes criticised as an unnecessary expense, but its basic importance is straightforward: it can help a business reach new customers. Brand recognition may also improve, yet that is not the specific benefit being emphasised here, and advertising does not automatically increase the price of every product. A campaign introduces an offer to people who might never encounter it through ordinary sales channels. Sponsoring sport, however, requires caution. A company may expect the popularity of a tournament to improve its own image, but the association works in both directions. If an event becomes connected with cheating, violence, corruption, or poor organisation, sponsorship can generate negative publicity for the sport. The main concern is not simply that tournaments are expensive or that sponsorship creates unfair competition. The reputational relationship itself is the risk. Businesses and organisers should examine values, governance, and possible public reaction before signing an agreement. Financial support can benefit athletes and fans, but a poorly chosen partnership may leave both the company and the sport remembered for the wrong reasons.', '{"source_key":"listening-p4-set045-audio","skill":"listening","part_number":4,"transcript":"Advertising is sometimes criticised as an unnecessary expense, but its basic importance is straightforward: it can help a business reach new customers. Brand recognition may also improve, yet that is not the specific benefit being emphasised here, and advertising does not automatically increase the price of every product. A campaign introduces an offer to people who might never encounter it through ordinary sales channels. Sponsoring sport, however, requires caution. A company may expect the popularity of a tournament to improve its own image, but the association works in both directions. If an event becomes connected with cheating, violence, corruption, or poor organisation, sponsorship can generate negative publicity for the sport. The main concern is not simply that tournaments are expensive or that sponsorship creates unfair competition. The reputational relationship itself is the risk. Businesses and organisers should examine values, governance, and possible public reaction before signing an agreement. Financial support can benefit athletes and fans, but a poorly chosen partnership may leave both the company and the sport remembered for the wrong reasons.","transcript_status":"source_word_comment","word_comment_ids":["549"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'a2cc109aa6a32fa63ae615de5f061fe36b24dac77543ad8e9b68bf09122d9629'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set046-audio', 'Listening Part 4: Work And Books Audio', 'Work provides income, but its contribution to an individual can be much wider. Through work, people develop skills, contribute to society, and gain a sense of purpose. A useful role can strengthen confidence and create relationships rather than serving as a way to avoid social contact. Nor should employment be understood mainly as a method for maximising weekend leisure. The value lies in applying knowledge and effort to something that matters beyond immediate payment. Books support a different but complementary kind of development. Reading introduces ideas, experiences, and perspectives that may not appear in a person''s daily job. When work and books are balanced, the result can be growth in every area of a person''s life. Professional experience tests ideas in practice, while reading encourages reflection and imagination. This balance does not require a complete separation of private and professional interests, and it does not make formal education unnecessary. Instead, the two activities reinforce each other. A thoughtful reader may become a more adaptable worker, and practical experience may deepen the meaning found in books.', '{"source_key":"listening-p4-set046-audio","skill":"listening","part_number":4,"transcript":"Work provides income, but its contribution to an individual can be much wider. Through work, people develop skills, contribute to society, and gain a sense of purpose. A useful role can strengthen confidence and create relationships rather than serving as a way to avoid social contact. Nor should employment be understood mainly as a method for maximising weekend leisure. The value lies in applying knowledge and effort to something that matters beyond immediate payment. Books support a different but complementary kind of development. Reading introduces ideas, experiences, and perspectives that may not appear in a person''s daily job. When work and books are balanced, the result can be growth in every area of a person''s life. Professional experience tests ideas in practice, while reading encourages reflection and imagination. This balance does not require a complete separation of private and professional interests, and it does not make formal education unnecessary. Instead, the two activities reinforce each other. A thoughtful reader may become a more adaptable worker, and practical experience may deepen the meaning found in books.","transcript_status":"source_word_comment","word_comment_ids":["550"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'f16037cc6d7324016b46634f077f7f05c766b9906bb224de3d3092eb2e849108'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set047-audio', 'Listening Part 4: Modern Society Audio', 'A striking of many modern works is that they have something to say about modern society. Rather than following classical artistic conventions without or concentrating only on historical figures, contemporary writers and artists examine technology, inequality, identity, isolation, and changing relationships. Their work can act as a response to the world in which audiences currently live. That relevance does not mean the message is always obvious. In fact, the meanings of these works are often not easily identified. Artists may use symbolism, fragmented structure, or an unreliable point of view instead of giving a direct moral lesson. The core message is rarely stated clearly in the opening. Viewers and readers have to connect images, notice contrasts, and consider why familiar situations are presented in an unusual way. Some people find this indirectness frustrating, while others value the freedom to interpret. The difficulty is not necessarily a weakness. It can encourage audiences to discuss the work and recognise that modern social problems often do not have simple explanations or one universally accepted conclusion.', '{"source_key":"listening-p4-set047-audio","skill":"listening","part_number":4,"transcript":"A striking of many modern works is that they have something to say about modern society. Rather than following classical artistic conventions without or concentrating only on historical figures, contemporary writers and artists examine technology, inequality, identity, isolation, and changing relationships. Their work can act as a response to the world in which audiences currently live. That relevance does not mean the message is always obvious. In fact, the meanings of these works are often not easily identified. Artists may use symbolism, fragmented structure, or an unreliable point of view instead of giving a direct moral lesson. The core message is rarely stated clearly in the opening. Viewers and readers have to connect images, notice contrasts, and consider why familiar situations are presented in an unusual way. Some people find this indirectness frustrating, while others value the freedom to interpret. The difficulty is not necessarily a weakness. It can encourage audiences to discuss the work and recognise that modern social problems often do not have simple explanations or one universally accepted conclusion.","transcript_status":"source_word_comment","word_comment_ids":["551"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '018ec9ddea35a80ce2a707ba527685f59f17a7baeb4e854db2f04cc5c4121b99'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set048-audio', 'Listening Part 4: The importance of sleep (Version 2) (2026) Audio', 'Several popular beliefs about sleep are misleading. Drinking coffee before bed does not generally relax the brain, and deliberately sleeping fewer hours is not a reliable way to improve deep sleep. According to the speaker, blocking out noise and light is key. A , dark room reduces stimulation and gives the body a more consistent signal that it is time to rest. Comfort and routine matter, but the sensory environment is the clearest recommendation. Insomnia is also misunderstood. It is not caused only by physical health problems, and people with insomnia do not usually sleep too much. One important difficulty is that people cannot always recognise the symptoms of tiredness. They may continue working, driving, or using a phone because they have become accustomed to poor concentration and low energy. As a result, they fail to respond to the body''s need for recovery and may make the sleep problem worse. Recognising subtle signs of fatigue is therefore part of managing insomnia, not merely counting the number of hours spent in bed.', '{"source_key":"listening-p4-set048-audio","skill":"listening","part_number":4,"transcript":"Several popular beliefs about sleep are misleading. Drinking coffee before bed does not generally relax the brain, and deliberately sleeping fewer hours is not a reliable way to improve deep sleep. According to the speaker, blocking out noise and light is key. A , dark room reduces stimulation and gives the body a more consistent signal that it is time to rest. Comfort and routine matter, but the sensory environment is the clearest recommendation. Insomnia is also misunderstood. It is not caused only by physical health problems, and people with insomnia do not usually sleep too much. One important difficulty is that people cannot always recognise the symptoms of tiredness. They may continue working, driving, or using a phone because they have become accustomed to poor concentration and low energy. As a result, they fail to respond to the body''s need for recovery and may make the sleep problem worse. Recognising subtle signs of fatigue is therefore part of managing insomnia, not merely counting the number of hours spent in bed.","transcript_status":"source_word_comment","word_comment_ids":["552"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'aeaa4707f679148ec490d98be0245b4f2dba1797a4a6d440315bd26f0e40a133'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set049-audio', 'Listening Part 4: The Sport (Version 3) (2026) Audio', 'In my recent review of modern educational programs, I''ve noticed that physical education remains a cornerstone of development. According to my findings, one of the most significant benefits of school sports is that they help promote students'' overall health by encouraging consistent physical activity. Furthermore, sports offer more than just physical fitness; for many young people, participating in these programs is essential because it provides balance. It helps them manage the heavy demands of their studies while developing social skills through teamwork.', '{"source_key":"listening-p4-set049-audio","skill":"listening","part_number":4,"transcript":"In my recent review of modern educational programs, I''ve noticed that physical education remains a cornerstone of development. According to my findings, one of the most significant benefits of school sports is that they help promote students'' overall health by encouraging consistent physical activity. Furthermore, sports offer more than just physical fitness; for many young people, participating in these programs is essential because it provides balance. It helps them manage the heavy demands of their studies while developing social skills through teamwork.","transcript_status":"source_word_comment","word_comment_ids":["553"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '6d461ba220ebd875683ac13007ff0ffc3088551d4782da0f7675b738ed7bfdc6'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set050-audio', 'Listening Part 4: Cycling expedition Audio', 'A long-distance cycling expedition needs physical preparation, suitable equipment, and emergency supplies, but my first advice is to be well informed about the places you are going to visit. Research road conditions, border rules, local transport, weather patterns, and access to accommodation before leaving. Carrying extra food and water can be sensible, and rough terrain may require caution, yet neither is a complete substitute for understanding the route. My broader advice is to learn about the people and cultures in the different countries. A cyclist moves slowly enough to enter small communities that ordinary tourists may pass without noticing. Knowing basic customs, respectful behaviour, and a few local expressions can prevent misunderstandings and create warmer encounters. I would not restrict the journey only to regions with perfect weather, and travelling at your own pace does not mean ignoring the destination or local context. A successful expedition is not measured only by distance. It is also shaped by how safely and respectfully the traveller interacts with the places through which the route passes.', '{"source_key":"listening-p4-set050-audio","skill":"listening","part_number":4,"transcript":"A long-distance cycling expedition needs physical preparation, suitable equipment, and emergency supplies, but my first advice is to be well informed about the places you are going to visit. Research road conditions, border rules, local transport, weather patterns, and access to accommodation before leaving. Carrying extra food and water can be sensible, and rough terrain may require caution, yet neither is a complete substitute for understanding the route. My broader advice is to learn about the people and cultures in the different countries. A cyclist moves slowly enough to enter small communities that ordinary tourists may pass without noticing. Knowing basic customs, respectful behaviour, and a few local expressions can prevent misunderstandings and create warmer encounters. I would not restrict the journey only to regions with perfect weather, and travelling at your own pace does not mean ignoring the destination or local context. A successful expedition is not measured only by distance. It is also shaped by how safely and respectfully the traveller interacts with the places through which the route passes.","transcript_status":"source_word_comment","word_comment_ids":["554"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '005c238c87e1f661fb938d652aa9c01df76c57932ef08ac3d7f0d73a8541800b'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set051-audio', 'Listening Part 4: Biography (2026) Audio', 'This biography''s greatest strength is its detailed description of a specific period of time. The author reconstructs the subject''s city, working conditions, political tensions, and ordinary routines so carefully that readers understand not only what happened but also why certain choices were possible in that historical moment. The book is not especially short, and it does not focus only on already famous people. Much of its value comes from the wider world surrounding the central figure. Critics have also described it as an unconventional biography. Instead of presenting events in a simple chronological sequence, the writer moves between letters, court records, memories, and imagined reconstructions clearly identified as interpretation. Some reviewers admire this method because it reveals uncertainty rather than pretending every detail is known. They do not mainly say that the book is too difficult to understand or that it contains an excessive amount of fictional material. Its unusual structure challenges traditional biography while remaining grounded in evidence. That combination makes the historical period feel vivid and open to debate.', '{"source_key":"listening-p4-set051-audio","skill":"listening","part_number":4,"transcript":"This biography''s greatest strength is its detailed description of a specific period of time. The author reconstructs the subject''s city, working conditions, political tensions, and ordinary routines so carefully that readers understand not only what happened but also why certain choices were possible in that historical moment. The book is not especially short, and it does not focus only on already famous people. Much of its value comes from the wider world surrounding the central figure. Critics have also described it as an unconventional biography. Instead of presenting events in a simple chronological sequence, the writer moves between letters, court records, memories, and imagined reconstructions clearly identified as interpretation. Some reviewers admire this method because it reveals uncertainty rather than pretending every detail is known. They do not mainly say that the book is too difficult to understand or that it contains an excessive amount of fictional material. Its unusual structure challenges traditional biography while remaining grounded in evidence. That combination makes the historical period feel vivid and open to debate.","transcript_status":"source_word_comment","word_comment_ids":["555"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '8985d4727081bda57f665892961a6bcb720bb2f1abd5af5be73712be3e66ff36'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set052-audio', 'Listening Part 4: Managing financial spending (Version 2) (2026) Audio', 'To control short-term spending, begin by monitoring what you spend and using that information to create a weekly plan. Small purchases are easy to forget, so recording food, transport, subscriptions, and entertainment reveals where money is actually going. Credit cards do not automatically control spending, and trying to save a large sum every single day is usually unrealistic. A weekly plan creates a practical limit while allowing adjustments between categories. Long-term decisions require a different kind of support. People should seek advice from someone who has experience, such as a financial adviser or a trusted person who has successfully managed similar goals. Keeping every saving in one account may not suit different time horizons, and avoiding long-term planning leaves major expenses unprepared. Experienced guidance can help someone compare risk, understand fees, and avoid decisions based only on fear or excitement. Financial control therefore combines close observation in the short term with informed advice for the future. Neither method removes personal responsibility, but both make decisions more deliberate and easier to review.', '{"source_key":"listening-p4-set052-audio","skill":"listening","part_number":4,"transcript":"To control short-term spending, begin by monitoring what you spend and using that information to create a weekly plan. Small purchases are easy to forget, so recording food, transport, subscriptions, and entertainment reveals where money is actually going. Credit cards do not automatically control spending, and trying to save a large sum every single day is usually unrealistic. A weekly plan creates a practical limit while allowing adjustments between categories. Long-term decisions require a different kind of support. People should seek advice from someone who has experience, such as a financial adviser or a trusted person who has successfully managed similar goals. Keeping every saving in one account may not suit different time horizons, and avoiding long-term planning leaves major expenses unprepared. Experienced guidance can help someone compare risk, understand fees, and avoid decisions based only on fear or excitement. Financial control therefore combines close observation in the short term with informed advice for the future. Neither method removes personal responsibility, but both make decisions more deliberate and easier to review.","transcript_status":"source_word_comment","word_comment_ids":["556"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '629ac51cbbb2f55182f85f4fb8a02afa60ef6a1a4648c7bd078caae69472809a'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set053-audio', 'Listening Part 4: Television Series (2026) Audio', 'Successful television series usually have more than a famous cast. One major strength is that they maintain consistent throughout. Viewers may forgive a weaker scene, but large changes in writing, acting, or production from one episode to the next can damage trust. Series are not automatically successful because they are shorter than films; many require a much greater total time commitment. Consistency allows audiences to believe that continued viewing will be rewarded. Television production is also changing because viewer habits influence the way series are made. Streaming audiences may watch several episodes in one evening, pause for weeks, or discover a programme long after its original broadcast. Writers and producers now consider episode length, opening pace, recap structure, and the timing of major revelations in response to those habits. Streaming platforms may affect costs, but reduced cost is not the main change described, and the speaker does not simply claim that television is becoming less creative. The form is adapting to how, when, and where people choose to watch.', '{"source_key":"listening-p4-set053-audio","skill":"listening","part_number":4,"transcript":"Successful television series usually have more than a famous cast. One major strength is that they maintain consistent throughout. Viewers may forgive a weaker scene, but large changes in writing, acting, or production from one episode to the next can damage trust. Series are not automatically successful because they are shorter than films; many require a much greater total time commitment. Consistency allows audiences to believe that continued viewing will be rewarded. Television production is also changing because viewer habits influence the way series are made. Streaming audiences may watch several episodes in one evening, pause for weeks, or discover a programme long after its original broadcast. Writers and producers now consider episode length, opening pace, recap structure, and the timing of major revelations in response to those habits. Streaming platforms may affect costs, but reduced cost is not the main change described, and the speaker does not simply claim that television is becoming less creative. The form is adapting to how, when, and where people choose to watch.","transcript_status":"source_word_comment","word_comment_ids":["557"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '4a0af155b68c648fb1bd27b72864442defe9c73388544f4f1175555f617c9f0c'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set054-audio', 'Listening Part 4: Script production (2026) Audio', 'The main weakness of this script is that the characters'' backgrounds are not adequately explored. We see them making major decisions, but we learn too little about their previous relationships, fears, and experiences to understand those choices. The setting is believable, and the dialogue is not especially complex; the emotional problem comes from missing context. Without a stronger sense of who the characters were before the story began, viewers may observe the action without becoming deeply involved. The speaker also criticises the effect of the industry on writing. New industry demands have a negative influence on script production. Tight deadlines, pressure to follow current trends, and repeated commercial revisions can reduce the time available for research and character development. These demands do not automatically increase audience engagement or provide writers with greater creative freedom. They may instead encourage safe, produced material. Improving this script therefore requires more than changing a few lines. Writers need time to build convincing personal histories and connect those histories naturally to the events shown on screen.', '{"source_key":"listening-p4-set054-audio","skill":"listening","part_number":4,"transcript":"The main weakness of this script is that the characters'' backgrounds are not adequately explored. We see them making major decisions, but we learn too little about their previous relationships, fears, and experiences to understand those choices. The setting is believable, and the dialogue is not especially complex; the emotional problem comes from missing context. Without a stronger sense of who the characters were before the story began, viewers may observe the action without becoming deeply involved. The speaker also criticises the effect of the industry on writing. New industry demands have a negative influence on script production. Tight deadlines, pressure to follow current trends, and repeated commercial revisions can reduce the time available for research and character development. These demands do not automatically increase audience engagement or provide writers with greater creative freedom. They may instead encourage safe, produced material. Improving this script therefore requires more than changing a few lines. Writers need time to build convincing personal histories and connect those histories naturally to the events shown on screen.","transcript_status":"source_word_comment","word_comment_ids":["558"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '18c9224654b42f264ff9e2354fd14f015602552dc9e6b95c6409dc78c3353056'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set055-audio', 'Listening Part 4: Criticism of the New Novel (2026) Audio', 'Since its release, the novel has received mixed comments about pacing, but the characters are one of its strongest features. They feel realistic and emotionally engaging. Their mistakes are understandable, their relationships change gradually, and even minor figures have motives that extend beyond moving the plot forward. The reviewer does not find them too difficult to understand, and they are certainly not less important than the storyline. This human may have a significant effect on the author''s career. The reviewer believes the novel will establish the author''s popularity. Some readers may disagree about individual chapters, but the emotional accessibility of the characters gives the book a wide appeal beyond academic audiences. The likely impact is therefore more specific than merely dividing opinion. Reviews, book-club discussions, and strong recommendations are already introducing the writer to people who had not read the earlier work. Popularity is never guaranteed, but the novel has the kind of memorable characters that can turn an emerging writer into a recognised public name.', '{"source_key":"listening-p4-set055-audio","skill":"listening","part_number":4,"transcript":"Since its release, the novel has received mixed comments about pacing, but the characters are one of its strongest features. They feel realistic and emotionally engaging. Their mistakes are understandable, their relationships change gradually, and even minor figures have motives that extend beyond moving the plot forward. The reviewer does not find them too difficult to understand, and they are certainly not less important than the storyline. This human may have a significant effect on the author''s career. The reviewer believes the novel will establish the author''s popularity. Some readers may disagree about individual chapters, but the emotional accessibility of the characters gives the book a wide appeal beyond academic audiences. The likely impact is therefore more specific than merely dividing opinion. Reviews, book-club discussions, and strong recommendations are already introducing the writer to people who had not read the earlier work. Popularity is never guaranteed, but the novel has the kind of memorable characters that can turn an emerging writer into a recognised public name.","transcript_status":"source_word_comment","word_comment_ids":["559"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '3f924665b2b5d92c9f5f2442315e503995f85167799348bf508a7251aca9aa37'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set056-audio', 'Listening Part 4: A Promotion Campaign for a Product (2026) Audio', 'My main criticism of this promotion campaign is that it makes exaggerated claims about the product. The advertisements promise immediate and dramatic results without presenting enough evidence, which may attract attention briefly but can weaken trust once customers compare the promise with reality. The problem is not a shortage of information or excessive focus on a low price. The language itself creates expectations that the product is unlikely to meet. There is also a financial concern. The campaign may not be profitable because it costs too much to make compared with the possible return. Celebrity fees, expensive video production, and repeated paid advertising have consumed a large budget, while projected sales remain uncertain. The campaign has already attracted public attention, and the target group appears appropriate, so those are not the main reasons for doubt. A simpler, more credible campaign might produce a better return and protect the brand''s reputation. Promotion should make a product visible, but spending and promises must remain proportionate to what the product can realistically deliver.', '{"source_key":"listening-p4-set056-audio","skill":"listening","part_number":4,"transcript":"My main criticism of this promotion campaign is that it makes exaggerated claims about the product. The advertisements promise immediate and dramatic results without presenting enough evidence, which may attract attention briefly but can weaken trust once customers compare the promise with reality. The problem is not a shortage of information or excessive focus on a low price. The language itself creates expectations that the product is unlikely to meet. There is also a financial concern. The campaign may not be profitable because it costs too much to make compared with the possible return. Celebrity fees, expensive video production, and repeated paid advertising have consumed a large budget, while projected sales remain uncertain. The campaign has already attracted public attention, and the target group appears appropriate, so those are not the main reasons for doubt. A simpler, more credible campaign might produce a better return and protect the brand''s reputation. Promotion should make a product visible, but spending and promises must remain proportionate to what the product can realistically deliver.","transcript_status":"source_word_comment","word_comment_ids":["560"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '7453de544c7d7a8149048b29ba5506bcfb9387984d65ea7b1ae93c68ba5c9339'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set057-audio', 'Listening Part 4: A book about a life of a scientist (Version 2) (2026) Audio', 'Many readers find this biography of a scientist interesting because it uses simple language to describe complex ideas. The author explains experiments through everyday comparisons and connects scientific to events in the subject''s life. The book does not depend heavily on technical vocabulary, nor does it avoid abstract concepts; it makes those concepts accessible. Its popularity has another explanation. The new biography is similar to the previous book about the scientist, which was also a bestseller. It follows a familiar structure, combines personal history with clear scientific explanation, and addresses many of the readers enjoyed in the earlier volume. Being similar does not mean every chapter is repeated. New letters and interviews provide additional material, but the tone and approach remain recognisable. The book is not popular because it is extremely long or difficult to understand. On the contrary, readers who trusted the style of the earlier biography know what kind of clear, engaging account to expect. Familiar accessibility has helped the new work reach a broad audience', '{"source_key":"listening-p4-set057-audio","skill":"listening","part_number":4,"transcript":"Many readers find this biography of a scientist interesting because it uses simple language to describe complex ideas. The author explains experiments through everyday comparisons and connects scientific to events in the subject''s life. The book does not depend heavily on technical vocabulary, nor does it avoid abstract concepts; it makes those concepts accessible. Its popularity has another explanation. The new biography is similar to the previous book about the scientist, which was also a bestseller. It follows a familiar structure, combines personal history with clear scientific explanation, and addresses many of the readers enjoyed in the earlier volume. Being similar does not mean every chapter is repeated. New letters and interviews provide additional material, but the tone and approach remain recognisable. The book is not popular because it is extremely long or difficult to understand. On the contrary, readers who trusted the style of the earlier biography know what kind of clear, engaging account to expect. Familiar accessibility has helped the new work reach a broad audience","transcript_status":"source_word_comment","word_comment_ids":["561"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '9875faae0cb726a863aee2f8cc60c610b18e1fdb18b60008bc98fac3962a7033'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set058-audio', 'Listening Part 4: Famous writers (Version 2) (2026) Audio', 'The two writers discussed today came from different countries and did not always write in the same genre. Their most interesting connection is that they both make references to each other in their work. One author adapts an image introduced by the other, while the second responds indirectly through an essay and a later fictional character. They were not born in the same place, and shared genre is not the reason they are compared. Their works also have a distinctive difficulty: the meaning is not always easily identified. Both writers use symbols, indirect narration, and hidden connections that reward careful reading. The stories are not all based on real events, and their language and structure cannot generally be described as simple. A reader may follow the surface plot while missing the intellectual conversation taking place between the two authors. Recognising their references can therefore change the interpretation of an entire passage. This combination of mutual influence and layered meaning explains why scholars continue comparing them and why new readers often discover additional ideas on a second or third reading.', '{"source_key":"listening-p4-set058-audio","skill":"listening","part_number":4,"transcript":"The two writers discussed today came from different countries and did not always write in the same genre. Their most interesting connection is that they both make references to each other in their work. One author adapts an image introduced by the other, while the second responds indirectly through an essay and a later fictional character. They were not born in the same place, and shared genre is not the reason they are compared. Their works also have a distinctive difficulty: the meaning is not always easily identified. Both writers use symbols, indirect narration, and hidden connections that reward careful reading. The stories are not all based on real events, and their language and structure cannot generally be described as simple. A reader may follow the surface plot while missing the intellectual conversation taking place between the two authors. Recognising their references can therefore change the interpretation of an entire passage. This combination of mutual influence and layered meaning explains why scholars continue comparing them and why new readers often discover additional ideas on a second or third reading.","transcript_status":"source_word_comment","word_comment_ids":["562"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '5b210e88a4229e92930d460bbcb2ff7049c97b0029ede8b77351de93f5b4dc9c'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set059-audio', 'Listening Part 4: Life after university (Version 2) (2026) Audio', 'Choosing a career after university can feel urgent, but students should be flexible and open-minded. Their first role may introduce an industry they had not considered, and skills gained in one position may later lead somewhere unexpected. Following friends into the same career or focusing only on salary can prevent graduates from noticing opportunities that better match their strengths. Flexibility does not mean accepting every offer; it means exploring possibilities before making a narrow long-term commitment. Applicants must also recognise that jobs are becoming more competitive. Many people may hold similar degrees, so employers increasingly compare experience, communication, digital skills, and evidence of initiative. It is not true that most jobs have stopped requiring , and handwritten applications are not a general preference. The practical lesson is to prepare carefully and show a distinctive combination of abilities. Graduates should research organisations, adapt applications to each role, and continue learning after formal education ends. Open-minded career choices and realistic awareness of competition make the transition into employment more manageable.', '{"source_key":"listening-p4-set059-audio","skill":"listening","part_number":4,"transcript":"Choosing a career after university can feel urgent, but students should be flexible and open-minded. Their first role may introduce an industry they had not considered, and skills gained in one position may later lead somewhere unexpected. Following friends into the same career or focusing only on salary can prevent graduates from noticing opportunities that better match their strengths. Flexibility does not mean accepting every offer; it means exploring possibilities before making a narrow long-term commitment. Applicants must also recognise that jobs are becoming more competitive. Many people may hold similar degrees, so employers increasingly compare experience, communication, digital skills, and evidence of initiative. It is not true that most jobs have stopped requiring , and handwritten applications are not a general preference. The practical lesson is to prepare carefully and show a distinctive combination of abilities. Graduates should research organisations, adapt applications to each role, and continue learning after formal education ends. Open-minded career choices and realistic awareness of competition make the transition into employment more manageable.","transcript_status":"source_word_comment","word_comment_ids":["563"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, '6e3cebb180bdb8e827b34dd855573c973421a9c0867ba3c93dd1c2c43acfa82c'),
  ('listening'::public.aptis_skill_enum, 'audio', 'listening-p4-set060-audio', 'Listening Part 4: Exhibition by Greek artist Jame Panos (2026) Audio', 'Good afternoon, everyone, and welcome to the National Gallery. Today, I''d like to introduce our new exhibition by the Greek artist Jame Panos. The exhibition includes more than thirty paintings, most of which were completed during the last ten years of his career. Panos is well known for his and emotional style. His paintings often show empty rooms, lonely figures, dark streets, and old buildings under grey skies. Because of this, many art critics have said that his paintings would be characterized by sadness. However, this sadness is not expressed in a dramatic way. Instead, it appears gently, through soft colours, simple shapes, and a strong sense of silence. One of the most interesting things about this exhibition is the way Panos uses memory. Several paintings were inspired by the small village in Greece where he grew up. The village has changed a lot since his childhood, and many of the places shown in the paintings no longer exist. For visitors, the exhibition feels like a window into the past, allowing them to see not only the artist''s personal memories, but also a disappearing part of Greek life. The exhibition will be open until the end of next month. Guided tours are available every Friday and Sunday afternoon.', '{"source_key":"listening-p4-set060-audio","skill":"listening","part_number":4,"transcript":"Good afternoon, everyone, and welcome to the National Gallery. Today, I''d like to introduce our new exhibition by the Greek artist Jame Panos. The exhibition includes more than thirty paintings, most of which were completed during the last ten years of his career. Panos is well known for his and emotional style. His paintings often show empty rooms, lonely figures, dark streets, and old buildings under grey skies. Because of this, many art critics have said that his paintings would be characterized by sadness. However, this sadness is not expressed in a dramatic way. Instead, it appears gently, through soft colours, simple shapes, and a strong sense of silence. One of the most interesting things about this exhibition is the way Panos uses memory. Several paintings were inspired by the small village in Greece where he grew up. The village has changed a lot since his childhood, and many of the places shown in the paintings no longer exist. For visitors, the exhibition feels like a window into the past, allowing them to see not only the artist''s personal memories, but also a disappearing part of Greek life. The exhibition will be open until the end of next month. Guided tours are available every Friday and Sunday afternoon.","transcript_status":"source_word_comment","word_comment_ids":["564"],"speaker_labels":["Speaker"],"status":"missing_audio","audio_url":null,"audio_path":null,"mime_type":"audio/mpeg"}'::jsonb, 'ae845930cdf16746812075c99891b7140678a7c63d1a1d269d9e3eca507ed0e6')
