existing_records AS (
  SELECT q.source_key, q.content_hash
  FROM public.aptis_questions q
  WHERE q.skill = 'listening'::public.aptis_skill_enum
),
inserted_rows AS (
  INSERT INTO public.aptis_questions (skill, part_number, question_type, source_key, source_file, content, display_order, ui_config, metadata, content_hash)
  SELECT bd.skill, bd.part_number, bd.question_type, bd.source_key, bd.source_file, bd.content, bd.display_order, bd.ui_config, bd.metadata, bd.content_hash
  FROM batch_data bd
  ON CONFLICT (skill, source_key)
  DO UPDATE SET
    part_number = EXCLUDED.part_number,
    question_type = EXCLUDED.question_type,
    source_file = EXCLUDED.source_file,
    content = EXCLUDED.content,
    display_order = EXCLUDED.display_order,
    ui_config = EXCLUDED.ui_config,
    metadata = EXCLUDED.metadata,
    content_hash = EXCLUDED.content_hash,
    import_status = 'updated'::public.aptis_question_status_enum,
    last_changed_at = NOW(),
    updated_at = NOW()
  WHERE aptis_questions.content_hash IS DISTINCT FROM EXCLUDED.content_hash
  RETURNING source_key, (xmax = 0) AS is_inserted
)
UPDATE _aptis_listening_stats SET
  inserted_count = (SELECT COUNT(*) FROM inserted_rows WHERE is_inserted = TRUE),
  updated_count = (SELECT COUNT(*) FROM inserted_rows WHERE is_inserted = FALSE),
  unchanged_count = 758 - (SELECT COUNT(*) FROM inserted_rows);

