DO UPDATE SET
  content = EXCLUDED.content,
  display_order = EXCLUDED.display_order,
  metadata = EXCLUDED.metadata
WHERE aptis_question_options.content IS DISTINCT FROM EXCLUDED.content
   OR aptis_question_options.display_order IS DISTINCT FROM EXCLUDED.display_order
   OR aptis_question_options.metadata IS DISTINCT FROM EXCLUDED.metadata;

-- 7. Upsert Question Solutions & Answers (Zero-Write via IS DISTINCT FROM)
INSERT INTO public.aptis_question_answers (question_id, correct_answer, solution_data, updated_at)
SELECT q.id, ans.correct_answer, ans.solution_data, NOW()
FROM public.aptis_questions q
CROSS JOIN LATERAL (
  SELECT 'listening-p1-set001-q001' AS sk, '{"correct_option":"A"}'::jsonb AS correct_answer, '{"transcript":"Man: I finally bought the small car I told you about! Friend: That''s great news! How much did it set you back? Man: The dealer first showed me a larger model for 3,550 pounds, and the version with a full service package came to 4,250. The small one itself cost me 3,250 pounds, which was within my budget. Friend: That sounds like a good deal. Man: Yes, I chose the basic package and used the money I saved to pay for insurance.","transcript_status":"source_word_comment","word_comment_ids":["0"],"speaker_labels":["Man"]}'::jsonb AS solution_data
  UNION ALL
  SELECT 'listening-p1-set001-q002' AS sk, '{"correct_option":"C"}'::jsonb AS correct_answer, '{"transcript":"Ahmed: Rose, are we still meeting for dinner tonight? I originally suggested half past seven, but my meeting may not finish until then. past seven is definitely too early for me. Could we make it to eight instead? Rose: That works well. I''ll book the table and wait inside if I arrive before you. Just message me when you leave the office. Nobody else needed to change their plans after the updated time was agreed.","transcript_status":"source_word_comment","word_comment_ids":["1"],"speaker_labels":["Ahmed"]}'::jsonb AS solution_data
  UNION ALL
  SELECT 'listening-p1-set001-q003' AS sk, '{"correct_option":"B"}'::jsonb AS correct_answer, '{"transcript":"Man: I''m trying to call the teleshop, but I have three similar numbers written down. Is it 102030? Friend: No, that belongs to the delivery company. And 301020 is the repair line. The teleshop number is 201030. Man: Great, I''ll save it properly this time. I need to ask whether the television I ordered is still available. A second check confirmed that no part of the total had been counted twice.","transcript_status":"source_word_comment","word_comment_ids":["2"],"speaker_labels":["Man"]}'::jsonb AS solution_data
  UNION ALL
  SELECT 'listening-p1-set001-q004' AS sk, '{"correct_option":"C"}'::jsonb AS correct_answer, '{"transcript":"Man: I like the green top in the window, but it is a little too bright for work. Do you have the same design in blue? Assistant: We do, although the blue one is only available in a larger size. Man: In that case, I''ll take the black top. It fits well and will match my trousers. I may come back for something more colourful another day.","transcript_status":"source_word_comment","word_comment_ids":["3"],"speaker_labels":["Man"]}'::jsonb AS solution_data
  UNION ALL
  SELECT 'listening-p1-set001-q005' AS sk, '{"correct_option":"C"}'::jsonb AS correct_answer, '{"transcript":"Man: Shall we meet at the station before lunch? Sister: It will be extremely crowded because several trains arrive together. The university is , but it is too far from the shops we need. Man: Let''s meet at the park instead, beside the main gate. Sister: Perfect. I''ll bring the documents, and afterwards we can walk into town together. The nearby landmarks were useful, although neither was the destination itself.","transcript_status":"source_word_comment","word_comment_ids":["4"],"speaker_labels":["Man"]}'::jsonb AS solution_data
  UNION ALL
  SELECT 'listening-p1-set001-q006' AS sk, '{"correct_option":"A"}'::jsonb AS correct_answer, '{"transcript":"Woman: Lisa and I have just returned from a week by the sea. People sometimes think we are mother and daughter because she is a little older and always looks after me. Others assume she was once my teacher. In fact, we are best friends and have known each other since secondary school. We travel together whenever our work schedules allow it. The explanation helped listeners understand why the other guesses sounded believable.","transcript_status":"source_word_comment","word_comment_ids":["5"],"speaker_labels":["Woman"]}'::jsonb AS solution_data
  UNION ALL
  SELECT 'listening-p1-set001-q007' AS sk, '{"correct_option":"A"}'::jsonb AS correct_answer, '{"transcript":"Woman: We talked about replacing the computer because it is slow, and my husband also wants a smaller car. However, the change we are making to the house is the window. The current one is too large and lets in too much sunlight during the afternoon. We have ordered a smaller design with thicker glass, and the work should begin next month. Nothing else needed to change once the main decision had been made.","transcript_status":"source_word_comment","word_comment_ids":["6"],"speaker_labels":["Woman"]}'::jsonb AS solution_data
  UNION ALL
  SELECT 'listening-p1-set001-q008' AS sk, '{"correct_option":"A"}'::jsonb AS correct_answer, '{"transcript":"Receptionist: I''ve checked today''s clinic list again. Carl, Harry and Matthew are from the UK, while two other clients are visiting from France. Leslie is the only person from the United States, so we have one American client today. Her appointment is at eleven. Please make sure the correct form is waiting at reception before she arrives. The receipt and the current price list were checked once more afterwards.","transcript_status":"source_word_comment","word_comment_ids":["7"],"speaker_labels":["Receptionist"]}'::jsonb AS solution_data
  UNION ALL
  SELECT 'listening-p1-set001-q009' AS sk, '{"correct_option":"C"}'::jsonb AS correct_answer, '{"transcript":"Anna: I enjoy walking early because everywhere is before classes begin. I sometimes walk through the park at weekends, and my neighbourhood is pleasant in the evening. Every morning, though, I go for a walk around the college campus. I usually pass the library and sports centre before returning to my accommodation to collect my books for the first lesson. The route becomes simple once the correct building or entrance comes into view.","transcript_status":"source_word_comment","word_comment_ids":["8"],"speaker_labels":["Anna"]}'::jsonb AS solution_data
  UNION ALL
  SELECT 'listening-p1-set001-q010' AS sk, '{"correct_option":"B"}'::jsonb AS correct_answer, '{"transcript":"Girl: Hi, I was in your café this afternoon and I think I left my bag there. I paid at the counter, but I am sure I still had it afterwards. I did not sit near the door. My table was in the corner beside a tall plant, so could you look there first? It is a small brown bag with my keys inside. They planned to arrive early enough to avoid any further confusion there.","transcript_status":"source_word_comment","word_comment_ids":["9"],"speaker_labels":["Girl"]}'::jsonb AS solution_data
  UNION ALL
  SELECT 'listening-p1-set001-q011' AS sk, '{"correct_option":"C"}'::jsonb AS correct_answer, '{"transcript":"Helen: My whole family has come to see me off before I start college. We are not inside the university area yet, and we are nowhere near the library complex. We are standing in the residential area just outside the campus, beside some small shops and trees. Dad is unloading my bags while everyone else is saying goodbye. It feels exciting and a little emotional.","transcript_status":"source_word_comment","word_comment_ids":["10"],"speaker_labels":["Helen"]}'::jsonb AS solution_data
  UNION ALL
  SELECT 'listening-p1-set001-q012' AS sk, '{"correct_option":"B"}'::jsonb AS correct_answer, '{"transcript":"Woman: I''m checking the timing for dinner tonight because I need to catch a train afterwards. The journey to the station is not thirty minutes unless I take a taxi, and fifty minutes would include waiting for the bus. Walking normally takes about forty minutes. I''ll leave the restaurant early enough to buy my ticket and find the correct platform without rushing. They noted the change immediately so nobody would follow the earlier timetable.","transcript_status":"source_word_comment","word_comment_ids":["11"],"speaker_labels":["Woman"]}'::jsonb AS solution_data
  UNION ALL
  SELECT 'listening-p1-set001-q013' AS sk, '{"correct_option":"B"}'::jsonb AS correct_answer, '{"transcript":"Man: Our train was supposed to depart at nine, but a signal problem caused a delay. At first, staff warned us that we might have to wait until ten o''clock. Fortunately, the problem was fixed sooner, and the train actually left at half past nine. We arrived later than planned, but we still had enough time to attend the morning meeting. The remaining activities could continue normally once the correct time was clear.","transcript_status":"source_word_comment","word_comment_ids":["12"],"speaker_labels":["Man"]}'::jsonb AS solution_data
  UNION ALL
  SELECT 'listening-p1-set002-q001' AS sk, '{"correct_option":"B"}'::jsonb AS correct_answer, '{"transcript":"Woman: I''m comparing the flights for my trip next month. There is an afternoon service for 300 pounds, but it arrives too late for the conference. The flexible ticket costs 400 pounds because changes are included. The morning flight I need is 350 pounds. It is not the cheapest option, although its arrival time is much more convenient. The figures became clear once the different products or categories were separated.","transcript_status":"source_word_comment","word_comment_ids":["13"],"speaker_labels":["Woman"]}'::jsonb AS solution_data
  UNION ALL
  SELECT 'listening-p1-set002-q002' AS sk, '{"correct_option":"A"}'::jsonb AS correct_answer, '{"transcript":"Woman: I advertised my old music player for sixty dollars, but nobody wanted to pay that much. One buyer offered forty, which felt too low because it still worked perfectly. We eventually agreed on fifty dollars, and I sold it last weekend. I used part of the money to buy new headphones and put the rest into my savings account. Everyone involved used the latest record instead of relying on memory.","transcript_status":"source_word_comment","word_comment_ids":["14"],"speaker_labels":["Woman"]}'::jsonb AS solution_data
  UNION ALL
  SELECT 'listening-p1-set002-q003' AS sk, '{"correct_option":"C"}'::jsonb AS correct_answer, '{"transcript":"Woman: He is often late, so people assume he oversleeps or returns home because he has forgotten something. Today neither of those things happened. He left the house on time but reached the platform just as the doors closed, so the main reason was that he missed the train. He had to wait twenty minutes for the next service and called the office immediately. Once that was understood, the rest of the situation made much more sense.","transcript_status":"source_word_comment","word_comment_ids":["15"],"speaker_labels":["Woman"]}'::jsonb AS solution_data
  UNION ALL
  SELECT 'listening-p1-set002-q004' AS sk, '{"correct_option":"A"}'::jsonb AS correct_answer, '{"transcript":"Mother: Hi, could you pick up a few groceries on your way home? Son: Sure, Mum. What do you need? Mother: The milk is two pounds fifty, and the large loaf of bread costs three pounds fifty. A dozen eggs is only one pound fifty today, so please buy two boxes if they still have them. Son: Got it. Is that everything? Mother: Yes, I need the eggs for a cake, but the other things are for tomorrow''s breakfast. Thank you, dear.","transcript_status":"source_word_comment","word_comment_ids":["16"],"speaker_labels":["Mother"]}'::jsonb AS solution_data
  UNION ALL
  SELECT 'listening-p1-set002-q005' AS sk, '{"correct_option":"C"}'::jsonb AS correct_answer, '{"transcript":"Man: Hi, I''m calling to confirm where we should meet. I could wait at home, but then we might miss each other when you arrive. Woman: True, and the garden is completely wet after all that rain. Man: Exactly. Let''s meet outside the shop opposite the station instead. I''ll be standing near the entrance with a blue umbrella. Woman: Perfect, I''ll head there now. We can walk home together from there.","transcript_status":"source_word_comment","word_comment_ids":["17"],"speaker_labels":["Man"]}'::jsonb AS solution_data
  UNION ALL
  SELECT 'listening-p1-set002-q006' AS sk, '{"correct_option":"C"}'::jsonb AS correct_answer, '{"transcript":"Julie: Professor, I cannot finish the assignment by Thursday morning. Could I submit it on Friday? Professor: Friday is difficult because the department will be closed. I can extend the deadline until Saturday morning. Upload it before midday, and make sure the reference list is included. Julie: Thank you. That gives me an extra evening to check the final section carefully. The new arrangement also avoided a rushed journey at the busiest part of the day.","transcript_status":"source_word_comment","word_comment_ids":["18"],"speaker_labels":["Julie"]}'::jsonb AS solution_data
  UNION ALL
  SELECT 'listening-p1-set002-q007' AS sk, '{"correct_option":"C"}'::jsonb AS correct_answer, '{"transcript":"Tour guide: Welcome to our town. Older guidebooks say around eight thousand people lived here, and an estimate from several years ago suggested nine thousand. The latest local records show that the population has reached ten thousand. Most new residents live near the railway station, while the historic centre still contains the small shops and cafés we will visit today. The written information was updated immediately to prevent another mistake later.","transcript_status":"source_word_comment","word_comment_ids":["19"],"speaker_labels":["Tour guide"]}'::jsonb AS solution_data
  UNION ALL
